import dayjs, { Dayjs } from "dayjs";
import { getShiftType } from "../../common/shiftTypes";
import type { PillTone } from "../../common/ui";

/**
 * Helpers for the persisted roster shape:
 * info.shift = [{ key: "YYYY-MM-DD", date: "dddd, YYYY-MM-DD", [driverId]: Slot[] }]
 * Slot = { time: ["YYYY-MM-DD HH:mm", "YYYY-MM-DD HH:mm"], shiftType, locationType }
 */

export const DAY_KEY = "YYYY-MM-DD";
export const DAY_LABEL = "dddd, YYYY-MM-DD";
export const SLOT_FORMAT = "YYYY-MM-DD HH:mm";
const ROW_META_KEYS = ["key", "date"];

export interface Slot {
  time: string[];
  shiftType?: string;
  locationType?: string;
}

export interface ParsedSlot {
  start: Dayjs;
  end: Dayjs;
  startLabel: string;
  endLabel: string;
  overnight: boolean;
  minutes: number;
}

/** Empty day rows (no driver columns) covering start..end inclusive. */
export const buildDayRows = (start: any, end: any) => {
  const rows: any[] = [];
  let current = dayjs(dayjs(start).format(DAY_KEY));
  const last = dayjs(dayjs(end).format(DAY_KEY));
  while (!current.isAfter(last, "day")) {
    rows.push({ key: current.format(DAY_KEY), date: current.format(DAY_LABEL) });
    current = current.add(1, "day");
  }
  return rows;
};

export const isDriverKey = (key: string) => !ROW_META_KEYS.includes(key);

/**
 * Anchors a stored slot to the row's day. Older copies kept the source
 * roster's dates inside `time`, so only HH:mm and the day offset are trusted.
 */
export const parseSlot = (slot: Slot, dayKey: string): ParsedSlot | null => {
  const [rawStart, rawEnd] = Array.isArray(slot?.time) ? slot.time : [];
  if (typeof rawStart !== "string" || typeof rawEnd !== "string") return null;
  const [startDay, startHm] = rawStart.split(" ");
  const [endDay, endHm] = rawEnd.split(" ");
  if (!startHm || !endHm) return null;
  const offset = Math.max(0, Math.min(1, dayjs(endDay).diff(dayjs(startDay), "day") || 0));
  const start = dayjs(`${dayKey} ${startHm}`);
  let end = dayjs(`${dayKey} ${endHm}`).add(offset, "day");
  if (!end.isAfter(start)) end = end.add(1, "day");
  return {
    start,
    end,
    startLabel: startHm,
    endLabel: endHm,
    overnight: !end.isSame(start, "day"),
    minutes: end.diff(start, "minute"),
  };
};

/** Untyped legacy slots count as on shift, matching the ride dashboard. */
export const isOnShiftSlot = (slot: { shiftType?: string }) => !slot?.shiftType || getShiftType(slot.shiftType).assignable;

export const cellSlots = (row: any, driverId: string): Slot[] =>
  Array.isArray(row?.[driverId]) ? row[driverId] : [];

export const minutesOnShift = (slots: Slot[], dayKey: string) =>
  slots.reduce((sum, slot) => {
    if (!isOnShiftSlot(slot)) return sum;
    return sum + (parseSlot(slot, dayKey)?.minutes || 0);
  }, 0);

export const formatHours = (minutes: number) => {
  if (!minutes) return "0h";
  const hours = minutes / 60;
  return `${Number.isInteger(hours) ? hours : hours.toFixed(1)}h`;
};

/** Drivers with at least one on-shift slot and their total on-shift minutes. */
export const getRosterStats = (shift: any) => {
  const drivers = new Set<string>();
  let minutes = 0;
  if (Array.isArray(shift)) {
    shift.forEach((row) => {
      Object.keys(row || {})
        .filter(isDriverKey)
        .forEach((driverId) => {
          const m = minutesOnShift(cellSlots(row, driverId), row.key);
          if (m > 0) drivers.add(driverId);
          minutes += m;
        });
    });
  }
  return { driverCount: drivers.size, minutes };
};

export const getRosterStatus = (
  startDate: string,
  endDate: string,
  today = dayjs()
): { label: string; tone: PillTone; order: number } => {
  const key = today.format(DAY_KEY);
  if (!startDate || !endDate) return { label: "No dates", tone: "gray", order: 3 };
  if (key < startDate) return { label: "Upcoming", tone: "blue", order: 1 };
  if (key > endDate) return { label: "Past", tone: "gray", order: 2 };
  return { label: "Active now", tone: "green", order: 0 };
};

/** e.g. "Sep 28 – Oct 4, 2026" */
export const formatPeriod = (startDate: string, endDate: string) => {
  if (!startDate || !endDate) return startDate || endDate || "—";
  const start = dayjs(startDate);
  const end = dayjs(endDate);
  const sameYear = start.year() === end.year();
  return `${start.format(sameYear ? "MMM D" : "MMM D, YYYY")} – ${end.format("MMM D, YYYY")}`;
};

export const countDays = (startDate: string, endDate: string) =>
  startDate && endDate ? Math.max(1, dayjs(endDate).diff(dayjs(startDate), "day") + 1) : 0;

export const rangesOverlap = (aStart: string, aEnd: string, bStart: string, bEnd: string) =>
  !!(aStart && aEnd && bStart && bEnd) && aStart <= bEnd && bStart <= aEnd;

/**
 * Copies a roster onto a new start date: every day row and every slot moves by
 * the same number of days so slot dates always match their row.
 */
export const shiftRosterRows = (shift: any, fromStart: string, fromEnd: string, toStart: string) => {
  const offset = dayjs(toStart).diff(dayjs(fromStart), "day");
  const sourceRows = Array.isArray(shift) ? shift : [];
  return buildDayRows(fromStart, fromEnd).map((day) => {
    const source = sourceRows.find((row) => row?.key === day.key) || {};
    const newDay = dayjs(day.key).add(offset, "day");
    const row: any = { key: newDay.format(DAY_KEY), date: newDay.format(DAY_LABEL) };
    Object.keys(source)
      .filter(isDriverKey)
      .forEach((driverId) => {
        row[driverId] = cellSlots(source, driverId).map((slot) => ({
          ...slot,
          time: Array.isArray(slot?.time)
            ? slot.time.map((t) =>
                typeof t === "string" && t.length >= 16
                  ? dayjs(t).add(offset, "day").format(SLOT_FORMAT)
                  : t
              )
            : slot?.time,
        }));
      });
    return row;
  });
};

export const isWeekend = (dayKey: string) => [0, 6].includes(dayjs(dayKey).day());
export const isToday = (dayKey: string) => dayKey === dayjs().format(DAY_KEY);

export const hexToRgba = (hex: string, alpha: number) => {
  const clean = (hex || "#91A5C6").replace("#", "");
  const n = parseInt(clean.length === 3 ? clean.replace(/(.)/g, "$1$1") : clean, 16);
  return `rgba(${(n >> 16) & 255}, ${(n >> 8) & 255}, ${n & 255}, ${alpha})`;
};

/** Re-dates a slot onto `dayKey`, keeping its times and overnight offset. */
export const anchorSlot = (slot: Slot, dayKey: string): Slot => {
  const parsed = parseSlot(slot, dayKey);
  if (!parsed) return slot;
  return { ...slot, time: [parsed.start.format(SLOT_FORMAT), parsed.end.format(SLOT_FORMAT)] };
};

export interface TimeOff {
  key: string;
  start: number;
  end: number;
  label: string;
  reason?: string;
}

export const intervalsOverlap = (aStart: number, aEnd: number, bStart: number, bEnd: number) =>
  aStart < bEnd && aEnd > bStart;

export const findTimeOffConflict = (start: number, end: number, timeOffs: TimeOff[]) =>
  (timeOffs || []).find((off) => intervalsOverlap(start, end, off.start, off.end));

/** Time off touching the given day (local midnight to midnight). */
export const timeOffsForDay = (dayKey: string, timeOffs: TimeOff[]) => {
  const start = dayjs(dayKey).startOf("day").valueOf();
  const end = dayjs(dayKey).endOf("day").valueOf();
  return (timeOffs || []).filter((off) => intervalsOverlap(start, end, off.start, off.end));
};
