import { useCallback, useEffect, useRef, useState } from "react";
import { getJob, getSchedule, solve } from "services/apis/collections/aiSchedulerApis";
import { getErrorMessage } from "services/apis/aiSchedulerClient";
import { Schedule, SchedJob, SolveRequest } from "services/apis/aiSchedulerTypes";
import { pushNotification } from "utils/notifications";

const POLL_MS = 2000;

interface UseSolveJobArgs {
  orgId: string | undefined;
  onScheduleReady: (schedule: Schedule, scheduleId: string) => void;
  onInfeasible: (diagnostics: string[], schedule?: Schedule) => void;
}

const useSolveJob = ({ orgId, onScheduleReady, onInfeasible }: UseSolveJobArgs) => {
  const [job, setJob] = useState<SchedJob | null>(null);
  const [solving, setSolving] = useState(false);
  const intervalRef = useRef<any>(null);
  const deadlineRef = useRef<number>(0);
  const callbacksRef = useRef({ onScheduleReady, onInfeasible });
  callbacksRef.current = { onScheduleReady, onInfeasible };

  const stopPolling = useCallback(() => {
    if (intervalRef.current) {
      clearInterval(intervalRef.current);
      intervalRef.current = null;
    }
    setSolving(false);
  }, []);

  useEffect(() => stopPolling, [stopPolling]);

  const startPolling = useCallback(
    (jobId: string, timeLimitSeconds?: number) => {
      if (!orgId) return;
      stopPolling();
      setSolving(true);
      // Solver default is 240s; allow that plus generous queue/fetch slack.
      deadlineRef.current =
        Date.now() + (Math.max(timeLimitSeconds || 240, 240) + 120) * 1000;

      const tick = async () => {
        if (Date.now() > deadlineRef.current) {
          stopPolling();
          pushNotification("Solve timed out — check jobs later", "error", "TOP_CENTER", 4000);
          return;
        }
        try {
          const j = await getJob(orgId, jobId);
          setJob({ ...j, jobId });
          if (j.status === "done") {
            stopPolling();
            const scheduleId = j.scheduleId;
            if (!scheduleId) {
              pushNotification("Job finished without a schedule id", "error", "TOP_CENTER", 4000);
              return;
            }
            const schedule = await getSchedule(orgId, scheduleId);
            callbacksRef.current.onScheduleReady(schedule, scheduleId);
          } else if (j.status === "infeasible") {
            stopPolling();
            let schedule: Schedule | undefined;
            if (j.scheduleId) {
              try {
                schedule = await getSchedule(orgId, j.scheduleId);
              } catch {
                schedule = undefined;
              }
            }
            callbacksRef.current.onInfeasible(schedule?.diagnostics || [], schedule);
          } else if (j.status === "failed") {
            stopPolling();
            pushNotification("Solve failed — try again", "error", "TOP_CENTER", 4000);
          }
        } catch (e) {
          // Transient poll errors are tolerated until the deadline.
        }
      };

      tick();
      intervalRef.current = setInterval(tick, POLL_MS);
    },
    [orgId, stopPolling]
  );

  const startSolve = useCallback(
    async (request: SolveRequest = {}) => {
      if (!orgId) return;
      try {
        setSolving(true);
        setJob({ status: "queued", progress: 0 });
        const { jobId } = await solve(orgId, request);
        startPolling(jobId, request.timeLimitSeconds);
      } catch (e) {
        setSolving(false);
        setJob(null);
        pushNotification(getErrorMessage(e), "error", "TOP_CENTER", 4000);
      }
    },
    [orgId, startPolling]
  );

  return {
    job,
    solving,
    startSolve,
    resumePolling: startPolling,
    stopWatching: stopPolling,
  };
};

export default useSolveJob;
