function getCustomerCpcCollapseKeys(
  cadSections: any[],
  hasLegacyFlatFields: boolean
): string[] {
  if (cadSections?.length > 0) {
    const keys: string[] = [];
    cadSections.forEach((section: any, si: number) => {
      const hasRows = (section.Rows || []).some(
        (r: any) => (r?.Cols?.length ?? 0) > 0
      );
      if (hasRows) keys.push(`customer-cpc-section-${si}`);
    });
    return keys;
  }
  if (hasLegacyFlatFields) return ["customer-cpc-legacy"];
  return [];
}

