import React, { FC, useMemo, useState } from "react";
import { Col, Input, Row, Select, Table } from "antd";
import { SearchOutlined } from "@ant-design/icons";

import {
  BillableEntity,
  BillingStatus,
  Domain,
  EntityKind,
  PaymentRequestTarget,
  ProjectRollup,
} from "../types";
import { DOMAIN_LABELS, PROJECTS, getProject } from "../mockData";
import { peopleFor, projectRollups } from "../mockEntities";
import { BILLING_STATUS_LABELS, billingStatusOf } from "../selectors";
import { directoryGroups, directoryLabel } from "../menu";
import { payeeColumns, playerColumns, projectColumns } from "../entityColumns";
import SendPaymentRequestModal from "../SendPaymentRequestModal";
import PaymentConfigEditor from "../PaymentConfigEditor";

interface Props {
  kind: EntityKind;
  onKindChange: (kind: EntityKind) => void;
  domain: Domain;
}

interface EditTarget {
  configId: string | null;
  subject: string;
}

const STATUS_OPTIONS = (Object.keys(BILLING_STATUS_LABELS) as BillingStatus[]).map(
  (value) => ({ value, label: BILLING_STATUS_LABELS[value] })
);

/** How many records each group holds, for the select. */
const countFor = (kind: EntityKind, domain: Domain): number =>
  kind === "teams" || kind === "events"
    ? projectRollups(domain, kind === "teams" ? "team" : "event").length
    : peopleFor(kind, domain).length;

/**
 * The Directory: one table page for every entity group - players, teams,
 * events, coaches, staff and vendors - picked with the select in the
 * page head rather than six sidebar buttons. The columns differ per
 * kind; the chrome, filters, status chip and the two actions do not.
 */
const EntityScreen: FC<Props> = ({ kind, onKindChange, domain }) => {
  const [search, setSearch] = useState("");
  const [projectFilter, setProjectFilter] = useState<string | undefined>();
  const [statusFilter, setStatusFilter] = useState<BillingStatus | undefined>();
  const [requestTarget, setRequestTarget] = useState<PaymentRequestTarget | null>(null);
  const [editTarget, setEditTarget] = useState<EditTarget | null>(null);

  const labels = DOMAIN_LABELS[domain];
  const isProjectKind = kind === "teams" || kind === "events";
  const title = directoryLabel(kind, domain);
  const groups = useMemo(() => directoryGroups(domain), [domain]);

  const projectOptions = useMemo(
    () =>
      PROJECTS.filter((project) => project.domain === domain).map((project) => ({
        value: project.id,
        label: project.name,
      })),
    [domain]
  );

  const term = search.trim().toLowerCase();

  const projectRows = useMemo<ProjectRollup[]>(() => {
    if (!isProjectKind) return [];
    return projectRollups(domain, kind === "teams" ? "team" : "event").filter((p) => {
      if (statusFilter && p.status !== statusFilter) return false;
      if (term && p.name.toLowerCase().indexOf(term) === -1) return false;
      return true;
    });
  }, [isProjectKind, domain, kind, statusFilter, term]);

  const peopleRows = useMemo<BillableEntity[]>(() => {
    if (isProjectKind) return [];
    return peopleFor(kind as Exclude<EntityKind, "teams" | "events">, domain).filter((e) => {
      if (projectFilter && e.projectIds.indexOf(projectFilter) === -1) return false;
      if (statusFilter && billingStatusOf(e.billing) !== statusFilter) return false;
      if (term) {
        const haystack = `${e.name} ${e.role} ${e.email} ${e.household || ""}`.toLowerCase();
        if (haystack.indexOf(term) === -1) return false;
      }
      return true;
    });
  }, [isProjectKind, kind, domain, projectFilter, statusFilter, term]);

  /* ---- actions ---- */

  const sendForPerson = (entity: BillableEntity) => {
    if (entity.kind === "player") {
      const project = entity.projectIds[0] ? getProject(entity.projectIds[0]) : null;
      setRequestTarget({ project, focusMemberIds: [entity.id] });
      return;
    }
    setRequestTarget({ project: null, payee: entity });
  };

  const editForPerson = (entity: BillableEntity) => {
    if (entity.kind === "player") {
      const project = entity.projectIds[0] ? getProject(entity.projectIds[0]) : null;
      setEditTarget({
        configId: project ? project.paymentConfigId : null,
        subject: project ? `${entity.name} (${project.name})` : entity.name,
      });
      return;
    }
    setEditTarget({ configId: entity.paymentConfigId, subject: entity.name });
  };

  const sendForProject = (project: ProjectRollup) =>
    setRequestTarget({ project });

  const editForProject = (project: ProjectRollup) =>
    setEditTarget({ configId: project.paymentConfigId, subject: project.name });

  const columns = useMemo(() => {
    if (kind === "players") {
      return playerColumns({ domain, onSend: sendForPerson, onEdit: editForPerson });
    }
    if (kind === "coaches" || kind === "staff" || kind === "vendors") {
      return payeeColumns(kind, { domain, onSend: sendForPerson, onEdit: editForPerson });
    }
    return projectColumns(kind === "teams" ? "team" : "event", {
      domain,
      onSend: sendForProject,
      onEdit: editForProject,
    });
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [kind, domain]);

  const count = isProjectKind ? projectRows.length : peopleRows.length;

  return (
    <React.Fragment>
      <Row>
        <Col span={24} className="cfo-page-head">
          <div className="cfo-directory-head">
            <div>
              <h2 style={{ marginBottom: 4 }}>Directory</h2>
              <p style={{ marginBottom: 0, color: "#8c8c8c" }}>
                Directory &gt; {title} · {count} {count === 1 ? "record" : "records"}
              </p>
            </div>
            <Select
              className="cfo-directory-select"
              value={kind}
              onChange={(value) => {
                setSearch("");
                setProjectFilter(undefined);
                setStatusFilter(undefined);
                onKindChange(value);
              }}
              dropdownMatchSelectWidth={false}
              optionLabelProp="label"
            >
              {groups.map((group) => (
                <Select.OptGroup key={group.label} label={group.label}>
                  {group.options.map((option) => (
                    <Select.Option key={option.value} value={option.value} label={option.label}>
                      <span className="cfo-directory-option">
                        <span>{option.label}</span>
                        <span className="cfo-directory-option__count">{countFor(option.value, domain)}</span>
                      </span>
                    </Select.Option>
                  ))}
                </Select.OptGroup>
              ))}
            </Select>
          </div>

          <div className="cfo-page-toolbar">
            <Input
              allowClear
              value={search}
              onChange={(e) => setSearch(e.target.value)}
              style={{ width: 240, flexShrink: 0 }}
              placeholder="Search by name"
              prefix={<SearchOutlined style={{ color: "#bfbfbf" }} />}
            />
            {!isProjectKind && (
              <Select
                allowClear
                showSearch
                placeholder={`Filter by ${labels.navSingular.team.toLowerCase()}`}
                options={projectOptions}
                value={projectFilter}
                onChange={(value) => setProjectFilter(value)}
                filterOption={(input, option) =>
                  (option?.label ?? "").toString().toLowerCase().includes(input.toLowerCase())
                }
                style={{ width: 220, flexShrink: 0 }}
              />
            )}
            <Select
              allowClear
              placeholder="Status"
              options={STATUS_OPTIONS}
              value={statusFilter}
              onChange={(value) => setStatusFilter(value)}
              style={{ width: 150, flexShrink: 0 }}
            />
          </div>
        </Col>
      </Row>

      <Row gutter={20} className="scrollable-table mt-3" style={{ display: "grid" }}>
        <Col span={24} style={{ overflow: "auto" }}>
          {isProjectKind ? (
            <Table<ProjectRollup>
              rowKey="id"
              dataSource={projectRows}
              columns={columns as any}
              scroll={{ x: true }}
              pagination={{ pageSize: 15, showSizeChanger: false }}
            />
          ) : (
            <Table<BillableEntity>
              rowKey="id"
              dataSource={peopleRows}
              columns={columns as any}
              scroll={{ x: true }}
              pagination={{ pageSize: 15, showSizeChanger: false }}
            />
          )}
        </Col>
      </Row>

      <SendPaymentRequestModal
        open={!!requestTarget}
        target={requestTarget}
        onClose={() => setRequestTarget(null)}
      />

      <PaymentConfigEditor
        open={!!editTarget}
        configId={editTarget ? editTarget.configId : null}
        subject={editTarget ? editTarget.subject : ""}
        onClose={() => setEditTarget(null)}
      />
    </React.Fragment>
  );
};

export default EntityScreen;
