import React, { FC, useEffect, useState } from "react";
import {
  Input,
  Button,
  Modal,
  Row,
  Col,
  Collapse,
  DatePicker,
  Tag,
  Checkbox,
  Tabs,
} from "antd";
import _ from "lodash";
import { useDispatch } from "react-redux";
import { useSelector } from "react-redux";
import { RootState } from "reducers/rootReducer";
import { Form, Select } from "antd";
import { SocketTopics } from "constants/enums";
import LocationInput from "../../../../../common/LocationInput";
import TimeInput from "../../../../../common/TimeInput";
import PhoneInput from "react-phone-number-input";
import { pushNotification } from "utils/notifications";
import { dateToCron, generateUUID, cronToDate } from "utils/appUtil";
import useSocketActions from "../../../../../hooks/socketActions";
import { ExtendedBioTopics, UserTopics } from "constants/enums";
import {
  getAdminRolesTopic,
  getProjectsSubscriptionTopic,
  getProjectsRequestPublishTopic,
  getCustomUpdateSubscriptionTopic,
  getCustomUpdateRequestPublishTopic,
} from "hooks/MQTTConstants";
import { wrapRequestPayload } from "../../../../../helpers/request/RequestPayload";

import {
  DeleteOutlined,
  CloseCircleOutlined,
  PlusOutlined,
} from "@ant-design/icons";
import moment, { Moment } from "moment";

const { Panel } = Collapse;

interface LocationOption {
  location?: string;
  time?: string;
  days?: string[];
  timeWindow?: number | "custom";
  customTimeWindow?: number;
}

interface StudentLocationInputProps {
  value?: LocationOption[];
  keyPrefix?: string;
  onChange?: (locations: LocationOption[]) => void;
}

interface HolidaySelectorProps {
  value?: Moment[];
  onChange?: (dates: Moment[]) => void;
}

const { TabPane } = Tabs;

const EditStudentModal: FC<{
  onClose: () => void;
  socket?: ISocket;
  student?: any;
  onAdd?: () => void;
  userRole?: any;
}> = (props) => {
  const { onClose, socket, student, onAdd, userRole } = props;
  const [isModalVisible, setIsModalVisible] = useState(true);
  const [registerForm] = Form.useForm();
  const [error, setError] = useState<string>("");
  const [saving, setSaving] = useState(false);
  const [activeTab, setActiveTab] = useState("1");
  const { projects, encrypted_token } = useSelector(
    (state: RootState) => state.auth
  );
  const { updateUserRequestPayloadV2 } = useSocketActions();

  const handleCancel = () => {
    setIsModalVisible(false);
    onClose && onClose();
  };

  useEffect(() => {
    if (student?.schoolBus) {
      let locationFormValues = {};
      const pickup = [],
        dropoff = [],
        holidays = [];
      Object.values(student?.schoolBus?.pickupLocationList || {})?.map(
        (location: any) => {
          const { date, daysOfWeek } = cronToDate(location?.condition?.cron);
          const formattedLocation = {
            location: {
              label: location?.location?.attributes?.address,
              value: {
                description: location?.location?.attributes?.address,
                place_id: "",
                coordinates: location?.location?.coordinates,
                attributes: location?.location?.attributes,
              },
            },
            // timeWindow: location?.condition?.timeWindow,
            // time: date,
            days: daysOfWeek,
          };
          pickup.push(formattedLocation);
          locationFormValues = {
            ...locationFormValues,
            [`location-Pickup-${pickup.length - 1}`]:
              formattedLocation.location,
            // [`time-Pickup-${pickup.length - 1}`]: formattedLocation.time,
            [`days-Pickup-${pickup.length - 1}`]: formattedLocation.days,
            // [`timeWindow-Pickup-${pickup.length - 1}`]:
            //   formattedLocation.timeWindow,
          };
        }
      );
      Object.values(student?.schoolBus?.dropoffLocationList || {})?.map(
        (location: any) => {
          const { date, daysOfWeek } = cronToDate(location?.condition?.cron);
          const formattedLocation = {
            location: {
              label: location?.location?.attributes?.address,
              value: {
                description: location?.location?.attributes?.address,
                place_id: "",
                coordinates: location?.location?.coordinates,
                attributes: location?.location?.attributes,
              },
            },
            // timeWindow: location?.condition?.timeWindow,
            // time: date,
            days: daysOfWeek,
          };
          dropoff.push(formattedLocation);
          locationFormValues = {
            ...locationFormValues,
            [`location-Dropoff-${dropoff.length - 1}`]:
              formattedLocation.location,
            // [`time-Dropoff-${dropoff.length - 1}`]: formattedLocation.time,
            [`days-Dropoff-${dropoff.length - 1}`]: formattedLocation.days,
            // [`timeWindow-Dropoff-${dropoff.length - 1}`]:
            //   formattedLocation.timeWindow,
          };
        }
      );
      Object.values(student?.schoolBus?.holidays || {})?.map((holiday: any) => {
        holidays.push(moment(holiday?.timestamp));
      });
      registerForm.setFieldsValue({
        pickup,
        dropoff,
        holidays,
        ...locationFormValues,
        emergency: student?.schoolBus?.emergency,
        rfidNumber: student?.schoolBus?.rfidNumber,
        preferences: student?.schoolBus?.preferences,
      });
    }
  }, []);

  const onSubmitHandler = async (values: any) => {
    console.log("values", values);
    let pickupLocationList = values?.pickup
      ?.map((x) => {
        return {
          locationType: "pickup",
          location: {
            coordinates: x?.location?.value?.coordinates,
            attributes: x?.location?.value?.attributes,
          },
          condition: {
            cron: dateToCron(new Date(), x?.days),
            validity: -1,
            // timeWindow: x?.timeWindow,
          },
        };
      })
      ?.reduce((acc, item, index) => {
        const id = generateUUID();
        acc[id] = { locationId: id, ...item };
        return acc;
      }, {} as { [key: string]: any });
    let dropoffLocationList = values?.dropoff
      ?.map((x) => {
        return {
          locationType: "dropoff",
          location: {
            coordinates: x?.location?.value?.coordinates,
            attributes: x?.location?.value?.attributes,
          },
          condition: {
            cron: dateToCron(new Date(), x?.days),
            validity: -1,
            // timeWindow: x?.timeWindow,
          },
        };
      })
      ?.reduce((acc, item, index) => {
        const id = generateUUID();
        acc[id] = { locationId: id, ...item };
        return acc;
      }, {} as { [key: string]: any });
    const holidays = values?.holidays?.reduce((acc, item, index) => {
      const timestamp = item.toDate().getTime();
      acc[timestamp] = {
        timestamp,
        type: "emergency",
      };
      return acc;
    }, {} as { [key: string]: any });
    setSaving(true);
    console.log("student here", student);

    await updateUser(student?.id, projects?.userServiceId, {
      pickupLocationList,
      dropoffLocationList,
      holidays,
      emergency: values?.emergency,
      preferences: values?.preferences,
      rfidNumber: values?.rfidNumber,
    });
    console.log("request", {
      // locationList,
      pickupLocationList,
      dropoffLocationList,
      holidays,
      emergency: values?.emergency,
      preferences: values?.preferences,
    });
    pushNotification(
      "User updated successfully",
      "success",
      "TOP_CENTER",
      3000
    );
    setSaving(false);
    onAdd();
  };

  const updateUser = async (userId, serviceId, updateData) => {
    return new Promise((resolve, reject) => {
      const {
        pickupLocationList,
        dropoffLocationList,
        holidays,
        emergency,
        preferences,
        rfidNumber,
      } = updateData;
      const updatedUserData = [];
      if (pickupLocationList) {
        updatedUserData.push({
          op: "add",
          path: "/info/schoolBus/pickupLocationList",
          value: pickupLocationList,
        });
      }
      if (dropoffLocationList) {
        updatedUserData.push({
          op: "add",
          path: "/info/schoolBus/dropoffLocationList",
          value: dropoffLocationList,
        });
      }
      if (holidays) {
        updatedUserData.push({
          op: "add",
          path: "/info/schoolBus/holidays",
          value: holidays,
        });
      }
      if (emergency) {
        updatedUserData.push({
          op: "add",
          path: "/info/schoolBus/emergency",
          value: emergency,
        });
      }
      if (preferences) {
        updatedUserData.push({
          op: "add",
          path: "/info/schoolBus/preferences",
          value: preferences,
        });
      }
      if (rfidNumber) {
        updatedUserData.push({
          op: "add",
          path: "/info/schoolBus/rfidNumber",
          value: rfidNumber,
        });
      }
      console.log("update user data", updatedUserData);

      // socket.publishToServiceIdSurvey(
      //   SocketTopics.SurveyTopics,
      //   UserTopics.UpdateUser,
      //   updateUserRequestPayloadV2(userId, updatedUserData),
      //   ExtendedBioTopics.UpdateUserBio,
      //   serviceId
      // );
      // socket.subscribeToSurvey(
      //   SocketTopics.SurveyTopics,
      //   ExtendedBioTopics.UpdateUserBio,
      //   (response) => {
      //     resolve(response);
      //   }
      // );

      // console.log('test', {
      //   objectId: userId,
      //   changes: updatedUserData
      // });

      socket.publishToEvent(
        SocketTopics.PublishPageTopics,
        getCustomUpdateRequestPublishTopic(encrypted_token?.connectionId),
        wrapRequestPayload({
          objectId: userId,
          changes: updatedUserData,
        })
      );

      socket.subscribeToEvent(
        SocketTopics.SubscribePageTopics,
        getCustomUpdateSubscriptionTopic(encrypted_token?.connectionId),
        (response) => {
          //   setSaving(false);
          console.log("update response", response);
          // pushNotification(
          //   "Timesheet saved successfully",
          //   "success",
          //   "TOP_CENTER",
          //   1000
          // );
          resolve(response);
        }
      );
    });
  };

  const daysOfWeek = [
    "Monday",
    "Tuesday",
    "Wednesday",
    "Thursday",
    "Friday",
    "Saturday",
    "Sunday",
  ];

  const timeWindowOptions = [
    { label: "± 10 mins", value: 10 },
    { label: "± 15 mins", value: 15 },
    { label: "± 20 mins", value: 20 },
    { label: "± 30 mins", value: 30 },
    { label: "Custom", value: "custom" },
  ];

  const StudentLocationInput: React.FC<StudentLocationInputProps> = ({
    value,
    keyPrefix = "Pickup",
    onChange,
  }) => {
    const [options, setOptions] = useState<LocationOption[]>(
      value || [
        {
          location: undefined,
          // time: undefined,
          days: undefined,
          // timeWindow: 10,
        },
      ]
    );

    useEffect(() => {
      if (value) {
        setOptions(value);
      }
    }, [value]);

    const addLocation = () => {
      setOptions((prevOptions) => [
        ...prevOptions,
        {
          location: undefined,
          // time: undefined,
          days: undefined,
          // timeWindow: 10,
        },
      ]);
    };

    const deleteLocation = (index: number) => {
      setOptions((prevOptions) => prevOptions.filter((_, i) => i !== index));
    };

    const handleLocationChange = (
      index: number,
      field: keyof LocationOption,
      newValue: any
    ) => {
      const updatedOptions = options.map((option, i) =>
        i === index ? { ...option, [field]: newValue } : option
      );
      // setOptions(updatedOptions);
      onChange?.(updatedOptions);
    };

    const getSelectedDays = (): string[] => {
      return options.reduce<string[]>((selectedDays, option) => {
        return option.days ? [...selectedDays, ...option.days] : selectedDays;
      }, []);
    };

    const LocationTimeInput = (props) => {
      const { value, onChange } = props;
      return (
        <TimeInput
          placeholder={`Select Time`}
          value={value ? moment(value).format("HH:mm") : undefined}
          onChange={onChange}
        />
      );
    };

    return (
      <>
        {options.map((option, index) => {
          const availableDays = daysOfWeek.filter(
            (day) =>
              !getSelectedDays().includes(day) || option.days?.includes(day)
          );
          return (
            <Row className="mb-3" key={`location-${index}`}>
              <Col span={22} className="pr-2">
                <Form.Item
                  label={`${keyPrefix} Location`}
                  name={`location-${keyPrefix}-${index}`}
                  rules={[{ required: true, message: "Location is required" }]}
                >
                  <LocationInput
                    placeholder={`Enter Location`}
                    onChange={(location) =>
                      handleLocationChange(index, "location", location)
                    }
                  />
                </Form.Item>
              </Col>
              <Col
                span={2}
                className="t-right d-flex justify-content-end align-items-end"
              >
                <Button
                  type="link"
                  className="beam-btn orange-btn bordered"
                  onClick={() => deleteLocation(index)}
                >
                  <DeleteOutlined />
                </Button>
              </Col>

              {/* <Col span={24} className="mt-3">
                <Form.Item
                  label={`${keyPrefix} Time`}
                  name={`time-${keyPrefix}-${index}`}
                  rules={[{ required: true, message: "Time is required" }]}
                >
                  <LocationTimeInput
                    onChange={(time) => {
                      handleLocationChange(index, "time", time);
                    }}
                  />
                </Form.Item>
              </Col> */}

              <Col span={24} className="mt-3">
                <Form.Item
                  label={`${keyPrefix} Days`}
                  name={`days-${keyPrefix}-${index}`}
                  rules={[
                    { required: true, message: "Days selection is required" },
                  ]}
                >
                  <Select
                    placeholder={`Select Days`}
                    mode="multiple"
                    value={option.days}
                    onChange={(days) =>
                      handleLocationChange(index, "days", days)
                    }
                    style={{ width: "100%" }}
                  >
                    {availableDays.map((day) => (
                      <Select.Option key={day} value={day}>
                        {day}
                      </Select.Option>
                    ))}
                  </Select>
                </Form.Item>
              </Col>

              {/* <Col span={24} className="mt-3">
                <Form.Item
                  label="Time Window"
                  name={`timeWindow-${keyPrefix}-${index}`}
                  rules={[
                    { required: true, message: "Time window is required" },
                  ]}
                >
                  <Select
                    placeholder="Select Time Window"
                    value={option.timeWindow}
                    onChange={(value) =>
                      handleLocationChange(index, "timeWindow", value)
                    }
                    style={{ width: "100%" }}
                  >
                    {timeWindowOptions.map((option) => (
                      <Select.Option key={option.value} value={option.value}>
                        {option.label}
                      </Select.Option>
                    ))}
                  </Select>
                </Form.Item>
              </Col>

              {option.timeWindow === "custom" && (
                <Col span={24} className="mt-3">
                  <Form.Item
                    label="Custom Time Window"
                    name={`customTimeWindow-${index}`}
                    rules={[
                      {
                        required: true,
                        message: "Custom time window is required",
                      },
                    ]}
                  >
                    <Input
                      className="beam-input"
                      placeholder="Enter custom time window (in mins)"
                      value={option.customTimeWindow}
                      onChange={(e) =>
                        handleLocationChange(
                          index,
                          "customTimeWindow",
                          e.target.value
                        )
                      }
                      style={{ width: "100%" }}
                      min={1}
                    />
                  </Form.Item>
                </Col>
              )} */}
            </Row>
          );
        })}
        <Row className="mt-3 mb-3">
          <Col span={24} className="d-flex justify-content-end align-items-end">
            <Button
              type="link"
              className="beam-btn yellow-btn bordered"
              onClick={() => addLocation()}
            >
              {/* <PlusOutlined /> */}
              Add
            </Button>
          </Col>
        </Row>
      </>
    );
  };

  const HolidaySelector: React.FC<HolidaySelectorProps> = ({
    value = [],
    onChange,
  }) => {
    const handleTagClose = (date: Moment) => {
      const updatedDates = value?.filter((d) => !d.isSame(date, "day"));
      onChange?.(updatedDates);
    };
    const handleAddDate = (date: Moment | null) => {
      if (date && !value?.find((d) => d.isSame(date, "day"))) {
        const updatedDates = [...value, date];
        onChange?.(updatedDates);
      }
    };
    return (
      <div>
        <label className="ant-form-item-required">{`Holidays`}</label>
        <DatePicker
          onChange={handleAddDate}
          disabledDate={(date) =>
            value?.some((selectedDate) => selectedDate?.isSame(date, "day"))
          }
          placeholder="Select date"
        />
        <div style={{ marginTop: "16px" }} className="custom-tag">
          {value?.map((date) => (
            <Tag
              key={date.toISOString()}
              className="tag-item"
              closable
              onClose={() => handleTagClose(date)}
              closeIcon={<CloseCircleOutlined />}
            >
              {date.format("YYYY-MM-DD")}
            </Tag>
          ))}
        </div>
      </div>
    );
  };

  const EmergencyContactInfo: React.FC<any> = ({ value, onChange }) => {
    return (
      <React.Fragment>
        <Form.Item label="Emergency Contact Name" required>
          <Input
            placeholder="Enter contact name"
            value={value?.name}
            onChange={(e) => onChange?.({ ...value, name: e.target.value })}
          />
        </Form.Item>

        <Form.Item label="Emergency Contact Number" required className="mt-3">
          <PhoneInput
            defaultCountry="US"
            placeholder="Enter contact number"
            value={value?.phoneNumber}
            onChange={(e) => onChange?.({ ...value, phoneNumber: e })}
          />
        </Form.Item>

        <Form.Item label="Relationship to Student" required className="mt-3">
          <Select
            placeholder="Select relationship"
            value={value?.relationship}
            onChange={(relationship) => onChange?.({ ...value, relationship })}
          >
            <Select.Option value="Mother">Mother</Select.Option>
            <Select.Option value="Father">Father</Select.Option>
            <Select.Option value="Relative">Relative</Select.Option>
            <Select.Option value="Guardian">Guardian</Select.Option>
            <Select.Option value="Other">Other</Select.Option>
          </Select>
        </Form.Item>
      </React.Fragment>
    );
  };

  const AdditionalConstraints: React.FC<any> = ({ value, onChange }) => {
    return (
      <React.Fragment>
        {/* <Form.Item label="Preferred Bus Type" required>
          <Select
            placeholder="Select preferred bus type"
            value={value?.busType}
            onChange={(busType) => onChange?.({ ...value, busType })}
          >
            <Select.Option value="Regular Bus">Regular Bus</Select.Option>
            <Select.Option value="Small Bus">Small Bus</Select.Option>
          </Select>
        </Form.Item> */}

        <Form.Item>
          <Checkbox
            checked={value?.hasSpecialNeeds}
            onChange={(e) =>
              onChange?.({ ...value, hasSpecialNeeds: e.target.checked })
            }
          >
            Special Needs Requirements
          </Checkbox>

          {value?.hasSpecialNeeds && (
            <>
              <Input
                placeholder="Specify special needs"
                value={value?.specialNeedsInfo}
                onChange={(e) =>
                  onChange?.({ ...value, specialNeedsInfo: e.target.value })
                }
                className="mt-2"
              />
              <Checkbox.Group
                className="mt-3"
                options={[
                  { label: "Wheelchair Access", value: "Wheelchair Access" },
                  { label: "Assistance Needed", value: "Assistance Needed" },
                ]}
                value={value?.specialNeeds}
                onChange={(checkedValues) => {
                  onChange?.({ ...value, specialNeeds: checkedValues });
                }}
              />
            </>
          )}
        </Form.Item>

        <Form.Item label="Safety Requirements" className="mt-3">
          <Checkbox.Group
            options={[
              { label: "Bus Monitor Required", value: "Bus Monitor Required" },
              { label: "Seat Belt Required", value: "Seat Belt Required" },
            ]}
            value={value?.safetyRequirements}
            onChange={(checkedValues) => {
              onChange?.({ ...value, safetyRequirements: checkedValues });
            }}
          />
        </Form.Item>
      </React.Fragment>
    );
  };

  return (
    <Modal
      title={`Edit (${student?.live?.beamIds?.[0] || "student"})`}
      visible={isModalVisible}
      onCancel={handleCancel}
      width="800px"
      className="beam-modal"
      footer={[]}
      destroyOnClose={true}
    >
      <Form
        className="auth-form"
        name="register-form"
        id="register-form"
        layout="vertical"
        form={registerForm}
        onFinish={onSubmitHandler}
        requiredMark={false}
      >
        <div className="main-cards mt-3">
          <Tabs
            defaultActiveKey="1"
            type="line"
            onChange={(active) => {
              setActiveTab(active);
            }}
          >
            {/* Tab 1 */}
            <TabPane tab="Pickup" key="1">
              {activeTab === "1" && (
                <Form.Item name="pickup">
                  <StudentLocationInput keyPrefix="Pickup" />
                </Form.Item>
              )}
            </TabPane>

            {/* Tab 2 */}
            <TabPane tab="Dropoff" key="2">
              {activeTab === "2" && (
                <Form.Item name="dropoff">
                  <StudentLocationInput keyPrefix="Dropoff" />
                </Form.Item>
              )}
            </TabPane>

            {/* Tab 3 */}
            <TabPane tab="Holidays" key="3">
              {activeTab === "3" && (
                <Form.Item name="holidays">
                  <HolidaySelector />
                </Form.Item>
              )}
            </TabPane>

            <TabPane tab="Emergency Contact" key="4">
              {activeTab === "4" && (
                <Form.Item name="emergency">
                  <EmergencyContactInfo />
                </Form.Item>
              )}
            </TabPane>

            <TabPane tab="Preferences" key="5">
              {activeTab === "5" && (
                <Form.Item name="preferences">
                  <AdditionalConstraints />
                </Form.Item>
              )}
            </TabPane>

            {userRole === "admin" && (
              <TabPane tab="RFID" key="6">
                {activeTab === "6" && (
                  <Form.Item
                    label="RFID Number"
                    name="rfidNumber"
                    //  rules={[
                    //    { required: true, message: "Please input the license number" },
                    //  ]}
                  >
                    <Input placeholder="Enter RFID Number" />
                  </Form.Item>
                )}
              </TabPane>
            )}
          </Tabs>
        </div>

        <Row className="action-grp mt-3">
          <Col span={24}>
            <Form.Item>
              <Button
                className="beam-btn green-btn cover w-full"
                loading={saving}
                type="primary"
                htmlType="submit"
                onClick={() => setError("")}
              >
                Save
              </Button>
            </Form.Item>
          </Col>
        </Row>
      </Form>
    </Modal>
  );
};

export default EditStudentModal;
