import React, { useState } from "react";
import { Button, Checkbox, Dropdown } from "antd";
import { SettingOutlined } from "@ant-design/icons";

interface Props {
  columns: { key: string; title: any }[];
  visibleKeys: string[];
  onChange: (keys: string[]) => void;
  onReset: () => void;
}

const ColumnVisibilityDropdown = ({ columns, visibleKeys, onChange, onReset }: Props) => {
  const [open, setOpen] = useState(false);

  const menu = (
    <div style={{ padding: 10, backgroundColor: "white" }} onClick={(e) => e.stopPropagation()}>
      <Checkbox.Group value={visibleKeys} onChange={(keys) => onChange(keys as string[])}>
        {columns.map((col) => (
          <div key={col.key} style={{ marginBottom: 8 }}>
            <Checkbox value={col.key}>{col.title}</Checkbox>
          </div>
        ))}
      </Checkbox.Group>
      <div style={{ marginTop: 10, textAlign: "right" }}>
        <Button size="small" onClick={onReset}>
          Reset
        </Button>
      </div>
    </div>
  );

  return (
    <Dropdown overlay={menu} trigger={["click"]} visible={open} onVisibleChange={setOpen}>
      <Button className="mx-dash-toolbar__btn" icon={<SettingOutlined />} aria-label="Columns" />
    </Dropdown>
  );
};

export default ColumnVisibilityDropdown;
