  const setLastLocation = (data: any): any => {
    const filtered = data.channels.filter((x) => {
      return x.timestamp && x.value;
    });
    if (filtered.length === 0) return;
    const latest = filtered.reduce(function (prev, current) {
      return prev.timestamp > current.timestamp ? prev : current;
    });
    // const segments = latest.objectId.split(":");
    // const lastLocation = state.lastLocation;
    // lastLocation[action.payload.id] = {
    //   userId: action.payload.id,
    //   timestamp: latest.timestamp,
    //   location: decodeGeoHash(latest.value),
    //   objectId: latest.objectId,
    //   iotUdid: segments?.[1],
    //   iotUserId: segments?.[2],
    //   imei: `${process.env.REACT_APP_ECO_SYSTEM}/device/${segments?.[1]}/user/${action.payload.id}/iotAppend/${segments?.[2]}/gps`,
    // };

    const location = decodeGeoHash(latest.value);
    return {
      ...latest,
      location,
    };
  };

