import React, { FC, useEffect, useMemo, useRef, useState } from "react";
import { Alert, Checkbox, Form, Input, Radio } from "antd";
import { useSelector } from "react-redux";
import { RootState } from "reducers/rootReducer";
import TimeInput from "../../../../../common/TimeInput";
import ResponderInput from "../../../../../common/ResponderInput";
import { pushNotification } from "utils/notifications";
import { FormModal, FormSection } from "../../common/ui";
import {
  CHANNELS,
  Channel,
  DAYS,
  NotificationRecord,
  SCHEDULE_TIME_FORMAT,
  buildCron,
  parseScheduleTime,
  previewSentence,
  sortDays,
  useScheduleApi,
} from "./notificationUtils";
import "./Scheduler.scss";

const NAME_MAX = 80;
// Far-future end date the scheduler uses to expire a schedule; kept as before.
const SCHEDULE_TO = 4920566400000;

/** ResponderInput's multi-select value: `{ type, responders, values }`. */
interface DriverValue {
  type?: string;
  responders?: { id: string; beamId?: string; name?: string }[];
  values?: string[];
}

/**
 * ResponderInput only rebuilds `responders` from the options it has loaded,
 * so drivers of a saved notification that aren't in the loaded page would be
 * silently dropped on the next change. Keep them from the previous value.
 */
const DriverSelect = ({
  value,
  onChange,
  adminRoles,
}: {
  value?: DriverValue;
  onChange?: (value: DriverValue) => void;
  adminRoles?: any;
}) => (
  <ResponderInput
    multiple
    placeholder="Select drivers"
    adminRoles={adminRoles}
    value={value}
    onChange={(next: DriverValue) => {
      const known = new Map<string, any>();
      [...(value?.responders || []), ...(next?.responders || [])].forEach((r) => {
        if (!r) return;
        known.set(`${r.id}`, r);
        // Before the options load, the select's values are beamIds.
        if (r.beamId) known.set(`${r.beamId}`, r);
      });
      const responders = Array.from(
        new Map(
          (next?.values || [])
            .map((v) => known.get(`${v}`))
            .filter(Boolean)
            .map((r) => [`${r.id}`, r] as [string, any])
        ).values()
      );
      onChange?.({ ...next, responders, values: responders.map((r) => `${r.id}`) });
    }}
  />
);

/** Seven toggle chips backed by a Checkbox.Group (stores full day names). */
const DayPicker = ({
  value,
  onChange,
}: {
  value?: string[];
  onChange?: (value: string[]) => void;
}) => (
  <div className="mx-notification-days">
    <Checkbox.Group value={value} onChange={(v) => onChange?.(sortDays(v as string[]))}>
      {DAYS.map((d) => (
        <Checkbox key={d.name} value={d.name} className="mx-notification-days__chip">
          {d.short}
        </Checkbox>
      ))}
    </Checkbox.Group>
    <div className="mx-notification-days__presets">
      <a onClick={() => onChange?.(DAYS.slice(0, 5).map((d) => d.name))}>Weekdays</a>
      <a onClick={() => onChange?.(DAYS.map((d) => d.name))}>Every day</a>
      <a onClick={() => onChange?.([])}>Clear</a>
    </div>
  </div>
);

const EditSchedulerModal: FC<{
  onClose: () => void;
  socket?: ISocket;
  /** `{}` to create, or `{ scheduleId, data }` to edit. */
  student?: Partial<NotificationRecord>;
  adminRoles?: any;
  onAdd?: () => void;
  /** userId -> display name, to label saved drivers before the picker loads. */
  driverNames?: Record<string, string>;
}> = ({ onClose, student, adminRoles, onAdd, driverNames }) => {
  const [form] = Form.useForm();
  const [saving, setSaving] = useState(false);
  const { projects } = useSelector((state: RootState) => state.auth);
  const { createSchedule, updateSchedule } = useScheduleApi();
  const mounted = useRef(true);
  useEffect(
    () => () => {
      mounted.current = false;
    },
    []
  );

  const isEdit = !!student?.scheduleId;
  const timezone = Intl.DateTimeFormat().resolvedOptions().timeZone;

  const initialValues = useMemo(() => {
    const data = student?.data;
    if (!isEdit || !data) return { notificationType: "push" };
    const saved = Object.values(data.drivers || {});
    return {
      name: data.name,
      notificationType: data.notificationType,
      daysOfTheWeek: sortDays(data.daysOfTheWeek),
      // Unparseable legacy times are left empty so the time must be re-picked.
      time: parseScheduleTime(data.scheduleTime)?.format(SCHEDULE_TIME_FORMAT),
      drivers: saved.length
        ? {
            type: "responder",
            responders: saved.map((x: any) => ({
              id: x?.userId,
              beamId: x?.beamId,
              name: driverNames?.[`${x?.userId}`],
            })),
            values: saved.map((x: any) => x?.userId),
          }
        : undefined,
    };
    // Seeded once; the modal is remounted per record.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  const channel = Form.useWatch("notificationType", form) as Channel | undefined;
  const days = Form.useWatch("daysOfTheWeek", form) as string[] | undefined;
  const time = Form.useWatch("time", form) as string | undefined;
  const drivers = Form.useWatch("drivers", form) as DriverValue | undefined;
  const preview = previewSentence(channel, days, time, drivers?.responders?.length || 0);

  const onFinish = async (values: any) => {
    const { name, daysOfTheWeek, notificationType, time, drivers } = values;
    const requestData = {
      name: `${name}`.trim(),
      daysOfTheWeek: sortDays(daysOfTheWeek),
      scheduleTime: time,
      notificationType,
      drivers: (drivers?.responders || []).reduce((acc, x) => {
        acc[x?.id] = { userId: x?.id, beamId: x?.beamId };
        return acc;
      }, {} as { [key: string]: any }),
      timezone,
      cudbServiceId: projects?.userServiceId,
    };
    const cron = buildCron(time, requestData.daysOfTheWeek, timezone);

    setSaving(true);
    try {
      if (!isEdit) {
        const created = await createSchedule({
          cron,
          topic: `${process.env.REACT_APP_ECO_SYSTEM}/service/scheduler-service/service/dps/sendReminderNotification`,
          data: requestData,
          info: {},
          to: SCHEDULE_TO,
        });
        const objectId = created.ok ? created.response?.data?.id?.toString() : undefined;
        if (!objectId) {
          pushNotification("Couldn't create the notification, please try again", "error", "TOP_CENTER", 3000);
          return;
        }
        // Partitions are what the list query (and org scoping) filters on.
        const tagged = await updateSchedule({
          objectId,
          changes: [
            {
              op: "replace",
              path: "/partitions",
              value: [`org:${projects?.userServiceId}`, "type:notification"],
            },
          ],
        });
        if (!tagged.ok) {
          pushNotification(
            "The notification was created but may not show in this list. Please check again shortly.",
            "error",
            "TOP_CENTER",
            4000
          );
        } else {
          pushNotification("Notification created", "success", "TOP_CENTER", 2000);
        }
      } else {
        const updated = await updateSchedule({
          objectId: student?.scheduleId?.toString(),
          changes: [
            { op: "replace", path: "/cron", value: cron },
            { op: "replace", path: "/data", value: requestData },
          ],
        });
        if (!updated.ok) {
          pushNotification("Couldn't save the notification, please try again", "error", "TOP_CENTER", 3000);
          return;
        }
        pushNotification("Notification saved", "success", "TOP_CENTER", 2000);
      }
      onAdd?.();
    } finally {
      if (mounted.current) setSaving(false);
    }
  };

  return (
    <FormModal
      open
      title={isEdit ? `Edit "${student?.data?.name || "notification"}"` : "New notification"}
      subtitle="A recurring reminder sent to drivers about their upcoming jobs."
      onCancel={() => !saving && onClose()}
      onSubmit={form.submit}
      saving={saving}
      okText={isEdit ? "Save" : "Create notification"}
      width={640}
    >
      <div className="mx-notification-form">
        <Form
          form={form}
          layout="vertical"
          requiredMark={false}
          initialValues={initialValues}
          onFinish={onFinish}
          scrollToFirstError
        >
          <FormSection index={1} title="What" description="Name it and choose how drivers are reminded.">
            <Form.Item
              label="Name"
              name="name"
              validateFirst
              rules={[
                { required: true, whitespace: true, message: "Give the notification a name" },
                { max: NAME_MAX, message: `Keep it under ${NAME_MAX} characters` },
              ]}
            >
              <Input placeholder="e.g. Morning job reminder" autoFocus={!isEdit} />
            </Form.Item>
            <Form.Item
              label="Channel"
              name="notificationType"
              rules={[{ required: true, message: "Choose a channel" }]}
            >
              <Radio.Group optionType="button" buttonStyle="solid">
                {(Object.keys(CHANNELS) as Channel[]).map((key) => (
                  <Radio.Button key={key} value={key}>
                    {CHANNELS[key].label}
                  </Radio.Button>
                ))}
              </Radio.Group>
            </Form.Item>
          </FormSection>

          <FormSection index={2} title="When" description={`Times are in your time zone (${timezone}).`}>
            <Form.Item
              label="Days"
              name="daysOfTheWeek"
              rules={[{ required: true, type: "array", min: 1, message: "Pick at least one day" }]}
            >
              <DayPicker />
            </Form.Item>
            <Form.Item label="Time" name="time" rules={[{ required: true, message: "Pick a time" }]}>
              <TimeInput placeholder="Select time" />
            </Form.Item>
          </FormSection>

          <FormSection index={3} title="Who" description="Drivers who receive this reminder.">
            <Form.Item
              label="Drivers"
              name="drivers"
              rules={[
                {
                  validator: (_, value: DriverValue) =>
                    value?.responders?.length
                      ? Promise.resolve()
                      : Promise.reject(new Error("Select at least one driver")),
                },
              ]}
            >
              <DriverSelect adminRoles={adminRoles} />
            </Form.Item>
          </FormSection>

          <Alert
            className="mx-notification-form__preview"
            type={preview ? "info" : "warning"}
            showIcon
            message={preview || "Choose a channel, days and a time to see when this is sent."}
          />
        </Form>
      </div>
    </FormModal>
  );
};

export default EditSchedulerModal;
