import React, { useEffect, useState } from 'react';
import { Card, Button, Col, Divider, Row, Typography, Tag } from 'antd';
import { CheckCircleOutlined } from '@ant-design/icons';
import './PricingPlans.scss';

const { Title, Text } = Typography;

const PricingPlans = ({onSelect, pricingPlans, data}) => {
  const [selectedPlan, setSelectedPlan] = useState<string>(data || '');
  const [planList, setPlanList] = useState<any[]>(pricingPlans || []);


  useEffect(()=>{
    if(pricingPlans){
      const filteredPlans = pricingPlans?.filter(plan=> plan.features.length && plan?.title );
      setPlanList([...filteredPlans]);
    }
  }, pricingPlans);

  const handleSelectPlan = (planTitle: string) => {
    setSelectedPlan(planTitle);
  };

  const onSelectPlan = (plan)=>{
    onSelect(plan);
  }

  return (
    <div className="pricing-plans">
      <div className="pricing-header">
        <Title level={1}>Pricing</Title>
        <Text> <strong>Choose a plan to schdule your Coach !</strong></Text>
      </div>
      <div style={{display: 'flex', placeContent:'center'}}>
      {
          planList?.length === 0 &&  <Text>No Plan available</Text>
        }
      { planList?.length !==0 && <Row className="pricing" gutter={[24, 24]} justify="center">
        {planList.map((plan, index) => (
          <Col xs={24} sm={12} md={8} key={`${plan.title}-${index}`} style={{  width: '150%', minWidth: '230px' }}>
            <div style={{ position: 'relative', display: 'inline-block', width: '100%', minWidth: '160px' }}>
              {plan?.recommended && (
                <Tag
                  color="#FBAE16"
                  style={{
                    position: 'absolute',
                    top: '10px',
                    left: '10px',
                    zIndex: 1,
                    display: 'flex',
                    alignItems: 'center',
                    gap: '4px',
                  }}
                >
                  <CheckCircleOutlined /> Recommended
                </Tag>
              )}
              <Card
                bordered={selectedPlan === plan.title}
                className={`pricing-card ${selectedPlan === plan.title ? 'selected' : ''}`}
                title={<Title level={3}>{plan.title}</Title>}
                onClick={() => handleSelectPlan(plan.title)}
                hoverable
                style={{
                  display: 'flex',
                  flexDirection: 'column',
                  justifyContent: 'space-between',
                  height: '100%',
                  // maxHeight: '700px',
                  minHeight: '450px', // Ensures all cards have a minimum height
                  minWidth: '180px'
                }}
              >
                <div>
                  <Title level={2}>${plan?.price}</Title>
                  {/* <Text>/ per month</Text> */}
                  <Divider />
                  <ul className="plan-features"
                      style={{
                        maxHeight: '350px', 
                        overflowY: 'auto', 
                        padding: '30px 10px 30px',
                      }}
                  >
                    {plan.features.map((item, index) => (
                      <li key={`${item}-${index}`}>
                        <CheckCircleOutlined
                          style={{
                            color: selectedPlan === plan.title ? '#FBAE16': '#1890ff',
                            marginRight: '8px',
                          }}
                        />{' '}
                        {item}
                      </li>
                    ))}
                  </ul>
                </div>
                <div style={{ display: 'flex', justifyContent: 'center', marginTop: '20px' }}>
                  <Button onClick={()=> onSelectPlan(plan.title)} className="beam-btn green-btn cover w-5">Schedule</Button>
                </div>
              </Card>
            </div>
          </Col>
        ))}
      </Row>}
      </div>
   
    </div>
  );
};

export default PricingPlans;

