import React from "react";
import { Row, Col, Button } from "antd";
import { useDispatchPanel } from "../context";

const DriversList: React.FC = () => {
  const { selectedResponders } = useDispatchPanel();

  if (!(selectedResponders && selectedResponders.length > 0)) return null;

  return (
    <Row className="mt-3">
      <Col span={24}>
        <h4>Drivers</h4>
        {selectedResponders.map((responder: any, index: number) => (
          <Row className="responder-item mt-3">
            <Col span={4}>
              <img
                src={`/images/users/user.png`}
                alt=""
                width="50"
                height="50"
              />
            </Col>
            <Col span={8}>
              <h5>{`${responder?.profile?.firstName} ${responder?.profile?.lastName}`}</h5>
              <p>ID: {responder?.beamIds?.[0]}</p>
            </Col>
            <Col span={6}>
              <Button className="beam-btn action-btn">Driver</Button>
            </Col>
            <Col span={6} className="t-right">
              <Button className="beam-btn mr-2">
                <img
                  src={`/images/flag-green.png`}
                  alt=""
                  width="15"
                  height="15"
                />
              </Button>
            </Col>
          </Row>
        ))}
      </Col>
    </Row>
  );
};

export default DriversList;
