import React, { useEffect, useRef, useState } from "react";
import { TimePicker } from "antd";
import moment, { Moment } from "moment";

/**
 * HH:mm TimePicker that accepts typed digits ("900", "0930", "1745") and
 * commits whatever was picked or typed when the panel closes.
 */
const AutoFormatTimePicker = (props: any) => {
  const { value = undefined, onChange, ...rest } = props;
  const wrapperRef = useRef<HTMLDivElement>(null);
  const [open, setOpen] = useState(false);
  const [pendingTime, setPendingTime] = useState<Moment | null>(null);

  const normalizedValue = value ? (moment.isMoment(value) ? value : moment(value)) : null;

  useEffect(() => {
    if (!open || !wrapperRef.current) return;
    const input = wrapperRef.current.querySelector("input") as HTMLInputElement;
    if (!input) return;

    let lastInputValue = input.value;

    const handleInput = (e: Event) => {
      let raw = (e.target as HTMLInputElement).value.replace(/[^\d]/g, "");
      // "900" -> "0900"; "130" stays ambiguous until a 4th digit arrives.
      if (raw.length === 3 && !["0", "1", "2"].includes(raw[0])) raw = `0${raw}`;
      if (raw.length !== 4) return;
      const parsed = moment(`${raw.slice(0, 2)}:${raw.slice(2, 4)}`, "HH:mm", true);
      if (parsed.isValid()) {
        lastInputValue = input.value;
        setPendingTime(parsed);
        onChange?.(parsed);
      }
    };

    // Panel clicks change the input value without firing an input event.
    const checkValueChange = () => {
      if (input.value !== lastInputValue && input.value) {
        const parsed = moment(input.value, "HH:mm", true);
        if (parsed.isValid()) {
          lastInputValue = input.value;
          setPendingTime(parsed);
        }
      }
    };
    const intervalId = setInterval(checkValueChange, 100);
    input.addEventListener("input", handleInput);
    return () => {
      input.removeEventListener("input", handleInput);
      clearInterval(intervalId);
    };
  }, [open, onChange]);

  const commitOnClose = () => {
    const current = normalizedValue?.format("HH:mm");
    if (pendingTime !== null) {
      if (current !== pendingTime.format("HH:mm")) onChange?.(pendingTime);
      return;
    }
    const input = wrapperRef.current?.querySelector("input") as HTMLInputElement;
    const parsed = input?.value ? moment(input.value, "HH:mm", true) : null;
    if (parsed?.isValid() && current !== parsed.format("HH:mm")) onChange?.(parsed);
  };

  return (
    <div ref={wrapperRef}>
      <TimePicker
        {...rest}
        value={normalizedValue}
        format="HH:mm"
        inputReadOnly={false}
        allowClear
        renderExtraFooter={() => null}
        onChange={(time) => {
          setPendingTime(time);
          onChange?.(time);
        }}
        onOpenChange={(isOpen) => {
          if (isOpen) {
            setPendingTime(normalizedValue);
          } else {
            commitOnClose();
            setPendingTime(null);
          }
          setOpen(isOpen);
        }}
      />
    </div>
  );
};

export default AutoFormatTimePicker;
