import { useCallback, useRef } from "react";
import { Button, Row, Col } from "antd";
import {
  MessageOutlined,
  FileSearchOutlined,
  PayCircleOutlined,
} from "@ant-design/icons";
import { ReactSVG } from "react-svg";
import { debounce } from "throttle-debounce";
import { SocketTopics, UserTopics } from "constants/enums";
import {
  getAggregateBdsPublishTopic,
  getAdminRolesTopic,
} from "hooks/MQTTConstants";
import { formatForRedis, popupCenter } from "utils/appUtil";
import { GET_AGGREGATE } from "reducers/reducer";
import { colorRideStatusMapping } from "../constants";
import { wrapRequestPayload } from "../../../../../../helpers/request/RequestPayload";

// All the aggregate/socket queries that feed the dashboard: admin roles, role
// users, area aggregates, single-page refresh, status counts and the main page
// search that builds the table.
export const useDashboardQueries = (d: any) => {
  // Monotonic id per searchPage call so a slow/stale response can never
  // overwrite the table after a newer search has already resolved.
  const searchSeqRef = useRef(0);

  const getPageById = (pageId: any) => {
    if (typeof pageId !== "string") return;
    const pageAggregateRequest = {
      select: {
        index: {
          searchIndex: `${process.env.REACT_APP_ECO_SYSTEM}:pageUpdatedAtIndex`,
          searchQuery: `@pageMembers:{'${d.encryptedTokenRef.current?.userId}'}`,
          searchOptions: "VERBATIM TIMEOUT 10000",
        },
        list: {
          objectIds: [pageId],
        },
        load: {
          persistent: "$.persistent",
          nonpersistent: "$.nonpersistent",
          pageId: "$.objectId",
        },
      },
      filter: {
        expression: "",
      },
    };
    d.dispatch(
      GET_AGGREGATE({
        requestData: pageAggregateRequest,
        callback: (response: any) => {
          // Queue instead of a single state slot: concurrent responses for
          // different pages would otherwise overwrite each other in one batch.
          if (response?.[0]) {
            d.setPageUpdatedQueue((prev: any[]) => [...prev, response[0]]);
          }
        },
      })
    );
  };

  const getPageStatus = () => {
    const expressions = ["!exists(@pageType)"];
    let timeIndex = "";
    if (!d.pageIndex.current.time) {
      const date = new Date();
      date.setHours(0);
      date.setMinutes(1);
      timeIndex += `@createdAt:[${date.getTime()},+inf]`;
    } else {
      timeIndex += d.pageIndex.current.time;
    }

    if (d.pagePaths.current) {
      Object.keys(d.pagePaths.current).map((key) => {
        if (d.pagePaths.current?.[key]) {
          expressions.push(d.pagePaths.current?.[key]);
        }
      });
    }

    const load = {};
    if (d.loadPaths.current) {
      d.loadPaths.current.map((x: any) => {
        load[x.key] = x.value;
      });
    }

    const pageStatusCountRequest = {
      select: {
        index: {
          searchIndex: `${process.env.REACT_APP_ECO_SYSTEM}:page:ride`,
          searchQuery: `@pageMembers:{'${d.encryptedTokenRef?.current?.userId}'}${!d.showHail.current ? "(-@rideType:{hail})" : ""
            }@pageType:{event}${timeIndex}`,
          searchOptions: "VERBATIM TIMEOUT 10000",
        },
        load: {
          profile: "$..profile",
          rideType: "$..profile.type",
          persistent: "$.persistent",
          nonpersistent: "$.nonpersistent",
          pageId: "$.objectId",
          iotAssetConfigId:
            "$.persistent.static.iotAsset.config.iotAssetConfigId",
          createdAt: "$.persistent.static.metadata.createdAt",
          status: "$.nonpersistent.static.live.status.name",
          pageType: "$..pageType",
          ...load,
        },
      },
      groupBy: {
        properties: ["@status"],
        reducers: [
          {
            func: "COUNT",
            arguments: [],
            name: "count",
          },
        ],
      },
      filter: {
        expression: expressions.join("&&"),
      },
    };
    d.dispatch(
      GET_AGGREGATE({
        requestData: pageStatusCountRequest,
        callback: (response: any) => {
          let all = 0;
          let status: any = {
            amber: 0,
            purple: 0,
            red: 0,
            green: 0,
            blue: 0,
            grey: 0,
            black: 0,
            brown: 0,
            aqua: 0,
          };
          response.map((x: any) => {
            status[x.status] = x.count;
            all += x.count;
          });
          d.setStatusCount({
            all: all - status.brown,
            live: all - status.brown,
            ...status,
          });
        },
      })
    );
  };

  const getPageStatusthrottleFunc = useCallback(
    debounce(
      2000,
      () => {
        console.log("debounce");
        getPageStatus();
      },
      { atBegin: true }
    ),
    []
  );

  const getPagethrottleFunc = useCallback((pageId: any) => {
    if (!d.pageThrottleRef.current?.[pageId]) {
      d.pageThrottleRef.current[pageId] = debounce(
        2000,
        (pageId: any) => {
          console.log("search page here", pageId);
          getPageById(pageId?.toString());
        },
        { atBegin: false }
      );
    }
    d.pageThrottleRef.current?.[pageId]?.(pageId);
  }, []);

  const getAdminRoles = (adminUserId: any, cudbServiceId: any) => {
    if (d.adminRoles.current) return;
    d.socket.publishToServiceIdSurvey(
      SocketTopics.SurveyTopics,
      UserTopics.SearchInUser,
      d.getUserRequestPayload(adminUserId, "$", "$..role"),
      getAdminRolesTopic(d.encrypted_token?.connectionId),
      cudbServiceId
    );
    d.socket.subscribeToSurvey(
      SocketTopics.SurveyTopics,
      getAdminRolesTopic(d.encrypted_token?.connectionId),
      (response: any) => {
        d.adminRoles.current = response.data?.[0]?.[0];
      },
      d.componentUuid
    );
  };

  const getUsersByRole = (roles: any, type: any) => {
    let userRoles;
    switch (type) {
      case "dispatcher":
        userRoles = roles.filter(
          (x: any) =>
            x.permissions.indexOf("cad") !== -1 &&
            x.permissions.indexOf("admin") === -1
        );
        break;
      case "responder":
        userRoles = roles.filter(
          (x: any) =>
            x.permissions.indexOf("onMove") !== -1 &&
            x.permissions.indexOf("admin") === -1
        );
        break;
      case "manager":
        userRoles = roles.filter(
          (x: any) =>
            x.permissions.indexOf("cad") !== -1 &&
            x.permissions.indexOf("onMove") !== -1 &&
            x.permissions.indexOf("admin") === -1
        );
        break;
    }
    const rolesQuery = userRoles.map((y: any) => {
      return `@roleId === '${y._id}'`;
    });
    const userRequest: any = {
      select: {
        index: {
          searchIndex: `${process.env.REACT_APP_ECO_SYSTEM}:userNameIndex`,
          searchQuery: `@serviceId:{'${formatForRedis(
            d.projects?.userServiceId
          )}'}`,
          searchOptions: "TIMEOUT 5000",
        },
        load: {
          id: "$.objectId",
          status: "$.nonpersistent.static.live.status",
          live: "$.persistent.static.live",
          roleId: "$..admin.profile.roleId",
        },
      },
      apply: {
        expression: "",
        name: "",
      },
      result: {},
      filter: {
        expression: `exists(@roleId) && (${rolesQuery.join("||")})`,
      },
      anyStatus: false,
    };
    d.socket.publishToEvent(
      SocketTopics.PublishPageTopics,
      getAggregateBdsPublishTopic(d.encrypted_token?.connectionId),
      wrapRequestPayload(userRequest, `${d.filterUserRequestId.current}:${type}`)
    );
    d.setProjectFilterLoading(true);
  };

  const getPageAggregateBds = (aggregateBy: any) => {
    d.setTimeFilterLoading(true);
    const pageAggregateRequest = {
      select: {
        index: {
          searchIndex: `${process.env.REACT_APP_ECO_SYSTEM}:pageUpdatedAtIndex`,
          searchQuery: `@pageMembers:{'${d.encrypted_token?.userId}'}`,
          searchOptions: "VERBATIM TIMEOUT 10000",
        },
        load: {
          [aggregateBy]: `$.persistent.static.profile.${aggregateBy}`,
        },
      },
      groupBy: {
        properties: [`@${aggregateBy}`],
        reducers: [
          {
            func: "COUNT",
            arguments: [],
            name: "count",
          },
        ],
      },
      filter: {
        expression: "",
      },
    };
    d.dispatch(
      GET_AGGREGATE({
        requestData: pageAggregateRequest,
        callback: (response: any) => {
          d.setTimeFilterLoading(false);
          let options = [];
          response?.map((aggregateBy: any) => {
            if (aggregateBy[Object.keys(aggregateBy)[0]]) {
              options.push({
                label: aggregateBy[Object.keys(aggregateBy)[0]],
                value: aggregateBy[Object.keys(aggregateBy)[0]],
              });
            }
          });
          d.setTimeFilterOptions(options);
        },
      })
    );
  };

  const searchPage = (offset = 0) => {
    const expressions = ["!exists(@pageType)"];
    let timeIndex = "";
    let statusIndex = "";
    let phoneIndex = "";
    if (d.selected === "advance") {
      d.selectedColor.current = "brown";
      statusIndex = `@rideStatus:{${colorRideStatusMapping["brown"]}}`;
    } else if (d.selected === "dispatch") {
      d.selectedColor.current = "purple";
      statusIndex = `@rideStatus:{${colorRideStatusMapping["purple"]}}`;
    } else if (d.pagePaths.current) {
      Object.keys(d.pagePaths.current).map((key) => {
        if (d.pagePaths.current?.[key]) {
          expressions.push(d.pagePaths.current?.[key]);
        }
      });
      if (!d.pageIndex.current.time && !d.pageIndex.current.phone) {
        const date = new Date();
        date.setHours(0);
        date.setMinutes(1);
        timeIndex += `@createdAt:[${date.getTime()},+inf]`;
      } else if (d.pageIndex.current.time) {
        timeIndex += d.pageIndex.current.time;
      }
    }
    if (
      d.pageIndex.current.status &&
      d.selected !== "advance" &&
      d.selected !== "dispatch"
    ) {
      statusIndex = d.pageIndex.current.status;
    }
    if (d.pageIndex.current.phone) {
      phoneIndex = d.pageIndex.current.phone;
    }

    const load = {};
    if (d.loadPaths.current) {
      d.loadPaths.current.map((x: any) => {
        load[x.key] = x.value;
      });
    }

    d.pageOffset.current = offset;

    const getPagesRequest = {
      select: {
        index: {
          searchIndex: `${process.env.REACT_APP_ECO_SYSTEM}:page:ride`,
          searchQuery: `@pageMembers:{${d.encrypted_token?.userId}}${!d.showHail.current ? "(-@rideType:{hail})" : ""
            }@pageType:{event}${timeIndex}${statusIndex}${phoneIndex}`,
          searchOptions: "VERBATIM TIMEOUT 10000",
        },
        load: {
          profile: "$..profile",
          dashboard: "$..dashboard",
          ride: "$.persistent.static.ride",
          stripe: "$.persistent.static.payment.stripe",
          paystack: "$.persistent.static.payment.paystack",
          dynamic: "$.persistent.dynamic.ride",
          type: "$..persistent.static.metadata.type",
          pageId: "$.objectId",
          iotAssetConfigId:
            "$.persistent.static.iotAsset.config.iotAssetConfigId",
          createdAt: "$.persistent.static.metadata.createdAt",
          updatedAt:
            "$.nonpersistent.dynamic.metadata.lastSent.members.updatedAt",
          status: "$.nonpersistent.static.live.status.name",
          requestedBy: "$.nonpersistent.dynamic.ride.dispatchRequestBy",
          manualUsers: "$.nonpersistent.dynamic.ride.manualUsers",
          rideType: "$..profile.type",
          phone: "$..dashboard.passengerPhoneNumber",
          pageType: "$..pageType",
          [d.timeFilter]: `$..dashboard.${d.timeFilter}`,
          ...load,
        },
      },
      filter: {
        expression: expressions.join("&&"),
      },
      sortBy: {
        properties: [
          d.selected === "advance"
            ? {
              field: "@createdAt",
              order: "ASC",
            }
            : {
              field: "@updatedAt",
              order: "DESC",
            },
        ],
        max: 1000,
      },
      result: d.pageIndex.current.phone
        ? {
          pagination: {
            offset: offset,
            limit: 50,
          },
        }
        : {},
    };

    const searchSeq = ++searchSeqRef.current;
    d.dispatch(
      GET_AGGREGATE({
        requestData: getPagesRequest,
        callback: (response: any) => {
          if (searchSeq !== searchSeqRef.current) return;
          console.log("page resppnse", response);
          d.setPages(response);
          d.pageOffset.current = d.pageOffset.current + 30;
          // Read from the synced ref, not the render-time closure: when this
          // fires from the 20s polling interval the closed-over state is stale.
          let sourceData =
            offset > 0 ? [...(d.tableDataSourceRef.current || [])] : [];
          const prevInvited = new Map(
            (d.tableDataSourceRef.current || []).map((row: any) => [
              row.key?.toString(),
              row.invited,
            ])
          );
          let columns: any = [
            {
              title: "Status",
              key: "pageStatus",
              dataIndex: "pageStatus",
              render: (status: string) => (
                <Button className="beam-btn icon-btn ml-2">
                  <ReactSVG
                    src="/images/flag-icon.svg"
                    className={`${status ?? "gray"}-icon`}
                  />
                </Button>
              ),
            },
            { title: "Schedule Date", key: "scheduleDate", dataIndex: "scheduleDate" },
            { title: "Schedule Time", key: "scheduleTime", dataIndex: "scheduleTime" },
            { title: "Requested at", key: "requestedAt", dataIndex: "requestedAt" },
            { title: "Pickup Address", key: "address", dataIndex: "address" },
            { title: "Dropoff Address", key: "dropoffAddress", dataIndex: "dropoffAddress" },
            { title: "Passenger Name", key: "passengerName", dataIndex: "passengerName" },
            { title: "Passenger Phone", key: "passengerPhoneNumber", dataIndex: "passengerPhoneNumber" },
            { title: "Account name", key: "accountName", dataIndex: "accountName" },
            { title: "Driver Name", key: "driverName", dataIndex: "driverName" },
            { title: "Vehicle Name", key: "vehicleName", dataIndex: "vehicleName" },
            { title: "Fixed Fare", key: "fixedFare", dataIndex: "fixedFare" },
            { title: "Invited Driver", key: "invited", dataIndex: "invited" },
            { title: "Assigned Driver", key: "assigned", dataIndex: "assigned" },
            { title: "Requested by", key: "requestedBy", dataIndex: "requestedBy" },
          ];
          response?.map((x: any, i: number) => {
            const profile = {
              ...(x?.profile || {}),
              ...(x?.dashboard || {}),
              ...(x?.ride || {}),
              ...(x?.dynamic || {}),
            };
            const source: any = {};
            Object.keys(profile).map((p) => {
              if (typeof profile[p] === "string") {
                source[p] = profile[p];
              }
            });

            const rideUsers =
              d.usersRef.current ||
              JSON.parse(localStorage.getItem("rideUsers") || "[]");
            const requestedBy =
              rideUsers?.find((user: any) => {
                return user.id === x?.requestedBy?.toString();
              })?.beamId || "";
            const assigned =
              rideUsers?.find((user: any) => {
                return user.id === Object.keys(x?.manualUsers || {})?.[0] || "";
              })?.beamId || "";

            let stripe;
            Object.keys(x?.stripe || {})?.map((key) => {
              if (
                x?.stripe?.[key]?.object === "payment_intent" &&
                x?.stripe?.[key]?.status === "succeeded"
              ) {
                stripe = x?.stripe?.[key];
              }
            });
            if (!stripe) {
              Object.keys(x?.stripe || {})?.map((key) => {
                if (
                  x?.stripe?.[key]?.object === "payment_intent" &&
                  x?.stripe?.[key]?.status === "requires_capture"
                ) {
                  stripe = x?.stripe?.[key];
                }
              });
            }
            sourceData.push({
              key: x.pageId,
              pageStatus: x.status,
              name: "",
              action: {
                pageId: x.pageId,
                page: {
                  ...x,
                  profile,
                },
                summary: source.summary,
                cudbServiceId: d.projects?.userServiceId,
                stripe,
                paystack: x?.paystack,
              },
              ...source,
              address:
                source?.address && source?.adress !== ""
                  ? source?.address
                  : profile?.pickupLocation?.attributes?.address,
              dropoffAddress:
                source?.dropoffAddress && source?.dropoffAddress !== ""
                  ? source?.dropoffAddress
                  : profile?.dropoffLocation?.attributes?.address,
              invited: prevInvited.get(x.pageId?.toString()) || "",
              requestedBy,
              requestedAt: new Date(x?.createdAt).toLocaleTimeString([], {
                hour: "2-digit",
                minute: "2-digit",
              }),
              assigned,
            });
          });
          sourceData.map((x: any) => {
            const profile = {
              ...(x?.profile || {}),
              ...(x?.dashboard || {}),
              ...(x?.ride || {}),
              ...(x?.dynamic || {}),
            };

            Object.keys(profile || {}).map((p) => {
              if (
                columns.findIndex((c: any) => {
                  return c.key === p;
                }) === -1 &&
                typeof profile[p] === "string"
              ) {
              }
            });
          });

          columns.push({
            title: "Action",
            key: "action",
            dataIndex: "action",
            render: (action: any) => (
              <Row style={{ width: 135 }}>
                <Col span={8}>
                  <Button
                    className="beam-btn icon-btn"
                    onClick={() => {
                      popupCenter(
                        `${process.env.REACT_APP_WEB}/page/${action?.pageId}`,
                        "BeamLive",
                        window.innerWidth * 0.7,
                        window.innerHeight * 0.9
                      );
                    }}
                  >
                    <MessageOutlined />
                  </Button>
                </Col>

                {action?.summary && (
                  <Col span={8}>
                    <Button
                      className="beam-btn icon-btn ml-2"
                      onClick={() => {
                        window.open(
                          `${window.location.origin}/${action?.summary ?? "summary"
                          }?connectionId=${d.encrypted_token?.connectionId
                          }&pageId=${action?.pageId}&cudbServiceId=${action?.cudbServiceId
                          }`,
                          "_blank"
                        );
                      }}
                    >
                      <FileSearchOutlined />
                    </Button>
                  </Col>
                )}

                {action?.stripe && (
                  <Col span={8}>
                    <Button
                      className="beam-btn icon-btn ml-2"
                      onClick={() => {
                        d.setIsPaymentModalVisible({
                          stripe: action?.stripe,
                          pageId: action?.pageId,
                        });
                      }}
                    >
                      <PayCircleOutlined />
                    </Button>
                  </Col>
                )}
              </Row>
            ),
          });
          d.setTableColumns(columns);
          d.setTableDataSource(sourceData);
          d.setStatusFilterLoading(false);
          d.setProjectFilterLoading(false);
          d.setTimeFilterLoading(false);
        },
      })
    );
    getPageStatusthrottleFunc();
  };

  return {
    getPageById,
    getPageStatus,
    getPageStatusthrottleFunc,
    getPagethrottleFunc,
    getAdminRoles,
    getUsersByRole,
    getPageAggregateBds,
    searchPage,
  };
};
