import { useCallback, useEffect, useState } from "react";
import { useSelector } from "react-redux";
import { RootState } from "reducers/rootReducer";
import { DashboardFilters, TimeRangeValue } from "../types";
import {
  DEFAULT_TIME_RANGE,
  loadStoredTimeRange,
  resolveTimeRange,
  saveTimeRange,
} from "../utils/timeRange";

const initialFilters = (): DashboardFilters => ({
  entityType: "project",
  areaType: "state",
  timeRange: loadStoredTimeRange(),
});

const shallowEqual = (a: object, b: object) =>
  Object.keys({ ...a, ...b }).every((k) => a[k] === b[k]);

/**
 * All table filters live in one state object. Changing a filter *type*
 * clears its value in the same update, so the UI and the query can never
 * disagree about what is being filtered.
 */
export const useDashboardFilters = () => {
  const { searchByPhone } = useSelector((state: RootState) => state.auth);
  const [filters, setFilters] = useState<DashboardFilters>(initialFilters);

  const update = useCallback((patch: Partial<DashboardFilters>) => {
    setFilters((prev) => {
      const next = { ...prev, ...patch };
      return shallowEqual(prev, next) ? prev : next;
    });
  }, []);

  const setTimeRange = useCallback(
    (value: TimeRangeValue) => {
      saveTimeRange(value);
      update({ timeRange: resolveTimeRange(value) });
    },
    [update]
  );

  const reset = useCallback(() => {
    saveTimeRange(undefined);
    setFilters({
      entityType: "project",
      areaType: "state",
      timeRange: resolveTimeRange(DEFAULT_TIME_RANGE),
    });
  }, []);

  useEffect(() => {
    if (searchByPhone?.phone) update({ phone: searchByPhone.phone });
  }, [searchByPhone, update]);

  return { filters, update, setTimeRange, reset };
};
