import React, { FC, useEffect, useState } from "react";
import { Button, Checkbox, Col, InputNumber, Modal, Row, Select, Tooltip } from "antd";
import {
  SchedActivity,
  SchedResource,
  SolveRequest,
} from "services/apis/aiSchedulerTypes";

export interface SolveOptions {
  timeLimitSeconds?: number;
  resourcesOffline: string[];
  activitiesExcluded: string[];
  minimalDisruption: boolean;
}

export const optionsToRequest = (
  options: SolveOptions,
  currentScheduleId?: string
): SolveRequest => {
  const request: SolveRequest = {};
  if (options.timeLimitSeconds) request.timeLimitSeconds = options.timeLimitSeconds;
  if (options.resourcesOffline.length || options.activitiesExcluded.length) {
    request.scenario = {
      ...(options.resourcesOffline.length
        ? { resourcesOffline: options.resourcesOffline }
        : {}),
      ...(options.activitiesExcluded.length
        ? { activitiesExcluded: options.activitiesExcluded }
        : {}),
    };
  }
  if (options.minimalDisruption && currentScheduleId) {
    request.previousScheduleId = currentScheduleId;
  }
  return request;
};

const SolveOptionsModal: FC<{
  visible: boolean;
  options: SolveOptions;
  resources: SchedResource[];
  activities: SchedActivity[];
  hasCurrentSchedule: boolean;
  onClose: () => void;
  onSolve: (options: SolveOptions) => void;
}> = ({ visible, options, resources, activities, hasCurrentSchedule, onClose, onSolve }) => {
  const [draft, setDraft] = useState<SolveOptions>(options);

  useEffect(() => {
    if (visible) setDraft(options);
  }, [visible, options]);

  const resourceOptions = resources
    .filter((r) => r.id)
    .map((r) => ({ label: `${r.name} (${r.kind})`, value: r.id as string }));
  const activityOptions = activities
    .filter((a) => a.id)
    .map((a) => ({ label: a.name, value: a.id as string }));

  return (
    <Modal
      title="Solve options"
      visible={visible}
      onCancel={onClose}
      width="520px"
      className="beam-modal"
      footer={[]}
      destroyOnClose
    >
      <div className="auth-form">
        <div className="ant-form-item-label">
          <label>Time limit (seconds)</label>
        </div>
        <InputNumber
          min={10}
          max={3600}
          placeholder="240"
          value={draft.timeLimitSeconds}
          onChange={(v) =>
            setDraft((d) => ({ ...d, timeLimitSeconds: v ?? undefined }))
          }
          style={{ width: "100%", marginBottom: 16 }}
        />

        <div className="ant-form-item-label">
          <label>What-if scenario</label>
        </div>
        <p style={{ color: "#8c8c8c", fontSize: 12, marginBottom: 8 }}>
          Runs a what-if (building offline, course excluded) without touching stored
          data.
        </p>
        <Select
          mode="multiple"
          allowClear
          placeholder="Resources offline"
          value={draft.resourcesOffline}
          onChange={(v) => setDraft((d) => ({ ...d, resourcesOffline: v }))}
          options={resourceOptions}
          filterOption={(input, option) =>
            (option?.label ?? "").toString().toLowerCase().includes(input.toLowerCase())
          }
          style={{ width: "100%", marginBottom: 12 }}
        />
        <Select
          mode="multiple"
          allowClear
          placeholder="Activities excluded"
          value={draft.activitiesExcluded}
          onChange={(v) => setDraft((d) => ({ ...d, activitiesExcluded: v }))}
          options={activityOptions}
          filterOption={(input, option) =>
            (option?.label ?? "").toString().toLowerCase().includes(input.toLowerCase())
          }
          style={{ width: "100%", marginBottom: 16 }}
        />

        <Tooltip
          title={
            hasCurrentSchedule
              ? "The solver keeps as much of the current schedule as possible — use after mid-term disruptions."
              : "Run a solve first to enable minimal disruption."
          }
        >
          <Checkbox
            checked={draft.minimalDisruption}
            disabled={!hasCurrentSchedule}
            onChange={(e) =>
              setDraft((d) => ({ ...d, minimalDisruption: e.target.checked }))
            }
          >
            Minimal disruption — keep as much of the current schedule as possible
          </Checkbox>
        </Tooltip>

        <Row className="mt-4">
          <Col span={14} className="pr-2">
            <Button
              className="beam-btn green-btn cover w-full"
              onClick={() => {
                onSolve(draft);
                onClose();
              }}
            >
              Solve
            </Button>
          </Col>
          <Col span={10} className="pl-2">
            <Button className="beam-btn orange-btn bordered w-full" onClick={onClose}>
              Cancel
            </Button>
          </Col>
        </Row>
      </div>
    </Modal>
  );
};

export default SolveOptionsModal;
