import React, { FC, useMemo, useState } from "react";
import { Button, Dropdown, Menu, Popconfirm, Select, Tooltip } from "antd";
import type { ColumnsType } from "antd/es/table";
import { EditOutlined, MoreOutlined, SendOutlined } from "@ant-design/icons";
import { DataTableCard, EmptyState, PageHeader, Pill, matchesSearch } from "../../Medical/common/ui";
import { CouponLifecycle, conditionLines, discountHeadline, lifecycle, validityLabel } from "../couponRules";
import { CouponInfo, CouponRecord } from "../types";
import { LIFECYCLE_PILL } from "./shared";

interface Props {
  coupons: CouponRecord[];
  loading: boolean;
  loadFailed: boolean;
  onReload: () => void;
  onCreate: () => void;
  onEdit: (coupon: CouponRecord) => void;
  onShare: (coupon: CouponRecord) => void;
  onOpen: (coupon: CouponRecord) => void;
  onStatus: (coupon: CouponRecord, status: CouponInfo["status"]) => void;
}

const CouponsScreen: FC<Props> = ({
  coupons,
  loading,
  loadFailed,
  onReload,
  onCreate,
  onEdit,
  onShare,
  onOpen,
  onStatus,
}) => {
  const [search, setSearch] = useState("");
  const [state, setState] = useState<CouponLifecycle | "all">("all");

  const rows = useMemo(
    () =>
      coupons.filter((c) => {
        const s = lifecycle(c.info, c.stats);
        if (state === "all" ? s === "archived" : s !== state) return false;
        return matchesSearch(search, c.info.title, c.info.brandName, c.info.code);
      }),
    [coupons, search, state]
  );

  const columns: ColumnsType<CouponRecord> = [
    {
      title: "Coupon",
      key: "title",
      render: (_, c) => (
        <div className="cpn-title-cell">
          {c.info.card?.logoUrl && <img src={c.info.card.logoUrl} alt="" />}
          <div>
            <strong>{c.info.title}</strong>
            <div className="cpn-muted">
              {[c.info.brandName, c.info.code].filter(Boolean).join(" · ") || "—"}
            </div>
          </div>
        </div>
      ),
    },
    {
      title: "Discount",
      key: "discount",
      render: (_, c) => (
        <div>
          <strong>{discountHeadline(c.info)}</strong>
          <div className="cpn-muted">{conditionLines(c.info).slice(0, -1).join(" · ")}</div>
        </div>
      ),
    },
    { title: "Validity", key: "validity", render: (_, c) => validityLabel(c.info) || "Always" },
    {
      title: "Status",
      key: "status",
      render: (_, c) => {
        const s = lifecycle(c.info, c.stats);
        return <Pill tone={LIFECYCLE_PILL[s].tone}>{LIFECYCLE_PILL[s].label}</Pill>;
      },
    },
    {
      title: "Generated / used",
      key: "usage",
      align: "right",
      render: (_, c) => (
        <span>
          {c.stats.issued} / <strong>{c.stats.redeemed}</strong>
        </span>
      ),
    },
    {
      title: "",
      key: "actions",
      align: "right",
      width: 170,
      render: (_, c) => (
        <span className="mx-row-actions" onClick={(e) => e.stopPropagation()}>
          <Tooltip title={c.info.status === "active" ? "Share" : "Activate to share"}>
            <Button size="small" icon={<SendOutlined />} disabled={c.info.status !== "active"} onClick={() => onShare(c)}>
              Share
            </Button>
          </Tooltip>
          <Tooltip title="Edit">
            <Button size="small" icon={<EditOutlined />} onClick={() => onEdit(c)} />
          </Tooltip>
          <Dropdown
            trigger={["click"]}
            overlay={
              <Menu
                items={[
                  c.info.status === "active"
                    ? { key: "pause", label: "Pause", onClick: () => onStatus(c, "paused") }
                    : { key: "activate", label: "Activate", onClick: () => onStatus(c, "active") },
                  c.info.status === "archived"
                    ? null
                    : {
                        key: "archive",
                        label: (
                          <Popconfirm
                            title="Archive this coupon? Its codes stop working."
                            okText="Archive"
                            okButtonProps={{ danger: true }}
                            onConfirm={() => onStatus(c, "archived")}
                          >
                            <span>Archive</span>
                          </Popconfirm>
                        ),
                      },
                ].filter(Boolean) as any}
              />
            }
          >
            <Button size="small" icon={<MoreOutlined />} />
          </Dropdown>
        </span>
      ),
    },
  ];

  return (
    <div className="cpn-screen">
      <PageHeader
        title="Coupons"
        subtitle="Create discounts, design their card, and share a unique QR code with each customer"
        search={{ value: search, onChange: setSearch, placeholder: "Search coupons" }}
        primaryAction={{ label: "Create coupon", onClick: onCreate }}
        extra={
          <Select
            value={state}
            onChange={setState}
            style={{ width: 150 }}
            options={[
              { label: "All current", value: "all" },
              ...(Object.keys(LIFECYCLE_PILL) as CouponLifecycle[]).map((k) => ({
                label: LIFECYCLE_PILL[k].label,
                value: k,
              })),
            ]}
          />
        }
      />
      <DataTableCard<CouponRecord>
        rowKey="objectId"
        loading={loading}
        caption={`${rows.length} ${rows.length === 1 ? "coupon" : "coupons"}`}
        columns={columns}
        dataSource={rows}
        clickable
        onRow={(c) => ({ onClick: () => onOpen(c) })}
        scroll={{ x: true }}
        empty={
          loadFailed ? (
            <EmptyState
              title="Couldn't load coupons"
              description={
                <Button className="mx-btn-secondary mt-2" onClick={onReload}>
                  Try again
                </Button>
              }
            />
          ) : search || state !== "all" ? (
            <EmptyState title="No coupons match" />
          ) : (
            <EmptyState
              title="No coupons yet"
              description="Create your first coupon to start sharing discounts."
              action={{ label: "Create coupon", onClick: onCreate }}
            />
          )
        }
      />
    </div>
  );
};

export default CouponsScreen;
