import { RootState } from "reducers/rootReducer";
import { Form, Select } from "antd";
import { SocketTopics } from "constants/enums";
import LocationInput from "../../../../../common/LocationInput";
import TimeInput from "../../../../../common/TimeInput";
import ResponderInput from "../../../../../common/ResponderInput";
import PhoneInput from "react-phone-number-input";
import { pushNotification } from "utils/notifications";
import { dateToCron, generateUUID, cronToDate } from "utils/appUtil";
import useSocketActions from "../../../../../hooks/socketActions";
import { ExtendedBioTopics, UserTopics } from "constants/enums";
import {
  DeleteOutlined,
  CloseCircleOutlined,
  PlusOutlined,
} from "@ant-design/icons";
import moment, { Moment } from "moment";

const { Panel } = Collapse;

interface LocationOption {
  location?: string;
  startTime?: string;
  endTime?: string;
  days?: string[];
  timeWindow?: number | "custom";
  customTimeWindow?: number;
}

interface LocationInputProps {
  value?: LocationOption[];
  keyPrefix?: string;
  onChange?: (locations: LocationOption[]) => void;
}

interface HolidaySelectorProps {
  value?: Moment[];
  onChange?: (dates: Moment[]) => void;
}
const { TabPane } = Tabs;

const EditDriverModal: FC<{
  onClose: () => void;
  socket?: ISocket;
  student?: any;
  adminRoles?: any;
  onAdd?: () => void;
}> = (props) => {
  const { onClose, socket, student, adminRoles, onAdd } = props;
  const [isModalVisible, setIsModalVisible] = useState(true);
  const [registerForm] = Form.useForm();
  const [error, setError] = useState<string>("");
  const [saving, setSaving] = useState(false);
  const { projects } = useSelector((state: RootState) => state.auth);
  const { updateUserRequestPayloadV2 } = useSocketActions();
  const [selectedTab, setSelectedTab] = useState("1");

  const handleCancel = () => {
    setIsModalVisible(false);
    onClose && onClose();
  };

  useEffect(() => {
    if (student?.static) {
      registerForm.setFieldsValue({
        ...student?.static,
        ...student?.static?.preferences,
        maintenanceDate: moment(student?.static?.maintenanceDate),
        responder: student?.static?.alternativeIds?.userId
          ? {
              type: "responder",
              id: student?.static?.alternativeIds?.userId,
              beamId: student?.static?.alternativeIds?.beamId,
              valueName: student?.static?.alternativeIds?.beamId,
            }
          : undefined,
      });
    }
  }, []);

  const onSubmitHandler = async (values: any) => {
    console.log("values", values);
    const {
      name,
      noOfBaggages,
      noOfPassengers,
      makeAndModel,
      mileage,
      licensePlate,
      vehicleType,
      vehicleYear,
      maintenanceDate,
      vin,
      accessibilityOptions,
      safetyEquipment,
      specialFeatures,
    } = values;
    const request = {
      vehicle:
        selectedTab === "1"
          ? {
              name,
              noOfBaggages,
              noOfPassengers,
              makeAndModel,
              mileage,
              licensePlate,
              vehicleType,
              vehicleYear,
              maintenanceDate: maintenanceDate.format("MM/DD/YYYY HH:mm:ss"),
              vin,
            }
          : undefined,
      preferences:
        selectedTab === "2"
          ? {
              accessibilityOptions,
              safetyEquipment,
              specialFeatures,
            }
          : undefined,
    };
    setSaving(true);
    await updateUser(student?.id, projects?.userServiceId, request);
    pushNotification(
      "User updated successfully",
      "success",
      "TOP_CENTER",
      3000
    );
    setSaving(false);
    onAdd();
  };

  const updateUser = async (userId, serviceId, updateData) => {
    return new Promise((resolve, reject) => {
      const { vehicle, preferences } = updateData;
      const updatedUserData = [];
      if (vehicle) {
        Object.keys(vehicle)?.map((key: any) => {
          updatedUserData.push({
            op: "add",
            path: `/persistent/static/asset/${key}`,
            value: vehicle?.[key],
          });
        });
      }
      if (preferences) {
        updatedUserData.push({
          op: "add",
          path: "/persistent/static/asset/preferences",
          value: preferences,
        });
      }
      console.log("update user data", updatedUserData);

      socket.publishToServiceIdSurvey(
        SocketTopics.SurveyTopics,
        UserTopics.UpdateUser,
        updateUserRequestPayloadV2(userId, updatedUserData),
        ExtendedBioTopics.UpdateUserBio,
        serviceId
      );
      socket.subscribeToSurvey(
        SocketTopics.SurveyTopics,
        ExtendedBioTopics.UpdateUserBio,
        (response) => {
          resolve(response);
        }
      );
    });
  };

  const VehicleInformationInput: React.FC<any> = ({ value, onChange }) => {
    const vehicleTypes = ["School Bus", "Mini Bus", "Van"];

    return (
      <React.Fragment>
        <Form.Item
          label="Vehicle Name"
          name="name"
          rules={[{ required: true, message: "Please input the vehicle name" }]}
        >
          <Input placeholder="Enter name" />
        </Form.Item>

        <Form.Item
          className="mt-3"
          label="Vehicle Type"
          name="vehicleType"
          rules={[
            { required: true, message: "Please select the vehicle type" },
          ]}
        >
          <Select placeholder="Select vehicle type">
            {vehicleTypes.map((type) => (
              <Select.Option key={type} value={type}>
                {type}
              </Select.Option>
            ))}
          </Select>
        </Form.Item>

        <Form.Item
          className="mt-3"
          label="Vehicle Make and Model"
          name="makeAndModel"
          rules={[
            {
              required: true,
              message: "Please enter the vehicle make and model",
            },
          ]}
        >
          <Input placeholder="e.g., Ford Transit 2021" />
        </Form.Item>

        <Form.Item
          className="mt-3"
          label="Vehicle Year"
          name="vehicleYear"
          rules={[{ required: true, message: "Please enter the vehicle year" }]}
        >
          <Input placeholder="Enter vehicle year" style={{ width: "100%" }} />
        </Form.Item>

        <Form.Item
          className="mt-3"
          label="License Plate Number"
          name="licensePlate"
          rules={[
            {
              required: true,
              message: "Please enter the license plate number",
            },
          ]}
        >
          <Input placeholder="Enter license plate number" />
        </Form.Item>

        <Form.Item
          className="mt-3"
          label="Vehicle Identification Number (VIN)"
          name="vin"
          rules={[
            {
              required: true,
              message: "Please enter the vehicle identification number (VIN)",
            },
          ]}
        >
          <Input placeholder="Enter VIN" />
        </Form.Item>

        <Form.Item
          className="mt-3"
          label="Current Mileage"
          name="mileage"
          rules={[
            { required: true, message: "Please enter the current mileage" },
          ]}
        >
          <Input
            placeholder="Enter mileage in miles or kilometers"
            style={{ width: "100%" }}
          />
        </Form.Item>

        <Form.Item
          className="mt-3"
          label="Last Maintenance Date"
          name="maintenanceDate"
          rules={[
            {
              required: true,
              message: "Please select the last maintenance date",
            },
          ]}
        >
          <DatePicker style={{ width: "100%" }} />
        </Form.Item>

        <Form.Item
          className="mt-3"
          label="Number of passengers"
          name="noOfPassengers"
          rules={[
            { required: true, message: "Please input number of passengers" },
            {
              pattern: /^[0-9]+$/,
              message: "The input must be a number",
            },
          ]}
        >
          <Input
            min={0}
            max={100}
            placeholder="Enter number of passengers"
            style={{ width: "100%" }}
          />
        </Form.Item>

        <Form.Item
          className="mt-3"
          label="Number of baggages"
          name="noOfBaggages"
          rules={[
            { required: true, message: "Please input number of baggages" },
            {
              pattern: /^[0-9]+$/,
              message: "The input must be a number",
            },
          ]}
        >
          <Input
            min={0}
            max={100}
            placeholder="Enter number of baggages"
            style={{ width: "100%" }}
          />
        </Form.Item>
      </React.Fragment>
    );
  };

  const AdditionalConstraints: React.FC<any> = ({ value, onChange }) => {
    const specialFeatures = [
      "Air Conditioning",
      "Wheelchair Lift",
      "GPS Tracking",
      "Wi-Fi",
      "Emergency Exit Alarm",
      "Seat Belts",
    ];

    const accessibilityOptions = [
      "Wheelchair Accessible",
      "Child Safety Seat",
      "Ramp Access",
    ];

    const safetyEquipment = [
      "Fire Extinguisher",
      "First Aid Kit",
      "Emergency Kit",
      "Backup Camera",
      "Seat Belt Alarm",
    ];

    return (
      <React.Fragment>
        <Form.Item label="Special Features" name="specialFeatures">
          <Checkbox.Group>
            {specialFeatures.map((feature) => (
              <Checkbox key={feature} value={feature}>
                {feature}
              </Checkbox>
            ))}
          </Checkbox.Group>
        </Form.Item>

        <Form.Item
          label="Accessibility Options"
          name="accessibilityOptions"
          className="mt-3"
        >
          <Checkbox.Group>
            {accessibilityOptions.map((option) => (
              <Checkbox key={option} value={option}>
                {option}
              </Checkbox>
            ))}
          </Checkbox.Group>
        </Form.Item>

        <Form.Item
          label="Safety Equipment"
          name="safetyEquipment"
          className="mt-3"
        >
          <Checkbox.Group>
            {safetyEquipment.map((equipment) => (
              <Checkbox key={equipment} value={equipment}>
                {equipment}
              </Checkbox>
            ))}
          </Checkbox.Group>
        </Form.Item>
      </React.Fragment>
    );
  };

  return (
    <Modal
      title={`Edit (${student?.static?.name || "vehicle"})`}
      visible={isModalVisible}
      onCancel={handleCancel}
      width="800px"
      className="beam-modal"
      // width="100%"
      // className="beam-modal analytics-summary-modal"
      footer={[]}
      destroyOnClose={true}
    >
      <Form
        className="auth-form"
        name="register-form"
        id="register-form"
        layout="vertical"
        form={registerForm}
        onFinish={onSubmitHandler}
        requiredMark={false}
      >
        <div className="main-cards mt-3">
          {/* <Collapse
            activeKey={["vehicle", "driver", "preferences"]}
            bordered={false}
            className="simple-collapse d-flex flex-column"
          >
            <Panel
              header={
                <div className="d-flex">
                  <h5 className="m-2">Vehicle Information</h5>
                </div>
              }
              key={"vehicle"}
            >
              <Form.Item name="vehicle">
                <VehicleInformationInput />
              </Form.Item>
            </Panel>

            <Panel
              header={
                <div className="d-flex">
                  <h5 className="m-2">Driver Assignment</h5>
                </div>
              }
              key={"driver"}
            >
              <Form.Item name="responder">
                <ResponderInput
                  placeholder="Assign driver"
                  adminRoles={adminRoles}
                />
              </Form.Item>
            </Panel>

            <Panel
              header={
                <div className="d-flex">
                  <h5 className="m-2">Preferences</h5>
                </div>
              }
              key={"preferences"}
            >
              <Form.Item name="preferences">
                <AdditionalConstraints />
              </Form.Item>
            </Panel>
          </Collapse> */}

          <Tabs
            defaultActiveKey="1"
            type="line"
            onChange={(key) => {
              setSelectedTab(key);
            }}
          >
            {/* Tab 1 */}
            <TabPane tab="Vehicle Information" key="1">
              {selectedTab === "1" && (
                <Form.Item name="vehicle">
                  <VehicleInformationInput />
                </Form.Item>
              )}
            </TabPane>

            {/* Tab 2 */}
            <TabPane tab="Preferences" key="2">
              {selectedTab === "2" && (
                <Form.Item name="preferences">
                  <AdditionalConstraints />
                </Form.Item>
              )}
            </TabPane>
          </Tabs>
        </div>

        <Row className="action-grp mt-3">
          <Col span={24}>
            <Form.Item>
              <Button
                className="beam-btn green-btn cover w-full"
                loading={saving}
                type="primary"
                htmlType="submit"
                onClick={() => setError("")}
              >
                Save
              </Button>
            </Form.Item>
          </Col>
        </Row>
      </Form>
    </Modal>
  );
};

export default EditDriverModal;
