import React, { useMemo } from "react";
import { Alert, DatePicker, Form, Input } from "antd";
import dayjs from "dayjs";
import moment from "moment";
import { FormModal } from "../../common/ui";
import { DAY_KEY, countDays, formatPeriod, rangesOverlap } from "./shiftUtils";

const { RangePicker } = DatePicker;
const PICKER_FORMAT = "ddd, MMM D, YYYY";

const nameRules = [
  { required: true, whitespace: true, message: "Give the roster a name" },
  { max: 80, message: "Keep the name under 80 characters" },
];

export interface RosterFormValues {
  name: string;
  startDate: string;
  endDate: string;
}

/** Create a roster, or duplicate `source` (a roster's info) onto a new start date. */
export const RosterFormModal = ({
  source,
  rosters,
  saving,
  onCancel,
  onSubmit,
}: {
  source?: any;
  rosters: any[];
  saving?: boolean;
  onCancel: () => void;
  onSubmit: (values: RosterFormValues) => void;
}) => {
  const [form] = Form.useForm();
  const watchedRange = Form.useWatch("range", form);
  const watchedStart = Form.useWatch("startDate", form);
  const sourceDays = source ? Math.max(1, countDays(source.startDate, source.endDate)) : 0;

  const initialValues = useMemo(
    () =>
      source
        ? {
            name: `${source.name || "Roster"} (copy)`,
            startDate: source.endDate ? moment(source.endDate).add(1, "day") : undefined,
          }
        : {},
    []
  );

  const candidate = useMemo(() => {
    if (source) {
      if (!watchedStart) return undefined;
      const start = watchedStart.format(DAY_KEY);
      return { start, end: dayjs(start).add(sourceDays - 1, "day").format(DAY_KEY) };
    }
    if (watchedRange?.[0] && watchedRange?.[1]) {
      return { start: watchedRange[0].format(DAY_KEY), end: watchedRange[1].format(DAY_KEY) };
    }
    return undefined;
  }, [source, watchedStart, watchedRange, sourceDays]);

  const overlapping = candidate
    ? rosters.filter((x) =>
        rangesOverlap(candidate.start, candidate.end, x?.info?.startDate, x?.info?.endDate)
      )
    : [];

  const handleFinish = (values: any) => {
    if (source) {
      const startDate = values.startDate.format(DAY_KEY);
      onSubmit({
        name: values.name.trim(),
        startDate,
        endDate: dayjs(startDate).add(sourceDays - 1, "day").format(DAY_KEY),
      });
    } else {
      onSubmit({
        name: values.name.trim(),
        startDate: values.range[0].format(DAY_KEY),
        endDate: values.range[1].format(DAY_KEY),
      });
    }
  };

  return (
    <FormModal
      open
      title={source ? "Duplicate roster" : "New roster"}
      subtitle={
        source
          ? `Copies every driver's slots from "${source.name || "Untitled"}" (${formatPeriod(
              source.startDate,
              source.endDate
            )}, ${sourceDays} days) to a new start date.`
          : "Pick the days this roster covers. You can fill in driver slots next."
      }
      onCancel={() => !saving && onCancel()}
      onSubmit={form.submit}
      saving={saving}
      okText={source ? "Duplicate" : "Create"}
    >
      <Form
        form={form}
        layout="vertical"
        requiredMark={false}
        initialValues={initialValues}
        onFinish={handleFinish}
      >
        <Form.Item label="Name" name="name" rules={nameRules}>
          <Input placeholder="e.g. Week of Sep 28" autoFocus />
        </Form.Item>

        {source ? (
          <Form.Item
            label="New start date"
            name="startDate"
            rules={[{ required: true, message: "Pick the first day of the new roster" }]}
            extra={
              candidate
                ? `Ends ${dayjs(candidate.end).format("ddd, MMM D, YYYY")} · ${sourceDays} days`
                : undefined
            }
          >
            <DatePicker className="w-full" format={PICKER_FORMAT} />
          </Form.Item>
        ) : (
          <Form.Item
            label="Dates"
            name="range"
            rules={[
              { required: true, message: "Pick the first and last day" },
              {
                validator: (_, value) =>
                  value?.[0] && value?.[1] && value[1].isBefore(value[0], "day")
                    ? Promise.reject(new Error("End date must be on or after the start date"))
                    : Promise.resolve(),
              },
            ]}
            extra={candidate ? `${countDays(candidate.start, candidate.end)} days` : undefined}
          >
            <RangePicker className="w-full" format={PICKER_FORMAT} />
          </Form.Item>
        )}

        {overlapping.length > 0 && (
          <Alert
            type="warning"
            showIcon
            message="These dates overlap another roster"
            description={
              <>
                {overlapping.map((x) => (
                  <div key={x.objectId}>
                    <strong>{x.info?.name || "Untitled"}</strong> ·{" "}
                    {formatPeriod(x.info?.startDate, x.info?.endDate)}
                  </div>
                ))}
                <div className="mt-1">
                  The dashboard reads one roster per day, so driver suggestions may come from the
                  other roster.
                </div>
              </>
            }
          />
        )}
      </Form>
    </FormModal>
  );
};

export const RenameRosterModal = ({
  name,
  onCancel,
  onSubmit,
}: {
  name?: string;
  onCancel: () => void;
  onSubmit: (name: string) => void;
}) => {
  const [form] = Form.useForm();
  return (
    <FormModal open title="Rename roster" onCancel={onCancel} onSubmit={form.submit} width={420}>
      <Form
        form={form}
        layout="vertical"
        requiredMark={false}
        initialValues={{ name: name || "" }}
        onFinish={(values) => onSubmit(values.name.trim())}
      >
        <Form.Item label="Name" name="name" rules={nameRules}>
          <Input autoFocus />
        </Form.Item>
      </Form>
    </FormModal>
  );
};
