import React, { FC, useEffect, useMemo, useState } from "react";
import { Button, DatePicker, Select } from "antd";
import { DownloadOutlined } from "@ant-design/icons";
import moment, { Moment } from "moment";
import { DataTableCard, EmptyState, PageHeader, matchesSearch } from "../../Medical/common/ui";
import { useCouponQueries } from "../couponApi";
import { downloadDataUrl } from "../card/renderCard";
import { CouponRecord, RedemptionRecord } from "../types";
import { REDEMPTION_COLUMNS } from "./shared";

const { RangePicker } = DatePicker;

const RedemptionsScreen: FC<{ coupons: CouponRecord[]; refreshKey: number }> = ({ coupons, refreshKey }) => {
  const { loadRedemptions } = useCouponQueries();
  const [range, setRange] = useState<[Moment, Moment]>([moment().subtract(29, "days").startOf("day"), moment().endOf("day")]);
  const [couponId, setCouponId] = useState<string>();
  const [status, setStatus] = useState<"accepted" | "rejected">();
  const [search, setSearch] = useState("");
  const [rows, setRows] = useState<RedemptionRecord[]>([]);
  const [loading, setLoading] = useState(false);
  const [failed, setFailed] = useState(false);

  useEffect(() => {
    let live = true;
    setLoading(true);
    loadRedemptions({ couponId, from: range[0].valueOf() }).then((result) => {
      if (!live) return;
      setLoading(false);
      setFailed(!result);
      if (result) setRows(result);
    });
    return () => {
      live = false;
    };
  }, [loadRedemptions, couponId, range, refreshKey]);

  const shown = useMemo(
    () =>
      rows.filter(
        (r) =>
          r.info.redeemedAt <= range[1].valueOf() &&
          (!status || r.info.status === status) &&
          matchesSearch(search, r.info.vendorName, r.info.recipientName, r.info.reference, r.info.couponTitle)
      ),
    [rows, range, status, search]
  );

  const exportCsv = () => {
    const header = ["redeemed_at", "coupon", "recipient", "store", "bill", "discount", "final", "currency", "result", "reason", "reference"];
    const lines = shown.map((r) => [
      moment(r.info.redeemedAt).format("YYYY-MM-DD HH:mm"),
      r.info.couponTitle || "",
      r.info.recipientName || "",
      r.info.vendorName,
      r.info.billAmount ?? "",
      r.info.discountApplied ?? "",
      r.info.finalAmount ?? "",
      r.info.currency || "",
      r.info.status,
      r.info.rejectReason || "",
      r.info.reference,
    ]);
    const csv = [header, ...lines].map((row) => row.map((c) => `"${`${c}`.replace(/"/g, '""')}"`).join(",")).join("\n");
    downloadDataUrl(`data:text/csv;charset=utf-8,${encodeURIComponent(csv)}`, `redemptions-${moment().format("YYYYMMDD")}.csv`);
  };

  return (
    <div className="cpn-screen">
      <PageHeader
        title="Redemptions"
        subtitle="Every scan a store approved or declined"
        search={{ value: search, onChange: setSearch, placeholder: "Search store, customer or reference" }}
        extra={
          <Button icon={<DownloadOutlined />} onClick={exportCsv} disabled={!shown.length}>
            Export CSV
          </Button>
        }
      />
      <div className="mx-card cpn-filters">
        <label>
          <span>Coupon</span>
          <Select
            allowClear
            placeholder="All coupons"
            value={couponId}
            onChange={setCouponId}
            showSearch
            optionFilterProp="label"
            options={coupons.map((c) => ({ label: c.info.title, value: c.objectId }))}
          />
        </label>
        <label>
          <span>Result</span>
          <Select
            allowClear
            placeholder="All results"
            value={status}
            onChange={setStatus}
            options={[
              { label: "Accepted", value: "accepted" },
              { label: "Declined", value: "rejected" },
            ]}
          />
        </label>
        <label>
          <span>Dates</span>
          <RangePicker
            value={range}
            format="MMM D, YYYY"
            allowClear={false}
            onChange={(v) => v?.[0] && v?.[1] && setRange([v[0].clone().startOf("day"), v[1].clone().endOf("day")])}
          />
        </label>
      </div>
      <DataTableCard<RedemptionRecord>
        rowKey="objectId"
        loading={loading}
        caption={`${shown.length} ${shown.length === 1 ? "redemption" : "redemptions"}`}
        columns={REDEMPTION_COLUMNS}
        dataSource={shown}
        pagination={shown.length > 50 ? { pageSize: 50, showSizeChanger: false } : false}
        scroll={{ x: true }}
        empty={<EmptyState title={failed ? "Couldn't load redemptions" : "No redemptions match"} />}
      />
    </div>
  );
};

export default RedemptionsScreen;
