import React, { FC } from "react";
import { Form, Radio, Select, Switch } from "antd";

import { Installment, RecurringPlan, UpfrontPlan } from "../../types";
import { BILLING_CYCLES, newId } from "../../paymentConfig";
import {
  AmountRuleFields,
  DateField,
  FormRow,
  NullableNumberField,
  NumberField,
  RowList,
  SwitchField,
  TextField,
} from "../fields";
import { SectionProps } from "./types";

const PlanSection: FC<SectionProps> = ({ config, patch, disabled }) => {
  const { upfront, recurring, currency } = config;
  const patchUpfront = (changes: Partial<UpfrontPlan>) => patch({ upfront: { ...upfront, ...changes } });
  const patchDeposit = (changes: Partial<UpfrontPlan["deposit"]>) =>
    patchUpfront({ deposit: { ...upfront.deposit, ...changes } });
  const patchInstallments = (changes: Partial<UpfrontPlan["installments"]>) =>
    patchUpfront({ installments: { ...upfront.installments, ...changes } });
  const patchDeferred = (changes: Partial<UpfrontPlan["installments"]["deferred"]>) =>
    patchInstallments({ deferred: { ...upfront.installments.deferred, ...changes } });
  const patchRecurring = (changes: Partial<RecurringPlan>) => patch({ recurring: { ...recurring, ...changes } });

  const { deposit, installments } = upfront;

  return (
    <>
      <Form.Item>
        <Radio.Group
          value={config.planType}
          disabled={disabled}
          onChange={(e) => patch({ planType: e.target.value })}
        >
          <Radio value="upfront">Upfront (one-time, with optional deposit and installments)</Radio>
          <Radio value="recurring">Recurring (charged every billing cycle)</Radio>
        </Radio.Group>
      </Form.Item>

      {config.planType === "upfront" && (
        <>
          <FormRow>
            <DateField
              label="Full payment due date"
              extra="Leave empty to make the full amount due at issue."
              value={upfront.dueDate}
              disabled={disabled}
              onChange={(dueDate) => patchUpfront({ dueDate })}
            />
          </FormRow>

          <SwitchField
            label="Require an initial deposit"
            checked={deposit.enabled}
            disabled={disabled}
            onChange={(enabled) => patchDeposit({ enabled })}
          />
          {deposit.enabled && (
            <FormRow>
              <AmountRuleFields
                value={deposit}
                currency={currency}
                typeLabel="Deposit type"
                valueLabel="Deposit value"
                disabled={disabled}
                onChange={(rule) => patchDeposit(rule)}
              />
              <DateField
                label="Deposit due date"
                value={deposit.dueDate}
                disabled={disabled}
                onChange={(dueDate) => patchDeposit({ dueDate })}
              />
            </FormRow>
          )}

          <SwitchField
            label="Allow installments"
            checked={installments.enabled}
            disabled={disabled}
            onChange={(enabled) => patchInstallments({ enabled })}
          />
          {installments.enabled && (
            <div className="cfo-config-form__nested">
              <p className="cfo-config-form__hint">
                Fixed amounts plus the deposit must not exceed the total; percentages must not exceed 100%.
              </p>

              <SwitchField
                label="Deferred start (first installment becomes due only after the deferral period)"
                checked={installments.deferred.enabled}
                disabled={disabled}
                onChange={(enabled) => patchDeferred({ enabled })}
              />
              {installments.deferred.enabled && (
                <FormRow>
                  <NullableNumberField
                    label="Days after registration"
                    value={installments.deferred.startDaysAfterRegistration}
                    disabled={disabled}
                    onChange={(startDaysAfterRegistration) =>
                      patchDeferred({ startDaysAfterRegistration, startDate: startDaysAfterRegistration === null ? installments.deferred.startDate : null })
                    }
                  />
                  <span className="cfo-config-form__or">or</span>
                  <DateField
                    label="Fixed start date"
                    value={installments.deferred.startDate}
                    disabled={disabled}
                    onChange={(startDate) =>
                      patchDeferred({ startDate, startDaysAfterRegistration: startDate === null ? installments.deferred.startDaysAfterRegistration : null })
                    }
                  />
                </FormRow>
              )}

              <RowList<Installment>
                items={installments.items}
                disabled={disabled}
                addLabel="Add installment"
                empty="No installments yet."
                create={() => ({ _id: newId("inst"), name: "", amountType: "fixed", value: 0, dueDate: null })}
                onChange={(items) => patchInstallments({ items })}
                renderRow={(row, update) => (
                  <FormRow>
                    <TextField label="Installment name" required value={row.name} disabled={disabled} onChange={(name) => update({ name })} />
                    <AmountRuleFields
                      value={row}
                      currency={currency}
                      required
                      disabled={disabled}
                      onChange={(rule) => update(rule)}
                    />
                    <DateField label="Due date" value={row.dueDate} disabled={disabled} onChange={(dueDate) => update({ dueDate })} />
                  </FormRow>
                )}
              />
            </div>
          )}
        </>
      )}

      {config.planType === "recurring" && (
        <>
          <FormRow>
            <NumberField
              label="Amount per cycle"
              required
              value={recurring.amount}
              disabled={disabled}
              step={0.01}
              addonAfter={currency}
              onChange={(amount) => patchRecurring({ amount })}
            />
            <Form.Item label="Billing cycle">
              <Select
                value={recurring.billingCycle}
                disabled={disabled}
                options={BILLING_CYCLES}
                onChange={(billingCycle) => patchRecurring({ billingCycle })}
              />
            </Form.Item>
            <NullableNumberField
              label="Number of cycles (blank = open ended)"
              min={1}
              value={recurring.numberOfCycles}
              disabled={disabled}
              onChange={(numberOfCycles) => patchRecurring({ numberOfCycles })}
            />
          </FormRow>
          <FormRow>
            <DateField label="Start date" value={recurring.startDate} disabled={disabled} onChange={(startDate) => patchRecurring({ startDate })} />
            <DateField label="End date" value={recurring.endDate} disabled={disabled} onChange={(endDate) => patchRecurring({ endDate })} />
            <Form.Item label="Auto-pay with card on file">
              <Switch checked={recurring.autoPay} disabled={disabled} onChange={(autoPay) => patchRecurring({ autoPay })} />
            </Form.Item>
          </FormRow>
        </>
      )}
    </>
  );
};

export default PlanSection;
