import React, { useMemo } from "react";
import { Modal, Table } from "antd";
import moment from "moment";
import { loadCachedUsers } from "../utils/rows";

interface Props {
  open: boolean;
  changelog?: Record<string, any> | null;
  users?: any[];
  onClose: () => void;
}

const toEntries = (changelog: Record<string, any>, users: any[]) =>
  Object.keys(changelog || {})
    .map((timestamp) => {
      const entry = changelog[timestamp];
      const user = users?.find((u) => u.id === entry?.userId?.toString());
      const userName = user
        ? `${user.firstName || ""} ${user.lastName || ""}`.trim() || user.beamId || "Unknown User"
        : entry?.userId || "Unknown User";
      return {
        key: timestamp,
        timestamp: Number(timestamp),
        timestampFormatted: moment(Number(timestamp)).format("YYYY-MM-DD HH:mm"),
        userName,
        message: entry?.message || "",
      };
    })
    .sort((a, b) => b.timestamp - a.timestamp);

const COLUMNS = [
  {
    title: "Timestamp",
    key: "timestamp",
    dataIndex: "timestampFormatted",
    sorter: (a, b) => a.timestamp - b.timestamp,
    defaultSortOrder: "descend" as const,
  },
  {
    title: "User",
    key: "userName",
    dataIndex: "userName",
    sorter: (a, b) => `${a.userName}`.localeCompare(`${b.userName}`),
  },
  { title: "Message", key: "message", dataIndex: "message" },
];

const HistoryModal = ({ open, changelog, users, onClose }: Props) => {
  const dataSource = useMemo(
    () => (changelog ? toEntries(changelog, users || loadCachedUsers()) : []),
    [changelog, users]
  );

  return (
    <Modal title="Change History" open={open} onCancel={onClose} footer={null} width={800}>
      <Table dataSource={dataSource} columns={COLUMNS} pagination={false} scroll={{ y: 400 }} />
    </Modal>
  );
};

export default HistoryModal;
