import React, { useEffect, useState } from "react";
import { Table, Select, DatePicker, TimePicker, Button, Space, Modal } from "antd";
import { PlusOutlined, DeleteOutlined } from "@ant-design/icons";
import dayjs from "dayjs";
import { useDispatch, useSelector } from "react-redux";
import moment from "moment";
import { ExtendedBioTopics, SocketTopics, UserTopics } from "../../constants/enums";
import useSocketActions from "../../hooks/socketActions";
import { getAdminRolesTopic } from "../../hooks/MQTTConstants";
import { PERMISSION_TYPES } from "../../utils/PageTypes";
import { formatForRedis } from "../../utils/appUtil";
import { GET_AGGREGATE } from "../../reducers/reducer";
import { RootState } from "../../reducers/rootReducer";


const createEmptyService = () => ({
    key: Date.now() + Math.random(),
    projectId: "", // store id of selected project (service)
    deadlineDate: null, // user-selected date
    deadlineTime: null, // user-selected time
    intakeStaffId: "", // store id of selected intake staff
    fulfillmentStaffId: "", // store id of selected fulfillment staff
    schedule: "",
    scheduleDate: null, // scheduled date (for now/next)
    scheduleTime: null, // scheduled time (for now/next)
    included: true, // new property to track inclusion
});

const createEmptyCategory = () => ({
    key: Date.now() + Math.random(),
    categoryId: "", // store _id of selected category
    services: [createEmptyService()],
});

const CategoryServiceTable = (props: any) => {
    const { placeholder, options, socket, onServiceChange, disabled } = props;

    console.log("disabled", disabled);

    const dispatch = useDispatch();
    const queryParams = new URLSearchParams(window.location.search);

    const [data, setData] = useState([createEmptyCategory()]);
    const [editingRow, setEditingRow] = useState({ catIdx: null, svcIdx: null });
    const [schedulePicker, setSchedulePicker] = useState({ catIdx: null, svcIdx: null });
    const [tempScheduleDate, setTempScheduleDate] = useState(null);
    const [tempScheduleTime, setTempScheduleTime] = useState(null);
    const { getUserRequestPayload } = useSocketActions();
    const [categories, setCategories] = useState([]);
    const [projects, setProjects] = useState([]);
    const [users, setUsers] = useState([]);
    const [buildings, setBuildings] = useState<string[]>([]);
    const [selectedBuilding, setSelectedBuilding] = useState<string>("");
    const { projects: projectsData, encrypted_token, page } = useSelector((state: RootState) => state.auth);

    const getUsersRoles = (userId, serviceId) => {
        socket.publishToServiceIdSurvey(
            SocketTopics.SurveyTopics,
            UserTopics.SearchInUser,
            getUserRequestPayload(userId, "$", "$..persistent.static.admin.role"),
            getAdminRolesTopic(localStorage.getItem('CID')), // need to decice
            serviceId
        );

        socket.subscribeToSurvey(
            SocketTopics.SurveyTopics,
            getAdminRolesTopic(localStorage.getItem('CID')), // need to decice
            (response) => {

                if (response) {
                    const staffRole = response.data?.[0]?.[0]?.filter(
                        (x: any) =>
                            x.permissions.includes(PERMISSION_TYPES.Cad)
                    );

                    getUsersByRole(staffRole, serviceId);
                }
            }
        );
    }

    const getUsersByRole = (userRoles, serviceId) => {

        let searchQuery = `@serviceId:{'${formatForRedis(serviceId)}'}`;

        const rolesQuery = userRoles.map((y: any) => {
            return `@roleId === '${y._id}'`;
        });

        let expression = `exists(@roleId) && (${rolesQuery.join("||")})`;

        const userRequest: any = {
            select: {
                index: {
                    searchIndex: `${process.env.REACT_APP_ECO_SYSTEM}:userNameIndex`,
                    searchQuery,
                    searchOptions: "TIMEOUT 5000",
                },
                load: {
                    id: "$.objectId",
                    live: "$.persistent.static.live",
                    roleId: "$..admin.profile.roleId",
                    beamId: "$..persistent.static.live.beamIds",
                    createdAt: '$.persistent.static.metadata.createdAt',
                },
            },
            apply: {
                expression: "",
                name: "",
            },
            sortBy: {
                properties: [
                    {
                        field: '@createdAt',
                        order: 'DESC',
                    },
                ],
                max: 1000,
            },
            result: {
                pagination: {
                    offset: 0,
                    limit: 1000,
                },
            },
            filter: {
                expression: expression
            },
            anyStatus: false,
        };
        // setLoading(true);

        dispatch(
            GET_AGGREGATE({
                requestData: userRequest,
                callback: (response) => {
                    const users = response?.map((user) => {
                        return {
                            id: user?.id,
                            beamId: user?.beamId?.length ? user?.beamId[0] : `${user?.live?.profile?.firstName}.${user?.live?.profile?.lastName}`,
                            name: `${user?.live?.profile?.firstName} ${user?.live?.profile?.lastName}`,
                        }
                    });

                    setUsers(users || []);
                },
            })
        );
    };

    // Fetch buildings from report config
    const fetchBuildings = (userId, serviceId) => {
        if (!userId || !serviceId || !socket?.client) return;

        socket.publishToServiceIdSurvey(
            SocketTopics.SurveyTopics,
            UserTopics.SearchInUser,
            getUserRequestPayload(
                userId,
                "$",
                "$.persistent.static.admin.reportManagement"
            ),
            ExtendedBioTopics.GetReportManagementBio,
            serviceId
        );

        socket.subscribeToSurvey(
            SocketTopics.SurveyTopics,
            ExtendedBioTopics.GetReportManagementBio,
            (resp) => {
                try {
                    const reportConfigData = resp?.data?.[0]?.[0] || {};
                    const configs = reportConfigData.reportConfig || [];

                    // Get all unique building names from all configs
                    const allBuildings: string[] = [];
                    configs.forEach((config: any) => {
                        if (config.buildings && Array.isArray(config.buildings)) {
                            config.buildings.forEach((building: any) => {
                                if (building.name && !allBuildings.includes(building.name)) {
                                    allBuildings.push(building.name);
                                }
                            });
                        }
                    });

                    setBuildings(allBuildings);
                    console.log("Buildings loaded:", allBuildings);
                } catch (error) {
                    console.error("Error parsing report config:", error);
                }
            }
        );
    };

    useEffect(() => {
        if (socket?.client) {

            let userId = queryParams.get("userId");
            let serviceId = queryParams.get("serviceId");
            if (queryParams.get("token")) {
                serviceId = encrypted_token?.cudbServiceId;
                userId = projectsData?.adminUserId;
            }

            if (!serviceId) {
                serviceId = projectsData?.userServiceId;
            }

            fetchBuildings(userId, serviceId);

            getUsersRoles(userId, serviceId);
            socket.publishToServiceIdSurvey(
                SocketTopics.SurveyTopics,
                UserTopics.SearchInUser,
                getUserRequestPayload(
                    userId,
                    "$",
                    "$.persistent.static.admin.project"
                ),
                ExtendedBioTopics.GetUserBio,
                serviceId
            );
            socket.subscribeToSurvey(
                SocketTopics.SurveyTopics,
                ExtendedBioTopics.GetUserBio,
                (resp) => {
                    const respProjects = Object.values(resp?.data[0][0]?.items || {}) || [];
                    const respCategories = resp?.data[0][0]?.types || [];
                    setProjects(respProjects);
                    setCategories(respCategories);
                }
            );
        }
    }, [socket?.client])

    useEffect(() => {

        if (page) {
            const data = page?.persistent?.static?.profile?.unstructuredAttributes['undefined'];
            Object.keys(data)?.map(key => {
                if (data[key]?.length && data[key][0]?.type === 'service') {
                    const withParsedDates = data[key].map(cat => ({
                        ...cat,
                        services: cat.services.map(svc => ({
                            ...svc,
                            scheduleDate: svc.scheduleDate ? moment(svc.scheduleDate, "YYYY-MM-DD") : null,
                            scheduleTime: svc.scheduleTime ? moment(svc.scheduleTime, "HH:mm") : null,
                            deadlineDate: svc.deadlineDate ? moment(svc.deadlineDate, "YYYY-MM-DD") : null,
                            deadlineTime: svc.deadlineTime ? moment(svc.deadlineTime, "HH:mm") : null,
                        }))
                    }));
                    setData(withParsedDates);

                    // Load buildingName from first category if available
                    if (withParsedDates.length > 0 && withParsedDates[0].buildingName) {
                        setSelectedBuilding(withParsedDates[0].buildingName);
                    }
                }
            })
        } else if (Array.isArray(options) && options.length > 0) {
            if (!disabled) {
                const withIncluded = options.map(cat => ({
                    ...cat,
                    services: cat.services.map(svc => ({ ...svc, included: false }))
                }));
                setData(withIncluded);

                // Load buildingName from first category if available
                if (withIncluded.length > 0 && withIncluded[0].buildingName) {
                    setSelectedBuilding(withIncluded[0].buildingName);
                }
            } else {
                setData(options);

                // Load buildingName from first category if available
                if (options.length > 0 && options[0].buildingName) {
                    setSelectedBuilding(options[0].buildingName);
                }
            }
        }

    }, [options, page]);

    useEffect(() => {
        // Enrich data with project, category, and staff names/beamId before passing to onServiceChange
        const enrichedData = data.map(cat => {
            const categoryObj = categories.find(c => c._id === cat.categoryId);
            return {
                ...cat,
                type: 'service',
                categoryName: categoryObj ? categoryObj.name : '',
                buildingName: selectedBuilding, // Add buildingName to each category
                services: (disabled
                    ? cat.services
                    : cat.services.filter(svc => svc.included)
                ).map(svc => {
                    const projectObj = projects.find(p => p._id === svc.projectId);
                    const intakeStaffObj = users.find(u => u.id === svc.intakeStaffId);
                    const fulfillmentStaffObj = users.find(u => u.id === svc.fulfillmentStaffId);
                    return {
                        ...svc,
                        projectName: projectObj ? projectObj.name : '',
                        intakeStaffName: intakeStaffObj ? intakeStaffObj.name : '',
                        intakeStaffBeamId: intakeStaffObj ? intakeStaffObj.beamId : '',
                        fulfillmentStaffName: fulfillmentStaffObj ? fulfillmentStaffObj.name : '',
                        fulfillmentStaffBeamId: fulfillmentStaffObj ? fulfillmentStaffObj.beamId : '',
                        scheduleDate: svc.scheduleDate ? dayjs(svc.scheduleDate).format('YYYY-MM-DD') : '',
                        scheduleTime: svc.scheduleTime ? (typeof svc.scheduleTime === 'string' ? dayjs(`1970-01-01 ${svc.scheduleTime}`).format('HH:mm') : dayjs(svc.scheduleTime).format('HH:mm')) : '',
                        deadlineDate: svc.deadlineDate ? dayjs(svc.deadlineDate).format('YYYY-MM-DD') : '',
                        deadlineTime: svc.deadlineTime ? dayjs(svc.deadlineTime).format('HH:mm') : '',
                    };
                })
            };
        });
        onServiceChange(enrichedData);
    }, [data, disabled, selectedBuilding]);

    const handleCategoryChange = (catIdx, categoryId) => {
        setData(current =>
            current.map((cat, idx) =>
                idx === catIdx
                    ? {
                        ...cat,
                        categoryId,
                        services: cat.services.map(svc => ({ ...svc, projectId: "" }))
                    }
                    : cat
            )
        );
    };

    const addCategory = () => setData(current => [...current, createEmptyCategory()]);
    const removeCategory = idx => setData(current => current.filter((_, i) => i !== idx));

    const handleCategoryServiceChange = (catIdx, svcIdx, field, value) => {
        setData(current => {
            const newData = current.map((cat, cIdx) =>
                cIdx === catIdx
                    ? {
                        ...cat,
                        services: cat.services.map((svc, sIdx) =>
                            sIdx === svcIdx ? { ...svc, [field]: value } : svc
                        ),
                    }
                    : cat
            );
            return newData;
        });
    };

    const handleAddService = catIdx => {
        setData(current =>
            current.map((cat, idx) =>
                idx === catIdx
                    ? { ...cat, services: [...cat.services, createEmptyService()] }
                    : cat
            )
        );
    };
    const handleRemoveService = (catIdx, svcIdx) => {
        setData(current =>
            current.map((cat, idx) =>
                idx === catIdx
                    ? { ...cat, services: cat.services.filter((_, sIdx) => sIdx !== svcIdx) }
                    : cat
            )
        );
    };

    const handleServiceIncludedChange = (catIdx, svcIdx, checked) => {
        setData(current =>
            current.map((cat, cIdx) =>
                cIdx === catIdx
                    ? {
                        ...cat,
                        services: cat.services.map((svc, sIdx) =>
                            sIdx === svcIdx ? { ...svc, included: checked } : svc
                        ),
                    }
                    : cat
            )
        );
    };

    // Table rendering
    const rows = [];
    data.forEach((cat, catIdx) => {
        cat.services.forEach((svc, svcIdx) => {
            const isEditing =
                editingRow.catIdx === catIdx && editingRow.svcIdx === svcIdx &&
                svc.schedule === "Schedule Next";

            // If user just picked date or time, and both are set, disable editing
            if (isEditing && svc.deadlineDate && svc.deadlineTime) {
                setTimeout(() => setEditingRow({ catIdx: null, svcIdx: null }), 0);
            }

            rows.push({
                key: `${cat.key}-${svc.key}`,
                category: svcIdx === 0 ? (
                    <div style={{ display: "flex", alignItems: "center", gap: 8 }}>
                        <Select
                            disabled={!disabled}
                            value={cat.categoryId}
                            onChange={val => handleCategoryChange(catIdx, val)}
                            placeholder="Select category"
                            style={{ minWidth: 120 }}
                            size="small"
                        >
                            {categories.map(catOpt => (
                                <Select.Option key={catOpt._id} value={catOpt._id}>
                                    {catOpt.name}
                                </Select.Option>
                            ))}
                        </Select>
                        <Button
                            icon={<DeleteOutlined />}
                            size="small"
                            type="link"
                            danger
                            onClick={() => removeCategory(catIdx)}
                            disabled={!disabled || data.length === 1}
                        />
                    </div>
                ) : "",
                categoryRowSpan: svcIdx === 0 ? cat.services.length : 0,
                project: (
                    <div style={{ display: 'flex', alignItems: 'center' }}>
                        <input
                            type="checkbox"
                            disabled={disabled}
                            checked={svc.included}
                            onChange={e => handleServiceIncludedChange(catIdx, svcIdx, e.target.checked)}
                            style={{ marginRight: 8 }}
                        />
                        <Select
                            value={svc.projectId}
                            onChange={val => {
                                handleCategoryServiceChange(catIdx, svcIdx, "projectId", val);
                            }}
                            placeholder="Select service"
                            style={{ minWidth: 180 }}
                            size="small"
                            disabled={!disabled || !cat.categoryId}
                        >
                            {projects
                                .filter(proj => proj.typeId === cat.categoryId)
                                .map(proj => (
                                    <Select.Option key={proj._id} value={proj._id}>
                                        {proj.name}
                                    </Select.Option>
                                ))}
                        </Select>
                    </div>
                ),
                deadlineDate: (
                    <DatePicker
                        value={svc.deadlineDate}
                        onChange={val => handleCategoryServiceChange(catIdx, svcIdx, "deadlineDate", val)}
                        placeholder="Pick date"
                        disabled={disabled || !svc.included}
                    />
                ),
                deadlineTime: (
                    <TimePicker
                        value={svc.deadlineTime}
                        onChange={val => handleCategoryServiceChange(catIdx, svcIdx, "deadlineTime", val)}
                        placeholder="Pick time"
                        disabled={disabled || !svc.included}
                    />
                ),
                intakeStaff: (
                    <Select
                        value={svc.intakeStaffId}
                        onChange={val => handleCategoryServiceChange(catIdx, svcIdx, "intakeStaffId", val)}
                        style={{ width: 110 }}
                        placeholder="Select staff"
                        disabled={disabled || !svc.included}
                    >
                        {users.map(user => (
                            <Select.Option key={user.id} value={user.id}>{user.name}</Select.Option>
                        ))}
                    </Select>
                ),
                fulfillmentStaff: (
                    <Select
                        value={svc.fulfillmentStaffId}
                        onChange={val => handleCategoryServiceChange(catIdx, svcIdx, "fulfillmentStaffId", val)}
                        style={{ width: 110 }}
                        placeholder="Select staff"
                        disabled={disabled || !svc.included}
                    >
                        {users.map(user => (
                            <Select.Option key={user.id} value={user.id}>{user.name}</Select.Option>
                        ))}
                    </Select>
                ),
                actions: (
                    <Space>
                        <Button
                            type={svc.schedule === "Schedule Now" ? "primary" : "default"}
                            size="small"
                            onClick={() => {
                                const now = moment();
                                handleCategoryServiceChange(catIdx, svcIdx, "schedule", "Schedule Now");
                                handleCategoryServiceChange(catIdx, svcIdx, "scheduleDate", now.format('YYYY-MM-DD'));
                                handleCategoryServiceChange(catIdx, svcIdx, "scheduleTime", now.format('HH:mm'));
                                setSchedulePicker({ catIdx: null, svcIdx: null });
                            }}
                            disabled={disabled || !svc.included}
                        >
                            Schedule Now
                        </Button>
                        <Button
                            type={
                                svc.schedule === "Schedule Later" || svc.schedule === "Schedule Next"
                                    ? "primary"
                                    : "default"
                            }
                            size="small"
                            onClick={() => {
                                handleCategoryServiceChange(catIdx, svcIdx, "schedule", "Schedule Later");
                                setSchedulePicker({ catIdx, svcIdx });
                                setTempScheduleDate(svc.scheduleDate ? moment(svc.scheduleDate, "YYYY-MM-DD") : null);
                                setTempScheduleTime(svc.scheduleTime ? moment(svc.scheduleTime, "HH:mm") : null);
                            }}
                            disabled={disabled || !svc.included}
                        >
                            Schedule Later
                        </Button>
                        <Button
                            type="link"
                            icon={<DeleteOutlined />}
                            danger
                            disabled={!disabled || cat.services.length === 1}
                            onClick={() => handleRemoveService(catIdx, svcIdx)}
                        />
                        {svcIdx === cat.services.length - 1 && (
                            <Button
                                type="dashed"
                                icon={<PlusOutlined />}
                                onClick={() => handleAddService(catIdx)}
                                size="small"
                                disabled={!disabled}
                            >
                                Add
                            </Button>
                        )}
                        {/* Schedule Later Picker Modal */}
                        {schedulePicker.catIdx === catIdx && schedulePicker.svcIdx === svcIdx && (
                            <Modal
                                title="Select Schedule Date & Time"
                                visible={true}
                                onOk={() => {
                                    handleCategoryServiceChange(catIdx, svcIdx, "scheduleDate", tempScheduleDate);
                                    handleCategoryServiceChange(catIdx, svcIdx, "scheduleTime", tempScheduleTime);
                                    setSchedulePicker({ catIdx: null, svcIdx: null });
                                }}
                                onCancel={() => setSchedulePicker({ catIdx: null, svcIdx: null })}
                                okButtonProps={{ disabled: !tempScheduleDate || !tempScheduleTime || disabled }}
                                cancelButtonProps={{ disabled }}
                            >
                                <DatePicker
                                    value={tempScheduleDate}
                                    onChange={setTempScheduleDate}
                                    style={{ width: '100%', marginBottom: 8 }}
                                    placeholder="Pick schedule date"
                                    disabled={disabled}
                                />
                                <TimePicker
                                    value={tempScheduleTime}
                                    onChange={setTempScheduleTime}
                                    style={{ width: '100%' }}
                                    placeholder="Pick schedule time"
                                    disabled={disabled}
                                />
                            </Modal>
                        )}
                    </Space>
                ),
                scheduleDate: svc.scheduleDate ? dayjs(svc.scheduleDate).format("YYYY-MM-DD") : '',
                scheduleTime: svc.scheduleTime ? dayjs(svc.scheduleTime).format("HH:mm") : '',
            });
        });
    });

    // Table columns
    const columns = [
        {
            title: "Category",
            dataIndex: "category",
            render: (text, row, idx) => ({
                children: text,
                props: {
                    rowSpan: row.categoryRowSpan,
                },
            }),
        },
        {
            title: "Service",
            dataIndex: "project",
        },
        { title: "Date", dataIndex: "deadlineDate" },
        { title: "Time", dataIndex: "deadlineTime" },
        { title: "Intake Staff", dataIndex: "intakeStaff" },
        { title: "Fulfillment Staff", dataIndex: "fulfillmentStaff" },
        { title: "Actions", dataIndex: "actions" },
    ];

    return (
        <div style={{ overflowX: 'auto' }}>
            {buildings.length > 0 && (
                <div style={{ marginBottom: 16 }}>
                    <label style={{ display: 'block', marginBottom: 8, fontWeight: 500, fontSize: 14 }}>
                        Building
                    </label>
                    <Select
                        value={selectedBuilding || undefined}
                        onChange={(value) => setSelectedBuilding(value || "")}
                        onClear={() => setSelectedBuilding("")}
                        placeholder="Select Building"
                        style={{ width: '100%', maxWidth: 300 }}
                        allowClear
                        disabled={disabled}
                    >
                        {buildings.map((building) => (
                            <Select.Option key={building} value={building}>
                                {building}
                            </Select.Option>
                        ))}
                    </Select>
                </div>
            )}
            <Table
                columns={columns}
                dataSource={rows}
                pagination={false}
                bordered
                scroll={{ x: 'max-content' }}
            />
            <Button
                type="dashed"
                icon={<PlusOutlined />}
                style={{ marginTop: 16 }}
                onClick={addCategory}
                block
                disabled={!disabled}
            >
                Add Category
            </Button>
        </div>
    );
};

export default CategoryServiceTable;

