import React, { FC, useEffect, useState } from "react";
import {
  Button,
  Checkbox,
  Col,
  Form,
  Input,
  InputNumber,
  Modal,
  Radio,
  Row,
  Select,
  Slider,
  Switch,
  TimePicker,
} from "antd";
import { DeleteOutlined, PlusOutlined } from "@ant-design/icons";
import moment from "moment";
import { createActivity, updateActivity } from "services/apis/collections/aiSchedulerApis";
import { getErrorMessage } from "services/apis/aiSchedulerClient";
import {
  Day,
  DAY_ORDER,
  OrgSettings,
  Requirement,
  SchedActivity,
  SchedResource,
} from "services/apis/aiSchedulerTypes";
import { pushNotification } from "utils/notifications";
import AvailabilityWindowsEditor, {
  formToWindows,
  windowsToForm,
} from "../shared/AvailabilityWindowsEditor";

const DAY_OPTIONS = DAY_ORDER.map((d) => ({
  label: d.charAt(0).toUpperCase() + d.slice(1, 3),
  value: d,
}));

interface RequirementFormValue {
  mode: "pin" | "match";
  resourceId?: string;
  count?: number;
  kind?: string[];
  tagsAll?: string[];
  tagsAny?: string[];
  capacityIsEnrollment?: boolean;
  capacityAtLeast?: number;
}

const requirementsToForm = (requirements?: Requirement[]): RequirementFormValue[] =>
  (requirements || []).map((r) => ({
    mode: r.resourceId ? "pin" : "match",
    resourceId: r.resourceId,
    count: r.count,
    kind: r.kind ? [r.kind] : undefined,
    tagsAll: r.tagsAll || [],
    tagsAny: r.tagsAny || [],
    capacityIsEnrollment: r.capacityAtLeast === "enrollment",
    capacityAtLeast:
      typeof r.capacityAtLeast === "number" ? r.capacityAtLeast : undefined,
  }));

const formToRequirements = (values?: RequirementFormValue[]): Requirement[] =>
  (values || []).map((v) => {
    if (v.mode === "pin") {
      const req: Requirement = { resourceId: v.resourceId };
      if (v.count && v.count > 1) req.count = v.count;
      return req;
    }
    const req: Requirement = { kind: v.kind?.[0] };
    if (v.tagsAll?.length) req.tagsAll = v.tagsAll;
    if (v.tagsAny?.length) req.tagsAny = v.tagsAny;
    if (v.capacityIsEnrollment) req.capacityAtLeast = "enrollment";
    else if (v.capacityAtLeast) req.capacityAtLeast = v.capacityAtLeast;
    return req;
  });

const ActivityFormModal: FC<{
  visible: boolean;
  orgId: string;
  activity?: SchedActivity; // undefined = create
  activities: SchedActivity[];
  resources: SchedResource[];
  settings?: OrgSettings;
  onClose: () => void;
  onSaved: () => void;
}> = ({ visible, orgId, activity, activities, resources, settings, onClose, onSaved }) => {
  const [form] = Form.useForm();
  const [saving, setSaving] = useState(false);

  useEffect(() => {
    if (visible) {
      form.setFieldsValue({
        name: activity?.name,
        durationMinutes: activity?.durationMinutes ?? settings?.slotMinutes ?? 60,
        countPerWeek: activity?.countPerWeek ?? 1,
        enrollment: activity?.enrollment,
        enrollmentMin: activity?.enrollmentMin,
        priority: activity?.priority ?? 50,
        active: activity?.active !== false,
        allowedDays: activity?.allowedDays || [],
        preferredLocations: activity?.preferredLocations || [],
        noOverlapWith: activity?.noOverlapWith || [],
        requirements: requirementsToForm(activity?.requirements),
        window: windowsToForm(activity?.window),
        pinned: (activity?.pinned || []).map((p) => ({
          occurrence: p.occurrence,
          day: p.day,
          start: p.start ? moment(p.start, "HH:mm") : undefined,
        })),
      });
    }
  }, [visible, activity, settings, form]);

  const resourceOptions = resources
    .filter((r) => r.id)
    .map((r) => ({ label: `${r.name} (${r.kind})`, value: r.id as string }));

  const knownKinds = Array.from(new Set(resources.map((r) => r.kind).filter(Boolean)));
  const knownLocations = Array.from(
    new Set(resources.map((r) => r.location).filter(Boolean))
  ) as string[];
  const otherActivityOptions = activities
    .filter((a) => a.id && a.id !== activity?.id)
    .map((a) => ({ label: a.name, value: a.id as string }));

  const handleSave = async () => {
    try {
      const values = await form.validateFields();
      const payload: SchedActivity = {
        name: values.name,
        durationMinutes: values.durationMinutes,
        countPerWeek: values.countPerWeek,
        priority: values.priority,
        active: values.active,
        requirements: formToRequirements(values.requirements),
        window: formToWindows(values.window),
      };
      if (values.enrollment) payload.enrollment = values.enrollment;
      if (values.enrollmentMin) payload.enrollmentMin = values.enrollmentMin;
      if (values.allowedDays?.length) payload.allowedDays = values.allowedDays;
      if (values.preferredLocations?.length) {
        payload.preferredLocations = values.preferredLocations;
      }
      if (values.noOverlapWith?.length) payload.noOverlapWith = values.noOverlapWith;
      const pinned = (values.pinned || [])
        .filter((p: any) => p && p.day && p.start && p.occurrence !== undefined)
        .map((p: any) => ({
          occurrence: p.occurrence,
          day: p.day as Day,
          start: p.start.format("HH:mm"),
        }));
      if (pinned.length) payload.pinned = pinned;

      setSaving(true);
      if (activity?.id) {
        await updateActivity(orgId, activity.id, payload);
        pushNotification("Activity updated", "success", "TOP_CENTER", 2000);
      } else {
        await createActivity(orgId, payload);
        pushNotification("Activity created", "success", "TOP_CENTER", 2000);
      }
      onSaved();
      onClose();
    } catch (e: any) {
      if (e?.errorFields) return;
      pushNotification(getErrorMessage(e), "error", "TOP_CENTER", 4000);
    } finally {
      setSaving(false);
    }
  };

  return (
    <Modal
      title={activity?.id ? `Edit ${activity.name}` : "New activity"}
      visible={visible}
      onCancel={onClose}
      width="680px"
      className="beam-modal"
      footer={[]}
      destroyOnClose
    >
      <Form
        className="auth-form"
        layout="vertical"
        form={form}
        requiredMark={false}
        preserve={false}
      >
        <Row gutter={12}>
          <Col span={12}>
            <Form.Item
              label="Name"
              name="name"
              rules={[{ required: true, message: "Name is required" }]}
            >
              <Input placeholder="e.g. MATH-101 Section A" />
            </Form.Item>
          </Col>
          <Col span={6}>
            <Form.Item
              label="Duration (min)"
              name="durationMinutes"
              rules={[{ required: true, message: "Required" }]}
            >
              <InputNumber
                min={settings?.slotMinutes || 5}
                step={settings?.slotMinutes || 5}
                style={{ width: "100%" }}
              />
            </Form.Item>
          </Col>
          <Col span={6}>
            <Form.Item
              label="Times / week"
              name="countPerWeek"
              rules={[{ required: true, message: "Required" }]}
            >
              <InputNumber min={1} max={21} style={{ width: "100%" }} />
            </Form.Item>
          </Col>
        </Row>

        <Row gutter={12}>
          <Col span={6}>
            <Form.Item label="Enrollment" name="enrollment">
              <InputNumber min={0} style={{ width: "100%" }} placeholder="—" />
            </Form.Item>
          </Col>
          <Col span={6}>
            <Form.Item label="Min enrollment" name="enrollmentMin">
              <InputNumber min={0} style={{ width: "100%" }} placeholder="—" />
            </Form.Item>
          </Col>
          <Col span={8}>
            <Form.Item
              label="Priority"
              name="priority"
              tooltip="Higher gets first pick when preferences collide."
            >
              <Slider min={0} max={100} />
            </Form.Item>
          </Col>
          <Col span={4}>
            <Form.Item label="Active" name="active" valuePropName="checked">
              <Switch />
            </Form.Item>
          </Col>
        </Row>

        <Form.Item
          label="Allowed days"
          name="allowedDays"
          tooltip="Restrict this activity to specific weekdays. Empty = any configured day."
        >
          <Checkbox.Group options={DAY_OPTIONS} />
        </Form.Item>

        <Row gutter={12}>
          <Col span={12}>
            <Form.Item
              label="Preferred buildings"
              name="preferredLocations"
              tooltip="Soft preference — the solver favors these locations."
            >
              <Select
                mode="tags"
                placeholder="e.g. Engineering"
                options={knownLocations.map((l) => ({ label: l, value: l }))}
              />
            </Form.Item>
          </Col>
          <Col span={12}>
            <Form.Item
              label="Never overlap with"
              name="noOverlapWith"
              tooltip="Co-requisites: same students attend both, so they never run at the same time."
            >
              <Select
                mode="multiple"
                allowClear
                placeholder="Select activities"
                options={otherActivityOptions}
                filterOption={(input, option) =>
                  (option?.label ?? "")
                    .toString()
                    .toLowerCase()
                    .includes(input.toLowerCase())
                }
              />
            </Form.Item>
          </Col>
        </Row>

        <div className="ant-form-item-label" style={{ paddingBottom: 4 }}>
          <label>Requirements</label>
        </div>
        <p style={{ color: "#8c8c8c", marginBottom: 8, fontSize: 12 }}>
          Each requirement either pins one resource or describes an acceptable one and
          lets the solver choose.
        </p>
        <Form.List
          name="requirements"
          rules={[
            {
              validator: async (_, value) => {
                if (!value || value.length === 0) {
                  return Promise.reject(new Error("Add at least one requirement"));
                }
              },
            },
          ]}
        >
          {(fields, { add, remove }, { errors }) => (
            <>
              {fields.map((field) => (
                <div key={field.key} className="requirement-row">
                  <Row gutter={8} align="middle">
                    <Col flex="auto">
                      <Form.Item
                        name={[field.name, "mode"]}
                        fieldKey={[field.fieldKey, "mode"]}
                        initialValue="match"
                        style={{ marginBottom: 8 }}
                      >
                        <Radio.Group size="small">
                          <Radio.Button value="match">Match by kind</Radio.Button>
                          <Radio.Button value="pin">Pin specific resource</Radio.Button>
                        </Radio.Group>
                      </Form.Item>
                    </Col>
                    <Col>
                      <Button
                        type="text"
                        icon={<DeleteOutlined />}
                        onClick={() => remove(field.name)}
                      />
                    </Col>
                  </Row>
                  <Form.Item noStyle shouldUpdate>
                    {({ getFieldValue }) => {
                      const mode = getFieldValue(["requirements", field.name, "mode"]);
                      const pinnedResource = resources.find(
                        (r) =>
                          r.id === getFieldValue(["requirements", field.name, "resourceId"])
                      );
                      return mode === "pin" ? (
                        <Row gutter={8}>
                          <Col span={16}>
                            <Form.Item
                              name={[field.name, "resourceId"]}
                              fieldKey={[field.fieldKey, "resourceId"]}
                              rules={[{ required: true, message: "Pick a resource" }]}
                            >
                              <Select
                                showSearch
                                placeholder="Resource"
                                options={resourceOptions}
                                filterOption={(input, option) =>
                                  (option?.label ?? "")
                                    .toString()
                                    .toLowerCase()
                                    .includes(input.toLowerCase())
                                }
                              />
                            </Form.Item>
                          </Col>
                          {(pinnedResource?.quantity || 1) > 1 && (
                            <Col span={8}>
                              <Form.Item
                                name={[field.name, "count"]}
                                fieldKey={[field.fieldKey, "count"]}
                              >
                                <InputNumber
                                  min={1}
                                  max={pinnedResource?.quantity}
                                  placeholder="Units"
                                  style={{ width: "100%" }}
                                />
                              </Form.Item>
                            </Col>
                          )}
                        </Row>
                      ) : (
                        <>
                          <Row gutter={8}>
                            <Col span={8}>
                              <Form.Item
                                name={[field.name, "kind"]}
                                fieldKey={[field.fieldKey, "kind"]}
                                rules={[{ required: true, message: "Kind required" }]}
                              >
                                <Select
                                  mode="tags"
                                  placeholder="Kind (room…)"
                                  options={knownKinds.map((k) => ({ label: k, value: k }))}
                                  onChange={(value: string[]) => {
                                    if (value?.length > 1) {
                                      form.setFields([
                                        {
                                          name: ["requirements", field.name, "kind"],
                                          value: [value[value.length - 1]],
                                        },
                                      ]);
                                    }
                                  }}
                                />
                              </Form.Item>
                            </Col>
                            <Col span={8}>
                              <Form.Item
                                name={[field.name, "tagsAll"]}
                                fieldKey={[field.fieldKey, "tagsAll"]}
                              >
                                <Select mode="tags" placeholder="All of these tags" />
                              </Form.Item>
                            </Col>
                            <Col span={8}>
                              <Form.Item
                                name={[field.name, "tagsAny"]}
                                fieldKey={[field.fieldKey, "tagsAny"]}
                              >
                                <Select mode="tags" placeholder="Any of these tags" />
                              </Form.Item>
                            </Col>
                          </Row>
                          <Row gutter={8} align="middle">
                            <Col>
                              <Form.Item
                                name={[field.name, "capacityIsEnrollment"]}
                                fieldKey={[field.fieldKey, "capacityIsEnrollment"]}
                                valuePropName="checked"
                                style={{ marginBottom: 8 }}
                              >
                                <Checkbox>Capacity at least enrollment</Checkbox>
                              </Form.Item>
                            </Col>
                            <Col span={8}>
                              <Form.Item
                                noStyle
                                shouldUpdate
                              >
                                {({ getFieldValue: gfv }) =>
                                  !gfv([
                                    "requirements",
                                    field.name,
                                    "capacityIsEnrollment",
                                  ]) && (
                                    <Form.Item
                                      name={[field.name, "capacityAtLeast"]}
                                      fieldKey={[field.fieldKey, "capacityAtLeast"]}
                                      style={{ marginBottom: 8 }}
                                    >
                                      <InputNumber
                                        min={1}
                                        placeholder="Min capacity"
                                        style={{ width: "100%" }}
                                      />
                                    </Form.Item>
                                  )
                                }
                              </Form.Item>
                            </Col>
                          </Row>
                        </>
                      );
                    }}
                  </Form.Item>
                </div>
              ))}
              <Form.ErrorList errors={errors} />
              <Button
                type="dashed"
                block
                icon={<PlusOutlined />}
                onClick={() => add({ mode: "match" })}
              >
                Add requirement
              </Button>
            </>
          )}
        </Form.List>

        <div className="mt-3">
          <AvailabilityWindowsEditor
            name="window"
            label="Time window"
            helpText="When this activity may run. No windows = any time in the org day."
            slotMinutes={settings?.slotMinutes}
          />
        </div>

        <div className="ant-form-item-label mt-3" style={{ paddingBottom: 4 }}>
          <label>Pinned meetings</label>
        </div>
        <p style={{ color: "#8c8c8c", marginBottom: 8, fontSize: 12 }}>
          Lock a specific meeting to a slot before solving.
        </p>
        <Form.List name="pinned">
          {(fields, { add, remove }) => (
            <>
              {fields.map((field) => (
                <Row key={field.key} gutter={8} align="middle" style={{ marginBottom: 8 }}>
                  <Col span={7}>
                    <Form.Item
                      name={[field.name, "occurrence"]}
                      fieldKey={[field.fieldKey, "occurrence"]}
                      rules={[
                        { required: true, message: "Required" },
                        ({ getFieldValue }) => ({
                          validator(_, value) {
                            const count = getFieldValue("countPerWeek") || 1;
                            if (value === undefined || value < count) {
                              return Promise.resolve();
                            }
                            return Promise.reject(
                              new Error(`Must be below times/week (${count})`)
                            );
                          },
                        }),
                      ]}
                      style={{ marginBottom: 0 }}
                    >
                      <InputNumber min={0} placeholder="Occurrence #" style={{ width: "100%" }} />
                    </Form.Item>
                  </Col>
                  <Col span={7}>
                    <Form.Item
                      name={[field.name, "day"]}
                      fieldKey={[field.fieldKey, "day"]}
                      rules={[{ required: true, message: "Required" }]}
                      style={{ marginBottom: 0 }}
                    >
                      <Select
                        placeholder="Day"
                        options={(settings?.days || DAY_ORDER).map((d) => ({
                          label: d,
                          value: d,
                        }))}
                      />
                    </Form.Item>
                  </Col>
                  <Col span={7}>
                    <Form.Item
                      name={[field.name, "start"]}
                      fieldKey={[field.fieldKey, "start"]}
                      rules={[{ required: true, message: "Required" }]}
                      style={{ marginBottom: 0 }}
                    >
                      <TimePicker
                        format="HH:mm"
                        minuteStep={settings?.slotMinutes || 5}
                        placeholder="Start"
                        style={{ width: "100%" }}
                      />
                    </Form.Item>
                  </Col>
                  <Col span={3}>
                    <Button
                      type="text"
                      icon={<DeleteOutlined />}
                      onClick={() => remove(field.name)}
                    />
                  </Col>
                </Row>
              ))}
              <Button type="dashed" block icon={<PlusOutlined />} onClick={() => add()}>
                Pin a meeting
              </Button>
            </>
          )}
        </Form.List>

        <Form.Item className="action-grp mt-4">
          <Row>
            <Col span={14} className="pr-2">
              <Button
                loading={saving}
                className="beam-btn green-btn cover w-full"
                onClick={handleSave}
              >
                Save
              </Button>
            </Col>
            <Col span={10} className="pl-2">
              <Button className="beam-btn orange-btn bordered w-full" onClick={onClose}>
                Cancel
              </Button>
            </Col>
          </Row>
        </Form.Item>
      </Form>
    </Modal>
  );
};

export default ActivityFormModal;
