import React from "react";
import { Row, Col, Form } from "antd";
import ScheduleInput from "common/ScheduleInput";
import NumberInput from "common/NumberInput";
import { useDispatchPanel } from "../context";

const DispatchScheduleSection: React.FC = () => {
  const { webBooker, dispatchType, setDispatchType } = useDispatchPanel();

  return (
    <React.Fragment>
      <Row className="mt-3">
        <Col span={24}>
          <Form.Item
            name="dispatch"
            rules={[
              { required: true, message: "**Required Field" },
              {
                message: "**Required Field",
                validator: async (_, value) => {
                  if (
                    value?.value === "schedule" &&
                    (!value?.date || !value?.time)
                  ) {
                    return Promise.reject("**Required Field");
                  }
                },
              },
            ]}
          >
            <ScheduleInput
              placeholder="Select dispatch"
              dispatchOptions={[
                { id: "immediate", name: "Immediate" },
                { id: "schedule", name: "Schedule" },
              ]}
              onChange={(value: any) => {
                setDispatchType(value.value);
              }}
              is12hour={webBooker}
            />
          </Form.Item>
        </Col>
      </Row>

      {dispatchType === "schedule" && !webBooker && (
        <Row className="mt-3">
          <Col span={24}>
            <Form.Item
              name="leadTime"
              rules={[{ required: true, message: "**Required Field" }]}
            >
              <NumberInput
                placeholder={"Enter lead time"}
                onChange={(value: any) => {}}
              />
            </Form.Item>
          </Col>
        </Row>
      )}
    </React.Fragment>
  );
};

export default DispatchScheduleSection;
