import React from "react";
import { Button, Input, Modal, Popconfirm, Skeleton, Table, Tooltip } from "antd";
import type { TableProps } from "antd/es/table";
import {
  CopyOutlined,
  DeleteOutlined,
  EditOutlined,
  EyeOutlined,
  InboxOutlined,
  PlusOutlined,
  SearchOutlined,
} from "@ant-design/icons";
import "./medical-ui.scss";

/* ------------------------------------------------------------ PageHeader */

interface PageHeaderProps {
  title: string;
  subtitle?: React.ReactNode;
  breadcrumb?: string;
  search?: {
    value: string;
    onChange: (value: string) => void;
    placeholder?: string;
    loading?: boolean;
  };
  primaryAction?: { label: string; onClick: () => void; icon?: React.ReactNode };
  extra?: React.ReactNode;
}

export const PageHeader = ({
  title,
  subtitle,
  breadcrumb = "Home",
  search,
  primaryAction,
  extra,
}: PageHeaderProps) => (
  <div className="mx-page-header">
    <div className="mx-page-header__titles">
      <div className="mx-page-header__breadcrumb">
        {breadcrumb} / {title}
      </div>
      <h2>{title}</h2>
      {subtitle && <p>{subtitle}</p>}
    </div>
    <div className="mx-page-header__actions">
      {search && (
        <Input
          className="mx-page-header__search"
          allowClear
          prefix={<SearchOutlined />}
          placeholder={search.placeholder || `Search ${title.toLowerCase()}`}
          value={search.value}
          onChange={(e) => search.onChange(e.target.value)}
        />
      )}
      {extra}
      {primaryAction && (
        <Button
          className="mx-btn-primary"
          icon={primaryAction.icon ?? <PlusOutlined />}
          onClick={primaryAction.onClick}
        >
          {primaryAction.label}
        </Button>
      )}
    </div>
  </div>
);

/* ------------------------------------------------------------ EmptyState */

export const EmptyState = ({
  title,
  description,
  action,
  icon,
}: {
  title: string;
  description?: React.ReactNode;
  action?: { label: string; onClick: () => void };
  icon?: React.ReactNode;
}) => (
  <div className="mx-empty">
    <div className="mx-empty__icon">{icon ?? <InboxOutlined />}</div>
    <div className="mx-empty__title">{title}</div>
    {description && <div>{description}</div>}
    {action && (
      <Button className="mx-btn-primary mt-2" icon={<PlusOutlined />} onClick={action.onClick}>
        {action.label}
      </Button>
    )}
  </div>
);

/* --------------------------------------------------------- DataTableCard */

interface DataTableCardProps<T> extends TableProps<T> {
  loading?: boolean;
  /** Shown above the table, e.g. "12 locations". */
  caption?: React.ReactNode;
  toolbar?: React.ReactNode;
  empty?: React.ReactNode;
  clickable?: boolean;
}

/** Table in a card with a skeleton while loading and a real empty state. */
export function DataTableCard<T extends object>({
  loading,
  caption,
  toolbar,
  empty,
  clickable,
  dataSource,
  ...tableProps
}: DataTableCardProps<T>) {
  const firstLoad = loading && !(dataSource as any[])?.length;
  return (
    <div className={`mx-table-card ${clickable ? "mx-table-card--clickable" : ""}`}>
      {(caption || toolbar) && (
        <div className="mx-table-card__toolbar">
          <span>{caption}</span>
          {toolbar}
        </div>
      )}
      {firstLoad ? (
        <div style={{ padding: 16 }}>
          <Skeleton active paragraph={{ rows: 6 }} />
        </div>
      ) : (
        <Table<T>
          pagination={false}
          loading={loading}
          dataSource={dataSource}
          locale={{ emptyText: empty ?? <EmptyState title="Nothing here yet" /> }}
          {...tableProps}
        />
      )}
    </div>
  );
}

/* ------------------------------------------------------------ RowActions */

interface RowActionsProps {
  onView?: () => void;
  onEdit?: () => void;
  onCopy?: () => void;
  onDelete?: () => void;
  /** e.g. "Delete this location?" */
  deleteConfirm?: string;
}

export const RowActions = ({ onView, onEdit, onCopy, onDelete, deleteConfirm }: RowActionsProps) => (
  <span className="mx-row-actions" onClick={(e) => e.stopPropagation()}>
    {onView && (
      <Tooltip title="View">
        <Button size="small" icon={<EyeOutlined />} onClick={onView} />
      </Tooltip>
    )}
    {onEdit && (
      <Tooltip title="Edit">
        <Button size="small" icon={<EditOutlined />} onClick={onEdit} />
      </Tooltip>
    )}
    {onCopy && (
      <Tooltip title="Duplicate">
        <Button size="small" icon={<CopyOutlined />} onClick={onCopy} />
      </Tooltip>
    )}
    {onDelete && (
      <Popconfirm
        title={deleteConfirm || "Delete this item?"}
        okText="Delete"
        okButtonProps={{ danger: true }}
        cancelText="Keep"
        onConfirm={onDelete}
      >
        <Tooltip title="Delete">
          <Button size="small" className="mx-row-actions__danger" icon={<DeleteOutlined />} />
        </Tooltip>
      </Popconfirm>
    )}
  </span>
);

/* ------------------------------------------------------------- FormModal */

interface FormModalProps {
  open: boolean;
  title: React.ReactNode;
  subtitle?: React.ReactNode;
  onCancel: () => void;
  /** Usually `form.submit` so antd validation runs first. */
  onSubmit: () => void;
  saving?: boolean;
  okText?: string;
  width?: number | string;
  children: React.ReactNode;
  destroyOnClose?: boolean;
  footerExtra?: React.ReactNode;
}

/** Modal with a consistent header, scrollable body and Cancel/Save footer. */
export const FormModal = ({
  open,
  title,
  subtitle,
  onCancel,
  onSubmit,
  saving,
  okText = "Save",
  width = 560,
  children,
  destroyOnClose = true,
  footerExtra,
}: FormModalProps) => (
  <Modal
    open={open}
    title={title}
    width={width}
    className="beam-modal mx-modal"
    onCancel={onCancel}
    destroyOnClose={destroyOnClose}
    maskClosable={!saving}
    footer={[
      footerExtra && (
        <span key="extra" style={{ marginRight: "auto" }}>
          {footerExtra}
        </span>
      ),
      <Button key="cancel" className="mx-btn-secondary" onClick={onCancel} disabled={saving}>
        Cancel
      </Button>,
      <Button key="save" className="mx-btn-primary" loading={saving} onClick={onSubmit}>
        {okText}
      </Button>,
    ]}
  >
    {subtitle && <p className="mx-modal__subtitle">{subtitle}</p>}
    {children}
  </Modal>
);

