/** Case-insensitive match of `query` against any of the given fields. */
export const matchesSearch = (query: string, ...fields: any[]) => {
  const q = query.trim().toLowerCase();
  if (!q) return true;
  return fields.some((f) => `${f ?? ""}`.toLowerCase().includes(q));
};

const findScrollParent = (el: HTMLElement | null): HTMLElement | null => {
  let node = el?.parentElement;
  while (node) {
    const { overflowY } = window.getComputedStyle(node);
    if (/(auto|scroll)/.test(overflowY) && node.scrollHeight > node.clientHeight) return node;
    node = node.parentElement;
  }
  return null;
};

/**
 * Scrolls `el` into view inside its nearest scrollable container only.
 * Unlike `scrollIntoView`, outer page containers are left alone, and the
 * CSS scale transform the Medical app renders under is accounted for.
 */
export const scrollWithinContainer = (
  el: HTMLElement | null,
  {
    align = "start",
    offset = 0,
    stickySelector,
  }: { align?: "start" | "center"; offset?: number; stickySelector?: string } = {}
) => {
  const container = findScrollParent(el);
  if (!el || !container) return;
  const containerRect = container.getBoundingClientRect();
  // Rects are post-transform; scrollTop is in layout pixels.
  const scale = containerRect.height / container.offsetHeight || 1;
  const sticky = stickySelector
    ? (container.querySelector(stickySelector) as HTMLElement | null)
    : null;
  const stickyHeight = sticky && !sticky.contains(el) ? sticky.offsetHeight : 0;
  const elTop = (el.getBoundingClientRect().top - containerRect.top) / scale + container.scrollTop;
  const top =
    align === "center"
      ? elTop - (container.clientHeight - el.offsetHeight) / 2
      : elTop - stickyHeight - offset;
  container.scrollTo({ top: Math.max(0, top), behavior: "smooth" });
};
