import React, { FC } from "react";

import { LateFeeRule } from "../../types";
import { AmountRuleFields, FormRow, NumberField, SwitchField } from "../fields";
import { SectionProps } from "./types";

const LateFeeSection: FC<SectionProps> = ({ config, patch, disabled }) => {
  const f = config.lateFee;
  const patchF = (changes: Partial<LateFeeRule>) => patch({ lateFee: { ...f, ...changes } });

  return (
    <>
      <SwitchField
        label="Charge a late fee on overdue installments"
        checked={f.enabled}
        disabled={disabled}
        onChange={(enabled) => patchF({ enabled })}
      />
      {f.enabled && (
        <FormRow>
          <NumberField
            label="Grace period (days)"
            step={1}
            value={f.graceDays}
            disabled={disabled}
            onChange={(graceDays) => patchF({ graceDays })}
          />
          <AmountRuleFields
            value={f}
            currency={config.currency}
            valueLabel="Fee value"
            disabled={disabled}
            onChange={(rule) => patchF(rule)}
          />
        </FormRow>
      )}
    </>
  );
};

export default LateFeeSection;
