import { getMaskedLocation, reverseGeocode } from "./utils";

export interface BuildRideRequestsCtx {
  userId: any;
  connectionId: any;
  responders: any[];
  pageId: any;
  submitPageId: { current: boolean };
  webBooker: boolean;
  encrypted_token: any;
  projects: any;
  locationTypeFare: { current: any };
  couponResponse: any;
  bookingOtp?: string;
}

// Builds the array of ride-create event requests (one-way and/or round-trip)
// from the resolved form attributes. Pure aside from geocoding lookups.
export async function buildRideRequests(
  sortedAttributes: any,
  values: any,
  ctx: BuildRideRequestsCtx
): Promise<any[]> {
  const {
    userId,
    connectionId,
    responders,
    pageId,
    submitPageId,
    webBooker,
    encrypted_token,
    projects,
    locationTypeFare,
    couponResponse,
    bookingOtp,
  } = ctx;

  const eventRequests: any[] = [];
  let tripDispatch, roundTripDispatch;

  await Promise.all(
    Object.keys(sortedAttributes).map(async (key) => {
      if (sortedAttributes?.[key]?.type === "dispatchType") {
        const oneWaysortedAttributes = {
          ...sortedAttributes,
        };
        if (sortedAttributes?.[key]?.value === "schedule") {
          oneWaysortedAttributes["scheduleDate"] =
            oneWaysortedAttributes?.[key]?.date;
          oneWaysortedAttributes["scheduleTime"] =
            oneWaysortedAttributes?.[key]?.time;
          const tempDate = new Date(
            oneWaysortedAttributes?.[key]?.dateTimestamp
          );
          const tempTime = new Date(
            oneWaysortedAttributes?.[key]?.timeTimestamp
          );
          tempDate.setHours(tempTime.getHours());
          tempDate.setMinutes(tempTime.getMinutes());
          let leadTime = webBooker
            ? 20
            : oneWaysortedAttributes?.leadTime || 0;
          if (tempDate.getTime() - leadTime * 60000 < new Date().getTime()) {
            tripDispatch = {
              type: "immediate",
            };
          } else {
            tripDispatch = {
              utcDateTime: new Date(
                tempDate.getTime() - leadTime * 60000
              ).toUTCString(),
              rideDateTime: new Date(tempDate.getTime()).toUTCString(),
              ridelocalDateTime: tempDate.getTime(),
              type: "schedule",
            };
          }
        } else {
          tripDispatch = {
            type: "immediate",
          };
        }
        delete oneWaysortedAttributes?.leadTime;
        delete oneWaysortedAttributes?.roundTripLeadTime;
        delete oneWaysortedAttributes?.roundTripNotify;
        if (oneWaysortedAttributes?.notify?.customTime) {
          oneWaysortedAttributes.notify.notifyTime =
            oneWaysortedAttributes.notify.customTime.toString();
        }
        oneWaysortedAttributes.vehicleTypeName =
          oneWaysortedAttributes.vehicleType?.name;
        oneWaysortedAttributes.vehicleType =
          oneWaysortedAttributes.vehicleType?.value;

        const maskedPickupCoordinates = getMaskedLocation(
          oneWaysortedAttributes?.pickupLocation?.coordinates?.lat,
          oneWaysortedAttributes?.pickupLocation?.coordinates?.long
        );
        const maskedAddress = await reverseGeocode(maskedPickupCoordinates);

        eventRequests.push({
          userId,
          rideRequestAttributes: {
            ...oneWaysortedAttributes,
            drivers: responders,
            pickupAddress:
              oneWaysortedAttributes?.pickupLocation?.attributes?.address,
            dropoffAddress:
              oneWaysortedAttributes?.dropoffLocation?.attributes?.address,
            maskedPickupLocation: {
              attributes: {
                address: maskedAddress,
              },
              coordinates: maskedPickupCoordinates,
            },
            maskedPickupAddress: maskedAddress,
            cudbServiceId: projects?.userServiceId,
          },
          drivers: responders,
          connectionId,
          unstructuredAttributes: {
            ...values,
            rideType: {
              type: "rideType",
              value: "oneWay",
            },
            vehicle: undefined,
            fixedPriceList: locationTypeFare.current,
          },
          pageId: submitPageId.current ? pageId : undefined,
          title: new Date().toLocaleString(),
          dispatch: tripDispatch,
          createdAt: tripDispatch?.ridelocalDateTime || new Date().getTime(),
          cudbServiceId: projects?.userServiceId,
          ...(webBooker && !encrypted_token?.location
            ? {
              verifyCustomer: true,
              bookingOtp,
            }
            : {}),
          couponId: couponResponse?.data?.couponId ?? undefined,
        });
      }
      if (
        sortedAttributes?.[key]?.type === "rideType" &&
        sortedAttributes?.[key]?.value === "roundTrip"
      ) {
        const roundTripAttributes = {
          ...sortedAttributes,
        };
        const roundTripUnstructuredAttributes = {
          ...values,
        };
        roundTripAttributes["scheduleDate"] =
          roundTripAttributes?.[key]?.date;
        roundTripAttributes["scheduleTime"] =
          roundTripAttributes?.[key]?.time;
        const tempDate = new Date(roundTripAttributes?.[key]?.dateTimestamp);
        const tempTime = new Date(roundTripAttributes?.[key]?.timeTimestamp);
        tempDate.setHours(tempTime.getHours());
        tempDate.setMinutes(tempTime.getMinutes());
        let leadTime = webBooker
          ? 20
          : roundTripAttributes?.roundTripLeadTime || 0;
        roundTripDispatch = {
          utcDateTime: new Date(
            tempDate.getTime() - leadTime * 60000
          ).toUTCString(),
          rideDateTime: new Date(tempDate.getTime()).toUTCString(),
          ridelocalDateTime: tempDate.getTime(),
          type: "schedule",
        };
        const tempLocation = roundTripAttributes.pickupLocation;
        roundTripAttributes.pickupLocation =
          roundTripAttributes.dropoffLocation;
        roundTripAttributes.dropoffLocation = tempLocation;

        const tempUnstructuredLocation =
          roundTripUnstructuredAttributes.pickupLocation;
        roundTripUnstructuredAttributes.pickupLocation =
          roundTripUnstructuredAttributes.dropoffLocation;
        roundTripUnstructuredAttributes.dropoffLocation =
          tempUnstructuredLocation;

        roundTripUnstructuredAttributes.dispatch = {
          date: roundTripUnstructuredAttributes.rideType.date,
          time: roundTripUnstructuredAttributes.rideType.time,
          type: "dispatchType",
          value: "schedule",
        };

        roundTripUnstructuredAttributes.rideType = {
          type: "rideType",
          value: "oneWay",
        };

        roundTripAttributes.notify = roundTripAttributes?.roundTripNotify;
        delete roundTripAttributes?.leadTime;
        delete roundTripAttributes?.roundTripLeadTime;
        delete roundTripAttributes?.roundTripNotify;
        if (roundTripAttributes?.notify?.customTime) {
          roundTripAttributes.notify.notifyTime =
            roundTripAttributes.notify.customTime.toString();
        }
        roundTripAttributes.vehicleTypeName =
          roundTripAttributes.vehicleType?.name;
        roundTripAttributes.vehicleType =
          roundTripAttributes.vehicleType?.value;
        const roundMaskedPickupCoordinates = getMaskedLocation(
          roundTripAttributes?.pickupLocation?.coordinates?.lat,
          roundTripAttributes?.pickupLocation?.coordinates?.long
        );
        const roundMaskedAddress = await reverseGeocode(
          roundMaskedPickupCoordinates
        );
        eventRequests.push({
          userId,
          rideRequestAttributes: {
            ...roundTripAttributes,
            drivers: responders,
            pickupAddress:
              roundTripAttributes?.pickupLocation?.attributes?.address,
            dropoffAddress:
              roundTripAttributes?.dropoffLocation?.attributes?.address,
            maskedPickupLocation: {
              attributes: {
                address: roundMaskedAddress,
              },
              coordinates: roundMaskedPickupCoordinates,
            },
            maskedPickupAddress: roundMaskedAddress,
            cudbServiceId: projects?.userServiceId,
          },
          drivers: [],
          connectionId,
          unstructuredAttributes: {
            ...roundTripUnstructuredAttributes,
            vehicle: undefined,
            fixedPriceList: locationTypeFare.current,
          },
          pageId: submitPageId.current ? pageId : undefined,
          title: new Date().toLocaleString(),
          dispatch: roundTripDispatch,
          createdAt:
            roundTripDispatch?.ridelocalDateTime || new Date().getTime(),
          cudbServiceId: projects?.userServiceId,
          ...(webBooker && !encrypted_token?.location
            ? {
              verifyCustomer: true,
              bookingOtp,
            }
            : {}),
        });
      }
    })
  );

  return eventRequests;
}
