import React, { FC, useEffect, useRef, useState } from "react";
import { Form, Input } from "antd";
import { useSelector } from "react-redux";
import { RootState } from "reducers/rootReducer";
import { SocketTopics } from "constants/enums";
import {
  getCustomCreateRequestPublishTopic,
  getCustomCreateSubscriptionTopic,
  getCustomUpdateRequestPublishTopic,
  getCustomUpdateSubscriptionTopic,
} from "hooks/MQTTConstants";
import LocationInput from "../../../../../common/LocationInput";
import { wrapRequestPayload } from "../../../../../helpers/request/RequestPayload";
import { generateUUID } from "utils/appUtil";
import { pushNotification } from "utils/notifications";
import { FormModal } from "../../common/ui";
import {
  LOCATION_NAME_MAX,
  LocationRecord,
  REQUEST_TIMEOUT_MS,
  findNameClash,
  locationNameKey,
  toLocationInfo,
  useLocationQuery,
} from "./locationApi";

const DUPLICATE_MESSAGE = "A location with this name already exists";

/**
 * Create (no `student`) or edit a saved location. With `readOnly` it only
 * shows the details.
 */
const EditLocationModal: FC<{
  onClose: () => void;
  socket?: ISocket;
  /** The location record being edited ({ objectId, info }). */
  student?: LocationRecord;
  adminRoles?: any;
  onAdd?: (saved: boolean) => void;
  readOnly?: boolean;
  /** Names already loaded in the list, for instant duplicate feedback. */
  existingNames?: string[];
}> = ({ onClose, socket, student, onAdd, readOnly, existingNames = [] }) => {
  const { encrypted_token } = useSelector((state: RootState) => state.auth);
  const [form] = Form.useForm();
  const [saving, setSaving] = useState(false);
  const queryLocations = useLocationQuery();
  const uuid = useRef(generateUUID()).current;
  const pending = useRef(false);
  const timer = useRef<any>();
  const mounted = useRef(true);
  const isEdit = !!student?.objectId;
  const objectId = student?.objectId?.toString();

  useEffect(() => {
    mounted.current = true;
    if (!readOnly) {
      socket.subscribeToEvent(
        SocketTopics.SubscribePageTopics,
        isEdit
          ? getCustomUpdateSubscriptionTopic(encrypted_token?.connectionId)
          : getCustomCreateSubscriptionTopic(encrypted_token?.connectionId),
        () => {
          // The reply topic is shared with other screens; only react to our own save.
          if (!pending.current || !mounted.current) return;
          pending.current = false;
          clearTimeout(timer.current);
          setSaving(false);
          pushNotification(isEdit ? "Location saved" : "Location added", "success", "TOP_CENTER", 2000);
          onAdd?.(true);
        },
        uuid
      );
    }
    return () => {
      mounted.current = false;
      clearTimeout(timer.current);
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  const save = async (values: { name: string; location: any }) => {
    setSaving(true);
    // Exact match against every location, not just the (possibly filtered) list.
    const all = await queryLocations();
    if (!mounted.current) return;
    if (all && findNameClash(all, values.name, objectId)) {
      setSaving(false);
      form.setFields([{ name: "name", errors: [DUPLICATE_MESSAGE] }]);
      return;
    }

    const info = toLocationInfo(values);
    pending.current = true;
    clearTimeout(timer.current);
    timer.current = setTimeout(() => {
      if (!pending.current || !mounted.current) return;
      pending.current = false;
      setSaving(false);
      pushNotification(
        "No response from the server. Refresh the list to check whether the location was saved.",
        "error",
        "TOP_CENTER",
        4000
      );
    }, REQUEST_TIMEOUT_MS);

    if (isEdit) {
      socket.publishToEvent(
        SocketTopics.PublishPageTopics,
        getCustomUpdateRequestPublishTopic(encrypted_token?.connectionId),
        wrapRequestPayload({
          objectId,
          changes: [{ op: "replace", path: "/info", value: info }],
        })
      );
    } else {
      socket.publishToEvent(
        SocketTopics.PublishPageTopics,
        getCustomCreateRequestPublishTopic(encrypted_token?.connectionId),
        wrapRequestPayload({
          changes: [
            {
              op: "add",
              path: "/partitions",
              value: [
                `org:${encrypted_token?.cudbServiceId || encrypted_token?.serviceId}`,
                `type:location`,
              ],
            },
            { op: "add", path: "/createdAt", value: new Date().getTime() },
            { op: "add", path: "/info", value: info },
          ],
        })
      );
    }
  };

  const title = readOnly ? "Location details" : isEdit ? "Edit location" : "Add location";

  return (
    <FormModal
      open
      title={title}
      subtitle={
        readOnly ? undefined : "Saved places appear as pickup and drop-off options in the booking form."
      }
      onCancel={onClose}
      onSubmit={readOnly ? onClose : form.submit}
      okText={readOnly ? "Close" : isEdit ? "Save" : "Add location"}
      saving={saving}
    >
      <Form
        form={form}
        layout="vertical"
        requiredMark={false}
        disabled={readOnly}
        initialValues={{ name: student?.info?.name, location: student?.info?.location }}
        onFinish={save}
      >
        <Form.Item
          label="Name"
          name="name"
          validateFirst
          rules={[
            { required: true, whitespace: true, message: "Enter a name" },
            { max: LOCATION_NAME_MAX, message: `Keep it under ${LOCATION_NAME_MAX} characters` },
            {
              validator: (_, value) =>
                existingNames.some((n) => locationNameKey(n) === locationNameKey(value))
                  ? Promise.reject(new Error(DUPLICATE_MESSAGE))
                  : Promise.resolve(),
            },
          ]}
        >
          <Input placeholder="e.g. Kingston General Hospital" autoFocus={!readOnly} />
        </Form.Item>

        <Form.Item
          label="Address"
          name="location"
          rules={[
            {
              validator: (_, value) =>
                value?.label
                  ? Promise.resolve()
                  : Promise.reject(new Error("Search for an address and pick it from the list")),
            },
          ]}
        >
          <LocationInput placeholder="Search address" disabled={readOnly} />
        </Form.Item>
      </Form>
    </FormModal>
  );
};

export default EditLocationModal;
