import React, { FC, useEffect, useRef, useState } from "react";
import { Alert, Button, Form, Modal, Popconfirm } from "antd";
import moment from "moment";
import { useDispatch, useSelector } from "react-redux";
import { RootState } from "reducers/rootReducer";
import { SocketTopics } from "constants/enums";
import { wrapRequestPayload } from "../../../../../helpers/request/RequestPayload";
import { pushNotification } from "utils/notifications";
import { SET_SUBMITTED } from "../../../../../reducers/reducer";
import DispatchingForm from "../../DispatchPanel/DispatchingForm";
import { pageToFormValues } from "../../DispatchPanel/dispatchPipeline";
import { FormModal, scrollWithinContainer } from "../../common/ui";
import ScheduleSection from "./ScheduleSection";
import RecurringSummaryBar, {
  SCHEDULE_STEP_INDEX,
  useRecurringStatus,
} from "./RecurringSummaryBar";
import { DEFAULT_SCHEDULE, RecurringSchedule } from "./recurrence";
import {
  RECURRING_EVENT_TOPIC,
  SCHEDULE_TO,
  buildRecurringRequestData,
  recurringCron,
} from "./recurringRequests";
import { isScheduleOk, useScheduleApi } from "./recurringApi";
import "./Recurring.scss";

/** Unsaved new-booking form, restored the next time "New" is opened. */
const DRAFT_KEY = "recurringForm";

const BASE_VALUES = {
  dispatch: { type: "dispatchType", value: "immediate" },
  rideType: { type: "rideType", value: "O/W" },
  fareType: { type: "fareType", value: "variable" },
  payType: { type: "payType", value: "meter" },
  numberOfStaff: 1,
};

const BLANK_VALUES = { ...BASE_VALUES, schedule: DEFAULT_SCHEDULE };

// Fields a booking copied from another patient's ride shouldn't inherit.
const PAGE_COPY_CLEARED = {
  appointmentTime: undefined,
  pickupDate: undefined,
  pickupTime: undefined,
  returnPickupTime: undefined,
  confirmationNumber: undefined,
  usedServiceBefore: undefined,
};

const hydrateSchedule = (schedule: any): RecurringSchedule =>
  schedule
    ? {
        ...schedule,
        endUntil: schedule.endUntil ? moment(schedule.endUntil) : undefined,
        startDate: schedule.startDate ? moment(schedule.startDate) : undefined,
        customDates: schedule.customDates?.map((x) => moment(x)),
      }
    : DEFAULT_SCHEDULE;

/** Stored booking values (or a draft) -> form values with dates rehydrated. */
const toFormValues = (attrs: any) => ({
  ...BASE_VALUES,
  ...pageToFormValues(attrs),
  schedule: hydrateSchedule(attrs?.schedule),
});

const readDraft = () => {
  try {
    const raw = localStorage.getItem(DRAFT_KEY);
    return raw ? JSON.parse(raw) : undefined;
  } catch {
    return undefined;
  }
};

const writeDraft = (values?: any) => {
  try {
    if (values) localStorage.setItem(DRAFT_KEY, JSON.stringify(values));
    else localStorage.removeItem(DRAFT_KEY);
  } catch {
    // Storage full or blocked: the draft is a convenience only.
  }
};

/**
 * Create or edit a recurring booking.
 * - `student.scheduleId` + `student.data`: edit that schedule.
 * - `student.data` only: new booking prefilled from it (duplicate).
 * - otherwise: new booking, resuming any unsaved draft.
 */
const EditRecurringModal: FC<{
  onClose: () => void;
  socket?: ISocket;
  student?: any;
  adminRoles?: any;
  onAdd?: () => void;
}> = ({ onClose, socket, student, onAdd }) => {
  const { projects, encrypted_token, accounts, selectedPage } = useSelector(
    (state: RootState) => state.auth
  );
  const dispatch = useDispatch();
  const api = useScheduleApi();
  const [form] = Form.useForm();
  const status = useRecurringStatus(form);
  const rootRef = useRef<HTMLDivElement>(null);
  const mounted = useRef(true);
  const initialSelectedPage = useRef(selectedPage);

  const isEdit = !!student?.scheduleId;
  const isDuplicate = !isEdit && !!student?.data;

  const [initial] = useState(() => {
    const attrs = student?.data?.events?.[0]?.unstructuredAttributes;
    if (isEdit) return { values: toFormValues(attrs), fromDraft: false };
    if (isDuplicate) {
      return { values: { ...toFormValues(attrs), confirmationNumber: undefined }, fromDraft: false };
    }
    const draft = readDraft();
    return draft
      ? { values: toFormValues(draft), fromDraft: true }
      : { values: BLANK_VALUES, fromDraft: false };
  });
  const [showDraftNotice, setShowDraftNotice] = useState(initial.fromDraft);
  const [dirty, setDirty] = useState(false);
  const [saving, setSaving] = useState(false);

  useEffect(() => {
    mounted.current = true;
    return () => {
      mounted.current = false;
    };
  }, []);

  const clearAll = () =>
    Object.fromEntries(Object.keys(form.getFieldsValue(true)).map((key) => [key, undefined]));

  // Picking an existing patient in the name fields loads their last ride.
  // Only react to picks made in this form, not a page selected before it opened.
  useEffect(() => {
    if (!selectedPage?.page || selectedPage === initialSelectedPage.current) return;
    dispatch({ type: SET_SUBMITTED, payload: false });
    const values = {
      ...clearAll(),
      ...toFormValues(selectedPage.page.profile?.unstructuredAttributes),
      ...(selectedPage.ignorePage ? PAGE_COPY_CLEARED : {}),
      // Keep the schedule already being set up.
      schedule: form.getFieldValue("schedule"),
    };
    form.setFieldsValue(values);
    setDirty(true);
    if (!isEdit) writeDraft(values);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [selectedPage]);

  const startOver = () => {
    writeDraft(undefined);
    form.setFieldsValue({ ...clearAll(), ...BLANK_VALUES });
    form.setFields(Object.keys(form.getFieldsValue(true)).map((name) => ({ name, errors: [] })));
    setShowDraftNotice(false);
    setDirty(false);
  };

  const handleCancel = () => {
    if (saving) return;
    if (!isEdit || !dirty) {
      // New bookings keep their draft, so closing loses nothing.
      onClose();
      return;
    }
    Modal.confirm({
      title: "Discard your changes?",
      content: "Your edits to this recurring booking haven't been saved.",
      okText: "Discard",
      okButtonProps: { danger: true },
      cancelText: "Keep editing",
      onOk: onClose,
    });
  };

  const onFinishFailed = () => {
    // Wait for antd to paint the error states, then bring the first into view.
    setTimeout(() => {
      const el = rootRef.current?.querySelector(".ant-form-item-has-error") as HTMLElement;
      scrollWithinContainer(el, { align: "center" });
    }, 50);
  };

  const save = async (values: any) => {
    if (saving) return;
    setSaving(true);
    try {
      const requestData = buildRecurringRequestData(values, {
        userId: encrypted_token?.userId,
        connectionId: encrypted_token?.connectionId,
        accounts,
        projects,
        existing: isEdit ? { scheduleUdid: student?.data?.scheduleUdid } : undefined,
      });
      const cron = recurringCron();

      if (isEdit) {
        const response = await api.update({
          objectId: student.scheduleId.toString(),
          changes: [
            { op: "replace", path: "/cron", value: cron },
            { op: "replace", path: "/data", value: requestData },
          ],
        });
        if (!mounted.current) return;
        if (!isScheduleOk(response)) {
          pushNotification(
            "Couldn't save your changes. Check your connection and try again.",
            "error",
            "TOP_CENTER",
            4000
          );
          return;
        }
        pushNotification("Recurring booking updated", "success", "TOP_CENTER", 3000);
      } else {
        const created = await api.create({
          cron,
          topic: RECURRING_EVENT_TOPIC,
          data: requestData,
          info: {},
          to: SCHEDULE_TO,
        });
        if (!mounted.current) return;
        const objectId = created?.data?.id?.toString();
        if (!objectId) {
          pushNotification(
            "Couldn't create the recurring booking. Nothing was saved; please try again.",
            "error",
            "TOP_CENTER",
            4000
          );
          return;
        }
        // The partitions are what make it show up in this list.
        const tag = {
          objectId,
          changes: [
            {
              op: "replace",
              path: "/partitions",
              value: [`org:${projects?.userServiceId}`, `type:recurringEvent`],
            },
          ],
        };
        const tagged = isScheduleOk(await api.update(tag)) || isScheduleOk(await api.update(tag));
        if (!mounted.current) return;
        if (tagged) {
          pushNotification("Recurring booking created", "success", "TOP_CENTER", 3000);
        } else {
          pushNotification(
            "The recurring booking was created but may not appear in this list. Refresh to check before adding it again.",
            "warning",
            "TOP_CENTER",
            6000
          );
        }
        writeDraft(undefined);
      }

      socket.publishToEvent(
        SocketTopics.PublishPageTopics,
        RECURRING_EVENT_TOPIC,
        wrapRequestPayload({ ...requestData, firstRun: true })
      );
      onAdd?.();
    } catch {
      pushNotification(
        "Something went wrong while saving. Please check the form and try again.",
        "error",
        "TOP_CENTER",
        4000
      );
    } finally {
      if (mounted.current) setSaving(false);
    }
  };

  const title = isEdit
    ? "Edit recurring booking"
    : isDuplicate
    ? "Duplicate recurring booking"
    : "New recurring booking";
  const subtitle = isEdit
    ? "Changes apply to rides created after you save. Rides that already exist aren't changed."
    : "Fill in the booking once, then choose the days it repeats. A ride is created automatically for each date.";

  return (
    <FormModal
      open
      title={title}
      subtitle={subtitle}
      width={1200}
      onCancel={handleCancel}
      onSubmit={form.submit}
      saving={saving}
      okText={isEdit ? "Save changes" : "Create recurring booking"}
      footerExtra={
        !isEdit && (
          <span className="mx-recurring-editor__footer-hint">
            <Popconfirm
              title="Clear the whole form?"
              okText="Clear"
              okButtonProps={{ danger: true }}
              cancelText="Keep"
              onConfirm={startOver}
            >
              <Button type="link" disabled={saving}>
                Start over
              </Button>
            </Popconfirm>
            {dirty && "Draft saved on this device"}
          </span>
        )
      }
    >
      <div className="mx-recurring-editor" ref={rootRef}>
        <Form
          className="auth-form"
          name="recurring-form"
          layout="vertical"
          form={form}
          requiredMark={false}
          initialValues={initial.values}
          onFinish={save}
          onFinishFailed={onFinishFailed}
          onValuesChange={(_, allValues) => {
            setDirty(true);
            if (!isEdit) writeDraft(allValues);
          }}
        >
          <RecurringSummaryBar form={form} status={status} />

          {showDraftNotice && (
            <Alert
              className="mb-3"
              type="info"
              showIcon
              message="We restored the recurring booking you didn't finish last time."
              action={
                <Button size="small" onClick={startOver}>
                  Start over
                </Button>
              }
              closable
              onClose={() => setShowDraftNotice(false)}
            />
          )}

          <DispatchingForm socket={socket} nine11Form={form} pickup={false} ridePageId="" />

          <ScheduleSection
            form={form}
            index={SCHEDULE_STEP_INDEX}
            done={status.schedule.length === 0}
          />
        </Form>
      </div>
    </FormModal>
  );
};

export default EditRecurringModal;
