import React, { useEffect, useState, useRef, useReducer, FC } from "react";
import { Row, Col, Input, Button, Popover, Switch, Tooltip } from "antd";
import { ReactSVG } from "react-svg";
import { useDispatch, useSelector } from "react-redux";
// import { InfoBox } from "react-google-maps/lib/components/addons/InfoBox";
import Geocode from "react-geocode";
import { ReloadOutlined, FileTextOutlined } from "@ant-design/icons";
import FilterIcon from "assets/SVGs/FilterIcon";
import SettingsIcon from "assets/SVGs/SettingsIcon";
// import { DrawingManager } from "react-google-maps/lib/components/drawing/DrawingManager";
import GooglePlacesAutocomplete from "react-google-places-autocomplete";
import { geocodeByPlaceId } from "react-google-places-autocomplete";
import Map from "./Map";
import { RootState } from "reducers/rootReducer";
import MapService from "./MapService";
import { SocketTopics } from "constants/enums";
import { wrapRequestPayload } from "../../../../helpers/request/RequestPayload";
import {
  getRespondersRequestPublishTopic,
  getAssetsRequestPublishTopic,
  getRespondersSubscriptionTopic,
} from "hooks/MQTTConstants";
import { useLocation } from "react-router-dom";
import Loader from "react-loader-spinner";
import { pushNotification } from "utils/notifications";
import GPSReportModal from "../Dashboard/GPSReportModal";
import { createPeopleMarker, getSpeedColor } from "../Dashboard/gpsConstants";

const DEFAULT_LOCATION = { lat: 29.95106579999999, lng: -90.0715323 };

/*global google*/

function useMounted() {
  const [isMounted, setIsMounted] = useState(false);
  useEffect(() => {
    setIsMounted(true);
  }, []);
  return isMounted;
}

const MapPanel: FC<{ socket: ISocket; params: any; userRole?: any }> = ({
  socket,
  params,
  userRole,
}) => {
  const { screens, setScreens } = params;
  const [activePop, setActivePop] = useState<string>();
  const [currentLocation, setCurrentLocation] = useState<any>();
  const [active, setActive] = useState<boolean>(true);
  const [showMap, setShowMap] = useState<boolean>(true);
  const [markers, setMarkers] = useState<any[]>([]);
  const [assetMarkers, setAssetMarkers] = useState<any[]>([]);
  const [currentMarkers, setCurrentMarkers] = useState<any[]>([]);
  const [panel, setPanel] = useState<boolean>(false);
  const [_, forceUpdate] = useReducer((x) => x + 1, 0);
  const {
    responders,
    vehicles,
    incidentLocation,
    project,
    otherLocations,
    assets,
    geofenceLocation,
    standLocations,
    encrypted_token,
    projects,
    driverFilter,
    gpsReportMarkers,
    gps,
    adminUserRoles,
  } = useSelector((state: RootState) => state.auth);
  const { search } = useLocation();
  const [mapBounds, setBounds] = useState<any>();
  const dispatch = useDispatch();
  const isMounted = useMounted();
  const { createPlaceMarker, createCurrentMarker, createAssetMarker } =
    MapService();
  const [searching, setSearching] = useState<boolean>(false);
  const [polygon, setPolygon] = useState<any>(undefined);
  const [circle, setCircle] = useState<any>(undefined);
  const [stands, setStands] = useState<any>([]);
  const [autoReload, setAutoReload] = useState<boolean>(false);
  const [autoZoom, setAutoZoom] = useState<boolean>(true);
  const intervalRef = useRef<NodeJS.Timeout | null>(null);
  const [isGPSReportModalVisible, setIsGPSReportModalVisible] = useState<boolean>(false);
  const [gpsReportLoading, setGpsReportLoading] = useState<boolean>(false);
  const getLastIndexSubscriptionRef = useRef<any>(null);

  useEffect(() => {
    const query = new URLSearchParams(search);
    const lat = query.get("lat");
    const lng = query.get("lng");
    if (lat && lng) {
      setCurrentLocation({
        lat: parseFloat(lat),
        lng: parseFloat(lng),
        current: true,
      });
    } else {
      getMyLocationHandler();
    }
  }, [search]);

  useEffect(() => {
    if (otherLocations) {
      console.log("other locations", otherLocations);
      const otherMarkers = Object.keys(otherLocations).map((key) => {
        return createCurrentMarker(otherLocations[key]);
      });
      setCurrentMarkers(otherMarkers);
    }
  }, [otherLocations]);

  useEffect(() => {
    if (geofenceLocation) {
      console.log("geofence location", geofenceLocation);
      if (geofenceLocation?.location.type === "Polygon") {
        const paths = geofenceLocation?.location.coordinates.map(
          (coordinate) => {
            return { lat: coordinate?.[1], lng: coordinate?.[0] };
          }
        );
        setPolygon({ paths });
      } else {
        setCircle(geofenceLocation);
      }
    } else {
      setPolygon(undefined);
      setCircle(undefined);
    }
  }, [geofenceLocation]);

  useEffect(() => {
    if (standLocations) {
      console.log("stand locations", standLocations);
      setStands(standLocations);
    }
  }, [standLocations]);

  const getResponders = (latLng: any, height: number, width: number) => {
    // const query = new URLSearchParams(search);
    // const userId = query.get("userId");
    // const connectionId = query.get("connectionId");

    // 321951

    setSearching(true);
    socket.publishToEvent(
      SocketTopics.PublishPageTopics,
      getRespondersRequestPublishTopic(encrypted_token?.connectionId),
      wrapRequestPayload({
        userId: encrypted_token?.userId,
        projectId: project,
        cudbServiceId: projects?.userServiceId,
        latLng,
        height: 300000,
        width: 300000,
      })
    );
    // socket.publishToEvent(
    //   SocketTopics.PublishPageTopics,
    //   getAssetsRequestPublishTopic(connectionId),
    //   wrapRequestPayload({
    //     userId,
    //     projectId: project,
    //     latLng,
    //     height,
    //     width,
    //   })
    // );
  };

  // useEffect(() => {
  //   if (incidentLocation) {
  //     setCurrentLocation({
  //       lat: incidentLocation?.value?.coordinates?.lat,
  //       lng: incidentLocation?.value?.coordinates?.long,
  //     });
  //   }
  // }, [incidentLocation]);

  useEffect(() => {
    if (projects?.adminUserId) {
      socket.subscribeToEvent(
        SocketTopics.SubscribePageTopics,
        getRespondersSubscriptionTopic(encrypted_token?.connectionId)
      );
    }
  }, [projects]);

  useEffect(() => {
    if (project && mapBounds) {
      const { latLong, height, width } = mapBounds;
      // getResponders(latLong, height, width);
    }
  }, [project]);

  // useEffect(() => {
  //   if (project && bounds) {
  //     // const { latLong, height, width } = bounds;
  //     // getResponders(latLong, height, width);
  //     console.log('bounds here')
  //   }
  // }, [bounds]);

  useEffect(() => {
    setSearching(false);
    if (responders) {
      // console.log('vehicles', vehicles);
      console.log("responders here", responders);

      // console.log('responders', responders);
      let markers = responders.map((responder) => {
        return createPlaceMarker(responder, false, vehicles);
      });
      markers = markers.filter((marker) => {
        return marker.lat !== undefined && marker.lng !== undefined;
      });
      // Filter markers by driver userId if driverFilter is set
      if (driverFilter !== undefined) {
        markers = markers.filter((marker) => {
          return marker.id === driverFilter;
        });
      }
      // if(markers.length === 0){
      //   pushNotification("No Responder available in the area", 'error', 'TOP_CENTER', 1000)

      // }
      console.log("markers here", markers);
      setMarkers(markers);
    }
  }, [responders, driverFilter]);

  useEffect(() => {
    setSearching(false);
    if (assets && assets.length > 0) {
      console.log("assets here", assets);
      let markers = assets.map((asset) => {
        return createAssetMarker(asset);
      });
      markers = markers.filter((marker) => {
        return marker.lat !== undefined && marker.lng !== undefined;
      });
      setAssetMarkers(markers);
    }
  }, [assets]);

  useEffect(() => {
    if (autoReload && mapBounds) {
      const { latLong, height, width } = mapBounds;
      intervalRef.current = setInterval(() => {
        getResponders(latLong, height, width);
      }, 10000);
    } else {
      if (intervalRef.current) {
        clearInterval(intervalRef.current);
        intervalRef.current = null;
      }
    }

    return () => {
      if (intervalRef.current) {
        clearInterval(intervalRef.current);
        intervalRef.current = null;
      }
    };
  }, [autoReload, mapBounds]);

  const getMyLocationHandler = () => {
    if (currentLocation && currentLocation?.current) {
      setCurrentLocation({ ...currentLocation });
      return;
    }
    if (navigator.geolocation) {
      navigator.geolocation.getCurrentPosition(
        (position) => {
          setCurrentLocation({
            lat: position?.coords?.latitude,
            lng: position?.coords?.longitude,
            current: true,
          });
          Geocode.fromLatLng(
            position?.coords?.latitude?.toString(),
            position.coords.longitude?.toString()
          ).then(
            (response) => {
              let city, country;
              for (
                let i = 0, len = response.results[0].address_components.length;
                i < len;
                i++
              ) {
                var ac = response.results[0].address_components[i];
                if (ac.types.indexOf("administrative_area_level_1") >= 0)
                  city = ac.short_name;
                if (ac.types.indexOf("country") >= 0) country = ac.short_name;
              }
            },
            (error) => {
              console.error(error);
              setCurrentLocation(DEFAULT_LOCATION);
            }
          );
        },
        (error) => {
          console.error(error);
          setCurrentLocation(DEFAULT_LOCATION);
        }
      );
    } else {
      alert("Geolocation is not supported by this browser.");
      setCurrentLocation(DEFAULT_LOCATION);
    }
  };

  const clearMapHandler = () => {
    setActive(false);
    setPanel(false);
    setMarkers([]);
    setAssetMarkers([]);
    dispatch({ type: "SET_GPS_REPORT_MARKERS", payload: [] });
  };

  const handleGPSReport = (driver: any, startDateTime: string, endDateTime: string) => {
    setGpsReportLoading(true);
    dispatch({ type: "SET_GPS_REPORT_MARKERS", payload: [] });
    
    // Clean up previous subscription if exists
    if (getLastIndexSubscriptionRef.current) {
      socket.unSubscribeToEvent(
        SocketTopics.UnSubscribePageTopics,
        `${process.env.REACT_APP_ECO_SYSTEM}/connection/${encrypted_token?.connectionId}/service/iot-service/getLastIndex/reply`
      );
    }

    // Subscribe to getLastIndex reply
    const subscriptionHandler = (response: any) => {
      console.log("last index response for GPS report", response);
      const lastIndexResponse = response?.response?.data;
      
      if (!lastIndexResponse || !lastIndexResponse.channels) {
        pushNotification("Failed to get last index data", "error", "TOP_CENTER", 2000);
        setGpsReportLoading(false);
        return;
      }

      const filtered = lastIndexResponse.channels.filter((x: any) => {
        return x.timestamp && x.value;
      });

      if (filtered.length === 0) {
        pushNotification("No GPS data found for this driver", "error", "TOP_CENTER", 2000);
        setGpsReportLoading(false);
        return;
      }

      const latest = filtered.reduce(function (prev: any, current: any) {
        return prev.timestamp > current.timestamp ? prev : current;
      });

      const segments = latest.objectId.split(":");
      const iotUdid = segments?.[1];
      const iotUserId = segments?.[2];

      if (!iotUdid || !iotUserId) {
        pushNotification("Failed to extract IoT device information", "error", "TOP_CENTER", 2000);
        setGpsReportLoading(false);
        return;
      }

      // Request historical GPS data
      const requestData = {
        filter: `ecosystem=${process.env.REACT_APP_ECO_SYSTEM} iotUdid=${iotUdid} userId=${driver.id} iotUserId=${iotUserId} page=true`,
        fromTimestamp: new Date(startDateTime).getTime(),
        toTimestamp: new Date(endDateTime).getTime(),
        options: {
          withLabels: true,
        },
      };

      console.log("request data", requestData);

      dispatch({
        type: "GET_HISTORICAL_GPS",
        payload: { requestData },
      });

      // Unsubscribe after receiving response
      socket.unSubscribeToEvent(
        SocketTopics.UnSubscribePageTopics,
        `${process.env.REACT_APP_ECO_SYSTEM}/connection/${encrypted_token?.connectionId}/service/iot-service/getLastIndex/reply`
      );
      getLastIndexSubscriptionRef.current = null;
    };

    getLastIndexSubscriptionRef.current = subscriptionHandler;

    // Publish getLastIndex request
    socket.publishToEvent(
      SocketTopics.PublishPageTopics,
      `${process.env.REACT_APP_ECO_SYSTEM}/connection/${encrypted_token?.connectionId}/service/iot-service/getLastIndex`,
      wrapRequestPayload(
        {
          filter: `ecosystem=${process.env.REACT_APP_ECO_SYSTEM} userId=${driver.id} channelName=locationGps`,
          options: {
            latest: false,
          },
        },
        driver.id
      )
    );

    // Subscribe to reply
    socket.subscribeToEvent(
      SocketTopics.PublishPageTopics,
      `${process.env.REACT_APP_ECO_SYSTEM}/connection/${encrypted_token?.connectionId}/service/iot-service/getLastIndex/reply`,
      subscriptionHandler
    );
  };

  // Process GPS response and create markers
  useEffect(() => {
    if (gps && gps.points && gpsReportLoading) {
      console.log("gps points", gps.points);
      if(gps.points.length === 0){
        pushNotification("No GPS data found for this driver", "error", "TOP_CENTER", 2000);
        setGpsReportLoading(false);
        return;
      }
      const markers = gps.points.map((point: any, index: number) => {
        const isStart = index === 0;
        const color = getSpeedColor(point.dataset.speedGps, "mps");
        return createPeopleMarker(point, color, isStart, false);
      });

      dispatch({ type: "SET_GPS_REPORT_MARKERS", payload: markers });
      setGpsReportLoading(false);
      setIsGPSReportModalVisible(false);
      pushNotification(`GPS report generated`, "success", "TOP_CENTER", 2000);
    }
  }, [gps, gpsReportLoading, dispatch]);

  const googleSuggestHandler = (place: any) => {
    geocodeByPlaceId(place.place_id)
      .then((results) => {
        if (results[0].geometry) {
          setCurrentLocation({
            lat: results[0].geometry.location.lat(),
            lng: results[0].geometry.location.lng(),
            current: false,
          });
        }
      })
      .catch((error) => console.error(error));
  };

  const getDistanceFromLatLonInKm = (lat1, lon1, lat2, lon2) => {
    var R = 6371; // Radius of the earth in km
    var dLat = deg2rad(lat2 - lat1); // deg2rad below
    var dLon = deg2rad(lon2 - lon1);
    var a =
      Math.sin(dLat / 2) * Math.sin(dLat / 2) +
      Math.cos(deg2rad(lat1)) *
        Math.cos(deg2rad(lat2)) *
        Math.sin(dLon / 2) *
        Math.sin(dLon / 2);
    var c = 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a));
    var d = R * c; // Distance in km
    return d * 1000;
  };

  const deg2rad = (deg) => {
    return deg * (Math.PI / 180);
  };

  return (
    <div className="main-column map-panel mr-4">
      <div className="main-content">
        {/* <div className="main-header"> */}
        {/* <div className="d-flex"></div> */}
        {/* <div className="d-flex">
            <ReactSVG
              src="/images/expand-icon.svg"
              className="close-icon mr-4"
              onClick={() =>
                setScreens({
                  ...screens,
                  active: screens.active ? "" : "map",
                })
              }
            />
            <ReactSVG
              src="/images/close-icon.svg"
              className="close-icon"
              onClick={() => setScreens({ ...screens, map: false })}
            />
          </div> */}
        {/* </div> */}
        <div className="search-bar mt-3">
          <div className="d-flex">
            <div className="g-map-search-input">
              <GooglePlacesAutocomplete
                autocompletionRequest={
                  {
                    // bounds: bounds,
                    // componentRestrictions: {
                    //   country: [addressComponent.country],
                    // }
                  }
                }
                selectProps={{
                  onChange: (place: any) => {
                    // console.log('place here', place)
                    if (place) googleSuggestHandler(place.value);
                  },
                  isClearable: true,
                  placeholder: "Search map",
                  styles: {
                    input: (provided: any) => ({
                      ...provided,
                      fontFamily: "Nunito-Regular",
                    }),
                  },
                }}
                apiKey={"AIzaSyDgNagv_ozKWc6IQ75Ol4cH8fxdntOaW6M"}
              />
            </div>
            <Button className="beam-btn ml-2">
              <ReactSVG
                src="/images/location-icon.svg"
                onClick={getMyLocationHandler}
              />
            </Button>
            <Button className="beam-btn ml-2">
              <ReactSVG
                src="/images/reload-icon.svg"
                onClick={() => {
                  clearMapHandler();
                  getMyLocationHandler();
                }}
              />
            </Button>
            {userRole === "admin" && (
              <>
                <Button
                  className="beam-btn ml-2"
                  onClick={() => {
                    if (searching) return;
                    if (mapBounds) {
                      const { latLong, height, width } = mapBounds;
                      getResponders(latLong, height, width);
                    }
                  }}
                >
                  {searching ? (
                    <Loader
                      type="TailSpin"
                      color="#95a8c8"
                      height={20}
                      width={20}
                    />
                  ) : (
                    <ReactSVG src="/images/car.svg" className="car-icon" />
                  )}
                </Button>
                <Tooltip title="Generate GPS Report">
                  <Button
                    className="beam-btn ml-2"
                    onClick={() => {
                      setIsGPSReportModalVisible(true);
                    }}
                  >
                    <FileTextOutlined style={{color: "#91a5c6"}} />
                  </Button>
                </Tooltip>
              </>
            )}
          </div>
        </div>
        <div className="main-cards">
          <Row className="map-container-layout">
            <Col md={panel ? 6 : 0}>
              <div id="direction-panel" />
            </Col>
            <Col md={panel ? 18 : 24} sm={24} style={{ width: "inherit", position: "relative" }}>
              {showMap && (
                <>
                  <Map
                    currentLocation={currentLocation}
                    markers={markers}
                    assetMarkers={assetMarkers}
                    currentMarkers={currentMarkers}
                    gpsReportMarkers={gpsReportMarkers || []}
                    polygon={polygon}
                    circle={circle}
                    stands={stands}
                    active={active}
                    setActive={setActive}
                    autoZoom={autoZoom}
                    getPlaces={(resp) => {
                      const { bounds, center } = resp;
                      const height = getDistanceFromLatLonInKm(
                        bounds.minLat,
                        bounds.maxLon,
                        bounds.maxLat,
                        bounds.maxLon
                      );
                      const width = getDistanceFromLatLonInKm(
                        bounds.minLat,
                        bounds.maxLon,
                        bounds.minLat,
                        bounds.minLon
                      );
                      const latLong = {
                        lat: center.lat(),
                        long: center.lng(),
                      };
                      // if (!mapBounds) {
                      //   getResponders(latLong, height, width);
                      // }
                      setBounds({ latLong, height: height, width: width });
                    }}
                  />
                  {userRole === "admin" && (
                    <div
                      style={{
                        position: "absolute",
                        bottom: "20px",
                        left: "20px",
                        zIndex: 1000,
                        backgroundColor: "white",
                        padding: "8px 12px",
                        borderRadius: "4px",
                        boxShadow: "0 2px 8px rgba(0,0,0,0.15)",
                        display: "flex",
                        flexDirection: "row",
                        gap: "24px",
                      }}
                    >
                      <div style={{ display: "flex", alignItems: "center", gap: "8px" }}>
                        <span style={{ fontSize: "14px", fontWeight: 500 }}>
                          Auto Reload
                        </span>
                        <Switch
                          checked={autoReload}
                          onChange={setAutoReload}
                          disabled={!mapBounds}
                        />
                      </div>
                      <div style={{ display: "flex", alignItems: "center", gap: "8px" }}>
                        <span style={{ fontSize: "14px", fontWeight: 500 }}>
                          Auto Zoom
                        </span>
                        <Switch
                          checked={autoZoom}
                          onChange={setAutoZoom}
                        />
                      </div>
                    </div>
                  )}
                </>
              )}
            </Col>

            {/* {encrypted_token && !encrypted_token?.cudbServiceId && (
              <Row className="lock-icons" onClick={()=>{
                if(searching)return;
                      if (mapBounds) {
                        const { latLong, height, width } = mapBounds;
                        getResponders(latLong, height, width);
                      }
                    }}>
                {searching && (
                  <Col span={2}>
                    <Loader
                      type="TailSpin"
                      color="#fff"
                      height={15}
                      width={15}
                    />
                  </Col>
                )}
                <Col span={22}>
                  Click here to search school buses in the area
                </Col>
                
              </Row>
            )} */}
          </Row>
        </div>
      </div>

      <GPSReportModal
        visible={isGPSReportModalVisible}
        onClose={() => {
          setIsGPSReportModalVisible(false);
        }}
        onProceed={handleGPSReport}
        loading={gpsReportLoading}
      />
    </div>
  );
};

export default MapPanel;
