// Layout.js
import React, { useCallback, useEffect, useState } from 'react';
import Header from './Header';
import Filter from './Filter';
import Categories from './Categories';
import ProfileList from './ProfileList';
import CoachProfile from './CoachProfile';
import "./index.scss";
import { useRouteMatch } from 'react-router-dom';

import { formatForRedis } from "utils/appUtil";
import { PERMISSION_TYPES } from "utils/PageTypes";
import { useDispatch, useSelector } from 'react-redux';

import { GET_AGGREGATE, SET_CATEGORIES, SET_COACHES } from "../../../reducers/reducer";
import { RootState } from "reducers/rootReducer";

// import "../index.scss";
//import MainContent from './MainContent'; // Main content of your app
import { SocketTopics, UserTopics } from "constants/enums";
import useSocketActions from "../../../hooks/socketActions";
import {
  getAdminRolesTopic,
} from "hooks/MQTTConstants";
import Loader from 'react-loader-spinner';


const CoachApp = ({ socket }) => {
  const { getUserRequestPayload } = useSocketActions();
  const dispatch = useDispatch();
  const [coachRole, setCoachRole] = useState<any>();
  const { coaches,  userInfo } = useSelector(
    (state: RootState) => state.auth
  );

  const [currentPage, setCurrentPage] = useState(1); 
  const [totalCount, setTotalCount] = useState(0); 
  const defaultPageSize = 9;

  const [categoriesInfo, setCategoriesInfo] = useState<any>({});
  const [coachesList, setCoachesList] = useState<any>([]);
  const [selectedCoach, setSelectedCoach] = useState<any>([]);
  const [isLoading, setIsLoading] = useState<boolean>(true);
  const [profileListLoading, setProfileListLoading] = useState<boolean>(true);
  const [filterOptions, setFilterOptions] = useState<any>({ yearsOfExperience: { min: 0, max: 500 }, dailyRate: { min: 0, max: 5000 }, hourlyRate: { min: 0, max: 500 },  name: '', availabilityDays: [], timeFilter: undefined });

  const convertToDaysFromCurrentDate = (availability = []) => {
    const dayNames = ["Sunday", "Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday"];
    
    // Get today's date and reset the time to 00:00:00 to only compare dates
    const today = new Date();
    today.setHours(0, 0, 0, 0); // Reset time portion of today's date
  
    return Array.from(
      new Set(
        Object.keys(availability)
          .filter((date) => {
            const availabilityDate = new Date(date);
            availabilityDate.setHours(0, 0, 0, 0); // Reset time of availability date
            return availabilityDate >= today; // Compare only dates
          })
          .map((date) => dayNames[new Date(date).getDay()]) // Map to day names
      )
    );
  };

  const getUserCoachData = ()=>{
    socket.publishToServiceIdSurvey(
      SocketTopics.SurveyTopics,
      UserTopics.SearchInUser,
      getUserRequestPayload(localStorage.getItem("adminUserId"), "$", "$..persistent.static.admin.role"),
      getAdminRolesTopic(localStorage.getItem('CID')),
      localStorage.getItem('coachServiceId')
    );
   
    socket.subscribeToSurvey(
      SocketTopics.SurveyTopics,
      getAdminRolesTopic(localStorage.getItem('CID')),
      (response) => {
        
        if(response){
        const coachRole = response.data?.[0]?.[0]?.filter(
          (x: any) =>
            x.permissions.includes(PERMISSION_TYPES.OnMove) &&
            x.permissions.indexOf(PERMISSION_TYPES.Admin) === -1
        )

        const candidateRoleId = response.data?.[0]?.[0]?.filter(
          (x: any) =>
            x.permissions.length === 1 &&
            x.permissions.indexOf(PERMISSION_TYPES.OnMove) === -1 &&
            x.permissions.indexOf(PERMISSION_TYPES.Admin) === -1 &&
            x.permissions.includes(PERMISSION_TYPES.Live)
        )

        localStorage.setItem("candidateRoleId", candidateRoleId[0]?._id)
        localStorage.setItem("coachRoleId", coachRole[0]?._id);
        setCoachRole(coachRole);

        getUsersByRole(coachRole, filterOptions);
        if (coachRole?.length && coachRole[0]?.extendedBio?.length) {
          const extendedBio = coachRole[0]?.extendedBio?.find(el => el?.type === "category");
          const formattedCategoriesData = {
            categories: [],
            subcategories: {}
          };

          extendedBio?.options?.forEach(el => {
            const categoryName = el?.name;
            const subCategoryList = el?.subCategories || [];

            if (categoryName) {
              formattedCategoriesData.categories.push(categoryName);

              formattedCategoriesData.subcategories[categoryName] = subCategoryList;
            }
          });
          setCategoriesInfo(formattedCategoriesData);
          dispatch({ type: SET_CATEGORIES, payload: { ...formattedCategoriesData } });
          setIsLoading(false);
        }
      }
      }
    );
  }

  useEffect(() => {
    if (socket.client) {
      setIsLoading(true);
      getUserCoachData();
    }

  }, [socket.client]);

  useEffect(()=>{
    
    if(Object.keys(userInfo)?.length){
      setIsLoading(true);
      getUserCoachData();
    }
  }, [userInfo])

  //TODO: refactor this code
  const routeMatch: any = useRouteMatch("/coach/:id");
  const id = routeMatch?.params?.id;


  useEffect(() => {
    if (id && coachesList?.length) {
      const coach = coachesList?.find(el => el?.id == id);
      if (coach) {
        setSelectedCoach(coach);
      }
    }

  }, [id, coachesList])

  const formatUserFilterText = (text: string) => {
    var result = "";
    let comp = text
      .trim()
      .split(" ")
      .filter((word) => word.length > 2)
      .map((x) => {
        return "*" + formatForRedis(x) + "*";
      });
    if (comp.length == 0) {
      return result;
    }
    comp.forEach((element) => {
      result += `@firstName:(${element})|@lastName:(${element})|`;
    });
    result += `@beamIds:{${comp.join("|")}}`;
    return `(${result})`;
  };

  const calculateRatings = (ratings) => {
    const ratingsData = ratings;
    const ratingsList: any = Object.values(ratingsData); 
  
   
    const totalNoOfRatings = ratingsList.length;
    const totalRatings: any = ratingsList.reduce((acc, curr) => acc + curr.rating, 0) / totalNoOfRatings;
  
    return {
      totalRatings: parseFloat(totalRatings.toFixed(1)), 
      totalNoOfRatings,
      ratings: ratingsList, 
    };
  };

  const getUsersByRoleCount = (roles, filterOptions) => {
    const  {
      yearsOfExperience,
      dailyRate,
      hourlyRate,
      availabilityDays,
      name= "",
      timeFilter = undefined
    } = filterOptions;
    
    setProfileListLoading(true);
    let searchQuery = `@serviceId:{'${formatForRedis(
      (localStorage.getItem('coachServiceId') || 'cudb-live')
    )}'}`;
    if (name && name.length > 2) {
      searchQuery += formatUserFilterText(name);
    }
   
    let userRoles;

    userRoles = roles.filter(
      (x: any) =>
        x.permissions.includes(PERMISSION_TYPES.OnMove) &&
        x.permissions.indexOf(PERMISSION_TYPES.Admin) === -1
    );

    const rolesQuery = userRoles.map((y: any) => {
      return `@roleId === '${y._id}'`;
    });

    let expression = `exists(@roleId) && (${rolesQuery.join("||")}) && exists(@type) && (@type === 'coach') && (exists(@hourlyRate) && @hourlyRate<=${hourlyRate.max} && @hourlyRate>=${hourlyRate.min}) && (exists(@dailyRate) && @dailyRate<=${dailyRate.max} && @dailyRate>=${dailyRate.min}) && (exists(@experience) && @experience<=${yearsOfExperience.max} && @experience>=${yearsOfExperience.min})`;
    if(timeFilter){
      expression =  expression + `&& exists(@${timeFilter.key}) && (@${timeFilter.key} === '${timeFilter.value}')`
    }
    const userRequest: any = {
      select: {
        index: {
          searchIndex: `${process.env.REACT_APP_ECO_SYSTEM}:userNameIndex`,
          searchQuery,
          searchOptions: "TIMEOUT 5000",
        },
        load: {
          id: "$.objectId",
          roleId: "$..admin.profile.roleId",
          type: "$..persistent.static.coach.type",
          coach: "$..persistent.static.coach",
          dailyRate: "$..persistent.static.coach.bio.dailyRate",
          experience: "$..persistent.static.coach.bio.experience",
          hourlyRate: "$..persistent.static.coach.bio.hourlyRate",
          createdAt: '$.persistent.static.metadata.createdAt',
          ...(timeFilter && {
            [timeFilter.key]: `$..persistent.static.coach.bio.location.attributes.${timeFilter.key}`,
          }),
        },
      },
      apply: {
        expression: "",
        name: "",
      },
      filter: {
        expression: expression,
      },
      anyStatus: false,
    };

   
    dispatch(
      GET_AGGREGATE({
        requestData: userRequest,
        callback: (response) => {
          
          const totalCoachCount = response?.map((coach) => {
            return {
              id: coach?.id,
              days: convertToDaysFromCurrentDate(coach?.coach?.assignAvailability),
              ...coach?.coach,
            }
          }) ?.filter(coach => coach?.bio && (!availabilityDays.length || availabilityDays.some((day) => coach?.days.includes(day))))?.length || 0;

         setTotalCount(totalCoachCount);
        },
      })
    );
  };

  const getUsersByRole = (roles, filterOptions, page = currentPage) => {
    getUsersByRoleCount(roles,filterOptions);
    
    const  {
      yearsOfExperience,
      dailyRate,
      hourlyRate,
      availabilityDays,
      name= "",
      timeFilter = undefined
    } = filterOptions;
    
    setProfileListLoading(true);
    let searchQuery = `@serviceId:{'${formatForRedis(
      (localStorage.getItem('coachServiceId') || 'cudb-live')
    )}'}`;
    if (name && name.length > 2) {
      searchQuery += formatUserFilterText(name);
    }
    let userRoles;

    userRoles = roles.filter(
      (x: any) =>
        x.permissions.includes(PERMISSION_TYPES.OnMove) &&
        x.permissions.indexOf(PERMISSION_TYPES.Admin) === -1
    );


    const rolesQuery = userRoles.map((y: any) => {
      return `@roleId === '${y._id}'`;
    });

    let expression = `exists(@roleId) && (${rolesQuery.join("||")}) && exists(@type) && (@type === 'coach') && (exists(@hourlyRate) && @hourlyRate<=${hourlyRate.max} && @hourlyRate>=${hourlyRate.min}) && (exists(@dailyRate) && @dailyRate<=${dailyRate.max} && @dailyRate>=${dailyRate.min}) && (exists(@experience) && @experience<=${yearsOfExperience.max} && @experience>=${yearsOfExperience.min})`;
    if(timeFilter){
      expression =  expression + `&& exists(@${timeFilter.key}) && (@${timeFilter.key} === '${timeFilter.value}')`
    }
    const userRequest: any = {
      select: {
        index: {
          searchIndex: `${process.env.REACT_APP_ECO_SYSTEM}:userNameIndex`,
          searchQuery,
          searchOptions: "TIMEOUT 5000",
        },
        load: {
          id: "$.objectId",
          status: "$.nonpersistent.static.live.status",
          live: "$.persistent.static.live",
          roleId: "$..admin.profile.roleId",
          coach: "$..persistent.static.coach",
          type: "$..persistent.static.coach.type",
          dailyRate: "$..persistent.static.coach.bio.dailyRate",
          experience: "$..persistent.static.coach.bio.experience",
          hourlyRate: "$..persistent.static.coach.bio.hourlyRate",
          createdAt: '$.persistent.static.metadata.createdAt',
          ...(timeFilter && {
            [timeFilter.key]: `$..persistent.static.coach.bio.location.attributes.${timeFilter.key}`,
          }),
        },
      },
      apply: {
        expression: "",
        name: "",
      },
      sortBy: {
        properties: [
          {
            field: '@createdAt',
            order: 'DESC',
          },
        ],
        max: 1000,
      },
      result: {
        pagination: {
          offset: (page - 1) * defaultPageSize,
          limit: defaultPageSize,
        },
      },
      filter: {
        expression: expression
      },
      anyStatus: false,
    };
    // setLoading(true);
   
    dispatch(
      GET_AGGREGATE({
        requestData: userRequest,
        callback: (response) => {
          
          const coachesListData = response?.map((coach) => {
            const image = coach?.live?.profile?.profileImage?.urls?.original?.url || '/images/users/user.png'
           const ratings = coach?.coach?.bio?.ratings ? calculateRatings(coach?.coach?.bio?.ratings) : { totalRatings: 0, 
            totalNoOfRatings: 0,
            ratings: [] }
            return {
              id: coach?.id,
              beamId: `${coach?.live?.profile?.firstName}.${coach?.live?.profile?.lastName}`,
              name: `${coach?.live?.profile?.firstName} ${coach?.live?.profile?.lastName}`,
              image,
              days: convertToDaysFromCurrentDate(coach?.coach?.assignAvailability),
              ...coach?.coach,
              ratings
            }
          }) ?.filter(coach => coach?.bio && (!availabilityDays.length || availabilityDays.some((day) => coach?.days.includes(day))));

          setCoachesList([...coachesListData]);
          dispatch({ type: SET_COACHES, payload: [...coachesListData] });

          setProfileListLoading(false);
          setIsLoading(false);
        },
      })
    );
  };

  const onChangePagination = (page)=>{
    setCurrentPage(page);
    getUsersByRole(coachRole, filterOptions, page);
  }

  const onChange = (filterOptions) => {

     const { yearsOfExperience = { min: 0, max: 500 }, dailyRate = { min: 0, max: 5000 }, hourlyRate = { min: 0, max: 500 }, name = "", availabilityDays= [], timeFilter = undefined } = filterOptions;
    
     setFilterOptions({
       name,
      yearsOfExperience,
      dailyRate,
      hourlyRate,
      availabilityDays,
      timeFilter
    });

    const filterOptionsChange = {
      name,
     yearsOfExperience,
     dailyRate,
     hourlyRate,
     availabilityDays,
     timeFilter
   };
    getUsersByRole(coachRole, filterOptionsChange, currentPage);
  };


  const onChangeCategories = useCallback((filter) => {
      const { selectedSubcategories } = filter;

    if (!selectedSubcategories || Object.keys(selectedSubcategories).length === 0) {
      setCoachesList([...coaches]);
      return;
    }

    const filteredCoaches = coaches.filter((coach) =>
      coach.categories.some((category) => {
        const subcategories = selectedSubcategories[category.name];

        if (subcategories && subcategories.length === 0) {
          return true;
        }
        
        return subcategories && subcategories.some((sub) => category.subcategories.includes(sub))
        
      })
    );

    setCoachesList([...filteredCoaches]);
  }, [coaches]);
  

  return (
    <div className="layout coach-app">
      <Header socket={socket} />
  
      {isLoading ? (
        <div className="loader-container">
          <Loader type="TailSpin" color="#007bff" height={50} width={100} />
        </div>
      ) : !routeMatch ? (
        <>
          <Filter onChange={onChange}  filterOptions ={filterOptions}/>
          {!isLoading && (
            <>
              <Categories
                categoriesInfo={categoriesInfo}
                onChange={onChangeCategories}
              />

              {!profileListLoading ? <ProfileList
                                       coachList={coachesList}
                                       currentCoachPage={currentPage}
                                       totalCount={totalCount}
                                       defaultPageSize={defaultPageSize}
                                       onChange={onChangePagination} /> : 
              <div className="loader-container">
              <Loader type="TailSpin" color="#007bff" height={50} width={100} />
            </div>
              }
            </>
          )}
        </>
      ) : (
        <CoachProfile socket={socket} coach={selectedCoach} />
      )}
    </div>
  );
  

};


export default CoachApp;


