import React, { FC, useCallback, useEffect, useMemo, useRef, useState } from "react";
import { Button } from "antd";
import type { ColumnsType } from "antd/es/table";
import { useSelector } from "react-redux";
import { RootState } from "reducers/rootReducer";
import { SocketTopics } from "constants/enums";
import {
  getCustomUpdateRequestPublishTopic,
  getCustomUpdateSubscriptionTopic,
} from "hooks/MQTTConstants";
import { wrapRequestPayload } from "../../../../../helpers/request/RequestPayload";
import { generateUUID } from "utils/appUtil";
import { pushNotification } from "utils/notifications";
import EditLocationModal from "./EditLocationModal";
import { LocationRecord, LocationRow, useLocationQuery } from "./locationApi";
import { DataTableCard, EmptyState, PageHeader, RowActions } from "../../common/ui";
import "../Dashboard.scss";

const SEARCH_DEBOUNCE_MS = 400;

/**
 * Saved locations. With `userId` (embedded elsewhere) the header is hidden
 * and rows can only be viewed.
 */
const LocationModal: FC<{
  socket: ISocket;
  params?: any;
  componentUuid?: string;
  userId?: string;
}> = ({ socket, componentUuid, userId }) => {
  const { encrypted_token, projects } = useSelector((state: RootState) => state.auth);
  const queryLocations = useLocationQuery();
  const uuid = useRef(componentUuid || generateUUID()).current;
  const readOnly = !!userId;

  const [rows, setRows] = useState<LocationRow[]>([]);
  const [loading, setLoading] = useState(false);
  const [loadFailed, setLoadFailed] = useState(false);
  const [search, setSearch] = useState("");
  // undefined = closed, null = creating, record = editing/viewing
  const [modalRecord, setModalRecord] = useState<LocationRecord | null | undefined>(undefined);

  const searchRef = useRef("");
  const searchTimeout = useRef<any>();
  const requestSeq = useRef(0);
  const pendingDeletes = useRef(0);
  const mounted = useRef(true);

  const load = useCallback(
    async (text = searchRef.current) => {
      const seq = ++requestSeq.current;
      setLoading(true);
      const result = await queryLocations(text);
      // Ignore stale replies from earlier searches.
      if (!mounted.current || seq !== requestSeq.current) return;
      setLoading(false);
      setLoadFailed(!result);
      if (result) setRows(result);
    },
    [queryLocations]
  );

  useEffect(() => {
    mounted.current = true;
    if (!readOnly) document.title = "Location | Beam";
    return () => {
      mounted.current = false;
      clearTimeout(searchTimeout.current);
    };
  }, [readOnly]);

  useEffect(() => {
    if (!projects?.userServiceId) return;
    load();
    socket.subscribeToEvent(
      SocketTopics.SubscribePageTopics,
      getCustomUpdateSubscriptionTopic(encrypted_token?.connectionId),
      () => {
        // Shared reply topic: only react to our own deletes.
        if (!mounted.current || pendingDeletes.current === 0) return;
        pendingDeletes.current -= 1;
        pushNotification("Location deleted", "success", "TOP_CENTER", 2000);
        load();
      },
      uuid
    );
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [projects?.userServiceId]);

  const onSearch = (value: string) => {
    setSearch(value);
    searchRef.current = value;
    clearTimeout(searchTimeout.current);
    searchTimeout.current = setTimeout(() => load(value), SEARCH_DEBOUNCE_MS);
  };

  const deleteLocation = (row: LocationRow) => {
    pendingDeletes.current += 1;
    setRows((current) => current.filter((r) => r.key !== row.key));
    socket.publishToEvent(
      SocketTopics.PublishPageTopics,
      getCustomUpdateRequestPublishTopic(encrypted_token?.connectionId),
      wrapRequestPayload({
        objectId: row.key,
        changes: [{ op: "replace", path: "/objectStatus", value: "deleted" }],
      })
    );
  };

  const columns: ColumnsType<LocationRow> = useMemo(
    () => [
      {
        title: "Name",
        dataIndex: "name",
        key: "name",
        width: "30%",
        sorter: (a, b) => a.name.localeCompare(b.name),
        render: (name) => <strong>{name || "Untitled"}</strong>,
      },
      {
        title: "Address",
        dataIndex: "address",
        key: "address",
        render: (address) => address || <span style={{ color: "#6b7a90" }}>No address</span>,
      },
      {
        title: "",
        key: "actions",
        align: "right",
        width: 110,
        render: (_, row) =>
          readOnly ? (
            <RowActions onView={() => setModalRecord(row.record)} />
          ) : (
            <RowActions
              onEdit={() => setModalRecord(row.record)}
              onDelete={() => deleteLocation(row)}
              deleteConfirm={`Delete "${row.name}"? It will no longer be offered when booking.`}
            />
          ),
      },
    ],
    // deleteLocation only closes over refs and stable values
    // eslint-disable-next-line react-hooks/exhaustive-deps
    [readOnly]
  );

  const emptyState = loadFailed ? (
    <EmptyState
      title="Couldn't load locations"
      description={
        <Button className="mx-btn-secondary mt-2" onClick={() => load()}>
          Try again
        </Button>
      }
    />
  ) : search.trim() ? (
    <EmptyState title="No matching locations" description="Try a different name." />
  ) : (
    <EmptyState
      title="No saved locations yet"
      description="Save hospitals, clinics and other frequent stops to pick them quickly when booking."
      action={readOnly ? undefined : { label: "Add location", onClick: () => setModalRecord(null) }}
    />
  );

  return (
    <React.Fragment>
      {!readOnly && (
        <PageHeader
          title="Locations"
          subtitle="Saved pickup & drop-off places used by the booking form"
          search={{ value: search, onChange: onSearch, placeholder: "Search by name", loading }}
          primaryAction={{ label: "Add location", onClick: () => setModalRecord(null) }}
        />
      )}

      <DataTableCard<LocationRow>
        rowKey="key"
        loading={loading}
        clickable
        caption={
          search.trim()
            ? `${rows.length} matching ${rows.length === 1 ? "location" : "locations"}`
            : `${rows.length} ${rows.length === 1 ? "location" : "locations"}`
        }
        columns={columns}
        dataSource={rows}
        empty={emptyState}
        scroll={{ x: true }}
        onRow={(row) => ({ onClick: () => setModalRecord(row.record) })}
      />

      {modalRecord !== undefined && (
        <EditLocationModal
          socket={socket}
          student={modalRecord || undefined}
          readOnly={readOnly}
          existingNames={rows.filter((r) => r.key !== modalRecord?.objectId).map((r) => r.name)}
          onClose={() => setModalRecord(undefined)}
          onAdd={() => {
            setModalRecord(undefined);
            load();
          }}
        />
      )}
    </React.Fragment>
  );
};

export default LocationModal;
