import { useEffect, useRef, useState } from "react";

/** Width of a block element, kept current through ResizeObserver. */
export const useElementWidth = (): [React.RefObject<HTMLDivElement>, number] => {
  const ref = useRef<HTMLDivElement>(null);
  const [width, setWidth] = useState(0);

  useEffect(() => {
    const el = ref.current;
    if (!el) return undefined;
    const measure = () => setWidth(el.clientWidth);
    measure();
    if (typeof ResizeObserver === "undefined") {
      window.addEventListener("resize", measure);
      return () => window.removeEventListener("resize", measure);
    }
    const observer = new ResizeObserver(measure);
    observer.observe(el);
    return () => observer.disconnect();
  }, []);

  return [ref, width];
};

export const linearScale = (domain: [number, number], range: [number, number]) => {
  const [d0, d1] = domain;
  const [r0, r1] = range;
  const span = d1 - d0 || 1;
  return (value: number) => r0 + ((value - d0) / span) * (r1 - r0);
};

/** Clean tick values from 0 to a rounded ceiling above `max`. */
export const niceTicks = (max: number, count = 4): number[] => {
  if (!(max > 0)) return [0, 1];
  const rough = max / count;
  const power = Math.pow(10, Math.floor(Math.log10(rough)));
  const candidates = [1, 2, 2.5, 5, 10];
  const step = candidates.map((c) => c * power).find((s) => s >= rough) || 10 * power;
  const ticks: number[] = [];
  for (let v = 0; v <= max + step * 0.999; v += step) ticks.push(Number(v.toFixed(6)));
  if (ticks[ticks.length - 1] < max) ticks.push(ticks[ticks.length - 1] + step);
  return ticks;
};

/** Compact tick text: 0 · 25K · 1.2M. */
export const tickText = (value: number, currency = "USD"): string => {
  const symbol = currency === "USD" ? "$" : "";
  const abs = Math.abs(value);
  if (abs >= 1_000_000) return `${symbol}${(abs / 1_000_000).toFixed(1).replace(/\.0$/, "")}M`;
  if (abs >= 1_000) return `${symbol}${(abs / 1_000).toFixed(abs >= 10_000 ? 0 : 1).replace(/\.0$/, "")}K`;
  return `${symbol}${abs}`;
};

/**
 * A bar path rounded only at its data end. `end` is the side that carries
 * the value; the opposite side sits square on the baseline.
 */
export const barPath = (
  x: number,
  y: number,
  w: number,
  h: number,
  r: number,
  end: "top" | "bottom" | "right"
): string => {
  const rr = Math.max(0, Math.min(r, w / 2, h / 2));
  if (w <= 0 || h <= 0) return "";
  if (end === "top") {
    return `M${x},${y + h} V${y + rr} Q${x},${y} ${x + rr},${y} H${x + w - rr} Q${x + w},${y} ${x + w},${y + rr} V${y + h} Z`;
  }
  if (end === "bottom") {
    return `M${x},${y} H${x + w} V${y + h - rr} Q${x + w},${y + h} ${x + w - rr},${y + h} H${x + rr} Q${x},${y + h} ${x},${y + h - rr} Z`;
  }
  return `M${x},${y} H${x + w - rr} Q${x + w},${y} ${x + w},${y + rr} V${y + h - rr} Q${x + w},${y + h} ${x + w - rr},${y + h} H${x} Z`;
};
