import React, { FC, useCallback, useEffect, useMemo, useState } from "react";
import { Button, Input, InputNumber, Result, Spin } from "antd";
import { CheckCircleFilled, CloseCircleFilled, DownloadOutlined } from "@ant-design/icons";
import moment from "moment";
import { useDispatch, useSelector } from "react-redux";
import { useLocation } from "react-router-dom";
import { RootState } from "reducers/rootReducer";
import { DECRYPT_TOKEN } from "reducers/reducer";
import { BrandCouponTopic, useBrandCouponApi } from "../couponApi";
import { computeDiscount, conditionLines, discountHeadline, formatMoney } from "../couponRules";
import { downloadDataUrl, renderCouponCardPng, slug } from "../card/renderCard";
import { CouponInfo, CouponLinkToken, PublicCouponView, RedeemResult } from "../types";
import "../Coupon.scss";

const VENDOR_KEY = "couponVendorName";

const readVendor = () => {
  try {
    return localStorage.getItem(VENDOR_KEY) || "";
  } catch {
    return "";
  }
};

/**
 * Public coupon link, no login.
 *  - `/coupon/view?token=`   the customer's coupon: card + QR to show at the till.
 *  - `/coupon/redeem?token=` what the store's phone opens after scanning the QR:
 *    coupon details, then store name + bill + vendor PIN to approve it.
 */
const CouponLinkPage: FC<{ socket: ISocket; mode: "view" | "redeem" }> = ({ socket, mode }) => {
  const dispatch = useDispatch();
  const { search } = useLocation();
  const { encrypted_token } = useSelector((state: RootState) => state.auth);
  const call = useBrandCouponApi(socket);
  const rawToken = useMemo(() => new URLSearchParams(search).get("token") || "", [search]);
  const link = encrypted_token?.brandCoupon ? (encrypted_token as CouponLinkToken) : undefined;

  const [view, setView] = useState<PublicCouponView>();
  const [error, setError] = useState<string>();
  const [cardSrc, setCardSrc] = useState<string>();

  const [vendorName, setVendorName] = useState(readVendor);
  const [bill, setBill] = useState<number | null>(null);
  const [pin, setPin] = useState("");
  const [submitting, setSubmitting] = useState(false);
  const [result, setResult] = useState<RedeemResult>();

  useEffect(() => {
    document.title = mode === "redeem" ? "Approve coupon | Beam" : "Your coupon | Beam";
  }, [mode]);

  useEffect(() => {
    if (!socket.client) return;
    if (!rawToken) {
      setError("This coupon link is incomplete.");
      return;
    }
    dispatch(
      DECRYPT_TOKEN({
        data: { payload: rawToken },
        callback: (data: any) => {
          if (!data?.decryptedPayload) setError("This coupon link has expired or is invalid.");
        },
      })
    );
  }, [rawToken, socket.client, dispatch]);

  // DECRYPT_TOKEN doesn't call back on failure (e.g. a link past its 7 days).
  useEffect(() => {
    if (view || error) return;
    const timer = setTimeout(() => setError("This coupon link has expired or is invalid."), 25000);
    return () => clearTimeout(timer);
  }, [view, error]);

  const load = useCallback(async () => {
    if (!link) return;
    const reply = await call<PublicCouponView>(BrandCouponTopic.Get, {
      cudbServiceId: link.cudbServiceId,
      couponId: link.couponId,
      recipientKey: link.recipientKey,
      viewer: mode === "redeem" ? "vendor" : "customer",
    });
    if (!reply) setError("We couldn't reach the server. Check your connection and try again.");
    else if (!reply.status) setError(reply.data?.details || "This coupon could not be found.");
    else setView(reply.data);
  }, [link, call, mode]);

  useEffect(() => {
    load();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [link?.recipientKey]);

  // The customer's QR encodes the store-side link.
  const redeemUrl = `${window.location.origin}/coupon/redeem?token=${encodeURIComponent(rawToken)}`;
  useEffect(() => {
    if (mode !== "view" || !view) return;
    renderCouponCardPng(view.coupon as CouponInfo, { url: redeemUrl, caption: view.recipient.name, scale: 2 })
      .then(setCardSrc)
      .catch(() => undefined);
  }, [mode, view, redeemUrl]);

  const approve = async () => {
    if (!link) return;
    setSubmitting(true);
    try {
      localStorage.setItem(VENDOR_KEY, vendorName.trim());
    } catch {
      /* private mode */
    }
    const reply = await call<RedeemResult>(BrandCouponTopic.Redeem, {
      cudbServiceId: link.cudbServiceId,
      couponId: link.couponId,
      recipientKey: link.recipientKey,
      pin,
      billAmount: bill,
      vendorName: vendorName.trim(),
    });
    setSubmitting(false);
    setPin("");
    if (!reply) setResult({ accepted: false, reason: "No response from the server. Try again." });
    else if (!reply.status) setResult({ accepted: false, reason: reply.data?.details || "Something went wrong." });
    else setResult(reply.data);
  };

  if (error) {
    return (
      <div className="cpn-public">
        <Result status="warning" title="Coupon unavailable" subTitle={error} />
      </div>
    );
  }
  if (!view) {
    return (
      <div className="cpn-public cpn-public--center">
        <Spin size="large" />
      </div>
    );
  }

  const coupon = view.coupon as CouponInfo;
  const brand = coupon.brandName || "the brand";
  const card = coupon.card || {};

  if (mode === "view") {
    return (
      <div className="cpn-public">
        <div className="cpn-public__panel">
          {cardSrc ? <img className="cpn-public__card" src={cardSrc} alt="Your coupon QR code" /> : <Spin />}
          <p className="cpn-public__hint">Show this QR code at the store. Staff will scan it to apply your discount.</p>
          {!view.redeemable.ok && <p className="cpn-public__warn">{view.redeemable.reason}</p>}
          {cardSrc && (
            <Button icon={<DownloadOutlined />} onClick={() => downloadDataUrl(cardSrc, `${slug(coupon.title)}.png`)}>
              Save image
            </Button>
          )}
          {coupon.terms && <p className="cpn-public__terms">{coupon.terms}</p>}
        </div>
      </div>
    );
  }

  // ---- store side
  if (result?.accepted) {
    return (
      <div className="cpn-public">
        <div className="cpn-public__panel cpn-public__done">
          <CheckCircleFilled className="cpn-public__ok" />
          <h2>Coupon approved</h2>
          {result.discountApplied !== null && result.discountApplied !== undefined ? (
            <p className="cpn-public__amount">{formatMoney(result.discountApplied, result.currency)} off</p>
          ) : (
            <p className="cpn-public__amount">{discountHeadline(coupon)}</p>
          )}
          {result.finalAmount !== null && result.finalAmount !== undefined && (
            <p>Customer pays {formatMoney(result.finalAmount, result.currency)}</p>
          )}
          <dl className="cpn-public__facts">
            <dt>Reference</dt>
            <dd className="cpn-mono">{result.reference}</dd>
            <dt>Time</dt>
            <dd>{moment(result.redeemedAt).format("MMM D, YYYY h:mm A")}</dd>
            {result.remainingUses !== null && result.remainingUses !== undefined && (
              <>
                <dt>Uses left</dt>
                <dd>{result.remainingUses}</dd>
              </>
            )}
          </dl>
        </div>
      </div>
    );
  }

  const preview = computeDiscount(coupon, bill);
  const belowMin = !!coupon.minPurchaseAmount && bill !== null && bill < coupon.minPurchaseAmount;
  const canSubmit = view.redeemable.ok && view.pinConfigured && !!vendorName.trim() && /^\d{4,8}$/.test(pin) && !belowMin;
  const accent = card.accentColor || "#463bbd";

  return (
    <div className="cpn-public">
      <div className="cpn-public__panel">
        <div className="cpn-public__brand" style={{ background: accent }}>
          {card.logoUrl ? <img src={card.logoUrl} alt={brand} /> : <span>{coupon.brandName || "Coupon"}</span>}
        </div>
        <h1 className="cpn-public__headline">
          {discountHeadline(coupon).replace(" OFF", "")} discount
          <small>valid from {brand}</small>
        </h1>
        <p className="cpn-public__title">{coupon.title}</p>
        <ul className="cpn-public__conditions">
          {conditionLines(coupon).map((line) => (
            <li key={line}>{line}</li>
          ))}
          {view.remainingUses !== null && <li>{view.remainingUses} use(s) left on this code</li>}
          {view.recipient.name && <li>Issued to {view.recipient.name}</li>}
        </ul>
        {coupon.terms && <p className="cpn-public__terms">{coupon.terms}</p>}

        {!view.redeemable.ok ? (
          <Result status="error" title="Can't be used" subTitle={view.redeemable.reason} />
        ) : !view.pinConfigured ? (
          <Result status="warning" title="Not ready" subTitle={`${brand} hasn't set up store approval yet.`} />
        ) : (
          <div className="cpn-public__form">
            <label>
              Store name
              <Input value={vendorName} maxLength={80} onChange={(e) => setVendorName(e.target.value)} placeholder="e.g. Main St Market" />
            </label>
            <label>
              Bill amount {coupon.minPurchaseAmount ? "" : "(optional)"}
              <InputNumber
                min={0}
                value={bill}
                onChange={(v) => setBill(v === null || v === undefined ? null : Number(v))}
                inputMode="decimal"
                style={{ width: "100%" }}
                placeholder={coupon.currency || ""}
              />
            </label>
            {belowMin && (
              <p className="cpn-public__warn">
                Minimum purchase is {formatMoney(coupon.minPurchaseAmount, coupon.currency)}.
              </p>
            )}
            {preview !== null && !belowMin && (
              <p className="cpn-public__calc">
                Discount: <strong>{formatMoney(preview, coupon.currency)}</strong>
                {bill !== null && <> · Customer pays {formatMoney(Math.max(0, bill - preview), coupon.currency)}</>}
              </p>
            )}
            <label>
              Store PIN
              <Input.Password
                value={pin}
                inputMode="numeric"
                maxLength={8}
                autoComplete="one-time-code"
                onChange={(e) => setPin(e.target.value.replace(/\D/g, ""))}
                placeholder="PIN from the brand"
              />
            </label>
            {result && !result.accepted && (
              <p className="cpn-public__error">
                <CloseCircleFilled /> {result.reason}
              </p>
            )}
            <Button
              type="primary"
              size="large"
              block
              className="cpn-public__approve"
              style={{ background: accent, borderColor: accent }}
              loading={submitting}
              disabled={!canSubmit || result?.code === "PIN_LOCKED"}
              onClick={approve}
            >
              Approve discount
            </Button>
          </div>
        )}
      </div>
    </div>
  );
};

export default CouponLinkPage;
