import React from "react";
import { Row, Col, Radio, Form } from "antd";
import { SocketTopics } from "constants/enums";
import { sharePaymentUrlPublishTopic } from "hooks/MQTTConstants";
import { pushNotification } from "utils/notifications";
import EditPaymentModal from "components/Modals/Payment/EditPaymentModal";
import EditPaymentPayFastModal from "components/Modals/Payment/EditPaymentPayFastModal";
import { useDispatchPanel } from "../context";
import { wrapRequestPayload } from "../../../../../helpers/request/RequestPayload";

const PaymentProviderSection: React.FC = () => {
  const {
    isAddCardModalVisible,
    setIsAddCardModalVisible,
    webBooker,
    payWith,
    setPayWith,
    socket,
    encrypted_token,
    form,
  } = useDispatchPanel();

  if (!isAddCardModalVisible) return null;

  return (
    <Row className="mt-3">
      <Col span={24}>
        <Form.Item
          name="payWith"
          rules={[{ required: true, message: "Select a provider" }]}
        >
          <div className="d-flex flex-column justify-content-start align-items-start mb-3">
            <div className="ant-col ant-form-item-label">
              <label className="ant-form-item-required">
                Pay with provider
              </label>
            </div>

            <Radio.Group
              onChange={(e) => {
                setPayWith(e.target.value);
              }}
              disabled={webBooker}
              value={payWith}
            >
              <Radio value="stripe">Stripe</Radio>
              <Radio value="paystack">PayStack</Radio>
            </Radio.Group>
          </div>
        </Form.Item>

        {payWith === "stripe" && (
          <EditPaymentModal
            onClose={() => {
              setIsAddCardModalVisible(undefined);
            }}
            socket={socket}
            payment={isAddCardModalVisible}
            onShare={() => {
              const phone = form.getFieldValue("passengerPhoneNumber");
              const email = form.getFieldValue("passengerEmail");
              if ((phone && phone !== "") || (email && email !== "")) {
                socket.publishToEvent(
                  SocketTopics.PublishPageTopics,
                  sharePaymentUrlPublishTopic(encrypted_token?.connectionId),
                  wrapRequestPayload({
                    userId: encrypted_token?.userId,
                    notificationChannels: {
                      email,
                      phone,
                    },
                  })
                );
                pushNotification(
                  "Payment link shared successfully",
                  "success",
                  "TOP_CENTER",
                  1000
                );
              }
            }}
          />
        )}
        {payWith === "paystack" && (
          <EditPaymentPayFastModal
            onClose={() => {
              setIsAddCardModalVisible(undefined);
            }}
            socket={socket}
            payment={isAddCardModalVisible}
            onShare={() => {
              console.log("disable share");
            }}
          />
        )}
      </Col>
    </Row>
  );
};

export default PaymentProviderSection;
