import React from "react";
import { Row, Col, Card, Select, Button, Switch } from "antd";
import { ReactSVG } from "react-svg";
import PhoneInput from "react-phone-number-input";
import { useDashboard } from "../context";
import TimeRangeSelector from "./TimeRangeSelector";

let typingTimeout;

// The collapsible filter panel: project/role filters, phone + hail search,
// area/time filters and the (disabled) export card.
const FilterPanel: React.FC = () => {
  const {
    showTableFilterModal,
    projectFilter,
    handleProjectFilter,
    projectFilterLoading,
    projectFilterValue,
    projectFilterOptions,
    setProjectPagePaths,
    setPhonePagePaths,
    showHail,
    setShowHailPaths,
    timeFilter,
    handleTimeFilter,
    timeFilterLoading,
    timeFilterOptions,
    timeFilterValue,
    setAreaPagePaths,
    setTimePagePaths,
  } = useDashboard();

  return (
    <Row
      gutter={30}
      className="mb-2"
      style={showTableFilterModal ? {} : { display: "none" }}
    >
      <Col className="gutter-row" sm={24} md={10}>
        <Card className="filter-card">
          <Row gutter={16} className="d-flex px-1 flex-wrap">
            <div>
              <h5 className="mb-0">Filters</h5>
            </div>
            <div onClick={() => handleProjectFilter("manager")}>
              <Button
                className={`beam-btn w-70 ${projectFilter === "manager" ? "green-btn cover" : ""
                  }`}
              >
                Manager
              </Button>
            </div>
            <div onClick={() => handleProjectFilter("project")}>
              <Button
                className={`beam-btn w-70 ${projectFilter === "project" ? "green-btn cover" : ""
                  }`}
              >
                Project
              </Button>
            </div>
            <div onClick={() => handleProjectFilter("dispatcher")}>
              <Button
                className={`beam-btn w-70 ${projectFilter === "dispatcher" ? "green-btn cover" : ""
                  }`}
              >
                Dispatcher
              </Button>
            </div>
            <div onClick={() => handleProjectFilter("responder")}>
              <Button
                className={`beam-btn w-70 ${projectFilter === "responder" ? "green-btn cover" : ""
                  }`}
              >
                Responder
              </Button>
            </div>
          </Row>
          <Row className="mt-3">
            <Col span={24}>
              <Select
                className="w-full"
                placeholder="Select ID"
                loading={projectFilterLoading}
                value={projectFilterValue}
                allowClear
                showSearch
                filterOption={(input, option) => {
                  return (option!.label as unknown as string)
                    ?.toLowerCase()
                    .includes(input.toLowerCase());
                }}
                options={projectFilterOptions}
                onChange={(value) => {
                  setProjectPagePaths(value);
                }}
              ></Select>
            </Col>
          </Row>
          <Row gutter={15} className="d-flex px-2 flex-wrap mt-4">
            <Col sm={24} md={4}>
              <h5 className="mb-0">Search</h5>
            </Col>
          </Row>
          <Row className="mt-3">
            <Col span={24}>
              <PhoneInput
                placeholder="Phone number"
                defaultCountry="US"
                allowClear
                onChange={(phone) => {
                  console.log("phone", phone);
                  if (typingTimeout) clearTimeout(typingTimeout);
                  typingTimeout = setTimeout(() => {
                    setPhonePagePaths(phone);
                  }, 700);
                }}
              />
            </Col>
          </Row>

          <Row className="d-flex px-2 flex-wrap mt-4">
            <Col span={24} style={{ display: "flex", alignItems: "center" }}>
              <h5 className="mr-3">Show hail rides</h5>
              <Switch
                onChange={(value) => {
                  setShowHailPaths(value);
                }}
                defaultChecked={showHail.current}
              />
            </Col>
          </Row>
        </Card>
      </Col>
      <Col className="gutter-row" sm={24} md={10}>
        <Card className="filter-card">
          <Row className="d-flex flex-wrap" id="filters">
            <div>
              <h5 className="mb-0">Filters</h5>
            </div>
            <div onClick={() => handleTimeFilter("state")}>
              <Button
                className={`beam-btn w-70 ${timeFilter === "state" ? "green-btn cover" : ""
                  }`}
              >
                State
              </Button>
            </div>
            <div onClick={() => handleTimeFilter("city")}>
              <Button
                className={`beam-btn w-70 ${timeFilter === "city" ? "green-btn cover" : ""
                  }`}
              >
                City
              </Button>
            </div>
            <div onClick={() => handleTimeFilter("county")}>
              <Button
                className={`beam-btn w-70 ${timeFilter === "county" ? "green-btn cover" : ""
                  }`}
              >
                County
              </Button>
            </div>
            <div onClick={() => handleTimeFilter("zip")}>
              <Button
                className={`beam-btn w-70 ${timeFilter === "zip" ? "green-btn cover" : ""
                  }`}
              >
                Zip
              </Button>
            </div>
          </Row>
          <Row className="mt-3">
            <Col xs={24}>
              <Select
                className="w-full"
                placeholder="Select ID"
                loading={timeFilterLoading}
                allowClear
                options={timeFilterOptions}
                value={timeFilterValue}
                onChange={(value) => {
                  setAreaPagePaths(value);
                }}
              ></Select>
            </Col>
          </Row>
          <Row gutter={15} className="d-flex flex-wrap mt-3 mx-0">
            <TimeRangeSelector
              onChange={(value) => {
                console.log("value here", value);
                setTimePagePaths(value);
              }}
              value={undefined}
            />
          </Row>
          <Row className="mt-3">
            <Col span={24}>
              <Select
                className="w-full"
                placeholder="Select Hour(s)"
                disabled
              ></Select>
            </Col>
          </Row>
        </Card>
      </Col>
      <Col className="gutter-row" sm={24} md={4}>
        <Card className="filter-card">
          <p className="mb-2 text-center">Export to</p>

          <div className="d-flex flex-row flex-md-column justify-content-center">
            <div>
              <Button
                className="beam-btn export mb-0 mb-md-2 mr-3 mr-md-0"
                disabled
              >
                <ReactSVG src="/images/export-csv.svg" />
              </Button>
            </div>
            <div>
              <Button
                className="beam-btn export mb-0 mb-md-2 mr-3 mr-md-0"
                disabled
              >
                <ReactSVG src="/images/export-xls.svg" />
              </Button>
            </div>
            <div>
              <Button
                className="beam-btn export mb-0 mb-md-2 mr-3 mr-md-0"
                disabled
              >
                <ReactSVG src="/images/export-pdf.svg" />
              </Button>
            </div>
          </div>
        </Card>
      </Col>
    </Row>
  );
};

export default FilterPanel;
