import React, { FC, useState, useEffect, useRef } from "react";
import { ReactSVG } from "react-svg";
import { SCHOOL_BUS_MENU_ITEMS } from "utils/PageTypes";
import { RootState } from "reducers/rootReducer";
import { useDispatch, useSelector } from "react-redux";
import { ENCRYPT_TOKEN } from "reducers/reducer";
import { SocketTopics, UserTopics, ExtendedBioTopics } from "constants/enums";
import { wrapRequestPayload } from "../../../helpers/request/RequestPayload";
import {
  getCreateAssistPagePublishTopic,
  getCreateAssistPageSubscriptionTopic,
} from "hooks/MQTTConstants";
import { pushNotification } from "utils/notifications";
import useSocketActions from "../../../hooks/socketActions";

const SideBar: FC<{ socket?: ISocket; params: any; userRole?: any }> = ({
  socket,
  params,
  userRole,
}) => {
  const { screen, setScreen } = params;
  const { projects, encrypted_token, userInfo } = useSelector(
    (state: RootState) => state.auth
  );
  const dispatch = useDispatch();
  const { getUserRequestPayload } = useSocketActions();
  const [isMobile, setIsMobile] = useState(window.innerWidth <= 768);
  // Current user's beamId, resolved from their live profile (userInfo isn't
  // populated in the School flow). Used in the createAssistPage request.
  const beamIdRef = useRef<string | undefined>(userInfo?.beamId);

  // Fetch the current user's live data so we have their beamId for assist pages.
  useEffect(() => {
    if (encrypted_token?.userId && socket?.client) {
      socket.publishToServiceIdSurvey(
        SocketTopics.SurveyTopics,
        UserTopics.SearchInUser,
        getUserRequestPayload(
          encrypted_token?.userId,
          "$",
          "$.persistent.static.live"
        ),
        ExtendedBioTopics.GetUserBio,
        encrypted_token?.serviceId
      );
      socket.subscribeToSurvey(
        SocketTopics.SurveyTopics,
        ExtendedBioTopics.GetUserBio,
        (response) => {
          const live = response?.data?.[0]?.[0];
          const profile = live?.profile;
          beamIdRef.current =
            live?.alternativeIds?.beamId ||
            live?.beamIds?.[0] ||
            (profile?.firstName && profile?.lastName
              ? `${profile.firstName}.${profile.lastName}`.toLowerCase()
              : undefined);
        }
      );
    }
  }, [encrypted_token?.userId, socket?.client]);

  // Create an assist (emergency) page for the current user, then open the
  // chat in a new tab redirected straight to that page.
  const createAssistPage = () => {
    if (!encrypted_token?.connectionId) return;
    const pageRequest: any = {
      userId: encrypted_token?.userId,
      beamId: beamIdRef.current || userInfo?.beamId, // current user beam id
      configRef: {
        configUserCudbServiceId: projects?.userServiceId,
        configUserId: projects?.adminUserId,
      },
    };
    socket?.subscribeToEvent(
      SocketTopics.SubscribePageTopics,
      getCreateAssistPageSubscriptionTopic(encrypted_token?.connectionId),
      (response) => {
        const assistPageId =
          response?.response?.data?.page?.objectId?.toString();
        console.log("assist page id", assistPageId);
        if (!assistPageId) {
          pushNotification(
            "Failed to create assist page",
            "error",
            "TOP_CENTER",
            1000
          );
          return;
        }
        dispatch(
          ENCRYPT_TOKEN({
            data: {
              payload: JSON.stringify({
                userId: encrypted_token?.userId,
                connectionId: encrypted_token?.connectionId,
                cudbServiceId: projects?.userServiceId,
              }),
            },
            callback: (token) => {
              window.open(
                `${process.env.REACT_APP_WEB}/auth/login?token=${token.encryptedPayload}&redirect=page/${assistPageId}`,
                "_blank"
              );
            },
          })
        );
      }
    );
    socket?.publishToEvent(
      SocketTopics.PublishPageTopics,
      getCreateAssistPagePublishTopic(encrypted_token?.connectionId),
      wrapRequestPayload(pageRequest)
    );
  };
  const MENU_ITEMS: MenuItems[] = [
    {
      id: SCHOOL_BUS_MENU_ITEMS.Overview,
      key: "dashboard",
      name: "Dashboard",
      src: "/images/school-dashboard-icon.svg",
      onClick: () => {
        setScreen(SCHOOL_BUS_MENU_ITEMS.Overview);
      },
    },
    {
      id: SCHOOL_BUS_MENU_ITEMS.Players,
      key: "players",
      name: "Players",
      src: "/images/school-students-icon.svg",
      onClick: () => {
        setScreen(SCHOOL_BUS_MENU_ITEMS.Students);
      },
    },
    {
      id: SCHOOL_BUS_MENU_ITEMS.Parents,
      key: "parents",
      name: "Parents",
      src: "/images/school-parents-icon.svg",
      onClick: () => {
        setScreen(SCHOOL_BUS_MENU_ITEMS.Parents);
      },
    },
    {
      id: SCHOOL_BUS_MENU_ITEMS.Coaches,
      key: "coaches",
      name: "Coaches",
      src: "/images/school-teachers-icon.svg",
      onClick: () => {
        setScreen(SCHOOL_BUS_MENU_ITEMS.Teachers);
      },
    },
    {
      id: SCHOOL_BUS_MENU_ITEMS.Staff,
      key: "staff",
      name: "Staff",
      src: "/images/school-staff-icon.svg",
      onClick: () => {
        setScreen(SCHOOL_BUS_MENU_ITEMS.Staff);
      },
    },
    {
      id: SCHOOL_BUS_MENU_ITEMS.Classes,
      key: "classes",
      name: "Teams",
      src: "/images/school-classes-icon.svg",
      onClick: () => {
        setScreen(SCHOOL_BUS_MENU_ITEMS.Classes);
      },
    },
    {
      id: SCHOOL_BUS_MENU_ITEMS.Scheduler,
      key: "scheduler",
      name: "Scheduler",
      src: "/images/school-schedule-icon.svg",
      onClick: () => {
        setScreen(SCHOOL_BUS_MENU_ITEMS.Scheduler);
      },
    },
    // {
    //   id: SCHOOL_BUS_MENU_ITEMS.Dashboard,
    //   key: "dashboard",
    //   name: "Lectures",
    //   src: "/images/school-lectures-icon.svg",
    //   onClick: () => {
    //     setScreen(SCHOOL_BUS_MENU_ITEMS.Dashboard);
    //   },
    // },
    {
      id: SCHOOL_BUS_MENU_ITEMS.Events,
      key: "events",
      name: "Events",
      src: "/images/school-events-icon.svg",
      onClick: () => {
        setScreen(SCHOOL_BUS_MENU_ITEMS.Events);
      },
    },
    {
      id: SCHOOL_BUS_MENU_ITEMS.Exams,
      key: "exams",
      name: "Exams",
      src: "/images/school-exams-icon.svg",
      onClick: () => {
        setScreen(SCHOOL_BUS_MENU_ITEMS.Exams);
      },
    },
    {
      id: SCHOOL_BUS_MENU_ITEMS.Documents,
      key: "documents",
      name: "Documents",
      src: "/images/school-documents-icon.svg",
      onClick: () => {
        setScreen(SCHOOL_BUS_MENU_ITEMS.Documents);
      },
    },
    {
      id: SCHOOL_BUS_MENU_ITEMS.Assist,
      key: "assist",
      name: "Assist",
      src: "/images/emergency-icon.svg",
      onClick: () => {
        createAssistPage();
      },
    },
    {
      id: SCHOOL_BUS_MENU_ITEMS.Chat,
      key: "chat",
      name: "Pages",
      src: "/images/school-chat-icon.svg",
      onClick: () => {
        dispatch(
          ENCRYPT_TOKEN({
            data: {
              payload: JSON.stringify({
                userId: encrypted_token?.userId,
                connectionId: encrypted_token?.connectionId,
                cudbServiceId: projects?.userServiceId,
              }),
            },
            callback: (token) => {
              window.open(
                `${process.env.REACT_APP_WEB}/auth/login?token=${token.encryptedPayload}`,
                "_blank"
              );
            },
          })
        );
      },
    },
  ];

  useEffect(() => {
    const mediaQuery = window.matchMedia('(max-width: 768px)');
    const handleChange = (e) => setIsMobile(e.matches);

    // Add listener for changes
    mediaQuery.addEventListener('change', handleChange);

    // Cleanup listener on unmount
    return () => mediaQuery.removeEventListener('change', handleChange);
  }, []);

  return (
    <div
      className="main-column search-panel mr-4"
      style={{
        width: isMobile ? 90 : 110,
        position: "fixed",
        top: 75,
        left: 0,
        height: "122vh",
      }}
    >
      <div className="sidebar" style={{ borderRadius: 0 }}>
        <ul>
          {MENU_ITEMS?.filter((x) => {
            // Lectures and Exams are hidden for admins
            const hiddenForAdmin = [
              SCHOOL_BUS_MENU_ITEMS.Dashboard, // Lectures
              SCHOOL_BUS_MENU_ITEMS.Exams,
            ];
            if (userRole === "admin") return !hiddenForAdmin.includes(x.id);
            // Dashboard (Overview) and Staff are admin-only
            const adminOnly = [
              SCHOOL_BUS_MENU_ITEMS.Overview,
              SCHOOL_BUS_MENU_ITEMS.Staff,
              SCHOOL_BUS_MENU_ITEMS.Classes,
              SCHOOL_BUS_MENU_ITEMS.Scheduler,
            ];
            if (adminOnly.includes(x.id)) return false;
            // Lectures, Exams, Documents, Parents and Events are visible to everyone
            const sharedItems = [
              SCHOOL_BUS_MENU_ITEMS.Dashboard, // Lectures
              SCHOOL_BUS_MENU_ITEMS.Exams,
              SCHOOL_BUS_MENU_ITEMS.Documents,
              SCHOOL_BUS_MENU_ITEMS.Parents,
              SCHOOL_BUS_MENU_ITEMS.Events,
              SCHOOL_BUS_MENU_ITEMS.Chat, // Pages
              SCHOOL_BUS_MENU_ITEMS.Assist,
            ];
            if (sharedItems.includes(x.id)) return true;
            if (userRole === x?.key) return true;
            return false;
          })?.map((item) => (
            <li
              key={"selected-" + item.id}
              className={screen === item.id && "selected"}
              onClick={() => {
                const tempItem = MENU_ITEMS.find((x) => {
                  return x.id === item.id;
                });
                tempItem?.onClick();
              }}
            >
              <div>
                <div>
                  <ReactSVG className={item.cssClass} src={item.src} />
                  <p>{item.name}</p>
                </div>
              </div>
            </li>
          ))}
        </ul>
      </div>
    </div>
  );
};

export default SideBar;
