import { useCallback, useEffect, useRef, useState } from "react";
import { useDispatch, useSelector } from "react-redux";
import { message } from "antd";
import { SocketTopics } from "constants/enums";
import {
  getCreateEventPagePublishTopic,
  getPageUpdateRequestPublishTopic,
} from "hooks/MQTTConstants";
import { RootState } from "reducers/rootReducer";
import { GET_AGGREGATE, SET_SUBMITTED } from "reducers/reducer";
import { formatForRedis } from "utils/appUtil";
import { wrapRequestPayload } from "../../../../../../helpers/request/RequestPayload";
import {
  buildEventRequestsFromValues,
  pageToFormValues,
  publishEventRequests,
} from "../../../DispatchPanel/dispatchPipeline";
import {
  DriverRecord,
  toResponderValue,
} from "../../../common/driverAvailability/availability";
import { RideRow } from "../types";

const PENDING_TIMEOUT_MS = 20000;

/**
 * Assigns a driver to a ride without opening the booking form.
 *
 * It rebuilds the form values from the ride's saved booking and runs them
 * through the same pipeline as "Save assignment", so the page, its return /
 * stair-chair siblings, crew permissions and the driver's "Accept job?"
 * message are all produced exactly as the form would.
 */
export const useQuickAssign = (socket: ISocket, rows: RideRow[]) => {
  const dispatch = useDispatch();
  const { encrypted_token, accounts, projects, vehicles, submitted } = useSelector(
    (state: RootState) => state.auth
  );
  // pageId -> driver being assigned, for optimistic display on the board.
  const [pending, setPending] = useState<Record<string, DriverRecord>>({});
  const awaitingReplies = useRef(0);

  const clearPending = useCallback((pageId: string) => {
    setPending((prev) => {
      if (!prev[pageId]) return prev;
      const next = { ...prev };
      delete next[pageId];
      return next;
    });
  }, []);

  // Done once the live update shows the new driver on the ride.
  useEffect(() => {
    Object.entries(pending).forEach(([pageId, driver]) => {
      const row = rows.find((r) => `${r.key}` === pageId);
      if (row?.driverId === driver.id) clearPending(pageId);
    });
  }, [rows, pending, clearPending]);

  // createEventPage replies land in `submitted`. Consume ours so a stale
  // "submitted" doesn't make the booking form close itself when opened later.
  useEffect(() => {
    if (!submitted || awaitingReplies.current === 0) return;
    awaitingReplies.current -= 1;
    if (submitted.status === false) {
      message.error("Assignment failed. Open the ride to try again.");
      setPending({});
    }
    dispatch({ type: SET_SUBMITTED, payload: false });
  }, [submitted, dispatch]);

  const getPagesByUuid = (uuid: string) =>
    new Promise<any>((resolve) =>
      dispatch(
        GET_AGGREGATE({
          requestData: {
            select: {
              index: {
                searchIndex: `${process.env.REACT_APP_ECO_SYSTEM}:page:ride`,
                searchQuery: `@partitions:{'org\\:${formatForRedis(projects?.userServiceId)}'}`,
                searchOptions: "VERBATIM TIMEOUT 10000",
              },
              load: { objectId: "$.objectId", uuid: "$..profile.uuid", order: "$..profile.order" },
            },
            filter: { expression: `exists(@uuid) && @uuid == '${uuid}'` },
          },
          callback: resolve,
        })
      )
    );

  /** Pre-fill the driver's usual vehicle when the ride has none. */
  const pairedVehicle = (driver: DriverRecord, current: any) => {
    if (current?.value) return current;
    const match = (vehicles || []).find(
      (v: any) => v?.obj?.assosiatedUserId?.toString() === driver.id
    );
    return match?.obj?.vehicleId
      ? { type: "vehicle", value: match.obj.vehicleId, obj: match.obj, valueName: match.obj.name }
      : current;
  };

  /** Returns false when the ride can't be quick-assigned (caller should open the form). */
  const assign = async (row: RideRow, driver: DriverRecord): Promise<boolean> => {
    const page = row.action?.page;
    const saved = page?.profile?.unstructuredAttributes;
    if (!saved) {
      message.info("This ride has no saved booking details — opening it instead.");
      return false;
    }
    const pageId = `${row.key}`;
    setPending((prev) => ({ ...prev, [pageId]: driver }));
    setTimeout(() => clearPending(pageId), PENDING_TIMEOUT_MS);

    try {
      const values: any = pageToFormValues(saved);
      // A driver can't be primary and secondary on the same leg.
      const secondaries = (values.secondaryResponder?.responders || []).filter(
        (r: any) => `${r.id}` !== driver.id
      );
      values.primaryResponder = toResponderValue(driver);
      if (values.secondaryResponder) {
        values.secondaryResponder = {
          type: "responder",
          responders: secondaries,
          values: secondaries.map((r: any) => `${r.id}`),
        };
      }
      values.vehicle = pairedVehicle(driver, values.vehicle);

      const { eventRequests, deletedPageIds } = await buildEventRequestsFromValues(values, {
        userId: encrypted_token?.userId,
        connectionId: encrypted_token?.connectionId,
        accounts,
        projects,
        pageId,
        selectedPage: { page },
        getPagesByUuid,
        submitPageId: true,
      });
      const requests = publishEventRequests(eventRequests, {
        skipStatusUpdate: row.pageStatus === "black",
        userId: encrypted_token?.userId,
      });

      awaitingReplies.current += requests.length;
      requests.forEach((request) =>
        socket.publishToEvent(
          SocketTopics.PublishPageTopics,
          getCreateEventPagePublishTopic(request.connectionId),
          wrapRequestPayload(request)
        )
      );
      // Same clean-up the booking form does for sibling pages it no longer needs.
      (deletedPageIds || []).forEach((id) =>
        socket.publishToEvent(
          SocketTopics.PublishPageTopics,
          getPageUpdateRequestPublishTopic(encrypted_token?.connectionId),
          wrapRequestPayload({
            objectId: `${id}`,
            changes: [{ op: "replace", path: "/objectStatus", value: "deleted" }],
          })
        )
      );
      message.success(`Assigning ${row.patientName || "ride"} to ${driver.name}…`);
      return true;
    } catch (error) {
      console.error("quick assign failed", error);
      clearPending(pageId);
      message.error("Couldn't assign this ride. Open it to assign manually.");
      return true;
    }
  };

  return { assign, pending };
};
