import React, { useMemo, useRef, useState } from "react";
import { Alert, Button, Form, Modal, Popconfirm, Select, Tag, Tooltip } from "antd";
import { DeleteOutlined, PlusOutlined } from "@ant-design/icons";
import dayjs from "dayjs";
import moment, { Moment } from "moment";
import { FormModal } from "../../common/ui";
import { SHIFT_LOCATIONS, SHIFT_TYPES, getShiftType } from "../../common/shiftTypes";
import AutoFormatTimePicker from "./AutoFormatTimePicker";
import {
  SLOT_FORMAT,
  Slot,
  TimeOff,
  findTimeOffConflict,
  formatHours,
  intervalsOverlap,
  isOnShiftSlot,
  parseSlot,
  timeOffsForDay,
} from "./shiftUtils";

const LAST_LOCATION_KEY = "mx-shift:lastLocation";

const readLastLocation = () => {
  try {
    const value = localStorage.getItem(LAST_LOCATION_KEY);
    return SHIFT_LOCATIONS.includes(value) ? value : undefined;
  } catch {
    return undefined;
  }
};

const writeLastLocation = (value: string) => {
  try {
    localStorage.setItem(LAST_LOCATION_KEY, value);
  } catch {
    // Storage can be unavailable (private mode); the default is a convenience.
  }
};

interface Item {
  id: string;
  start?: Moment;
  end?: Moment;
  shiftType?: string;
  locationType?: string;
  raw: any;
}

let nextId = 0;
const newId = () => `slot-${++nextId}`;

const toItems = (slots: Slot[], dayKey: string): Item[] =>
  (slots || [])
    .map((slot) => {
      const parsed = typeof slot === "object" ? parseSlot(slot, dayKey) : null;
      return {
        id: newId(),
        start: parsed ? moment(parsed.start.valueOf()) : undefined,
        end: parsed ? moment(parsed.end.valueOf()) : undefined,
        shiftType: slot?.shiftType,
        locationType: slot?.locationType,
        raw: slot,
      };
    })
    .sort((a, b) => (a.start?.valueOf() ?? 0) - (b.start?.valueOf() ?? 0));

const toSlot = (item: Item): Slot => {
  // Unparseable legacy entries are kept exactly as stored.
  if (!item.start || !item.end) return item.raw;
  return {
    ...(typeof item.raw === "object" ? item.raw : {}),
    time: [item.start.format(SLOT_FORMAT), item.end.format(SLOT_FORMAT)],
    shiftType: item.shiftType,
    locationType: item.locationType,
  };
};

const rangeLabel = (start: Moment, end: Moment) =>
  `${start.format("HH:mm")}–${end.format("HH:mm")}`;

const typeOptions = SHIFT_TYPES.map((t) => ({
  value: t.value,
  label: (
    <span className="mx-shift-option">
      <i style={{ background: t.color }} />
      {t.label}
    </span>
  ),
}));
const locationOptions = SHIFT_LOCATIONS.map((l) => ({ value: l, label: l }));

interface SlotEditorModalProps {
  driverName: string;
  dayKey: string;
  slots: Slot[];
  timeOffs: TimeOff[];
  timeOffLoading?: boolean;
  /** Roster days after `dayKey`, used by "Copy to rest of week". */
  remainingDays: string[];
  onCancel: () => void;
  onSave: (slots: Slot[]) => void;
  onCopyToRest: (slots: Slot[]) => void;
  onClearDay: () => void;
}

const SlotEditorModal = ({
  driverName,
  dayKey,
  slots,
  timeOffs,
  timeOffLoading,
  remainingDays,
  onCancel,
  onSave,
  onCopyToRest,
  onClearDay,
}: SlotEditorModalProps) => {
  const [form] = Form.useForm();
  const [items, setItems] = useState<Item[]>(() => toItems(slots, dayKey));
  const [dirty, setDirty] = useState(false);
  const [showMissing, setShowMissing] = useState(false);
  const draftRef = useRef<HTMLDivElement>(null);
  const dayOffs = timeOffsForDay(dayKey, timeOffs);
  const initialValues = useMemo(
    () => ({ shiftType: "Shift", locationType: readLastLocation() }),
    []
  );

  const toInterval = (startTime: Moment, endTime: Moment) => {
    const start = moment(`${dayKey} ${startTime.format("HH:mm")}`, SLOT_FORMAT);
    const end = moment(`${dayKey} ${endTime.format("HH:mm")}`, SLOT_FORMAT);
    if (!end.isAfter(start)) end.add(1, "day"); // overnight
    return { start, end };
  };

  const focusDraft = (selector: string) =>
    setTimeout(() => (draftRef.current?.querySelector(`${selector} input`) as HTMLInputElement)?.focus());

  /** Validates the draft row and appends it; resolves to the new list or null. */
  const addDraft = async (): Promise<Item[] | null> => {
    let values: any;
    try {
      values = await form.validateFields();
    } catch {
      return null;
    }
    const { start, end } = toInterval(values.startTime, values.endTime);
    const next = [
      ...items,
      {
        id: newId(),
        start,
        end,
        shiftType: values.shiftType,
        locationType: values.locationType,
        raw: {},
      },
    ].sort((a, b) => (a.start?.valueOf() ?? 0) - (b.start?.valueOf() ?? 0));
    setItems(next);
    setDirty(true);
    writeLastLocation(values.locationType);
    form.setFieldsValue({ startTime: null, endTime: null });
    focusDraft(".mx-shift-slot__start");
    return next;
  };

  const hasDraft = () => {
    const { startTime, endTime } = form.getFieldsValue(["startTime", "endTime"]);
    return !!(startTime || endTime);
  };

  /** Current slots including a filled-in draft, or null when invalid. */
  const collect = async (): Promise<Slot[] | null> => {
    let list = items;
    if (hasDraft()) {
      const next = await addDraft();
      if (!next) return null;
      list = next;
    }
    if (list.some((i) => i.start && (!i.shiftType || !i.locationType))) {
      setShowMissing(true);
      return null;
    }
    return list.map(toSlot);
  };

  const handleSave = async () => {
    const result = await collect();
    if (result) onSave(result);
  };

  const handleCopy = async () => {
    const result = await collect();
    if (result) onCopyToRest(result);
  };

  const handleCancel = () => {
    if (!dirty && !hasDraft()) return onCancel();
    Modal.confirm({
      title: "Discard changes?",
      content: "The slots you changed for this day haven't been saved.",
      okText: "Discard",
      okButtonProps: { danger: true },
      cancelText: "Keep editing",
      onOk: onCancel,
    });
  };

  const updateItem = (id: string, changes: Partial<Item>) => {
    setItems((prev) => prev.map((i) => (i.id === id ? { ...i, ...changes } : i)));
    setDirty(true);
  };

  const removeItem = (id: string) => {
    setItems((prev) => prev.filter((i) => i.id !== id));
    setDirty(true);
  };

  // Enter in the start field jumps to the end field; Enter in the end field adds the slot.
  const handleDraftKeyDown = (e: React.KeyboardEvent) => {
    if (e.key !== "Enter") return;
    const target = e.target as HTMLElement;
    if (target.closest(".mx-shift-slot__start")) {
      focusDraft(".mx-shift-slot__end");
    } else if (target.closest(".mx-shift-slot__end")) {
      setTimeout(addDraft);
    }
  };

  const endTimeRules = [
    { required: true, message: "End time" },
    ({ getFieldValue }) => ({
      validator: (_, value: Moment) => {
        const startTime: Moment = getFieldValue("startTime");
        if (!value || !startTime) return Promise.resolve();
        if (value.format("HH:mm") === startTime.format("HH:mm")) {
          return Promise.reject(new Error("End must differ from start"));
        }
        const { start, end } = toInterval(startTime, value);
        const clash = items.find(
          (i) => i.start && intervalsOverlap(start.valueOf(), end.valueOf(), i.start.valueOf(), i.end.valueOf())
        );
        if (clash) {
          return Promise.reject(new Error(`Overlaps ${rangeLabel(clash.start, clash.end)}`));
        }
        const off = findTimeOffConflict(start.valueOf(), end.valueOf(), timeOffs);
        if (off) return Promise.reject(new Error(`Overlaps time off (${off.label})`));
        return Promise.resolve();
      },
    }),
  ];

  const totalMinutes = items.reduce(
    (sum, i) => (i.start && isOnShiftSlot(i) ? sum + i.end.diff(i.start, "minute") : sum),
    0
  );

  return (
    <FormModal
      open
      width={680}
      title={driverName}
      subtitle={dayjs(dayKey).format("dddd, MMMM D, YYYY")}
      onCancel={handleCancel}
      onSubmit={handleSave}
      footerExtra={
        <span className="mx-shift-slot__quick">
          <Popconfirm
            title="Remove every slot for this day?"
            okText="Clear"
            okButtonProps={{ danger: true }}
            onConfirm={onClearDay}
            disabled={!items.length && !slots?.length}
          >
            <Button type="text" danger disabled={!items.length && !slots?.length}>
              Clear day
            </Button>
          </Popconfirm>
          <Popconfirm
            title={
              <div style={{ maxWidth: 280 }}>
                Replace {driverName}'s slots on the {remainingDays.length} remaining{" "}
                {remainingDays.length === 1 ? "day" : "days"} (
                {dayjs(remainingDays[0]).format("ddd")}
                {remainingDays.length > 1 && ` – ${dayjs(remainingDays[remainingDays.length - 1]).format("ddd")}`}
                ) with these? Days with time off are skipped.
              </div>
            }
            okText="Copy"
            onConfirm={handleCopy}
            disabled={!remainingDays.length || !items.length}
          >
            <Tooltip title={!remainingDays.length ? "This is the last day of the roster" : undefined}>
              <Button className="mx-btn-secondary" disabled={!remainingDays.length || !items.length}>
                Copy to rest of week
              </Button>
            </Tooltip>
          </Popconfirm>
        </span>
      }
    >
      <div className="mx-shift mx-shift-slot">
        {dayOffs.length > 0 && (
          <Alert
            className="mb-3"
            type="error"
            showIcon
            message={`${driverName} has approved time off`}
            description={dayOffs.map((off) => (
              <div key={off.key}>
                {off.label}
                {off.reason ? ` · ${off.reason}` : ""}
              </div>
            ))}
          />
        )}
        {timeOffLoading && <div className="mx-shift-slot__hint mb-2">Checking time off…</div>}

        <div className="mx-shift-slot__panel" ref={draftRef} onKeyDown={handleDraftKeyDown}>
          <div className="mx-shift-slot__panel-title">Add a slot</div>
          <Form form={form} layout="vertical" requiredMark={false} initialValues={initialValues}>
            <div className="mx-shift-slot__draft">
              <Form.Item
                className="mx-shift-slot__start"
                label="Start"
                name="startTime"
                rules={[{ required: true, message: "Start time" }]}
              >
                <AutoFormatTimePicker placeholder="06:00" autoComplete="off" autoFocus />
              </Form.Item>
              <Form.Item
                className="mx-shift-slot__end"
                label="End"
                name="endTime"
                dependencies={["startTime"]}
                rules={endTimeRules}
              >
                <AutoFormatTimePicker placeholder="14:00" autoComplete="off" />
              </Form.Item>
              <Form.Item
                label="Type"
                name="shiftType"
                rules={[{ required: true, message: "Pick a type" }]}
              >
                <Select options={typeOptions} style={{ width: 130 }} />
              </Form.Item>
              <Form.Item
                label="Location"
                name="locationType"
                rules={[{ required: true, message: "Pick a location" }]}
              >
                <Select options={locationOptions} placeholder="Location" style={{ width: 140 }} />
              </Form.Item>
              <Form.Item label=" " colon={false}>
                <Button className="mx-btn-primary" icon={<PlusOutlined />} onClick={() => addDraft()}>
                  Add
                </Button>
              </Form.Item>
            </div>
          </Form>
          <div className="mx-shift-slot__hint">
            Type times like 0600 and press Enter. An end time earlier than the start runs overnight.
          </div>
        </div>

        <div className="mx-shift-slot__list-head">
          <span>Slots this day</span>
          {totalMinutes > 0 && <span>{formatHours(totalMinutes)} on shift</span>}
        </div>
        {items.length === 0 ? (
          <div className="mx-shift-slot__empty">No slots yet — this driver is off.</div>
        ) : (
          items.map((item) => {
            const type = getShiftType(item.shiftType);
            if (!item.start) {
              return (
                <div key={item.id} className="mx-shift-slot__item">
                  <span className="mx-shift-slot__item-time">{String(item.raw)}</span>
                  <Button size="small" icon={<DeleteOutlined />} onClick={() => removeItem(item.id)} />
                </div>
              );
            }
            const overnight = !item.end.isSame(item.start, "day");
            const offClash = findTimeOffConflict(item.start.valueOf(), item.end.valueOf(), timeOffs);
            const overlap = items.some(
              (o) =>
                o.id !== item.id &&
                o.start &&
                intervalsOverlap(item.start.valueOf(), item.end.valueOf(), o.start.valueOf(), o.end.valueOf())
            );
            return (
              <div
                key={item.id}
                className="mx-shift-slot__item"
                style={{ borderLeftColor: type.color }}
              >
                <span className="mx-shift-slot__item-time">
                  {rangeLabel(item.start, item.end)}
                  {overnight && <sup className="mx-shift-chip__next">+1d</sup>}
                  <small>{formatHours(item.end.diff(item.start, "minute"))}</small>
                </span>
                {offClash && <Tag color="red">Time off</Tag>}
                {overlap && <Tag color="orange">Overlaps</Tag>}
                <Select
                  value={item.shiftType}
                  options={typeOptions}
                  placeholder="Type"
                  status={showMissing && !item.shiftType ? "error" : undefined}
                  onChange={(v) => updateItem(item.id, { shiftType: v })}
                  style={{ width: 130 }}
                />
                <Select
                  value={item.locationType}
                  options={locationOptions}
                  placeholder="Location"
                  status={showMissing && !item.locationType ? "error" : undefined}
                  onChange={(v) => updateItem(item.id, { locationType: v })}
                  style={{ width: 140 }}
                />
                <Tooltip title="Remove">
                  <Button
                    size="small"
                    className="mx-shift-slot__remove"
                    icon={<DeleteOutlined />}
                    onClick={() => removeItem(item.id)}
                  />
                </Tooltip>
              </div>
            );
          })
        )}
        {showMissing && items.some((i) => i.start && (!i.shiftType || !i.locationType)) && (
          <div className="mx-shift-slot__error">Pick a type and location for every slot.</div>
        )}
      </div>
    </FormModal>
  );
};

export default SlotEditorModal;
