const FareTypeInput = (props: any) => {
  const { value, placeholder, onChange, dispatchOptions, disabled, estimatedFare } = props;

  const options = dispatchOptions || [
    { id: "fixed", name: "Fixed" },
    { id: "fixedEstimate", name: "Fixed Estimate" },
    { id: "variable", name: "Variable" },
    { id: "bid", name: "Bid" },
  ];

  // Memoize bid boundaries to update with estimatedFare
  const { isBidAllowed, minBid, maxBid } = useMemo(() => {
    const allowed = estimatedFare && estimatedFare > 0;
    return {
      isBidAllowed: allowed,
      minBid: allowed ? estimatedFare * 0.7 : 0,
      maxBid: allowed ? estimatedFare * 1.3 : Infinity,
    };
  }, [estimatedFare]);

  return (
    <div className="d-flex flex-column justify-content-start align-items-start">
      <div className="ant-col ant-form-item-label">
        <label className="ant-form-item-required">{placeholder}</label>
      </div>

      <Radio.Group
        disabled={disabled}
        value={value?.value}
        onChange={(e) => {
          onChange({
            value: e.target.value,
            type: "fareType",
          });
        }}
      >
        {options.map((option) => (
          <Radio
            key={option.id}
            value={option.id}
            disabled={option.id === "bid" && !isBidAllowed || (option.id === "fixedEstimate" && (!estimatedFare || estimatedFare <= 0))}
          >
            {option.name}
          </Radio>
        ))}
      </Radio.Group>

      {value?.value === "fixed" && (
        <Row className="mt-3 w-100">
          <label className="ant-form-item-required">Fixed price</label>
          <Col span={24}>
            <NumberInput
              disabled={disabled}
              placeholder="Fixed price"
              value={value?.fare}
              onChange={(fare) => {
                onChange({
                  value: value?.value,
                  type: "fareType",
                  fare,
                });
              }}
            />
          </Col>
        </Row>
      )}

      {value?.value === "bid" && (
        <Row className="mt-3 w-100">
          <label className="ant-form-item-required">
            Bid price{" "}
            <span style={{ color: "#888" }}>
              (allowed: {minBid.toFixed(0)} - {maxBid.toFixed(0)})
            </span>
          </label>
          <Col span={24}>
            <NumberInput
              disabled={disabled}
              placeholder="Bid price"
              value={value?.fare}
              // min={minBid}
              // max={maxBid}
              onChange={(fare) => {
                // if (fare < minBid || fare > maxBid) return;
                onChange({
                  value: value?.value,
                  type: "fareType",
                  fare,
                  estimatedFare
                });
              }}
            />
          </Col>
        </Row>
      )}
    </div>
  );
};

export default FareTypeInput;
