import React, { FC, useMemo } from "react";
import { Badge, Collapse, Form } from "antd";

import { PaymentConfig } from "../types";
import { FormSectionKey, sectionOfError } from "../paymentConfig";
import BasicsSection from "./sections/Basics";
import CollectionSection from "./sections/Collection";
import PlanSection from "./sections/Plan";
import ScholarshipSection from "./sections/Scholarship";
import PricingWindowsSection from "./sections/PricingWindows";
import DiscountsSection from "./sections/Discounts";
import LateFeeSection from "./sections/LateFee";
import RemindersSection from "./sections/Reminders";

const { Panel } = Collapse;

interface Props {
  value: PaymentConfig;
  onChange: (next: PaymentConfig) => void;
  /** Validation messages; each is counted on the panel it belongs to. */
  errors?: string[];
  disabled?: boolean;
}

const SECTIONS: { key: FormSectionKey; title: string; Component: FC<any> }[] = [
  { key: "basics", title: "Basics", Component: BasicsSection },
  { key: "collection", title: "Collection method", Component: CollectionSection },
  { key: "plan", title: "Payment plan", Component: PlanSection },
  { key: "scholarship", title: "Scholarship / financial aid", Component: ScholarshipSection },
  { key: "windows", title: "Early bird & late registration", Component: PricingWindowsSection },
  { key: "discounts", title: "Discounts", Component: DiscountsSection },
  { key: "lateFee", title: "Late fee", Component: LateFeeSection },
  { key: "reminders", title: "Reminders & suspension", Component: RemindersSection },
];

/**
 * The complete payment configuration as an editable form, in the same
 * section order and wording as the admin portal's Payment Configuration
 * screen. Controlled: every change produces a new configuration object.
 */
const PaymentConfigForm: FC<Props> = ({ value, onChange, errors = [], disabled }) => {
  const patch = (changes: Partial<PaymentConfig>) => onChange({ ...value, ...changes });

  const errorCounts = useMemo(() => {
    const counts: Partial<Record<FormSectionKey, number>> = {};
    errors.forEach((message) => {
      const key = sectionOfError(message);
      counts[key] = (counts[key] || 0) + 1;
    });
    return counts;
  }, [errors]);

  return (
    <Form layout="vertical" className="cfo-config-form" onFinish={(e) => e && e.preventDefault && e.preventDefault()}>
      <Collapse
        ghost
        defaultActiveKey={SECTIONS.map((section) => section.key)}
        expandIconPosition="end"
      >
        {SECTIONS.map(({ key, title, Component }) => (
          <Panel
            key={key}
            header={
              <span className="cfo-config-form__panel-title">
                {title}
                {errorCounts[key] ? (
                  <Badge count={errorCounts[key]} style={{ backgroundColor: "#E5484D", marginLeft: 8 }} />
                ) : null}
              </span>
            }
          >
            <Component config={value} patch={patch} disabled={disabled} />
          </Panel>
        ))}
      </Collapse>
    </Form>
  );
};

export default PaymentConfigForm;
