import React, { FC, useState } from "react";
import { Alert, Checkbox, Radio, Tag } from "antd";

import ConfirmationModal from "../../../../../common/Confirmation";

import { PaymentConfig, PaymentRequestDraft } from "../types";
import PaymentConfigForm from "../PaymentConfigForm";
import AppliedStrip from "./AppliedStrip";
import { WizardMode } from "./draft";

interface Props {
  draft: PaymentRequestDraft;
  setDraft: (update: (current: PaymentRequestDraft) => PaymentRequestDraft) => void;
  errors: string[];
  wizardMode: WizardMode;
  /** The stored configuration the draft was cloned from. */
  source: PaymentConfig;
  subjectName: string;
}

/**
 * Step 1: the configuration this request is built on, editable in
 * full, and whether every recipient gets the same request.
 */
const StepConfiguration: FC<Props> = ({ draft, setDraft, errors, wizardMode, source, subjectName }) => {
  const [confirmSwitch, setConfirmSwitch] = useState(false);
  const overrideCount = Object.keys(draft.overrides).length;

  const switchMode = (mode: PaymentRequestDraft["mode"]) => {
    if (mode === "same" && overrideCount > 0) {
      setConfirmSwitch(true);
      return;
    }
    setDraft((current) => ({ ...current, mode }));
  };

  return (
    <div className="cfo-wizard-step">
      <div className="cfo-wizard-source">
        <div>
          <span className="cfo-wizard-source__label">
            {wizardMode === "payee" ? "Payout terms" : "Project configuration"}
          </span>
          <span className="cfo-wizard-source__name">
            {source.name}{" "}
            <Tag color={source.status === "active" ? "green" : "red"}>{source.status}</Tag>
          </span>
        </div>
        <span className="cfo-wizard-source__hint">
          Changes below apply to this request for {subjectName}. The stored configuration stays as the admin set it
          unless you tick "Also save" at the bottom.
        </span>
      </div>

      {wizardMode !== "payee" && (
        <div className="cfo-wizard-mode">
          <Radio.Group value={draft.mode} onChange={(e) => switchMode(e.target.value)}>
            <Radio value="same">
              <strong>Same request for everyone</strong>
              <span className="cfo-wizard-mode__hint">Every selected member receives this configuration unchanged.</span>
            </Radio>
            <Radio value="custom">
              <strong>Customise for specific members</strong>
              <span className="cfo-wizard-mode__hint">
                Pick members on the next step and give them their own copy; the rest get the group request.
              </span>
            </Radio>
          </Radio.Group>
        </div>
      )}

      {errors.length > 0 && (
        <Alert
          className="cfo-modal-alert cfo-modal-alert--top"
          type="error"
          showIcon
          message="Please fix the highlighted sections before continuing"
          description={
            <ul className="cfo-error-list">
              {errors.map((message) => (
                <li key={message}>{message}</li>
              ))}
            </ul>
          }
        />
      )}

      <AppliedStrip
        scope="group"
        config={draft.config}
        value={draft.applied}
        onChange={(applied) => setDraft((current) => ({ ...current, applied }))}
      />

      <PaymentConfigForm
        value={draft.config}
        errors={errors}
        onChange={(config) => setDraft((current) => ({ ...current, config }))}
      />

      {wizardMode !== "payee" && (
        <div className="cfo-wizard-save">
          <Checkbox
            checked={draft.saveToProject}
            onChange={(e) => setDraft((current) => ({ ...current, saveToProject: e.target.checked }))}
          >
            Also save as the project's configuration
          </Checkbox>
          <span className="cfo-wizard-save__hint">
            Off by default: the request carries its own snapshot and the project keeps "{source.name}".
          </span>
        </div>
      )}

      {confirmSwitch && (
        <ConfirmationModal
          message={`Send the same request to everyone? The ${overrideCount} customised member${
            overrideCount === 1 ? "" : "s"
          } will lose their changes.`}
          onClose={() => setConfirmSwitch(false)}
          handleConfirm={() => {
            setConfirmSwitch(false);
            setDraft((current) => ({ ...current, mode: "same", overrides: {} }));
          }}
        />
      )}
    </div>
  );
};

export default StepConfiguration;
