import React, { FC } from "react";
import { Tooltip } from "antd";
import { ReactSVG } from "react-svg";

import { Domain } from "./types";
import { CFO_MENU_GROUPS, CFO_MENU_ITEMS } from "./menu";

interface Props {
  screen: CFO_MENU_ITEMS;
  setScreen: (screen: CFO_MENU_ITEMS) => void;
  domain: Domain;
}

/**
 * The icon rail. Same markup as School3's sidebar so the global
 * `.main-column.search-panel .sidebar` rules style it; only the fixed
 * positioning is left to the shell.
 *
 * Entries are grouped: the finance screens first, then the directory.
 * A caption separates the groups so the rail reads as two sections
 * rather than one long list.
 */
const SideBar: FC<Props> = ({ screen, setScreen, domain }) => (
  <div className="main-column search-panel cfo-rail">
    <div className="sidebar" style={{ borderRadius: 0 }}>
      {CFO_MENU_GROUPS.map((group) => (
        <div key={group.id} className="cfo-rail__group">
          {group.caption && <span className="cfo-rail__caption">{group.caption}</span>}
          <ul>
            {group.items.map((item) => (
              <Tooltip key={item.id} title={item.hint} placement="right" mouseEnterDelay={0.4}>
                <li
                  className={screen === item.id ? "selected" : ""}
                  onClick={() => setScreen(item.id)}
                >
                  <div>
                    <div>
                      <ReactSVG src={item.src} />
                      <p>{item.label(domain)}</p>
                    </div>
                  </div>
                </li>
              </Tooltip>
            ))}
          </ul>
        </div>
      ))}
    </div>
  </div>
);

export default SideBar;
