import React from "react";
import type { ColumnsType } from "antd/es/table";
import moment from "moment";
import { Pill, PillTone } from "../../Medical/common/ui";
import { CouponLifecycle, formatMoney } from "../couponRules";
import { RedemptionRecord } from "../types";

export const LIFECYCLE_PILL: Record<CouponLifecycle, { label: string; tone: PillTone }> = {
  active: { label: "Active", tone: "green" },
  scheduled: { label: "Scheduled", tone: "blue" },
  paused: { label: "Paused", tone: "amber" },
  expired: { label: "Expired", tone: "gray" },
  exhausted: { label: "Limit reached", tone: "purple" },
  archived: { label: "Archived", tone: "gray" },
};

export const REDEMPTION_COLUMNS: ColumnsType<RedemptionRecord> = [
  {
    title: "When",
    key: "when",
    render: (_, r) => moment(r.info.redeemedAt).format("MMM D, h:mm A"),
  },
  {
    title: "Coupon",
    key: "coupon",
    render: (_, r) => (
      <div>
        <strong>{r.info.couponTitle || "Coupon"}</strong>
        {r.info.recipientName && <div className="cpn-muted">{r.info.recipientName}</div>}
      </div>
    ),
  },
  { title: "Store", key: "vendor", render: (_, r) => r.info.vendorName },
  {
    title: "Bill",
    key: "bill",
    align: "right",
    render: (_, r) => formatMoney(r.info.billAmount ?? null, r.info.currency),
  },
  {
    title: "Discount",
    key: "discount",
    align: "right",
    render: (_, r) => formatMoney(r.info.discountApplied ?? null, r.info.currency),
  },
  {
    title: "Result",
    key: "status",
    render: (_, r) =>
      r.info.status === "accepted" ? (
        <Pill tone="green">Accepted</Pill>
      ) : (
        <Pill tone="red" title={r.info.rejectReason}>
          Declined
        </Pill>
      ),
  },
  { title: "Reference", key: "ref", render: (_, r) => <span className="cpn-mono">{r.info.reference}</span> },
];

