import { useEffect, useRef } from "react";

/** Mirrors horizontal scroll between a top scrollbar and the antd table body. */
export const useSyncedScroll = (deps: any[]) => {
  const topRef = useRef<HTMLDivElement>(null);
  const tableRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const top = topRef.current;
    const body = tableRef.current?.querySelector(".ant-table-body") as HTMLElement;
    if (!top || !body) return;

    const onTop = () => {
      if (body.scrollLeft !== top.scrollLeft) body.scrollLeft = top.scrollLeft;
    };
    const onBody = () => {
      if (top.scrollLeft !== body.scrollLeft) top.scrollLeft = body.scrollLeft;
    };
    top.addEventListener("scroll", onTop);
    body.addEventListener("scroll", onBody);
    return () => {
      top.removeEventListener("scroll", onTop);
      body.removeEventListener("scroll", onBody);
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, deps);

  return { topRef, tableRef };
};
