export const REQUEST_TIMEOUT_MS = 20000;

export const BrandCouponTopic = {
  SetPin: "brandCouponSetPin",
  Issue: "brandCouponIssue",
  Send: "brandCouponSend",
  Get: "brandCouponGet",
  Redeem: "brandCouponRedeem",
} as const;

export interface SocketReply<T = any> {
  status: boolean;
  message?: string;
  /** On failure first-dps puts the reason in `data.details`. */
  data: T & { details?: string };
}

const asObject = (value: any) => {
  if (typeof value !== "string") return value;
  try {
    return JSON.parse(value);
  } catch {
    return value;
  }
};

/* ------------------------------------------------------------- requests */

/**
 * Publish + await the reply on `<topic>/reply`. Replies carry the request id,
 * so concurrent requests on one topic resolve the right promise. Resolves null
 * on timeout.
 */
export const useSocketRequest = (socket: ISocket | undefined) => {
  const pending = useRef(new Map<string, { replyTopic: string; resolve: (r: any) => void; timer: any }>());
  const subscribed = useRef(new Set<string>());
  const uuid = useRef(generateUUID()).current;

  useEffect(
    () => () => {
      pending.current.forEach((p) => clearTimeout(p.timer));
      pending.current.clear();
    },
    []
  );

  return useCallback(
    <T = any>(publishTopic: string, replyTopic: string, payload: any, timeoutMs = REQUEST_TIMEOUT_MS) =>
      new Promise<SocketReply<T> | null>((resolve) => {
        if (!socket) return resolve(null);
        if (!subscribed.current.has(replyTopic)) {
          subscribed.current.add(replyTopic);
          socket.subscribeToEvent(
            SocketTopics.SubscribePageTopics,
            replyTopic,
            (message: any) => {
              let id: string | undefined = message?.id;
              if (!id || !pending.current.has(id)) {
                // No id echoed: oldest request on this topic.
                id = Array.from(pending.current.entries()).find(([, p]) => p.replyTopic === replyTopic)?.[0];
              }
              const entry = id ? pending.current.get(id) : undefined;
              if (!id || !entry) return;
              pending.current.delete(id);
              clearTimeout(entry.timer);
              const response = message?.response ?? message;
              entry.resolve({
                status: response?.status !== false,
                message: response?.message,
                data: response?.data,
              });
            },
            `${uuid}:${replyTopic}`
          );
        }
        const id = generateUUID();
        const timer = setTimeout(() => {
          pending.current.delete(id);
          resolve(null);
        }, timeoutMs);
        pending.current.set(id, { replyTopic, resolve, timer });
        socket.publishToEvent(SocketTopics.PublishPageTopics, publishTopic, wrapRequestPayload(payload, id));
      }),
    [socket, uuid]
  );
};

/** first-dps brand coupon topics. Resolves null on timeout. */
export const useBrandCouponApi = (socket: ISocket | undefined) => {
  const request = useSocketRequest(socket);
  const { encrypted_token } = useSelector((state: RootState) => state.auth);
  const connectionId = encrypted_token?.connectionId;

  return useCallback(
    <T = any>(body: typeof BrandCouponTopic[keyof typeof BrandCouponTopic], payload: any, timeoutMs?: number) =>
      request<T>(
        getBrandCouponPublishTopic(connectionId, body),
        getBrandCouponSubscriptionTopic(connectionId, body),
        payload,
        timeoutMs
      ),
    [request, connectionId]
  );
};

/** Admin-side coupon writes through custom-bds. */
export const useCouponWrites = (socket: ISocket | undefined) => {
  const request = useSocketRequest(socket);
  const { encrypted_token, projects } = useSelector((state: RootState) => state.auth);
  const connectionId = encrypted_token?.connectionId;
  const orgId = projects?.userServiceId;

  const createCoupon = useCallback(
    (info: CouponInfo) =>
      request(getCustomCreateRequestPublishTopic(connectionId), getCustomCreateSubscriptionTopic(connectionId), {
        changes: [
          { op: "add", path: "/partitions", value: [`org:${orgId}`, "type:brandCoupon"] },
          { op: "add", path: "/createdAt", value: Date.now() },
          { op: "add", path: "/info", value: { ...info, createdBy: encrypted_token?.userId, updatedAt: Date.now() } },
          { op: "add", path: "/stats", value: EMPTY_STATS },
        ],
      }),
    [request, connectionId, orgId, encrypted_token?.userId]
  );

  /** Replaces /info only; /stats belongs to first-dps. */
  const updateCoupon = useCallback(
    (objectId: string, info: CouponInfo) =>
      request(getCustomUpdateRequestPublishTopic(connectionId), getCustomUpdateSubscriptionTopic(connectionId), {
        objectId,
        changes: [{ op: "replace", path: "/info", value: { ...info, updatedAt: Date.now() } }],
      }),
    [request, connectionId]
  );

  const setCouponStatus = useCallback(
    (objectId: string, status: CouponInfo["status"]) =>
      request(getCustomUpdateRequestPublishTopic(connectionId), getCustomUpdateSubscriptionTopic(connectionId), {
        objectId,
        changes: [
          { op: "replace", path: "/info/status", value: status },
          { op: "add", path: "/info/updatedAt", value: Date.now() },
        ],
      }),
    [request, connectionId]
  );

  return { createCoupon, updateCoupon, setCouponStatus };
};

/* ---------------------------------------------------------------- reads */

/** GET_AGGREGATE as a promise; null on failure/timeout (the saga never calls back on errors). */
const useAggregate = () => {
  const dispatch = useDispatch();
  return useCallback(
    (requestData: any) =>
      new Promise<any[] | null>((resolve) => {
        const timer = setTimeout(() => resolve(null), REQUEST_TIMEOUT_MS);
        dispatch(
          GET_AGGREGATE({
            requestData,
            callback: (response: any[]) => {
              clearTimeout(timer);
              resolve(response || []);
            },
          })
        );
      }),
    [dispatch]
  );
};

export const useCouponQueries = () => {
  const aggregate = useAggregate();
  const { projects } = useSelector((state: RootState) => state.auth);
  const orgId = projects?.userServiceId;

  const query = useCallback(
    (type: string, extra = "", filter = "") =>
      aggregate({
        select: {
          index: {
            searchIndex: `${process.env.REACT_APP_ECO_SYSTEM}:custom:createdAt`,
            searchQuery: `@partitions:{'org\\:${formatForRedis(orgId)}'}@partitions:{type\\:${type}}${extra}`,
            searchOptions: "VERBATIM TIMEOUT 10000",
          },
          load: {
            info: "$.info",
            objectId: "$.objectId",
            createdAt: "$.createdAt",
            stats: "$.stats",
            redeemedAt: "$.info.redeemedAt",
          },
        },
        filter: { expression: filter },
      }),
    [aggregate, orgId]
  );

  const loadCoupons = useCallback(async (): Promise<CouponRecord[] | null> => {
    const rows = await query("brandCoupon");
    if (!rows) return null;
    return rows
      .map((x) => ({
        objectId: `${x?.objectId}`,
        createdAt: Number(x?.createdAt) || undefined,
        info: asObject(x?.info) || {},
        stats: { ...EMPTY_STATS, ...(asObject(x?.stats) || {}) },
      }))
      .sort((a, b) => (b.createdAt || 0) - (a.createdAt || 0));
  }, [query]);

  const loadRecipients = useCallback(
    async (couponId?: string): Promise<RecipientRecord[] | null> => {
      const rows = await query(
        "brandCouponRecipient",
        couponId ? `@partitions:{coupon\\:${formatForRedis(couponId)}}` : ""
      );
      if (!rows) return null;
      return rows
        .map((x) => ({ objectId: `${x?.objectId}`, info: asObject(x?.info) || {} }))
        .sort((a, b) => (b.info.issuedAt || 0) - (a.info.issuedAt || 0));
    },
    [query]
  );

  const loadRedemptions = useCallback(
    async ({ couponId, from }: { couponId?: string; from?: number } = {}): Promise<RedemptionRecord[] | null> => {
      const rows = await query(
        "brandCouponRedemption",
        couponId ? `@partitions:{coupon\\:${formatForRedis(couponId)}}` : "",
        from ? `exists(@redeemedAt) && @redeemedAt >= ${from}` : ""
      );
      if (!rows) return null;
      return rows
        .map((x) => ({ objectId: `${x?.objectId}`, info: asObject(x?.info) || {} }))
        .sort((a, b) => (b.info.redeemedAt || 0) - (a.info.redeemedAt || 0));
    },
    [query]
  );

  /** Never exposes the hash; only the hint and timestamps. */
  const loadSettings = useCallback(async (): Promise<CouponSettings | null | undefined> => {
    const rows = await query("brandCouponSettings");
    if (!rows) return null;
    const row = rows[0];
    if (!row) return undefined;
    const info = asObject(row.info) || {};
    return {
      objectId: `${row.objectId}`,
      pinHint: info.pinHint,
      pinLength: info.pinLength,
      pinUpdatedAt: info.pinUpdatedAt,
    };
  }, [query]);

  return useMemo(
    () => ({ orgId, loadCoupons, loadRecipients, loadRedemptions, loadSettings }),
    [orgId, loadCoupons, loadRecipients, loadRedemptions, loadSettings]
  );
};
