import React, { FC, useEffect, useMemo, useState } from "react";
import { Button, Progress, Select } from "antd";
import type { ColumnsType } from "antd/es/table";
import { ReloadOutlined } from "@ant-design/icons";
import moment from "moment";
import { DataTableCard, EmptyState, PageHeader, Pill } from "../../Medical/common/ui";
import { useCouponQueries } from "../couponApi";
import { discountHeadline, formatMoney, lifecycle } from "../couponRules";
import { CouponRecord, RedemptionRecord } from "../types";
import DailyBars from "./DailyBars";
import { LIFECYCLE_PILL, REDEMPTION_COLUMNS } from "./shared";

const RANGES: Record<string, number> = { "Last 7 days": 7, "Last 30 days": 30, "Last 90 days": 90 };

interface Props {
  coupons: CouponRecord[];
  loading: boolean;
  refreshKey: number;
  onReload: () => void;
  onOpenCoupon: (coupon: CouponRecord) => void;
  onCreate: () => void;
}

const pct = (part: number, whole: number) => (whole > 0 ? Math.round((part / whole) * 100) : 0);

const DashboardScreen: FC<Props> = ({ coupons, loading, refreshKey, onReload, onOpenCoupon, onCreate }) => {
  const { loadRedemptions } = useCouponQueries();
  const [range, setRange] = useState("Last 30 days");
  const [redemptions, setRedemptions] = useState<RedemptionRecord[]>([]);
  const [loadingRedemptions, setLoadingRedemptions] = useState(false);

  const days = RANGES[range];
  useEffect(() => {
    let live = true;
    setLoadingRedemptions(true);
    loadRedemptions({ from: moment().subtract(days - 1, "days").startOf("day").valueOf() }).then((rows) => {
      if (!live) return;
      setLoadingRedemptions(false);
      if (rows) setRedemptions(rows);
    });
    return () => {
      live = false;
    };
  }, [loadRedemptions, days, refreshKey]);

  const totals = useMemo(() => {
    const t = { active: 0, issued: 0, sent: 0, redeemed: 0, discount: 0 };
    for (const c of coupons) {
      if (c.info.status === "archived") continue;
      if (lifecycle(c.info, c.stats) === "active") t.active += 1;
      t.issued += c.stats.issued;
      t.sent += c.stats.sent;
      t.redeemed += c.stats.redeemed;
      t.discount += c.stats.discountTotal;
    }
    return t;
  }, [coupons]);

  const currencies = Array.from(new Set(coupons.map((c) => c.info.currency || "USD")));
  const mainCurrency = currencies.length === 1 ? currencies[0] : undefined;

  const accepted = redemptions.filter((r) => r.info.status === "accepted");
  const rejected = redemptions.length - accepted.length;
  const daily = useMemo(() => {
    const counts: Record<string, number> = {};
    for (const r of accepted) {
      const day = moment(r.info.redeemedAt).format("YYYY-MM-DD");
      counts[day] = (counts[day] || 0) + 1;
    }
    return Array.from({ length: days }, (_, i) => {
      const day = moment().subtract(days - 1 - i, "days").format("YYYY-MM-DD");
      return { day, value: counts[day] || 0 };
    });
  }, [accepted, days]);

  const live = coupons.filter((c) => c.info.status !== "archived");

  const columns: ColumnsType<CouponRecord> = [
    {
      title: "Coupon",
      key: "title",
      render: (_, c) => (
        <div>
          <strong>{c.info.title}</strong>
          <div className="cpn-muted">
            {discountHeadline(c.info)}
            {c.info.brandName ? ` · ${c.info.brandName}` : ""}
          </div>
        </div>
      ),
    },
    {
      title: "Status",
      key: "status",
      render: (_, c) => {
        const state = lifecycle(c.info, c.stats);
        return <Pill tone={LIFECYCLE_PILL[state].tone}>{LIFECYCLE_PILL[state].label}</Pill>;
      },
    },
    { title: "Generated", key: "issued", align: "right", render: (_, c) => c.stats.issued },
    { title: "Sent", key: "sent", align: "right", render: (_, c) => c.stats.sent },
    { title: "Used", key: "redeemed", align: "right", render: (_, c) => <strong>{c.stats.redeemed}</strong> },
    {
      title: "Usage rate",
      key: "rate",
      width: 180,
      render: (_, c) => (
        <Progress
          percent={pct(c.stats.redeemed, c.stats.issued)}
          size="small"
          strokeColor="#463bbd"
          format={(p) => `${p}%`}
        />
      ),
    },
    {
      title: "Discount given",
      key: "discount",
      align: "right",
      render: (_, c) => formatMoney(c.stats.discountTotal, c.info.currency),
    },
  ];

  return (
    <div className="cpn-screen">
      <PageHeader
        title="Dashboard"
        subtitle="Coupons generated, sent and used across your campaigns"
        primaryAction={{ label: "Create coupon", onClick: onCreate }}
        extra={
          <Button icon={<ReloadOutlined />} onClick={onReload} loading={loading || loadingRedemptions}>
            Refresh
          </Button>
        }
      />

      <div className="cpn-kpis">
        <Kpi label="Active coupons" value={totals.active} tone="purple" />
        <Kpi label="Generated" value={totals.issued} hint="Unique QR codes created" tone="blue" />
        <Kpi label="Sent" value={totals.sent} hint={`${pct(totals.sent, totals.issued)}% of generated`} tone="blue" />
        <Kpi
          label="Used"
          value={totals.redeemed}
          hint={`${pct(totals.redeemed, totals.issued)}% of generated`}
          tone="green"
        />
        <Kpi
          label="Discount given"
          value={mainCurrency ? formatMoney(totals.discount, mainCurrency) : totals.discount.toFixed(2)}
          hint={mainCurrency ? undefined : "Mixed currencies"}
          tone="amber"
        />
      </div>

      <div className="mx-card cpn-panel">
        <div className="cpn-panel__head">
          <div>
            <h4>Redemptions per day</h4>
            <span className="cpn-muted">
              {accepted.length} accepted{rejected ? ` · ${rejected} declined` : ""}
            </span>
          </div>
          <Select
            value={range}
            onChange={setRange}
            options={Object.keys(RANGES).map((r) => ({ label: r, value: r }))}
            style={{ width: 150 }}
          />
        </div>
        <DailyBars data={daily} label={`Accepted redemptions per day, ${range.toLowerCase()}`} />
      </div>

      <DataTableCard<CouponRecord>
        rowKey="objectId"
        loading={loading}
        caption="Generated vs used, by coupon"
        columns={columns}
        dataSource={live}
        clickable
        onRow={(c) => ({ onClick: () => onOpenCoupon(c) })}
        scroll={{ x: true }}
        empty={
          <EmptyState
            title="No coupons yet"
            description="Create a coupon, then share it by email or SMS."
            action={{ label: "Create coupon", onClick: onCreate }}
          />
        }
      />

      <DataTableCard<RedemptionRecord>
        rowKey="objectId"
        loading={loadingRedemptions}
        caption="Latest redemptions"
        dataSource={redemptions.slice(0, 8)}
        columns={REDEMPTION_COLUMNS}
        scroll={{ x: true }}
        empty={<EmptyState title="No redemptions in this period" />}
      />
    </div>
  );
};

const Kpi: FC<{ label: string; value: React.ReactNode; hint?: string; tone: string }> = ({ label, value, hint, tone }) => (
  <div className={`cpn-kpi cpn-kpi--${tone}`}>
    <span className="cpn-kpi__label">{label}</span>
    <span className="cpn-kpi__value">{value}</span>
    {hint && <span className="cpn-kpi__hint">{hint}</span>}
  </div>
);

export default DashboardScreen;
