import React, { useCallback, useEffect, useMemo, useRef, useState } from "react";
import { Button, DatePicker, Form, Input } from "antd";
import type { ColumnsType } from "antd/es/table";
import { PlusOutlined } from "@ant-design/icons";
import moment, { Moment } from "moment";
import { useDispatch, useSelector } from "react-redux";
import { RootState } from "reducers/rootReducer";
import { SocketTopics } from "constants/enums";
import {
  getCustomCreateRequestPublishTopic,
  getCustomCreateSubscriptionTopic,
} from "hooks/MQTTConstants";
import { wrapRequestPayload } from "../../../../../helpers/request/RequestPayload";
import { formatForRedis, generateUUID } from "utils/appUtil";
import { pushNotification } from "utils/notifications";
import { GET_AGGREGATE } from "../../../../../reducers/reducer";
import { DataTableCard, EmptyState, FormModal, Pill, PillTone } from "../../common/ui";
import { REQUEST_TIMEOUT_MS } from "./staffApi";
import "./Driver.scss";

// Time-off requests are custom objects partitioned
// [`org:<id>`, `user:<driverId>`, `type:timeoff`, `date:<YYYYMMDD created>`] with
// `/info = { timestamp, startDate, startDateTimestamp, endDate, endDateTimestamp,
// reason, status }`. The Time off admin screen, the shift editor and driver
// availability read this shape; admins set `status` to Accepted/Rejected.

const DATE_FORMAT = "YYYY-MM-DD hh:mm A";
const REASON_MAX = 500;

const STATUS_TONES: { [status: string]: PillTone } = {
  Accepted: "green",
  Rejected: "red",
  Pending: "amber",
};

interface LeaveRow {
  key: string;
  startDate?: string;
  endDate?: string;
  startDateTimestamp?: number;
  endDateTimestamp?: number;
  reason?: string;
  status?: string;
  timestamp?: number;
}

/**
 * Requests need notice: before Wednesday the rest of this week is blocked;
 * from Wednesday on, next week is blocked too.
 */
const firstAllowedDay = (today = moment()) => {
  const thisSunday = today.clone().endOf("isoWeek");
  const lastBlocked = today.isoWeekday() < 3 ? thisSunday : thisSunday.clone().add(1, "week");
  return lastBlocked.clone().add(1, "day").startOf("day");
};

const isBlockedDay = (current: Moment) =>
  !!current && current.isBefore(firstAllowedDay(), "day");

const parseLeaveDate = (row: LeaveRow, which: "start" | "end") => {
  const ts = which === "start" ? row.startDateTimestamp : row.endDateTimestamp;
  if (ts) return moment(ts);
  const raw = which === "start" ? row.startDate : row.endDate;
  const m = raw ? moment(raw, DATE_FORMAT) : undefined;
  return m?.isValid() ? m : undefined;
};

const formatRange = (row: LeaveRow) => {
  const start = parseLeaveDate(row, "start");
  const end = parseLeaveDate(row, "end");
  if (!start) return row.startDate || "—";
  if (!end || start.isSame(end, "day")) return start.format("ddd, MMM D, YYYY");
  const sameYear = start.isSame(end, "year");
  return `${start.format(sameYear ? "MMM D" : "MMM D, YYYY")} – ${end.format("MMM D, YYYY")}`;
};

const countDays = (row: LeaveRow) => {
  const start = parseLeaveDate(row, "start");
  const end = parseLeaveDate(row, "end");
  if (!start || !end) return undefined;
  return end.clone().startOf("day").diff(start.clone().startOf("day"), "days") + 1;
};

const COLUMNS: ColumnsType<LeaveRow> = [
  {
    title: "Dates",
    key: "dates",
    sorter: (a, b) => (a.startDateTimestamp || 0) - (b.startDateTimestamp || 0),
    render: (_, row) => {
      const days = countDays(row);
      return (
        <div>
          <div className="mx-timeoff__dates">{formatRange(row)}</div>
          {days !== undefined && (
            <div className="mx-timeoff__sub">
              {days} {days === 1 ? "day" : "days"}
            </div>
          )}
        </div>
      );
    },
  },
  {
    title: "Reason",
    dataIndex: "reason",
    key: "reason",
    render: (reason) => reason || <span className="mx-timeoff__sub">No reason given</span>,
  },
  {
    title: "Status",
    dataIndex: "status",
    key: "status",
    render: (status) => <Pill tone={STATUS_TONES[status] || "gray"}>{status || "Unknown"}</Pill>,
  },
  {
    title: "Requested",
    dataIndex: "timestamp",
    key: "timestamp",
    render: (ts) => (ts ? moment(ts).format("MMM D, YYYY") : "—"),
  },
];

/** The driver's time-off requests and the form to request more. */
const LeaveRequest = ({ socket, userId }: { socket: ISocket; userId?: string }) => {
  const { encrypted_token } = useSelector((state: RootState) => state.auth);
  const dispatch = useDispatch();
  const [form] = Form.useForm();
  const [rows, setRows] = useState<LeaveRow[]>([]);
  const [loading, setLoading] = useState(false);
  const [loadFailed, setLoadFailed] = useState(false);
  const [modalOpen, setModalOpen] = useState(false);
  const [saving, setSaving] = useState(false);
  const uuid = useRef(generateUUID()).current;
  const pending = useRef(false);
  const saveTimer = useRef<any>();
  const mounted = useRef(true);
  const requestSeq = useRef(0);
  const orgId = encrypted_token?.cudbServiceId || encrypted_token?.serviceId;
  const startDate: Moment | undefined = Form.useWatch("startDate", form);

  const load = useCallback(() => {
    if (!userId) return;
    const seq = ++requestSeq.current;
    setLoading(true);
    const timer = setTimeout(() => {
      if (!mounted.current || seq !== requestSeq.current) return;
      setLoading(false);
      setLoadFailed(true);
    }, REQUEST_TIMEOUT_MS);
    dispatch(
      GET_AGGREGATE({
        requestData: {
          select: {
            index: {
              searchIndex: `${process.env.REACT_APP_ECO_SYSTEM}:custom:createdAt`,
              searchQuery: `@partitions:{'org\\:${formatForRedis(
                orgId
              )}'}@partitions:{user\\:${userId}}@partitions:{type\\:timeoff}`,
              searchOptions: "VERBATIM TIMEOUT 10000",
            },
            load: { info: "$.info", objectId: "$.objectId" },
          },
          filter: { expression: "" },
        },
        callback: (response: any[]) => {
          clearTimeout(timer);
          if (!mounted.current || seq !== requestSeq.current) return;
          setLoading(false);
          setLoadFailed(false);
          setRows(
            (response || [])
              .map((x) => ({ key: x?.objectId, ...x?.info }))
              .sort((a, b) => (b.startDateTimestamp || 0) - (a.startDateTimestamp || 0))
          );
        },
      })
    );
  }, [dispatch, orgId, userId]);

  useEffect(() => {
    mounted.current = true;
    return () => {
      mounted.current = false;
      clearTimeout(saveTimer.current);
    };
  }, []);

  useEffect(() => {
    if (!userId) return;
    load();
    socket.subscribeToEvent(
      SocketTopics.SubscribePageTopics,
      getCustomCreateSubscriptionTopic(encrypted_token?.connectionId),
      () => {
        // Shared reply topic: only react to our own request.
        if (!pending.current || !mounted.current) return;
        pending.current = false;
        clearTimeout(saveTimer.current);
        setSaving(false);
        setModalOpen(false);
        pushNotification("Time off requested", "success", "TOP_CENTER", 2000);
        load();
      },
      uuid
    );
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [userId]);

  const openForm = () => setModalOpen(true);

  const submit = (values: { startDate: Moment; endDate: Moment; reason: string }) => {
    const start = values.startDate.clone();
    const end = values.endDate.clone();
    const requestData = {
      timestamp: new Date().getTime(),
      startDate: start.format(DATE_FORMAT),
      startDateTimestamp: start.clone().startOf("day").valueOf(),
      endDate: end.format(DATE_FORMAT),
      endDateTimestamp: end.clone().endOf("day").valueOf(),
      reason: values.reason.trim(),
      status: "Pending",
    };

    setSaving(true);
    pending.current = true;
    clearTimeout(saveTimer.current);
    saveTimer.current = setTimeout(() => {
      if (!pending.current || !mounted.current) return;
      pending.current = false;
      setSaving(false);
      pushNotification(
        "No response from the server. Check the list before requesting again.",
        "error",
        "TOP_CENTER",
        4000
      );
      load();
    }, REQUEST_TIMEOUT_MS);

    socket.publishToEvent(
      SocketTopics.PublishPageTopics,
      getCustomCreateRequestPublishTopic(encrypted_token?.connectionId),
      wrapRequestPayload({
        changes: [
          {
            op: "add",
            path: "/partitions",
            value: [
              `org:${orgId}`,
              `user:${userId}`,
              `type:timeoff`,
              `date:${moment().format("YYYYMMDD")}`,
            ],
          },
          { op: "add", path: "/createdAt", value: new Date().getTime() },
          { op: "add", path: "/info", value: requestData },
        ],
      })
    );
  };

  const earliest = useMemo(() => firstAllowedDay(), [modalOpen]);
  const pendingCount = rows.filter((r) => r.status === "Pending").length;

  const emptyState = loadFailed ? (
    <EmptyState
      title="Couldn't load time off"
      description={
        <Button className="mx-btn-secondary mt-2" onClick={load}>
          Try again
        </Button>
      }
    />
  ) : (
    <EmptyState
      title="No time off requested"
      description="Requests appear here with their approval status."
      action={{ label: "Request time off", onClick: openForm }}
    />
  );

  const pickerProps = {
    className: "w-full mobile-datepicker-modal",
    inputReadOnly: true,
    getPopupContainer: () => document.body,
    showTime: { use12Hours: true, format: "hh:mm A" },
    format: DATE_FORMAT,
  };

  return (
    <div className="mx-timeoff">
      <div className="mx-timeoff__toolbar">
        <span className="mx-timeoff__hint">
          {pendingCount > 0
            ? `${pendingCount} ${pendingCount === 1 ? "request" : "requests"} awaiting approval`
            : `The earliest day you can request is ${earliest.format("ddd, MMM D")}.`}
        </span>
        <Button className="mx-btn-primary" icon={<PlusOutlined />} onClick={openForm} disabled={!userId}>
          Request time off
        </Button>
      </div>

      <DataTableCard<LeaveRow>
        rowKey="key"
        loading={loading}
        caption={`${rows.length} ${rows.length === 1 ? "request" : "requests"}`}
        columns={COLUMNS}
        dataSource={rows}
        empty={emptyState}
        scroll={{ x: true }}
      />

      <FormModal
        open={modalOpen}
        title="Request time off"
        subtitle={`Requests need notice: the earliest start is ${earliest.format(
          "dddd, MMM D"
        )}. An admin approves or rejects each request.`}
        onCancel={() => !saving && setModalOpen(false)}
        onSubmit={form.submit}
        saving={saving}
        okText="Submit request"
      >
        {/* preserve={false}: every opening starts with an empty form. */}
        <Form form={form} layout="vertical" requiredMark={false} preserve={false} onFinish={submit}>
          <Form.Item
            label="Starts"
            name="startDate"
            rules={[
              { required: true, message: "Pick when your time off starts" },
              {
                validator: (_, value) =>
                  value && isBlockedDay(value)
                    ? Promise.reject(
                        new Error(`Pick ${earliest.format("MMM D")} or later`)
                      )
                    : Promise.resolve(),
              },
            ]}
          >
            <DatePicker {...pickerProps} disabledDate={isBlockedDay} />
          </Form.Item>
          <Form.Item
            label="Ends"
            name="endDate"
            dependencies={["startDate"]}
            rules={[
              { required: true, message: "Pick when your time off ends" },
              ({ getFieldValue }) => ({
                validator: (_, value) => {
                  const from: Moment | undefined = getFieldValue("startDate");
                  if (!value || !from || !value.isBefore(from)) return Promise.resolve();
                  return Promise.reject(new Error("End must be on or after the start"));
                },
              }),
            ]}
          >
            <DatePicker
              {...pickerProps}
              disabledDate={(current: Moment) =>
                isBlockedDay(current) || (!!startDate && current.isBefore(startDate, "day"))
              }
            />
          </Form.Item>
          <Form.Item
            label="Reason"
            name="reason"
            rules={[
              { required: true, whitespace: true, message: "Tell your admin why you need the time off" },
              { max: REASON_MAX, message: `Keep it under ${REASON_MAX} characters` },
            ]}
          >
            <Input.TextArea
              autoSize={{ minRows: 3, maxRows: 6 }}
              placeholder="e.g. Medical appointment"
              showCount
              maxLength={REASON_MAX}
            />
          </Form.Item>
        </Form>
      </FormModal>
    </div>
  );
};

export default LeaveRequest;
