// Filter.js
import React, { useState } from 'react';
import { Input, Button } from 'antd';
import Loader from "react-loader-spinner";
import { FilterOutlined, SearchOutlined } from '@ant-design/icons';
import "./index.scss";
import FilterIcon from "assets/SVGs/FilterIcon";
import FilterByModal from './FilterByModal';

const Filter: React.FC<{ onChange: (filters: any) => void, filterOptions: any }> = ({ onChange, filterOptions }) => {
  const [isFilterByModalVisible, setIsFilterByModalVisible] = useState<boolean>(false);
  const [filters, setFilters] = useState<any>({});
  const [input, setInput] = useState<string>("");

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement>) => {
      const newInput = e.target.value;
      setInput(newInput);
      const updatedFilters = { ...filters, name: newInput };
      setFilters(updatedFilters);
      onChange(updatedFilters);
  };

  const handleModalChange = (values: any) => {
      const updatedFilters = { ...filters, ...values };
      setFilters(updatedFilters);
      onChange(updatedFilters);
  };

  return (
      <div className="filter-container">
          <Input
              className="beam-input"
              value={input}
              onChange={handleInputChange}
              placeholder="Search Coaches"
              suffix={<SearchOutlined style={{ fontSize: 23 }} />}
          />
          <Button
              className="beam-btn ml-2"
              onClick={() => setIsFilterByModalVisible(!isFilterByModalVisible)}
          >
              <FilterIcon />
          </Button>

          {isFilterByModalVisible && (
              <FilterByModal
                  isModalVisible={isFilterByModalVisible}
                  setIsModalVisible={setIsFilterByModalVisible}
                  onChange={handleModalChange}
                  filterOptions={filterOptions}
              />
          )}
      </div>
  );
};

export default Filter;
