import React, { useState, useEffect } from "react";
import { useDispatch, useSelector } from "react-redux";
import { useLocation } from "react-router-dom";
import { RootState } from "reducers/rootReducer";
import { GET_AGGREGATE } from "reducers/reducer";

import { formatForRedis } from "utils/appUtil";
import { Select, Input } from "antd";
import { CheckCircleTwoTone } from '@ant-design/icons';

const { Option } = Select;

const CustomerInput = (props: any) => {
  const { value, placeholder, onChange, multiple, required } = props;
  const { projects, encrypted_token } = useSelector((state: RootState) => state.auth);

  const [searching, setSearching] = useState(false);
  const [showTanF, setShowTanF] = useState(false);

  const [options, setOptions] = useState([]);
  const dispatch = useDispatch();
  const [timeoutId, setTimeoutId] = useState<any>(null);
  const [inputValue, setInputValue] = useState(value || "");

  const location = useLocation();
  const queryParams = new URLSearchParams(location.search);
  const customerId = queryParams.get("customerId");
  const userId = queryParams.get("userId");

  useEffect(() => {
    if (customerId) {
      getCustomer(customerId);
    }

  }, [customerId]);

  const getCustomer = (search: string) => {
    let expression = "";

    if (search) {
      const formatted = formatForRedis(search);
      expression = `(exists(@name) && contains(lower(@name),lower('${formatted}'))) || (exists(@email) && contains(lower(@email),lower('${formatted}'))) || (exists(@phone) && contains(lower(@phone),lower('${formatted}'))) || (exists(@id) && contains(lower(@id),lower('${formatted}'))) || (exists(@objectId) && contains(lower(@objectId),lower('${formatted}')))`
    }

    setSearching(true);

    const customerRequest: any = {
      select: {
        index: {
          searchIndex: `${process.env.REACT_APP_ECO_SYSTEM}:custom:id`,
          searchQuery: `@partitions:{'org\\:${formatForRedis(
            projects?.userServiceId
          )}'}`,
          searchOptions: "VERBATIM TIMEOUT 10000",
        },
        load: {
          info: "$.info",
          objectId: "$.objectId",
          name: "$..info..name",
          email: "$..info..email",
          phone: "$..info..phone",
          id: "$..info.id",
        },
      },
      filter: {
        expression,
      },
    };

    dispatch(
      GET_AGGREGATE({
        requestData: customerRequest,
        callback: (response) => {
          setSearching(false);
          const customers = response?.map((customer) => ({
            ...customer,
            label: `${customer?.name} (${customer?.id})`,
          }));

          if (customerId && customers?.length) {

            const searchedCustomer = customers.find((customer) => customer?.objectId.toString() === customerId.toString() || customer?.id.toString() === customerId.toString());
            setInputValue(searchedCustomer?.id);
            onChange({ id: searchedCustomer?.id })
          }
          setOptions([...customers]);
        },
      })
    );
  };

  if (userId) {
    return (
      <Input
        value={inputValue || value?.id || ""}
        placeholder={placeholder}
        required={required}
        onChange={(e) => {
          onChange({ id: e.target.value })
          setInputValue(e.target.value)
        }}
        allowClear
      />
    );
  }
  const CREATE_PROFILE_URL = `${window.location.origin}/customer-cpc?userId=${encrypted_token?.userId}&connectionId=${encrypted_token?.connectionId}&serviceId=${encrypted_token?.cudbServiceId}`;

  return (
    <div>
      {showTanF && (
        <div style={{ display: "flex", alignItems: "center", gap: 4, marginBottom: '10px' }}>
          <CheckCircleTwoTone
            twoToneColor="#52c41a"
            style={{ fontSize: 30 }}
          />
          <span style={{ color: "#52c41a", fontWeight: 500, fontSize: 16 }}>
            Eligible for tanF
          </span>
        </div>
      )}
      <div style={{ display: "flex", alignItems: "center", gap: 12 }}>
        <Select
          showSearch
          value={value}
          mode={multiple ? "multiple" : undefined}
          className="w-full"
          placeholder={placeholder}
          allowClear
          onChange={(selectedValue) => {
            if (selectedValue) {
              if (multiple) {
                const selectedCustomers = selectedValue.map((val: string) =>
                  options.find((customer) => customer.id === val)
                );
                onChange(selectedCustomers);
              } else {
                const customer = options.find((customer) => customer.id === selectedValue);
                const customerInfoObj = customer?.info?.customer;
                const hasTanFYes = customerInfoObj
                  ? Object.entries(customerInfoObj).some(
                    ([key, value]) => /^tanF/i.test(key) && value === "Yes"
                  )
                  : false;

                setShowTanF(hasTanFYes);
                onChange(customer);
              }
            } else {
              setShowTanF(false);
              onChange(undefined);
            }
          }}
          loading={searching}
          filterOption={(input, option) =>
            (option!.children as unknown as string)
              .toLowerCase()
              .includes(input.toLowerCase())
          }
          onSearch={(search) => {
            if (timeoutId) clearTimeout(timeoutId);
            const newTimeout = setTimeout(() => {
              if (search && search !== "") {
                getCustomer(search);
              }
            }, 500);
            setTimeoutId(newTimeout);
          }}
        >
          {options?.map((option, index) => (
            <Option key={index} value={option.id}>
              {option.label}
            </Option>
          ))}
        </Select>
        <a
          href={CREATE_PROFILE_URL}
          target="_blank"
          rel="noopener noreferrer"
          style={{
            whiteSpace: "nowrap",
            fontWeight: 500,
            color: "#1677ff",
            marginLeft: 8,
            textDecoration: "underline",
            fontSize: 14,
          }}
        >
          Create Profile
        </a>
      </div>
    </div>
  );
};

export default CustomerInput;
