import React, { FC, useEffect, useState } from "react";
import { Alert, Button, Empty, Modal, Tag } from "antd";

import ConfirmationModal from "../../../../common/Confirmation";
import { pushNotification } from "utils/notifications";

import { PaymentConfig } from "./types";
import { getPaymentConfig } from "./mockData";
import { cloneConfig, validatePaymentConfig } from "./paymentConfig";
import PaymentConfigForm from "./PaymentConfigForm";

interface Props {
  open: boolean;
  /** Configuration (or payout terms) being edited; null when none is attached. */
  configId: string | null;
  /** Who the edit is for - a team, an event, a player or a payee. */
  subject: string;
  onClose: () => void;
}

/**
 * "Edit payment request": the complete configuration a group is billed
 * on (or the payout terms a payee is paid on), editable in full. Save
 * validates with the same rules as the admin API, then runs the
 * confirm-and-notify flow; the write itself is a TODO until a
 * CFO-facing endpoint exists.
 */
const PaymentConfigEditor: FC<Props> = ({ open, configId, subject, onClose }) => {
  const [draft, setDraft] = useState<PaymentConfig | null>(null);
  const [errors, setErrors] = useState<string[]>([]);
  const [confirming, setConfirming] = useState(false);

  useEffect(() => {
    const stored = getPaymentConfig(configId);
    setDraft(stored ? cloneConfig(stored) : null);
    setErrors([]);
  }, [configId, open]);

  const requestSave = () => {
    if (!draft) return;
    const problems = validatePaymentConfig(draft);
    setErrors(problems);
    if (problems.length === 0) setConfirming(true);
  };

  const save = () => {
    // TODO(backend): write the configuration through the admin API once a
    // CFO-facing endpoint exists.
    setConfirming(false);
    pushNotification("Payment configuration saved", "success", "TOP_CENTER", 1500);
    onClose();
  };

  return (
    <>
      <Modal
        visible={open}
        width={960}
        onCancel={onClose}
        className="beam-modal cfo-action-modal cfo-config-modal"
        bodyStyle={{ maxHeight: "72vh", overflow: "auto" }}
        title={
          <div className="cfo-action-modal__title">
            <span>Edit Payment Request</span>
            {subject && <Tag color="geekblue">{subject}</Tag>}
            {draft && (
              <span className="cfo-action-modal__scope">
                {draft.name} · applies to everyone billed on this configuration
              </span>
            )}
          </div>
        }
        footer={[
          <Button key="cancel" className="beam-btn orange-btn bordered" onClick={onClose}>
            Cancel
          </Button>,
          <Button key="save" className="beam-btn green-btn cover" disabled={!draft} onClick={requestSave}>
            Save configuration
          </Button>,
        ]}
      >
        {!draft && (
          <Empty
            image={Empty.PRESENTED_IMAGE_SIMPLE}
            description={`${subject || "This item"} has no payment configuration attached. Attach one from the admin portal's Payment Configuration screen.`}
          />
        )}

        {draft && (
          <>
            {errors.length > 0 && (
              <Alert
                className="cfo-modal-alert cfo-modal-alert--top"
                type="error"
                showIcon
                message="Please fix the highlighted sections"
                description={
                  <ul className="cfo-error-list">
                    {errors.map((message) => (
                      <li key={message}>{message}</li>
                    ))}
                  </ul>
                }
              />
            )}
            <PaymentConfigForm value={draft} onChange={setDraft} errors={errors} />
            <Alert
              className="cfo-modal-alert"
              type="info"
              showIcon
              message="Saving is a preview."
              description="The admin API exposes payment configurations read-only to this screen - the confirm step notifies but does not write until a CFO-facing endpoint exists."
            />
          </>
        )}
      </Modal>

      {confirming && (
        <ConfirmationModal
          message={`Save changes to "${draft ? draft.name : ""}" for ${subject}?`}
          onClose={() => setConfirming(false)}
          handleConfirm={save}
        />
      )}
    </>
  );
};

export default PaymentConfigEditor;
