import React, { useState } from "react";
import { Button, Checkbox, Col, Form, FormInstance, Row, Skeleton } from "antd";
import { useSelector } from "react-redux";
import dayjs from "dayjs";
import { RootState } from "reducers/rootReducer";
import ResponderInput from "../../../../common/ResponderInput";
import VehicleInput from "../../../../common/VehicleInput";
import FixedAssetInput from "../../../../common/EquipmentInput";
import { FormSection, Pill } from "../common/ui";
import DriverPicker from "../common/driverAvailability/DriverPicker";
import {
  addToResponderList,
  DriverRecord,
  toResponderValue,
} from "../common/driverAvailability/availability";

/** Form values may hold moment/dayjs objects, ISO strings or "HH:mm". */
export const toTimeString = (value: any): string | undefined => {
  if (!value) return undefined;
  if (typeof value === "string" && /^\d{1,2}:\d{2}$/.test(value)) return value;
  const parsed = dayjs(value?.valueOf?.() ?? value);
  return parsed.isValid() ? parsed.format("HH:mm") : undefined;
};

export const toDayTimestamp = (value: any): number | undefined => {
  if (!value) return undefined;
  const parsed = dayjs(value?.valueOf?.() ?? value);
  return parsed.isValid() ? parsed.startOf("day").valueOf() : undefined;
};


const locationLabel = (value: any) =>
  value?.label || value?.attributes?.address || value?.address || undefined;

/** What the dispatcher needs to know about the job while assigning it. */
const JobSummary = ({ form }: { form: FormInstance }) => {
  const first = Form.useWatch("patientFirstName", form);
  const last = Form.useWatch("patientLastName", form);
  const pickupDate = Form.useWatch("pickupDate", form);
  const pickupTime = Form.useWatch("pickupTime", form);
  const appointmentTime = Form.useWatch("appointmentTime", form);
  const serviceType = Form.useWatch("serviceType", form);
  const transferType = Form.useWatch("transferType", form);
  const equipment = Form.useWatch("equipmentNeeded", form);
  const pickup = Form.useWatch("pickupLocation", form);
  const dropoff = Form.useWatch("dropoffLocation", form);
  const instructions = Form.useWatch("instructions", form);

  const day = toDayTimestamp(pickupDate);
  const when = [
    day ? dayjs(day).format("ddd, MMM D") : "No date",
    toTimeString(pickupTime) ? `pickup ${toTimeString(pickupTime)}` : "no pickup time",
    toTimeString(appointmentTime) && `appt ${toTimeString(appointmentTime)}`,
  ]
    .filter(Boolean)
    .join(" · ");
  const tags = [serviceType, transferType, ...(Array.isArray(equipment) ? equipment : [])].filter(
    Boolean
  );

  return (
    <div className="mx-job-summary">
      <div className="mx-job-summary__head">
        <div className="mx-job-summary__patient">
          {[first, last].filter(Boolean).join(" ") || "Unnamed patient"}
        </div>
        <div className="mx-job-summary__when">{when}</div>
      </div>
      <div className="mx-job-summary__route">
        <div>
          <span className="mx-job-summary__dot mx-job-summary__dot--from" />
          {locationLabel(pickup) || "Pickup address missing"}
        </div>
        <div>
          <span className="mx-job-summary__dot mx-job-summary__dot--to" />
          {locationLabel(dropoff) || "Drop-off address missing"}
        </div>
      </div>
      {tags.length > 0 && (
        <div className="mx-job-summary__tags">
          {tags.map((t) => (
            <Pill key={t} tone="blue" plain>
              {t}
            </Pill>
          ))}
        </div>
      )}
      {instructions && <div className="mx-job-summary__note">{instructions}</div>}
    </div>
  );
};

const RESPONSIVE = { xs: 24, md: 12, xl: 8 };

interface Props {
  form: FormInstance;
  socket: ISocket;
  serviceType?: string;
  stairsLocations?: string[];
  differentVehicle?: boolean;
  /** Drawer mode: the rest of the form is hidden. */
  compact?: boolean;
  preferredDriverId?: string;
  index?: number;
  done?: boolean;
}

const AssignmentSection = ({
  form,
  socket,
  serviceType,
  stairsLocations,
  differentVehicle,
  compact,
  preferredDriverId,
  index,
  done,
}: Props) => {
  const { adminUserRoles, selectedPage, vehicles } = useSelector(
    (state: RootState) => state.auth
  );
  const [showReturnPicker, setShowReturnPicker] = useState(false);

  const pickupDate = Form.useWatch("pickupDate", form);
  const pickupTime = Form.useWatch("pickupTime", form);
  const returnPickupTime = Form.useWatch("returnPickupTime", form);
  const primary = Form.useWatch("primaryResponder", form);
  const secondary = Form.useWatch("secondaryResponder", form);
  const returnPrimary = Form.useWatch("returnPrimaryResponder", form);
  const returnSecondary = Form.useWatch("returnSecondaryResponder", form);

  const day = toDayTimestamp(pickupDate);
  const pageId = selectedPage?.ignorePage ? undefined : selectedPage?.page?.pageId?.toString();
  const hasStairs = stairsLocations?.includes("Dropoff") || stairsLocations?.includes("Pickup");
  const isCallReturn = serviceType === "C/R";
  const rolesReady = adminUserRoles && adminUserRoles.length > 0;

  // Pre-fill the driver's usual vehicle, but never overwrite a chosen one.
  const pairVehicle = (driver: DriverRecord, field: "vehicle" | "returnVehicle") => {
    if (form.getFieldValue(field)?.value) return;
    const match = (vehicles || []).find(
      (v: any) => v?.obj?.assosiatedUserId?.toString() === driver.id
    );
    if (match?.obj?.vehicleId) {
      form.setFieldsValue({
        [field]: {
          type: "vehicle",
          value: match.obj.vehicleId,
          obj: match.obj,
          valueName: match.obj.name,
        },
      });
    }
  };

  const assign = (
    driver: DriverRecord,
    primaryField: "primaryResponder" | "returnPrimaryResponder",
    secondaryField: "secondaryResponder" | "returnSecondaryResponder",
    vehicleField: "vehicle" | "returnVehicle"
  ) => {
    const secondaryValue = form.getFieldValue(secondaryField);
    // A driver can't be both primary and secondary on the same leg.
    const remaining = (secondaryValue?.responders || []).filter(
      (r: any) => `${r.id}` !== driver.id
    );
    form.setFieldsValue({
      [primaryField]: toResponderValue(driver),
      ...(secondaryValue
        ? {
            [secondaryField]: {
              type: "responder",
              responders: remaining,
              values: remaining.map((r: any) => `${r.id}`),
            },
          }
        : {}),
    });
    pairVehicle(driver, vehicleField);
  };

  const responderInput = (multiple = false) => (
    <ResponderInput placeholder="Search drivers" adminRoles={adminUserRoles} multiple={multiple} />
  );
  const vehicleInput = (
    <VehicleInput placeholder="Select vehicle" vehicleId socket={socket} />
  );

  return (
    <FormSection
      id="section-assignment"
      index={compact ? undefined : index}
      done={done}
      title="Assignment"
      description="Pick a driver using their shift, time off and existing jobs for the day."
    >
      {compact && <JobSummary form={form} />}

      <DriverPicker
        day={day}
        pickupTime={toTimeString(pickupTime)}
        pageId={pageId}
        primaryId={primary?.id?.toString() ?? primary?.value?.toString()}
        secondaryIds={(secondary?.responders || []).map((r: any) => `${r.id}`)}
        highlightId={preferredDriverId}
        onAssignPrimary={(driver) =>
          assign(driver, "primaryResponder", "secondaryResponder", "vehicle")
        }
        onAddSecondary={(driver) =>
          form.setFieldsValue({
            secondaryResponder: addToResponderList(form.getFieldValue("secondaryResponder"), driver),
          })
        }
      />

      <div className="mx-crew mt-3">
        <div className="mx-crew__title">{isCallReturn ? "Outbound crew" : "Crew"}</div>
        {!rolesReady ? (
          <Skeleton active paragraph={{ rows: 2 }} title={false} />
        ) : (
          <Row gutter={16}>
            <Col {...RESPONSIVE} {...(compact ? { xl: 12 } : {})}>
              <Form.Item name="primaryResponder" label="Primary driver">
                {responderInput()}
              </Form.Item>
            </Col>
            <Col {...RESPONSIVE} {...(compact ? { xl: 12 } : {})}>
              <Form.Item name="secondaryResponder" label="Second driver(s)">
                {responderInput(true)}
              </Form.Item>
            </Col>
            <Col {...RESPONSIVE} {...(compact ? { xl: 12 } : {})}>
              <Form.Item label="Vehicle" name="vehicle">
                {vehicleInput}
              </Form.Item>
            </Col>
            <Col {...RESPONSIVE} {...(compact ? { xl: 12 } : {})}>
              <Form.Item name="equipment" label="Equipment">
                <FixedAssetInput placeholder="" socket={socket} />
              </Form.Item>
            </Col>
            {hasStairs && (
              <Col span={24}>
                <Form.Item name="differentVehicle" valuePropName="checked">
                  <Checkbox>Stair chair crew travels in a different vehicle</Checkbox>
                </Form.Item>
              </Col>
            )}
            {differentVehicle && (
              <>
                <Col {...RESPONSIVE} {...(compact ? { xl: 12 } : {})}>
                  <Form.Item name="stairchairResponder" label="Stair chair driver">
                    {responderInput()}
                  </Form.Item>
                </Col>
                <Col {...RESPONSIVE} {...(compact ? { xl: 12 } : {})}>
                  <Form.Item label="Stair chair vehicle" name="stairchairVehicle">
                    {vehicleInput}
                  </Form.Item>
                </Col>
              </>
            )}
          </Row>
        )}
      </div>

      {rolesReady && (isCallReturn || (differentVehicle && serviceType === "W/R")) && (
        <div className="mx-crew mt-3">
          <div className="mx-crew__title">
            Return trip
            {isCallReturn && (
              <Button
                type="link"
                size="small"
                onClick={() => setShowReturnPicker((v) => !v)}
              >
                {showReturnPicker ? "Hide suggestions" : "Suggest a return driver"}
              </Button>
            )}
          </div>

          {isCallReturn && showReturnPicker && (
            <div className="mb-3">
              <DriverPicker
                title="Suggested return drivers"
                day={day}
                pickupTime={toTimeString(returnPickupTime)}
                pageId={pageId}
                primaryId={returnPrimary?.id?.toString() ?? returnPrimary?.value?.toString()}
                secondaryIds={(returnSecondary?.responders || []).map((r: any) => `${r.id}`)}
                onAssignPrimary={(driver) =>
                  assign(driver, "returnPrimaryResponder", "returnSecondaryResponder", "returnVehicle")
                }
                onAddSecondary={(driver) =>
                  form.setFieldsValue({
                    returnSecondaryResponder: addToResponderList(
                      form.getFieldValue("returnSecondaryResponder"),
                      driver
                    ),
                  })
                }
              />
            </div>
          )}

          <Row gutter={16}>
            {isCallReturn && (
              <>
                <Col {...RESPONSIVE} {...(compact ? { xl: 12 } : {})}>
                  <Form.Item name="returnPrimaryResponder" label="Return primary driver">
                    {responderInput()}
                  </Form.Item>
                </Col>
                <Col {...RESPONSIVE} {...(compact ? { xl: 12 } : {})}>
                  <Form.Item name="returnSecondaryResponder" label="Return second driver(s)">
                    {responderInput(true)}
                  </Form.Item>
                </Col>
                <Col {...RESPONSIVE} {...(compact ? { xl: 12 } : {})}>
                  <Form.Item label="Return vehicle" name="returnVehicle">
                    {vehicleInput}
                  </Form.Item>
                </Col>
                <Col {...RESPONSIVE} {...(compact ? { xl: 12 } : {})}>
                  <Form.Item name="returnEquipment" label="Return equipment">
                    <FixedAssetInput placeholder="" socket={socket} />
                  </Form.Item>
                </Col>
              </>
            )}
            {differentVehicle && (
              <>
                <Col {...RESPONSIVE} {...(compact ? { xl: 12 } : {})}>
                  <Form.Item name="returnStairchairResponder" label="Return stair chair driver">
                    {responderInput()}
                  </Form.Item>
                </Col>
                <Col {...RESPONSIVE} {...(compact ? { xl: 12 } : {})}>
                  <Form.Item label="Return stair chair vehicle" name="returnStairchairVehicle">
                    {vehicleInput}
                  </Form.Item>
                </Col>
              </>
            )}
          </Row>
        </div>
      )}
    </FormSection>
  );
};

export default AssignmentSection;
