import React, { FC, useCallback, useMemo, useRef, useState } from "react";
import { Button, Empty, Table, Tooltip } from "antd";
import { BarChartOutlined, TableOutlined } from "@ant-design/icons";

import { Series } from "./theme";

export interface TooltipRow {
  label: string;
  value: string;
  swatch?: string;
}

export interface TooltipState {
  /** Coordinates inside the chart box, in CSS pixels. */
  x: number;
  y: number;
  title: string;
  rows: TooltipRow[];
}

/** What a chart uses to drive the frame's tooltip. */
export interface ChartApi {
  show: (state: TooltipState) => void;
  hide: () => void;
}

export type ChartView = "chart" | "table";

export interface TableColumn<T> {
  key: string;
  title: string;
  align?: "left" | "right";
  render: (row: T) => React.ReactNode;
}

interface Props<T extends object> {
  view: ChartView;
  legend?: Series[];
  data: T[];
  columns: TableColumn<T>[];
  rowKey: (row: T) => string;
  empty?: string;
  ariaLabel: string;
  children: (api: ChartApi) => React.ReactNode;
}

/** The chart / table switch that sits in a card's `extra`. */
export const ChartViewToggle: FC<{ view: ChartView; onChange: (view: ChartView) => void }> = ({
  view,
  onChange,
}) => (
  <span className="cfo-chart__toggle">
    <Tooltip title="Chart">
      <Button
        type="text"
        size="small"
        className={view === "chart" ? "is-active" : ""}
        icon={<BarChartOutlined />}
        onClick={() => onChange("chart")}
      />
    </Tooltip>
    <Tooltip title="Table">
      <Button
        type="text"
        size="small"
        className={view === "table" ? "is-active" : ""}
        icon={<TableOutlined />}
        onClick={() => onChange("table")}
      />
    </Tooltip>
  </span>
);

/**
 * Chrome shared by every chart: the legend row, the hover tooltip, the
 * table-view twin and the empty state. The chart itself is rendered by
 * the child function and reports hover through `ChartApi`.
 */
function ChartFrame<T extends object>({ view, legend, data, columns, rowKey, empty, ariaLabel, children }: Props<T>) {
  const box = useRef<HTMLDivElement>(null);
  const [tip, setTip] = useState<TooltipState | null>(null);

  const api = useMemo<ChartApi>(
    () => ({ show: (state) => setTip(state), hide: () => setTip(null) }),
    []
  );

  const tipStyle = useCallback((): React.CSSProperties => {
    if (!tip || !box.current) return {};
    const width = box.current.clientWidth;
    const left = Math.min(Math.max(tip.x, 90), Math.max(90, width - 90));
    return { left, top: tip.y };
  }, [tip]);

  if (data.length === 0) {
    return <Empty image={Empty.PRESENTED_IMAGE_SIMPLE} description={empty || "Nothing in this window"} />;
  }

  if (view === "table") {
    return (
      <Table<T>
        className="cfo-chart__table"
        size="small"
        rowKey={rowKey}
        pagination={false}
        dataSource={data}
        columns={columns.map((column) => ({
          key: column.key,
          title: column.title,
          align: column.align,
          render: (_: unknown, row: T) => column.render(row),
        }))}
      />
    );
  }

  return (
    <div className="cfo-chart">
      {legend && legend.length > 1 && (
        <ul className="cfo-chart__legend" aria-hidden="true">
          {legend.map((series) => (
            <li key={series.key}>
              <span className="cfo-chart__swatch" style={{ background: series.color }} />
              {series.label}
            </li>
          ))}
        </ul>
      )}
      <div className="cfo-chart__box" ref={box} role="img" aria-label={ariaLabel}>
        {children(api)}
        {tip && (
          <div className="cfo-chart__tooltip" style={tipStyle()}>
            <div className="cfo-chart__tooltip-title">{tip.title}</div>
            {tip.rows.map((row) => (
              <div key={row.label} className="cfo-chart__tooltip-row">
                {row.swatch && <span className="cfo-chart__swatch" style={{ background: row.swatch }} />}
                <span>{row.label}</span>
                <strong>{row.value}</strong>
              </div>
            ))}
          </div>
        )}
      </div>
    </div>
  );
}

export default ChartFrame;
