import { useCallback, useRef, useState } from "react";

// useState plus a ref that is updated atomically with the state inside the
// functional updater. Every write goes through React's update queue (so
// concurrent writers — socket callbacks, polling responses, effects — compose
// instead of overwriting each other), and the ref always mirrors the latest
// committed value for callers that live outside the render cycle.
export function useSyncedRefState<T>(initialValue: T) {
  const [state, setState] = useState<T>(initialValue);
  const ref = useRef<T>(initialValue);

  const setSyncedState = useCallback(
    (updater: T | ((prevState: T) => T)) => {
      setState((prev) => {
        const next =
          typeof updater === "function"
            ? (updater as (prevState: T) => T)(prev)
            : updater;
        ref.current = next;
        return next;
      });
    },
    []
  );

  return [state, setSyncedState, ref] as const;
}
