import React, { useMemo } from "react";
import { Button, Form, Input, InputNumber, Table, Tooltip } from "antd";
import type { FormInstance } from "antd/es/form";
import type { FormListFieldData } from "antd/es/form/FormList";
import type { ColumnsType } from "antd/es/table";
import { PlusOutlined } from "@ant-design/icons";
import LocationInput from "../../../../../common/LocationInput";
import { generateUUID } from "utils/appUtil";
import { EmptyState, FormModal, RowActions } from "../../common/ui";
import { nameKey } from "./adminCollection";

// Persisted shapes (read by PriceTypeInput -> DispatchPanel/QuotationModal):
//   location: { key, name, address: { attributes: { address }, coordinates }, geofenceRadius }
//   rate row: { key, service, type, [locationName]: value }
// QuotationModal parseFloat()s rate values and picks a service's rows by
// position (0 = base, 1 = km, 2 = wait), so row order must be preserved.
// Values are written as strings, matching what the old text inputs stored.

export interface PlanLocation {
  key: string;
  name: string;
  address?: { attributes?: { address?: string }; coordinates?: any };
  geofenceRadius?: number | string;
}

export type RateRow = { key: string; service: string; type: string; [location: string]: any };

export const DEFAULT_SERVICES = [
  "Stretcher",
  "Broda",
  "Wheelchair",
  "Additional staff (Per Person)",
  "Hulpr Wheelchair",
  "Hulpr Broda",
  "Oxygen",
  "Overnight",
  "Tax",
];

const RATE_TYPES: Record<string, string[]> = {
  "Hulpr Wheelchair": ["Flat Rate"],
  "Hulpr Broda": ["Flat Rate"],
  Overnight: ["Overnight/Holiday multiplier"],
  Oxygen: ["Oxygen (per L/min)"],
  Tax: ["%"],
};

const DEFAULT_RATE_TYPES = ["Base Rate", "KM Rate", "Wait Time"];

// A location's name becomes a property on every rate row, so these are taken.
const RESERVED_LOCATION_NAMES = ["key", "service", "type"];

export const NAME_MAX = 60;
export const PLAN_NAME_MAX = 80;

export const buildRateRows = (services: string[], locations: PlanLocation[]): RateRow[] =>
  services.flatMap((service) =>
    (RATE_TYPES[service] || DEFAULT_RATE_TYPES).map((type) => ({
      key: generateUUID(),
      service,
      type,
      ...Object.fromEntries(locations.map((loc) => [loc.name, "0"])),
    }))
  );

/** InputNumber -> stored string ("" while the cell is empty). */
export const toStoredNumber = (value: any) =>
  value === null || value === undefined || value === "" ? "" : String(value);

const nonNegative = (label: string) => ({
  validator: (_: any, value: any) =>
    value === "" || value === undefined || value === null || Number(value) >= 0
      ? Promise.resolve()
      : Promise.reject(new Error(`${label} can't be negative`)),
});

export const locationAddress = (loc?: PlanLocation) => loc?.address?.attributes?.address || "";

/* ---------------------------------------------------------- Address input */

/** Adapts LocationInput's value to the stored `{attributes:{address}, coordinates}` shape. */
export const PlanAddressInput = ({
  value,
  onChange,
  placeholder,
}: {
  value?: PlanLocation["address"];
  onChange?: (value: PlanLocation["address"]) => void;
  placeholder?: string;
}) => {
  const address = value?.attributes?.address;
  const lat = value?.coordinates?.lat;
  const long = value?.coordinates?.long;
  // Memoised so LocationInput doesn't reset its text on every parent render.
  const inputValue = useMemo(
    () =>
      address
        ? {
            label: address,
            value: { description: address, place_id: "", coordinates: value?.coordinates },
          }
        : undefined,
    // eslint-disable-next-line react-hooks/exhaustive-deps
    [address, lat, long]
  );
  return (
    <LocationInput
      value={inputValue}
      placeholder={placeholder}
      onChange={(location: any) =>
        onChange?.({
          attributes: { address: location?.label },
          coordinates: location?.value?.coordinates,
        })
      }
    />
  );
};

const addressRule = {
  validator: (_: any, value: PlanLocation["address"]) =>
    value?.attributes?.address?.trim()
      ? Promise.resolve()
      : Promise.reject(new Error("Pick an address")),
};

/* -------------------------------------------------------- Locations table */

export const LocationsTable = ({
  form,
  fields,
  onRemove,
  onAdd,
}: {
  form: FormInstance;
  fields: FormListFieldData[];
  onRemove: (index: number) => void;
  onAdd: () => void;
}) => {
  const columns: ColumnsType<FormListFieldData> = [
    {
      title: "Name",
      key: "name",
      width: 180,
      render: (_, field) => (
        <Tooltip title="Rates are stored per location name, so names can't be changed. Delete and re-add to rename.">
          <strong>{form.getFieldValue(["locations", field.name, "name"])}</strong>
        </Tooltip>
      ),
    },
    {
      title: "Address",
      key: "address",
      render: (_, field) => (
        // Not required here: legacy plans may lack an address and must stay editable.
        <Form.Item name={[field.name, "address"]} style={{ margin: 0, minWidth: 240 }}>
          <PlanAddressInput placeholder="Search address" />
        </Form.Item>
      ),
    },
    {
      title: "Geofence radius",
      key: "geofenceRadius",
      width: 170,
      render: (_, field) => (
        <Form.Item
          name={[field.name, "geofenceRadius"]}
          normalize={toStoredNumber}
          rules={[nonNegative("Radius")]}
          style={{ margin: 0 }}
        >
          <InputNumber min={0} addonAfter="km" style={{ width: "100%" }} />
        </Form.Item>
      ),
    },
    {
      title: "",
      key: "actions",
      width: 60,
      align: "right",
      render: (_, field) => (
        <RowActions
          onDelete={() => onRemove(field.name)}
          deleteConfirm={`Remove "${form.getFieldValue([
            "locations",
            field.name,
            "name",
          ])}" and its rates from this plan?`}
        />
      ),
    },
  ];

  return (
    <Table<FormListFieldData>
      size="small"
      rowKey="key"
      pagination={false}
      columns={columns}
      dataSource={fields}
      scroll={{ x: "max-content" }}
      locale={{
        emptyText: (
          <EmptyState
            title="No locations yet"
            description="Add the base locations this plan prices trips from."
            action={{ label: "Add location", onClick: onAdd }}
          />
        ),
      }}
    />
  );
};

/* -------------------------------------------------------------- Rates grid */

interface GridRow {
  field: FormListFieldData;
  row: RateRow;
}

const unitFor = (type: string) => (type === "%" ? "%" : "$");

export const RatesGrid = ({
  form,
  fields,
  locations,
  onDeleteService,
}: {
  form: FormInstance;
  fields: FormListFieldData[];
  locations: PlanLocation[];
  onDeleteService: (service: string) => void;
}) => {
  const rows: GridRow[] = fields.map((field) => ({
    field,
    row: form.getFieldValue(["rates", field.name]) || {},
  }));

  // Group consecutive rows of the same service (Base / KM / Wait) under one cell.
  const spans = rows.map(() => 0);
  for (let i = 0; i < rows.length; ) {
    let j = i;
    while (j + 1 < rows.length && rows[j + 1].row.service === rows[i].row.service) j++;
    spans[i] = j - i + 1;
    i = j + 1;
  }
  const groupCell = (_: GridRow, index?: number) => ({ rowSpan: spans[index ?? 0] });

  const columns: ColumnsType<GridRow> = [
    {
      title: "Service",
      key: "service",
      fixed: "left",
      width: 170,
      onCell: groupCell,
      render: (_, { row }) => <strong>{row.service}</strong>,
    },
    {
      title: "Rate",
      key: "type",
      fixed: "left",
      width: 150,
      render: (_, { row }) => <span style={{ color: "#6b7a90" }}>{row.type === "%" ? "Tax rate" : row.type}</span>,
    },
    ...locations.map((loc) => ({
      title: (
        <div style={{ lineHeight: 1.2 }}>
          <div>{loc.name}</div>
          {locationAddress(loc) && (
            <div
              title={locationAddress(loc)}
              style={{
                fontSize: 11,
                fontWeight: 400,
                color: "#6b7a90",
                maxWidth: 150,
                overflow: "hidden",
                textOverflow: "ellipsis",
                whiteSpace: "nowrap",
              }}
            >
              {locationAddress(loc)}
            </div>
          )}
        </div>
      ),
      key: `loc-${loc.key || loc.name}`,
      width: 160,
      render: (_: any, { field, row }: GridRow) => {
        const unit = unitFor(row.type);
        return (
          <Form.Item
            name={[field.name, loc.name]}
            normalize={toStoredNumber}
            rules={[nonNegative("Rate")]}
            style={{ margin: 0 }}
          >
            <InputNumber
              min={0}
              placeholder="0"
              style={{ width: "100%" }}
              {...(unit === "$" ? { prefix: "$" } : { addonAfter: unit })}
            />
          </Form.Item>
        );
      },
    })),
    {
      title: "",
      key: "actions",
      width: 60,
      align: "right" as const,
      onCell: groupCell,
      render: (_, { row }) => (
        <RowActions
          onDelete={() => onDeleteService(row.service)}
          deleteConfirm={`Remove "${row.service}" and all of its rates?`}
        />
      ),
    },
  ];

  return (
    <Table<GridRow>
      size="small"
      bordered
      rowKey={(r) => r.field.key}
      pagination={false}
      columns={columns}
      dataSource={rows}
      scroll={{ x: "max-content", y: 420 }}
    />
  );
};

/* ------------------------------------------------------- Add service row */

export const AddServiceRow = ({
  existingServices,
  onAdd,
}: {
  existingServices: string[];
  onAdd: (name: string) => void;
}) => {
  const [form] = Form.useForm();
  return (
    // component={false}: this form lives inside the plan's <form>.
    <Form
      form={form}
      component={false}
      onFinish={({ service }) => {
        onAdd(service.trim());
        form.resetFields();
      }}
    >
      <div style={{ display: "flex", gap: 8, alignItems: "flex-start", marginTop: 12 }}>
        <Form.Item
          name="service"
          style={{ flex: 1, maxWidth: 360, margin: 0 }}
          validateFirst
          rules={[
            { required: true, whitespace: true, message: "Enter a service name" },
            { max: NAME_MAX, message: `Keep it under ${NAME_MAX} characters` },
            {
              validator: (_, value) =>
                existingServices.some((s) => nameKey(s) === nameKey(value))
                  ? Promise.reject(new Error("This service is already priced"))
                  : Promise.resolve(),
            },
          ]}
        >
          <Input placeholder="New service, e.g. Bariatric stretcher" onPressEnter={() => form.submit()} />
        </Form.Item>
        <Button icon={<PlusOutlined />} className="mx-btn-secondary" onClick={() => form.submit()}>
          Add service
        </Button>
      </div>
    </Form>
  );
};

/* ------------------------------------------------------ Add location modal */

export const AddLocationModal = ({
  open,
  existingNames,
  onCancel,
  onAdd,
}: {
  open: boolean;
  existingNames: string[];
  onCancel: () => void;
  onAdd: (location: PlanLocation) => void;
}) => {
  const [form] = Form.useForm();
  return (
    <FormModal
      open={open}
      title="Add location"
      subtitle="Every service in this plan gets a $0 rate for the new location until you set it."
      onCancel={onCancel}
      onSubmit={form.submit}
      okText="Add location"
    >
      <Form
        form={form}
        layout="vertical"
        requiredMark={false}
        onFinish={(values) =>
          onAdd({
            key: generateUUID(),
            name: values.name.trim(),
            address: values.address,
            geofenceRadius: toStoredNumber(values.geofenceRadius),
          })
        }
      >
        <Form.Item
          label="Location name"
          name="name"
          validateFirst
          rules={[
            { required: true, whitespace: true, message: "Enter a location name" },
            { max: NAME_MAX, message: `Keep it under ${NAME_MAX} characters` },
            {
              validator: (_, value) => {
                if (RESERVED_LOCATION_NAMES.includes(nameKey(value)))
                  return Promise.reject(new Error("Please choose a different name"));
                if (existingNames.some((n) => nameKey(n) === nameKey(value)))
                  return Promise.reject(new Error("This plan already has a location with this name"));
                return Promise.resolve();
              },
            },
          ]}
        >
          <Input placeholder="e.g. Kingston" autoFocus />
        </Form.Item>
        <Form.Item label="Address" name="address" rules={[addressRule]}>
          <PlanAddressInput placeholder="Search address" />
        </Form.Item>
        <Form.Item
          label="Geofence radius"
          name="geofenceRadius"
          normalize={toStoredNumber}
          rules={[{ required: true, message: "Enter a radius" }, nonNegative("Radius")]}
        >
          <InputNumber min={0} addonAfter="km" style={{ width: "100%" }} />
        </Form.Item>
      </Form>
    </FormModal>
  );
};
