import React, { FC, useState } from "react";
import { Alert, Button, DatePicker, Empty, Radio, Select, Switch } from "antd";
import { ArrowLeftOutlined, ReloadOutlined } from "@ant-design/icons";
import moment, { Moment } from "moment";
import { DotFilter } from "./FleetMap";
import { MAX_HISTORY_MS } from "./fleetApi";
import {
  FleetVehicle,
  formatDistance,
  formatDuration,
  formatSpeed,
  SPEED_COLORS,
  SpeedUnit,
  Stop,
  TrackPoint,
  TrackSummary,
} from "./fleetUtils";

export interface HistoryRange {
  from: number;
  to: number;
}

export interface Layers {
  dots: boolean;
  stops: boolean;
  arrows: boolean;
}

type Preset = "1h" | "6h" | "12h" | "24h" | "today" | "yesterday" | "custom";

const PRESETS: { id: Preset; label: string }[] = [
  { id: "1h", label: "1h" },
  { id: "6h", label: "6h" },
  { id: "12h", label: "12h" },
  { id: "24h", label: "24h" },
  { id: "today", label: "Today" },
  { id: "yesterday", label: "Yesterday" },
];

export const presetRange = (preset: Exclude<Preset, "custom">, now = Date.now()): HistoryRange => {
  const hours = { "1h": 1, "6h": 6, "12h": 12, "24h": 24 } as Record<string, number>;
  if (hours[preset]) return { from: now - hours[preset] * 3600000, to: now };
  if (preset === "today") return { from: moment(now).startOf("day").valueOf(), to: now };
  const y = moment(now).subtract(1, "day");
  // Up to 23:59:59.999 so the range stays inside the 24 h limit.
  return { from: y.clone().startOf("day").valueOf(), to: y.clone().endOf("day").valueOf() };
};

interface Props {
  vehicle: FleetVehicle;
  onBack: () => void;
  range?: HistoryRange;
  onLoad: (range: HistoryRange) => void;
  loading: boolean;
  error?: string;
  track?: TrackPoint[];
  summary?: TrackSummary;
  unit: SpeedUnit;
  onUnit: (unit: SpeedUnit) => void;
  layers: Layers;
  onLayers: (next: Layers) => void;
  dotFilter: DotFilter;
  onDotFilter: (next: DotFilter) => void;
  minStopMin: number;
  onMinStopMin: (minutes: number) => void;
  onJump: (index: number) => void;
}

const HistoryPanel: FC<Props> = ({
  vehicle,
  onBack,
  range,
  onLoad,
  loading,
  error,
  track,
  summary,
  unit,
  onUnit,
  layers,
  onLayers,
  dotFilter,
  onDotFilter,
  minStopMin,
  onMinStopMin,
  onJump,
}) => {
  const [preset, setPreset] = useState<Preset>("24h");
  const [custom, setCustom] = useState<[Moment, Moment] | null>(null);

  const customTooLong = !!custom && custom[1].valueOf() - custom[0].valueOf() > MAX_HISTORY_MS;

  const load = () => {
    if (preset !== "custom") return onLoad(presetRange(preset));
    if (custom && !customTooLong) onLoad({ from: custom[0].valueOf(), to: custom[1].valueOf() });
  };

  const stat = (label: string, value: React.ReactNode, color?: string) => (
    <div className="flt-stat">
      <div className="flt-stat__label">
        {color && <span className="flt-dot" style={{ background: color }} />}
        {label}
      </div>
      <div className="flt-stat__value">{value}</div>
    </div>
  );

  return (
    <div className="flt-panel">
      <div className="flt-panel__section">
        <div className="flt-panel__title">
          <Button type="text" size="small" icon={<ArrowLeftOutlined />} onClick={onBack} />
          <div>
            <div className="flt-vehicle__name">{vehicle.name}</div>
            <div className="flt-muted">Breadcrumb history</div>
          </div>
        </div>

        <div className="flt-label">Time range</div>
        <Radio.Group
          size="small"
          value={preset}
          onChange={(e) => setPreset(e.target.value)}
          className="flt-presets"
          optionType="button"
          options={[...PRESETS.map((p) => ({ value: p.id, label: p.label })), { value: "custom", label: "Custom" }]}
        />
        {preset === "custom" && (
          <>
            <DatePicker.RangePicker
              className="mt-2 w-100"
              showTime={{ format: "HH:mm" }}
              format="MMM D, HH:mm"
              value={custom as any}
              disabledDate={(d) => d.isAfter(moment().endOf("day"))}
              onChange={(v) => setCustom(v && v[0] && v[1] ? [v[0], v[1]] : null)}
            />
            {customTooLong && <div className="flt-error">Pick 24 hours or less.</div>}
          </>
        )}
        <Button
          className="mx-btn-primary mt-2 w-100"
          icon={<ReloadOutlined />}
          loading={loading}
          disabled={preset === "custom" && (!custom || customTooLong)}
          onClick={load}
        >
          {track ? "Reload track" : "Load track"}
        </Button>
        {range && (
          <div className="flt-muted mt-1">
            {moment(range.from).format("MMM D, h:mm A")} – {moment(range.to).format("MMM D, h:mm A")}
          </div>
        )}
        {error && <Alert className="mt-2" type="error" showIcon message={error} />}
      </div>

      <div className="flt-list">
        {track && track.length === 0 && (
          <Empty className="mt-4" image={Empty.PRESENTED_IMAGE_SIMPLE} description="No GPS points in this range" />
        )}

        {track && track.length > 0 && summary && (
          <>
            <div className="flt-panel__section">
              <div className="flt-stats">
                {stat("Distance", formatDistance(summary.distanceM, unit))}
                {stat("Duration", formatDuration(summary.durationMs))}
                {stat("Moving", formatDuration(summary.movingMs), SPEED_COLORS.moving)}
                {stat("Idle", formatDuration(summary.idleMs), SPEED_COLORS.idle)}
                {stat("Speeding", formatDuration(summary.speedingMs), SPEED_COLORS.speeding)}
                {stat("Max speed", formatSpeed(summary.maxSpeed, unit))}
                {stat("Avg moving", formatSpeed(summary.avgMovingSpeed, unit))}
                {stat("GPS points", track.length.toLocaleString())}
              </div>
            </div>

            <div className="flt-panel__section">
              <div className="flt-label">Map layers</div>
              <div className="flt-toggle">
                <span>Breadcrumb markers</span>
                <Switch size="small" checked={layers.dots} onChange={(dots) => onLayers({ ...layers, dots })} />
              </div>
              {layers.dots && (
                <Select<DotFilter>
                  size="small"
                  className="w-100 mb-2"
                  value={dotFilter}
                  onChange={onDotFilter}
                  options={[
                    { value: "all", label: "All points" },
                    { value: "moving", label: "Moving only" },
                    { value: "idle", label: "Idle only" },
                    { value: "speeding", label: "Speeding only" },
                  ]}
                />
              )}
              <div className="flt-toggle">
                <span>Direction arrows</span>
                <Switch size="small" checked={layers.arrows} onChange={(arrows) => onLayers({ ...layers, arrows })} />
              </div>
              <div className="flt-toggle">
                <span>Stops</span>
                <Switch size="small" checked={layers.stops} onChange={(stops) => onLayers({ ...layers, stops })} />
              </div>
              <div className="flt-toggle">
                <span>Stop longer than</span>
                <Select<number>
                  size="small"
                  style={{ width: 96 }}
                  value={minStopMin}
                  onChange={onMinStopMin}
                  options={[1, 3, 5, 10, 15, 30].map((m) => ({ value: m, label: `${m} min` }))}
                />
              </div>
              <div className="flt-toggle">
                <span>Units</span>
                <Radio.Group
                  size="small"
                  optionType="button"
                  value={unit}
                  onChange={(e) => onUnit(e.target.value)}
                  options={[
                    { value: "mph", label: "mph" },
                    { value: "kph", label: "km/h" },
                  ]}
                />
              </div>
            </div>

            <div className="flt-panel__section">
              <div className="flt-label">Stops ({summary.stops.length})</div>
              {summary.stops.length === 0 && <div className="flt-muted">No stops of {minStopMin}+ minutes</div>}
              {summary.stops.map((s: Stop, i) => (
                <div key={s.start} className="flt-stop" onClick={() => onJump(s.index)}>
                  <span className="flt-stop__badge">{i + 1}</span>
                  <div>
                    <div>
                      {moment(s.start).format("h:mm A")} – {moment(s.end).format("h:mm A")}
                    </div>
                    <div className="flt-muted">{formatDuration(s.end - s.start)}</div>
                  </div>
                </div>
              ))}
            </div>
          </>
        )}
      </div>
    </div>
  );
};

export default HistoryPanel;
