import React, { FC, useEffect, useMemo, useState } from "react";
import { Button, Form, Input } from "antd";
import type { ColumnsType } from "antd/es/table";
import { generateUUID } from "utils/appUtil";
import { pushNotification } from "utils/notifications";
import EditEquipmentModal, { EquipmentType, TYPE_NAME_MAX } from "./EditEquipmentModal";
import {
  collectionPath,
  itemPath,
  nameKey,
  useAdminItems,
  useAdminUserUpdate,
} from "../Pricing/adminCollection";
import {
  DataTableCard,
  EmptyState,
  FormModal,
  PageHeader,
  Pill,
  RowActions,
  matchesSearch,
} from "../../common/ui";
import "../Dashboard.scss";

// GetUserBio replies for the pricing collection must not be taken as equipment types.
const isPricingItem = (x: any) =>
  (Array.isArray(x?.rates) || Array.isArray(x?.locations)) && !("equipments" in x);

const itemNames = (type: EquipmentType) =>
  (type.equipments || []).map((e) => e?.name).filter(Boolean);

const EquipmentModal: FC<{
  socket: ISocket;
  params?: any;
  componentUuid?: string;
}> = ({ socket, componentUuid }) => {
  const { items, loading, status, reload, needsContainer, markContainerCreated } =
    useAdminItems<EquipmentType>(socket, "equipmentManagement", isPricingItem, componentUuid);
  const updateAdmin = useAdminUserUpdate(socket, componentUuid);
  const [search, setSearch] = useState("");
  const [editing, setEditing] = useState<EquipmentType | undefined>(undefined);
  const [creating, setCreating] = useState(false);
  const [saving, setSaving] = useState(false);
  const [createForm] = Form.useForm();

  useEffect(() => {
    document.title = "Equipment | Beam";
  }, []);

  useEffect(() => {
    reload();
  }, [reload]);

  const filtered = useMemo(
    () => items.filter((t) => matchesSearch(search, t.name, ...itemNames(t))),
    [items, search]
  );

  const openCreate = () => {
    if (status !== "ok") {
      pushNotification("Equipment is still loading, please try again", "error", "TOP_CENTER", 2000);
      return;
    }
    createForm.resetFields();
    setCreating(true);
  };

  const createType = async ({ name }: { name: string }) => {
    const id = generateUUID();
    const type: EquipmentType = { _id: id, name: name.trim(), equipments: [] };
    const changes: any[] = [];
    const addContainer = needsContainer();
    if (addContainer) {
      changes.push({ op: "add", path: collectionPath("equipmentManagement"), value: { items: {} } });
    }
    changes.push({ op: "add", path: itemPath("equipmentManagement", id), value: type });
    setSaving(true);
    try {
      const ok = await updateAdmin(changes);
      if (!ok) {
        pushNotification("Couldn't create the equipment type, please try again", "error", "TOP_CENTER", 3000);
        return;
      }
      if (addContainer) markContainerCreated();
      pushNotification("Equipment type created — now add its items", "success", "TOP_CENTER", 2000);
      setCreating(false);
      reload();
      setEditing(type);
    } finally {
      setSaving(false);
    }
  };

  const deleteType = async (type: EquipmentType) => {
    const ok = await updateAdmin([{ op: "remove", path: itemPath("equipmentManagement", type._id) }]);
    if (ok) {
      pushNotification(`"${type.name}" deleted`, "success", "TOP_CENTER", 2000);
      reload();
    } else {
      pushNotification("Couldn't delete the equipment type, please try again", "error", "TOP_CENTER", 3000);
    }
  };

  const columns: ColumnsType<EquipmentType> = useMemo(
    () => [
      {
        title: "Name",
        dataIndex: "name",
        key: "name",
        sorter: (a, b) => `${a.name || ""}`.localeCompare(`${b.name || ""}`),
        render: (name) => <strong>{name || "Untitled"}</strong>,
      },
      {
        title: "Items",
        key: "count",
        width: 120,
        render: (_, type) => {
          const count = type.equipments?.length || 0;
          return count ? (
            <Pill tone="blue" plain>
              {count} {count === 1 ? "item" : "items"}
            </Pill>
          ) : (
            <Pill tone="amber">No items</Pill>
          );
        },
      },
      {
        title: "Includes",
        key: "preview",
        render: (_, type) => {
          const names = itemNames(type);
          if (!names.length) return <span style={{ color: "#6b7a90" }}>—</span>;
          return (
            <span title={names.join(", ")}>
              {names.slice(0, 4).join(", ")}
              {names.length > 4 ? ` +${names.length - 4} more` : ""}
            </span>
          );
        },
      },
      {
        title: "",
        key: "actions",
        align: "right",
        width: 110,
        render: (_, type) => (
          <RowActions
            onEdit={() => setEditing(type)}
            onDelete={() => deleteType(type)}
            deleteConfirm={`Delete "${type.name}" and its ${type.equipments?.length || 0} items?`}
          />
        ),
      },
    ],
    // deleteType only closes over these
    // eslint-disable-next-line react-hooks/exhaustive-deps
    [updateAdmin, reload]
  );

  const emptyState =
    status === "error" ? (
      <EmptyState
        title="Couldn't load equipment"
        description={
          <Button className="mx-btn-secondary mt-2" onClick={reload}>
            Try again
          </Button>
        }
      />
    ) : search ? (
      <EmptyState title="No matching equipment" description="Try a different type or item name." />
    ) : (
      <EmptyState
        title="No equipment types yet"
        description="Group equipment (e.g. Wheelchairs, Stretchers) so dispatchers can request it."
        action={{ label: "Add equipment type", onClick: openCreate }}
      />
    );

  return (
    <React.Fragment>
      <PageHeader
        title="Equipment"
        subtitle="Equipment types and items dispatchers can request on a booking"
        search={{ value: search, onChange: setSearch, placeholder: "Search types or items" }}
        primaryAction={{ label: "Add equipment type", onClick: openCreate }}
      />

      <DataTableCard<EquipmentType>
        rowKey="_id"
        loading={loading}
        clickable
        caption={
          search
            ? `${filtered.length} of ${items.length} types`
            : `${items.length} equipment ${items.length === 1 ? "type" : "types"}`
        }
        columns={columns}
        dataSource={filtered}
        empty={emptyState}
        scroll={{ x: true }}
        onRow={(type) => ({ onClick: () => setEditing(type) })}
      />

      {editing && (
        <EditEquipmentModal
          socket={socket}
          student={editing}
          existingNames={items.filter((t) => t._id !== editing._id).map((t) => t.name)}
          onClose={() => setEditing(undefined)}
          onAdd={() => {
            setEditing(undefined);
            reload();
          }}
        />
      )}

      <FormModal
        open={creating}
        title="New equipment type"
        subtitle="Name the type. You'll add its items next."
        onCancel={() => setCreating(false)}
        onSubmit={createForm.submit}
        saving={saving}
        okText="Create type"
      >
        <Form form={createForm} layout="vertical" onFinish={createType} requiredMark={false}>
          <Form.Item
            label="Type name"
            name="name"
            validateFirst
            rules={[
              { required: true, whitespace: true, message: "Enter a name" },
              { max: TYPE_NAME_MAX, message: `Keep it under ${TYPE_NAME_MAX} characters` },
              {
                validator: (_, value) =>
                  items.some((t) => nameKey(t.name) === nameKey(value))
                    ? Promise.reject(new Error("An equipment type with this name already exists"))
                    : Promise.resolve(),
              },
            ]}
          >
            <Input placeholder="e.g. Wheelchairs" autoFocus />
          </Form.Item>
        </Form>
      </FormModal>
    </React.Fragment>
  );
};

export default EquipmentModal;
