import { useCallback, useEffect, useRef } from "react";
import { useSelector } from "react-redux";
import { RootState } from "reducers/rootReducer";
import { SocketTopics } from "constants/enums";
import {
  getIotLastIndexPublishTopic,
  getIotLastIndexSubscriptionTopic,
  getRespondersRequestPublishTopic,
  getRespondersSubscriptionTopic,
} from "hooks/MQTTConstants";
import { getGPSHistoricalData } from "services/apis/collections/oAuthApis";
import { wrapRequestPayload } from "../../../helpers/request/RequestPayload";
import { generateUUID } from "utils/appUtil";
import { parseTrack, TrackPoint } from "./fleetUtils";

const REQUEST_TIMEOUT_MS = 20000;
const ecoSystem = process.env.REACT_APP_ECO_SYSTEM;

/** Half-width of the getResponders box, in metres (School uses the same 300 km). */
export const LIVE_SEARCH_SIZE_M = 300000;

/** /getRange only accepts up to 24 h per request, as School's GPS report enforces. */
export const MAX_HISTORY_MS = 24 * 60 * 60 * 1000;

/**
 * Publish + await `<topic>/reply`, matching on the echoed request id (oldest
 * pending request when none is echoed). Resolves the reply's `response`, or
 * null on timeout.
 */
const useSocketRequest = (socket: ISocket | undefined) => {
  const pending = useRef(new Map<string, { replyTopic: string; resolve: (r: any) => void; timer: any }>());
  const subscribed = useRef(new Set<string>());
  const uuid = useRef(generateUUID()).current;

  useEffect(
    () => () => {
      pending.current.forEach((p) => {
        clearTimeout(p.timer);
        p.resolve(null);
      });
      pending.current.clear();
    },
    []
  );

  return useCallback(
    (publishTopic: string, replyTopic: string, payload: any, id: string = generateUUID()) =>
      new Promise<any | null>((resolve) => {
        if (!socket) return resolve(null);
        if (!subscribed.current.has(replyTopic)) {
          subscribed.current.add(replyTopic);
          socket.subscribeToEvent(
            SocketTopics.SubscribePageTopics,
            replyTopic,
            (message: any) => {
              let key: string | undefined = message?.id;
              if (!key || !pending.current.has(key)) {
                key = Array.from(pending.current.entries()).find(([, p]) => p.replyTopic === replyTopic)?.[0];
              }
              const entry = key ? pending.current.get(key) : undefined;
              if (!key || !entry) return;
              pending.current.delete(key);
              clearTimeout(entry.timer);
              entry.resolve(message?.response ?? message);
            },
            `${uuid}:${replyTopic}`
          );
        }
        // A newer request with the same id supersedes the older one.
        const previous = pending.current.get(id);
        if (previous) {
          clearTimeout(previous.timer);
          previous.resolve(null);
        }
        const timer = setTimeout(() => {
          pending.current.delete(id);
          resolve(null);
        }, REQUEST_TIMEOUT_MS);
        pending.current.set(id, { replyTopic, resolve, timer });
        socket.publishToEvent(SocketTopics.PublishPageTopics, publishTopic, wrapRequestPayload(payload, id));
      }),
    [socket, uuid]
  );
};

export interface LatLng {
  lat: number;
  lng: number;
}

/** Live positions: hpd-dps getResponders around `center`. Resolves null on failure. */
export const useLiveFleet = (socket: ISocket | undefined, projectId?: string) => {
  const request = useSocketRequest(socket);
  const { encrypted_token, projects } = useSelector((state: RootState) => state.auth);
  const connectionId = encrypted_token?.connectionId;

  return useCallback(
    async (center: LatLng): Promise<any[] | null> => {
      if (!connectionId) return null;
      const response = await request(
        getRespondersRequestPublishTopic(connectionId),
        getRespondersSubscriptionTopic(connectionId),
        {
          userId: encrypted_token?.userId,
          projectId,
          cudbServiceId: projects?.userServiceId,
          latLng: { lat: center.lat, long: center.lng },
          height: LIVE_SEARCH_SIZE_M,
          width: LIVE_SEARCH_SIZE_M,
        },
        // One live request in flight at a time; a newer poll replaces it.
        "fleet-live"
      );
      if (!response || response.status === false) return null;
      return response?.data?.responders ?? [];
    },
    [request, connectionId, encrypted_token?.userId, projectId, projects?.userServiceId]
  );
};

export class TrackError extends Error {}

/**
 * Historical breadcrumbs for one user, same two steps as School's GPS report:
 * getLastIndex finds the device on the user's locationGps channel, then
 * /getRange returns its samples.
 */
export const useTrackHistory = (socket: ISocket | undefined) => {
  const request = useSocketRequest(socket);
  const { encrypted_token } = useSelector((state: RootState) => state.auth);
  const connectionId = encrypted_token?.connectionId;

  return useCallback(
    async (userId: string, from: number, to: number): Promise<TrackPoint[]> => {
      if (!connectionId) throw new TrackError("Not connected yet");
      if (to <= from) throw new TrackError("End must be after start");
      if (to - from > MAX_HISTORY_MS) throw new TrackError("Pick a range of 24 hours or less");

      const index = await request(
        getIotLastIndexPublishTopic(connectionId),
        getIotLastIndexSubscriptionTopic(connectionId),
        {
          filter: `ecosystem=${ecoSystem} userId=${userId} channelName=locationGps`,
          options: { latest: false },
        },
        // School sends the user id as the request id; keep the same contract.
        userId
      );
      if (!index) throw new TrackError("The GPS service didn't respond");
      const channels = (index?.data?.channels ?? []).filter((c: any) => c?.timestamp && c?.value);
      if (!channels.length) throw new TrackError("This vehicle has no GPS device on record");

      const latest = channels.reduce((a: any, b: any) => (a.timestamp > b.timestamp ? a : b));
      const [, iotUdid, iotUserId] = `${latest.objectId ?? ""}`.split(":");
      if (!iotUdid || !iotUserId) throw new TrackError("Couldn't identify the GPS device");

      const response: any = await getGPSHistoricalData({
        filter: `ecosystem=${ecoSystem} iotUdid=${iotUdid} userId=${userId} iotUserId=${iotUserId} page=true`,
        fromTimestamp: from,
        toTimestamp: to,
        options: { withLabels: true },
      });
      if (!response || response.status === false || typeof response === "string") {
        throw new TrackError(typeof response === "string" ? response : "Couldn't load the GPS history");
      }
      return parseTrack(response?.data?.[0]?.samples);
    },
    [request, connectionId]
  );
};
