import React, { FC, useCallback, useEffect, useRef, useState } from "react";
import { Spin, Tooltip } from "antd";
import { ReactSVG } from "react-svg";
import { useDispatch, useSelector } from "react-redux";
import { useLocation } from "react-router-dom";
import { RootState } from "reducers/rootReducer";
import { DECRYPT_TOKEN } from "reducers/reducer";
import { SocketTopics } from "constants/enums";
import {
  getBrandCouponRedeemedTopic,
  getProjectsRequestPublishTopic,
  getProjectsSubscriptionTopic,
} from "hooks/MQTTConstants";
import { wrapRequestPayload } from "../../../helpers/request/RequestPayload";
import { generateUUID } from "utils/appUtil";
import { pushNotification } from "utils/notifications";
import { useCouponQueries, useCouponWrites } from "./couponApi";
import { COUPON_MENU, COUPON_MENU_ITEMS } from "./menu";
import CouponFormModal from "./CouponFormModal";
import ShareCouponModal from "./ShareCouponModal";
import CouponDetailDrawer from "./CouponDetailDrawer";
import DashboardScreen from "./screens/DashboardScreen";
import CouponsScreen from "./screens/CouponsScreen";
import RedemptionsScreen from "./screens/RedemptionsScreen";
import SettingsScreen from "./screens/SettingsScreen";
import { CouponInfo, CouponRecord } from "./types";
import "./Coupon.scss";

const SCREEN_KEY = "couponWrapperScreen";

/**
 * Brand coupon admin (`/coupon?token=…`). Like the Medical app, the token is
 * decrypted into encrypted_token, projects are requested, and every record is
 * stored under the org `projects.userServiceId`.
 */
const CouponWrapper: FC<{ socket: ISocket }> = ({ socket }) => {
  const dispatch = useDispatch();
  const { search } = useLocation();
  const { encrypted_token, projects } = useSelector((state: RootState) => state.auth);
  const orgId: string | undefined = projects?.userServiceId;
  const { loadCoupons } = useCouponQueries();
  const { createCoupon, updateCoupon, setCouponStatus } = useCouponWrites(socket);
  const uuid = useRef(generateUUID()).current;

  const [screen, setScreenState] = useState<COUPON_MENU_ITEMS>(() => {
    try {
      const saved = localStorage.getItem(SCREEN_KEY) as COUPON_MENU_ITEMS | null;
      return saved && Object.values(COUPON_MENU_ITEMS).includes(saved) ? saved : COUPON_MENU_ITEMS.Dashboard;
    } catch {
      return COUPON_MENU_ITEMS.Dashboard;
    }
  });
  const [coupons, setCoupons] = useState<CouponRecord[]>([]);
  const [loading, setLoading] = useState(false);
  const [loadFailed, setLoadFailed] = useState(false);
  const [refreshKey, setRefreshKey] = useState(0);
  const [editing, setEditing] = useState<{ open: boolean; coupon?: CouponRecord }>({ open: false });
  const [saving, setSaving] = useState(false);
  const [sharing, setSharing] = useState<CouponRecord>();
  const [openCouponId, setOpenCouponId] = useState<string>();

  const setScreen = (next: COUPON_MENU_ITEMS) => {
    setScreenState(next);
    try {
      localStorage.setItem(SCREEN_KEY, next);
    } catch {
      /* private mode */
    }
  };

  // 1. Token → encrypted_token (same as Medical RideWrapper).
  useEffect(() => {
    if (!socket.client) return;
    const query = new URLSearchParams(search);
    const token = query.get("token");
    if (token) {
      dispatch(DECRYPT_TOKEN({ data: { payload: token }, callback: () => {} }));
    } else {
      dispatch({
        type: "ADD_ENCRYPTED_TOKEN",
        payload: { connectionId: query.get("connectionId"), userId: query.get("userId") },
      });
    }
  }, [search, socket.client, dispatch]);

  // 2. encrypted_token → projects (org).
  useEffect(() => {
    if (!encrypted_token?.connectionId) return;
    socket.subscribeToEvent(SocketTopics.SubscribePageTopics, getProjectsSubscriptionTopic(encrypted_token.connectionId));
    socket.publishToEvent(
      SocketTopics.PublishPageTopics,
      getProjectsRequestPublishTopic(encrypted_token.connectionId),
      wrapRequestPayload({
        userId: encrypted_token.userId,
        cudbServiceId: encrypted_token.cudbServiceId || encrypted_token.serviceId,
      })
    );
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [encrypted_token]);

  const reload = useCallback(async () => {
    if (!orgId) return;
    setLoading(true);
    const rows = await loadCoupons();
    setLoading(false);
    setLoadFailed(!rows);
    if (rows) setCoupons(rows);
  }, [orgId, loadCoupons]);

  useEffect(() => {
    document.title = "Coupons | Beam";
    reload();
  }, [reload]);

  // 3. Live redemptions pushed by first-dps.
  useEffect(() => {
    if (!orgId) return;
    socket.subscribeToEvent(
      SocketTopics.SubscribePageTopics,
      getBrandCouponRedeemedTopic(orgId),
      (event: any) => {
        pushNotification(
          `Coupon used at ${event?.vendorName || "a store"}`,
          "success",
          "TOP_CENTER",
          2500
        );
        setRefreshKey((k) => k + 1);
        reload();
      },
      uuid
    );
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [orgId]);

  const refreshAll = () => {
    setRefreshKey((k) => k + 1);
    reload();
  };

  const save = async (info: CouponInfo) => {
    setSaving(true);
    const reply = editing.coupon ? await updateCoupon(editing.coupon.objectId, info) : await createCoupon(info);
    setSaving(false);
    if (!reply || !reply.status) {
      pushNotification("Couldn't save the coupon. Try again.", "error", "TOP_CENTER", 3000);
      return;
    }
    pushNotification(editing.coupon ? "Coupon updated" : "Coupon created", "success", "TOP_CENTER", 2000);
    setEditing({ open: false });
    // custom-bds indexes asynchronously; give it a moment before re-reading.
    setTimeout(reload, 800);
  };

  const changeStatus = async (coupon: CouponRecord, status: CouponInfo["status"]) => {
    const reply = await setCouponStatus(coupon.objectId, status);
    if (!reply || !reply.status) {
      pushNotification("Couldn't update the coupon", "error", "TOP_CENTER", 3000);
      return;
    }
    setCoupons((prev) =>
      prev.map((c) => (c.objectId === coupon.objectId ? { ...c, info: { ...c.info, status } } : c))
    );
  };

  const openCoupon = coupons.find((c) => c.objectId === openCouponId);

  const renderScreen = () => {
    switch (screen) {
      case COUPON_MENU_ITEMS.Coupons:
        return (
          <CouponsScreen
            coupons={coupons}
            loading={loading}
            loadFailed={loadFailed}
            onReload={reload}
            onCreate={() => setEditing({ open: true })}
            onEdit={(coupon) => setEditing({ open: true, coupon })}
            onShare={setSharing}
            onOpen={(c) => setOpenCouponId(c.objectId)}
            onStatus={changeStatus}
          />
        );
      case COUPON_MENU_ITEMS.Redemptions:
        return <RedemptionsScreen coupons={coupons} refreshKey={refreshKey} />;
      case COUPON_MENU_ITEMS.Settings:
        return <SettingsScreen socket={socket} />;
      default:
        return (
          <DashboardScreen
            coupons={coupons}
            loading={loading}
            refreshKey={refreshKey}
            onReload={refreshAll}
            onOpenCoupon={(c) => setOpenCouponId(c.objectId)}
            onCreate={() => setEditing({ open: true })}
          />
        );
    }
  };

  return (
    <div className="cpn-shell">
      <div className="cpn-shell__header">
        <img src="https://media.staging.beam.live/109220_original.png" alt="Beam" />
        <span className="cpn-shell__title">Coupons</span>
      </div>
      <div className="cpn-shell__body">
        <div className="cpn-shell__rail">
          <div className="main-column search-panel cpn-rail">
            <div className="sidebar" style={{ borderRadius: 0 }}>
              <ul>
                {COUPON_MENU.map((item) => (
                  <Tooltip key={item.id} title={item.hint} placement="right" mouseEnterDelay={0.4}>
                    <li className={screen === item.id ? "selected" : ""} onClick={() => setScreen(item.id)}>
                      <div>
                        <div>
                          <ReactSVG src={item.src} />
                          <p>{item.label}</p>
                        </div>
                      </div>
                    </li>
                  </Tooltip>
                ))}
              </ul>
            </div>
          </div>
        </div>
        <div className="cpn-shell__content">
          {orgId ? (
            renderScreen()
          ) : (
            <div className="cpn-shell__loading">
              <Spin />
              <span>Loading your organization…</span>
            </div>
          )}
        </div>
      </div>

      <CouponFormModal
        open={editing.open}
        coupon={editing.coupon}
        saving={saving}
        onCancel={() => setEditing({ open: false })}
        onSave={save}
      />
      <ShareCouponModal
        socket={socket}
        coupon={sharing}
        open={!!sharing}
        onClose={(changed) => {
          setSharing(undefined);
          if (changed) refreshAll();
        }}
      />
      <CouponDetailDrawer
        socket={socket}
        coupon={openCoupon}
        open={!!openCoupon}
        refreshKey={refreshKey}
        onClose={() => setOpenCouponId(undefined)}
        onShare={setSharing}
      />
    </div>
  );
};

export default CouponWrapper;
