import React, { FC } from "react";
import { Button, Dropdown, Menu, Table, Tag, Tooltip } from "antd";
import { ColumnsType } from "antd/lib/table";
import {
  CreditCardOutlined,
  FileTextOutlined,
  FlagOutlined,
  MoreOutlined,
} from "@ant-design/icons";

import { LedgerAction, LedgerRow } from "./types";
import { agingBucketOf, formatMoney } from "./selectors";

const ADJUSTMENT_COLORS: Record<string, string> = {
  scholarship: "purple",
  sibling: "cyan",
  promo: "green",
  earlybird: "blue",
  waiver: "magenta",
};

const ACTION_ITEMS: { key: LedgerAction; label: string }[] = [
  { key: "flags", label: "View Flags" },
  { key: "refund", label: "Refund" },
  { key: "schedule", label: "Schedule (CFO override)" },
  { key: "discount", label: "Discount / Aid" },
  { key: "cancel", label: "Cancel" },
  { key: "notify", label: "Notify" },
];

interface Props {
  rows: LedgerRow[];
  currency: string;
  /** Pass both to get row checkboxes; the dashboard passes neither. */
  selectedKeys?: React.Key[];
  onSelectionChange?: (keys: React.Key[]) => void;
  onRowAction: (action: LedgerAction, row: LedgerRow) => void;
  /** Row the alert centre asked to highlight. */
  highlightKey: string | null;
}

/**
 * The unified CFO ledger grid. Every line carries both its financial
 * metadata and the relational context needed to act on it, and six
 * executive actions are available per row.
 */
const LedgerGrid: FC<Props> = ({
  rows,
  currency,
  selectedKeys,
  onSelectionChange,
  onRowAction,
  highlightKey,
}) => {
  const money = (value: number) => formatMoney(value, currency);

  const columns: ColumnsType<LedgerRow> = [
    {
      title: "Project / Event",
      dataIndex: "project",
      key: "project",
      fixed: "left",
      width: 190,
      render: (_: string, row) => (
        <div className="cfo-cell">
          <div className="cfo-cell__main">{row.project}</div>
          <div className="cfo-cell__sub">{row.projectKind}</div>
        </div>
      ),
    },
    {
      title: "Entity / Person",
      dataIndex: "entity",
      key: "entity",
      width: 180,
      render: (_: string, row) => (
        <div className="cfo-cell">
          <div className="cfo-cell__main">{row.entity}</div>
          <div className="cfo-cell__sub">
            {row.entityRole}
            <Tag
              className="cfo-side-tag"
              color={row.side === "ar" ? "geekblue" : "orange"}
            >
              {row.side.toUpperCase()}
            </Tag>
          </div>
        </div>
      ),
    },
    {
      title: "Service Fee",
      dataIndex: "serviceFee",
      key: "serviceFee",
      align: "right",
      width: 130,
      sorter: (a, b) => a.serviceFee - b.serviceFee,
      render: (value: number, row) => (
        <div className="cfo-cell cfo-cell--right">
          <div className="cfo-cell__main">{money(value)}</div>
          <div className="cfo-cell__sub">{row.cadence}</div>
        </div>
      ),
    },
    {
      title: "Adjustments",
      dataIndex: "adjustments",
      key: "adjustments",
      width: 210,
      render: (_: unknown, row) => {
        if (row.adjustments.length === 0) {
          return <span className="cfo-muted">-</span>;
        }
        const total = row.adjustments.reduce((acc, a) => acc + a.amount, 0);
        return (
          <div className="cfo-cell">
            <div className="cfo-adjustments">
              {row.adjustments.map((adjustment) => (
                <Tooltip
                  key={adjustment.label}
                  title={`${adjustment.label}: -${money(adjustment.amount)}`}
                >
                  <Tag color={ADJUSTMENT_COLORS[adjustment.type]}>
                    {adjustment.label}
                  </Tag>
                </Tooltip>
              ))}
            </div>
            <div className="cfo-cell__sub">-{money(total)}</div>
          </div>
        );
      },
    },
    {
      title: "Invoiced Service Fee",
      dataIndex: "invoicedServiceFee",
      key: "invoicedServiceFee",
      align: "right",
      width: 150,
      sorter: (a, b) => a.invoicedServiceFee - b.invoicedServiceFee,
      render: (value: number) => <strong>{money(value)}</strong>,
    },
    {
      title: "Form & Method",
      key: "form",
      width: 150,
      render: (_: unknown, row) => (
        <div className="cfo-cell">
          <div className="cfo-cell__main">
            {row.form === "card" ? (
              <>
                <CreditCardOutlined /> Credit Card
              </>
            ) : (
              <>
                <FileTextOutlined /> Invoice (CPC)
              </>
            )}
          </div>
          <div className="cfo-cell__sub">{row.method}</div>
        </div>
      ),
    },
    {
      title: "Invoice ID",
      dataIndex: "invoiceId",
      key: "invoiceId",
      width: 210,
      render: (value: string) => <code className="cfo-invoice-id">{value}</code>,
    },
    {
      title: "Collected",
      dataIndex: "collected",
      key: "collected",
      align: "right",
      width: 125,
      sorter: (a, b) => a.collected - b.collected,
      render: (value: number) => (
        <span className={value > 0 ? "cfo-amount--in" : "cfo-muted"}>
          {money(value)}
        </span>
      ),
    },
    {
      title: "Outstanding",
      dataIndex: "outstanding",
      key: "outstanding",
      align: "right",
      width: 125,
      sorter: (a, b) => a.outstanding - b.outstanding,
      render: (value: number) =>
        value > 0 ? money(value) : <span className="cfo-muted">-</span>,
    },
    {
      title: "Past Due",
      dataIndex: "pastDue",
      key: "pastDue",
      align: "right",
      width: 150,
      sorter: (a, b) => a.pastDue - b.pastDue,
      render: (value: number, row) => {
        if (value <= 0) return <span className="cfo-muted">-</span>;
        return (
          <div className="cfo-cell cfo-cell--right">
            <div className="cfo-amount--due">{money(value)}</div>
            <div className="cfo-cell__sub">
              <Tag color="volcano">T+{row.pastDueHours}h</Tag>
            </div>
          </div>
        );
      },
    },
    {
      title: "Refunds",
      dataIndex: "refund",
      key: "refund",
      align: "right",
      width: 150,
      render: (_: unknown, row) => {
        if (!row.refund) return <span className="cfo-muted">-</span>;
        return (
          <Tooltip
            title={`Reason: ${row.refund.reason}. Retained processing fee ${money(
              row.refund.retainedFee
            )}.`}
          >
            <div className="cfo-cell cfo-cell--right">
              <div className="cfo-amount--out">{money(row.refund.amount)}</div>
              <div className="cfo-cell__sub">{row.refund.reason}</div>
            </div>
          </Tooltip>
        );
      },
    },
    {
      title: "Flags",
      key: "flags",
      width: 120,
      render: (_: unknown, row) =>
        row.flags.length === 0 ? (
          <span className="cfo-muted">-</span>
        ) : (
          <Tooltip
            title={row.flags.map((flag) => flag.note).join(" / ")}
          >
            <Button
              size="small"
              type="text"
              icon={<FlagOutlined />}
              onClick={() => onRowAction("flags", row)}
            >
              {row.flags.length}
            </Button>
          </Tooltip>
        ),
    },
    {
      title: "",
      key: "actions",
      fixed: "right",
      width: 56,
      render: (_: unknown, row) => (
        <Dropdown
          trigger={["click"]}
          overlay={
            <Menu
              onClick={({ key }) => onRowAction(key as LedgerAction, row)}
              items={ACTION_ITEMS.map((item) => ({
                key: item.key,
                label: item.label,
                danger: item.key === "cancel",
              }))}
            />
          }
        >
          <Button type="text" icon={<MoreOutlined />} />
        </Dropdown>
      ),
    },
  ];

  /**
   * Derived, not hard-coded: the widths below add up to more than the
   * 1900px this used to declare, and antd lays fixed columns out against
   * `scroll.x`. Under-declaring it drifts the left and right fixed
   * columns out of line with the body, which is why rows looked wrong.
   * Adding a column can no longer break the alignment.
   */
  const selectable = !!selectedKeys && !!onSelectionChange;
  const SELECTION_COLUMN_WIDTH = selectable ? 60 : 0;
  const tableWidth =
    columns.reduce(
      (total, column) => total + (Number(column.width) || 0),
      0
    ) + SELECTION_COLUMN_WIDTH;
  /* The summary row counts cells from the left; a selection column shifts them by one. */
  const offset = selectable ? 1 : 0;

  return (
    <Table<LedgerRow>
      className="cfo-ledger"
      rowKey="key"
      columns={columns}
      dataSource={rows}
      scroll={{ x: tableWidth }}
      pagination={{ pageSize: 10, showSizeChanger: false }}
      rowSelection={
        selectable
          ? { selectedRowKeys: selectedKeys, onChange: onSelectionChange }
          : undefined
      }
      rowClassName={(row) => {
        const classes = [`cfo-row--${agingBucketOf(row)}`];
        if (row.key === highlightKey) classes.push("row-selected");
        return classes.join(" ");
      }}
      summary={(pageRows) => {
        const totals = pageRows.reduce(
          (acc, row) => ({
            invoiced: acc.invoiced + row.invoicedServiceFee,
            collected: acc.collected + row.collected,
            outstanding: acc.outstanding + row.outstanding,
            pastDue: acc.pastDue + row.pastDue,
          }),
          { invoiced: 0, collected: 0, outstanding: 0, pastDue: 0 }
        );

        return (
          <Table.Summary fixed>
            <Table.Summary.Row className="cfo-ledger__summary">
              <Table.Summary.Cell index={0} colSpan={4 + offset}>
                Page total
              </Table.Summary.Cell>
              <Table.Summary.Cell index={4 + offset} align="right">
                {money(totals.invoiced)}
              </Table.Summary.Cell>
              <Table.Summary.Cell index={5 + offset} colSpan={2} />
              <Table.Summary.Cell index={7 + offset} align="right">
                {money(totals.collected)}
              </Table.Summary.Cell>
              <Table.Summary.Cell index={8 + offset} align="right">
                {money(totals.outstanding)}
              </Table.Summary.Cell>
              <Table.Summary.Cell index={9 + offset} align="right">
                {money(totals.pastDue)}
              </Table.Summary.Cell>
              <Table.Summary.Cell index={10 + offset} colSpan={3} />
            </Table.Summary.Row>
          </Table.Summary>
        );
      }}
    />
  );
};

export default LedgerGrid;
