/*global google*/
import React, { useEffect, useMemo, useRef, useState } from "react";
import { GoogleMap, InfoWindow, Marker, Polyline, withGoogleMap, withScriptjs } from "react-google-maps";
import { MAP } from "react-google-maps/lib/constants";
import { compose, withProps } from "recompose";
import moment from "moment";
import {
  FleetVehicle,
  formatSpeed,
  SPEED_COLORS,
  SpeedBand,
  speedBand,
  segmentsBySpeed,
  SpeedUnit,
  statusMeta,
  Stop,
  TrackPoint,
} from "./fleetUtils";

export type DotFilter = "all" | SpeedBand;

export interface FleetMapProps {
  vehicles: FleetVehicle[];
  selectedId?: string;
  onSelect: (id: string | undefined) => void;
  track?: TrackPoint[];
  stops?: Stop[];
  showDots: boolean;
  showStops: boolean;
  showArrows: boolean;
  dotFilter: DotFilter;
  playbackIndex?: number;
  unit: SpeedUnit;
  /** Bump to fit the map to the track (when shown) or the vehicles. */
  fitKey: number;
  /** Bump `key` to pan to a point. */
  focus?: { lat: number; lng: number; key: number };
  /** Bump `key` to fit a searched place's viewport (google.maps.LatLngBounds). */
  viewport?: { bounds: any; key: number };
  defaultCenter: { lat: number; lng: number };
  onCenterChanged: (center: { lat: number; lng: number }) => void;
}

/**
 * Breadcrumb markers are drawn only for points inside the viewport, and only
 * once zoomed in far enough that at most this many are visible (the School
 * map uses the same 200 cut-off). Zoomed out, the line alone shows the track.
 */
const MAX_MARKERS_IN_VIEW = 200;

const MAP_STYLES = [
  { featureType: "poi", stylers: [{ visibility: "off" }] },
  { featureType: "transit", stylers: [{ visibility: "off" }] },
];

/**
 * GPS breadcrumb arrow as the SchoolBus map draws it: solid in the speed
 * colour, rotated by the raw headingGps (0 = north). School's own
 * createPeopleMarker subtracts 180°, which points the arrows backwards.
 * `playback` is the larger blue arrow marking the replay position.
 */
const gpsArrowIcon = (p: TrackPoint, playback = false) => {
  const color = SPEED_COLORS[speedBand(p.speed)];
  return {
    path: google.maps.SymbolPath.FORWARD_CLOSED_ARROW,
    scale: playback ? 8 : 6,
    rotation: p.heading,
    fillColor: playback ? "#4682f4" : color,
    fillOpacity: 1,
    strokeColor: playback ? "#ffffff" : color,
    strokeWeight: playback ? 2 : 1,
  };
};

const FleetMapInner = ({
  vehicles,
  selectedId,
  onSelect,
  track,
  stops,
  showDots,
  showStops,
  showArrows,
  dotFilter,
  playbackIndex,
  unit,
  fitKey,
  focus,
  viewport,
  defaultCenter,
  onCenterChanged,
}: FleetMapProps) => {
  const mapRef = useRef<any>(null);
  const idleTimer = useRef<any>();
  const [info, setInfo] = useState<{ key: string; lat: number; lng: number; body: React.ReactNode }>();
  /** Current viewport, updated when the map settles after a pan or zoom. */
  const [bounds, setBounds] = useState<any>();
  const hasTrack = !!track && track.length > 0;

  useEffect(() => () => clearTimeout(idleTimer.current), []);

  // Fit on request only, so live refreshes never yank the viewport around.
  useEffect(() => {
    if (!mapRef.current) return;
    const bounds = new google.maps.LatLngBounds();
    if (hasTrack) {
      track!.forEach((p) => bounds.extend({ lat: p.lat, lng: p.lng }));
    } else {
      vehicles.forEach((v) => bounds.extend({ lat: v.lat!, lng: v.lng! }));
    }
    if (bounds.isEmpty()) return;
    mapRef.current.fitBounds(bounds);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [fitKey]);

  useEffect(() => {
    if (focus && mapRef.current) {
      mapRef.current.panTo({ lat: focus.lat, lng: focus.lng });
      if (mapRef.current.getZoom() < 15) mapRef.current.context[MAP].setZoom(16);
    }
  }, [focus?.key]); // eslint-disable-line react-hooks/exhaustive-deps

  useEffect(() => {
    if (viewport && mapRef.current) mapRef.current.fitBounds(viewport.bounds);
  }, [viewport?.key]); // eslint-disable-line react-hooks/exhaustive-deps

  useEffect(() => setInfo(undefined), [track]);

  const segments = useMemo(() => (track ? segmentsBySpeed(track) : []), [track]);

  const dots = useMemo(() => {
    if (!track || !showDots || !bounds) return [];
    const inView: { p: TrackPoint; i: number }[] = [];
    for (let i = 0; i < track.length; i += 1) {
      const p = track[i];
      if (dotFilter !== "all" && speedBand(p.speed) !== dotFilter) continue;
      if (!bounds.contains({ lat: p.lat, lng: p.lng })) continue;
      inView.push({ p, i });
      // Too many to draw: zoomed out, show the line only.
      if (inView.length > MAX_MARKERS_IN_VIEW) return [];
    }
    return inView;
  }, [track, showDots, dotFilter, bounds]);

  const arrowIcons = showArrows
    ? [
        {
          icon: { path: google.maps.SymbolPath.FORWARD_OPEN_ARROW, scale: 2, strokeColor: "#1d2433", strokeWeight: 1.5 },
          repeat: "110px",
          offset: "60px",
        },
      ]
    : [];

  const head = hasTrack && playbackIndex !== undefined ? track![Math.min(playbackIndex, track!.length - 1)] : undefined;

  const pointInfo = (p: TrackPoint) => (
    <div className="flt-info">
      <strong>{moment(p.t).format("MMM D, h:mm:ss A")}</strong>
      <div>
        {formatSpeed(p.speed, unit)} · heading {Math.round(p.heading)}°
      </div>
      <div className="flt-muted">
        {p.lat.toFixed(5)}, {p.lng.toFixed(5)}
      </div>
    </div>
  );

  return (
    <GoogleMap
      ref={mapRef}
      defaultZoom={12}
      defaultCenter={defaultCenter}
      options={{ maxZoom: 20, styles: MAP_STYLES, fullscreenControl: false, streetViewControl: false }}
      onClick={() => setInfo(undefined)}
      onIdle={() => {
        clearTimeout(idleTimer.current);
        idleTimer.current = setTimeout(() => {
          const c = mapRef.current?.getCenter();
          if (c) onCenterChanged({ lat: c.lat(), lng: c.lng() });
          setBounds(mapRef.current?.getBounds());
        }, 300);
      }}
    >
      {/* Live vehicles. Dimmed while a track is on screen. */}
      {vehicles.map((v) => {
        const selected = v.id === selectedId;
        return (
          <Marker
            key={v.id}
            position={{ lat: v.lat!, lng: v.lng! }}
            opacity={hasTrack && !selected ? 0.35 : 1}
            zIndex={selected ? 1000 : undefined}
            icon={{
              url: `/images/car-${selected ? "blue" : statusMeta(v.status).tone}.svg`,
              scaledSize: new google.maps.Size(selected ? 56 : 44, selected ? 56 : 44),
              anchor: new google.maps.Point(selected ? 28 : 22, selected ? 28 : 22),
            }}
            title={v.name}
            onClick={() => onSelect(selected ? undefined : v.id)}
          />
        );
      })}

      {/* Historical breadcrumbs, coloured by speed band. */}
      {segments.map((s, i) => (
        <Polyline
          key={`seg-${i}`}
          path={s.path}
          options={{
            strokeColor: SPEED_COLORS[s.band],
            strokeOpacity: 0.9,
            strokeWeight: 5,
            icons: arrowIcons,
            zIndex: 10,
          }}
        />
      ))}

      {dots.map(({ p, i }) => (
        <Marker
          key={`dot-${i}`}
          position={{ lat: p.lat, lng: p.lng }}
          zIndex={20}
          icon={gpsArrowIcon(p)}
          onClick={() => setInfo({ key: `dot-${i}`, lat: p.lat, lng: p.lng, body: pointInfo(p) })}
        />
      ))}

      {showStops &&
        stops?.map((s, i) => (
          <Marker
            key={`stop-${s.start}`}
            position={{ lat: s.lat, lng: s.lng }}
            zIndex={30}
            label={{ text: "P", color: "#ffffff", fontSize: "11px", fontWeight: "700" }}
            icon={{
              path: google.maps.SymbolPath.CIRCLE,
              scale: 9,
              fillColor: "#463bbd",
              fillOpacity: 1,
              strokeColor: "#ffffff",
              strokeWeight: 2,
            }}
            onClick={() =>
              setInfo({
                key: `stop-${s.start}`,
                lat: s.lat,
                lng: s.lng,
                body: (
                  <div className="flt-info">
                    <strong>Stop {i + 1}</strong>
                    <div>
                      {moment(s.start).format("h:mm A")} – {moment(s.end).format("h:mm A")}
                    </div>
                    <div className="flt-muted">{moment.duration(s.end - s.start).humanize()}</div>
                  </div>
                ),
              })
            }
          />
        ))}

      {hasTrack && (
        <>
          <Marker
            position={{ lat: track![0].lat, lng: track![0].lng }}
            zIndex={40}
            label={{ text: "A", color: "#ffffff", fontSize: "12px", fontWeight: "700" }}
            icon={{
              path: google.maps.SymbolPath.CIRCLE,
              scale: 11,
              fillColor: "#40CC52",
              fillOpacity: 1,
              strokeColor: "#ffffff",
              strokeWeight: 2,
            }}
            onClick={() => setInfo({ key: "start", lat: track![0].lat, lng: track![0].lng, body: pointInfo(track![0]) })}
          />
          <Marker
            position={{ lat: track![track!.length - 1].lat, lng: track![track!.length - 1].lng }}
            zIndex={40}
            label={{ text: "B", color: "#ffffff", fontSize: "12px", fontWeight: "700" }}
            icon={{
              path: google.maps.SymbolPath.CIRCLE,
              scale: 11,
              fillColor: "#e5484d",
              fillOpacity: 1,
              strokeColor: "#ffffff",
              strokeWeight: 2,
            }}
            onClick={() => {
              const last = track![track!.length - 1];
              setInfo({ key: "end", lat: last.lat, lng: last.lng, body: pointInfo(last) });
            }}
          />
        </>
      )}

      {head && (
        <Marker
          position={{ lat: head.lat, lng: head.lng }}
          zIndex={50}
          icon={gpsArrowIcon(head, true)}
          onClick={() => setInfo({ key: "head", lat: head.lat, lng: head.lng, body: pointInfo(head) })}
        />
      )}

      {info && (
        <InfoWindow position={{ lat: info.lat, lng: info.lng }} onCloseClick={() => setInfo(undefined)}>
          {info.body}
        </InfoWindow>
      )}
    </GoogleMap>
  );
};

const FleetMap = compose<FleetMapProps, FleetMapProps>(
  withProps({
    googleMapURL:
      "https://maps.googleapis.com/maps/api/js?key=AIzaSyDgNagv_ozKWc6IQ75Ol4cH8fxdntOaW6M&v=3.exp&libraries=geometry,drawing,places",
    loadingElement: <div style={{ height: "100%" }} />,
    containerElement: <div style={{ height: "100%" }} />,
    mapElement: <div style={{ height: "100%" }} />,
  }),
  withScriptjs,
  withGoogleMap
)(FleetMapInner as any);

export default FleetMap;
