import moment from "moment";
import { CouponInfo, CouponStats } from "./types";

// Display copy of first-dps src/dps/coupon/coupon.rules.ts. The backend is the
// authority at redemption time; keep the two in sync.

export const EMPTY_STATS: CouponStats = { issued: 0, sent: 0, redeemed: 0, discountTotal: 0 };

const isSet = (n: unknown): n is number => typeof n === "number" && Number.isFinite(n);

export const round2 = (n: number) => Math.round(n * 100) / 100;

export const computeDiscount = (info: CouponInfo, billAmount?: number | null): number | null => {
  const hasBill = isSet(billAmount) && billAmount > 0;
  if (info.discountType === "fixed") {
    return round2(hasBill ? Math.min(info.discountValue, billAmount as number) : info.discountValue);
  }
  if (!hasBill) return null;
  const raw = ((billAmount as number) * info.discountValue) / 100;
  const capped =
    isSet(info.maxDiscountAmount) && info.maxDiscountAmount > 0 ? Math.min(raw, info.maxDiscountAmount) : raw;
  return round2(capped);
};

export const formatMoney = (amount: number | null | undefined, currency?: string) => {
  if (!isSet(amount)) return "—";
  try {
    return new Intl.NumberFormat(undefined, {
      style: "currency",
      currency: currency || "USD",
      maximumFractionDigits: 2,
    }).format(amount);
  } catch {
    return `${amount.toFixed(2)} ${currency || ""}`.trim();
  }
};

/** "20% OFF" / "$5 OFF". */
export const discountHeadline = (info: Pick<CouponInfo, "discountType" | "discountValue" | "currency">) =>
  info.discountType === "percentage"
    ? `${info.discountValue ?? 0}% OFF`
    : `${formatMoney(info.discountValue ?? 0, info.currency)} OFF`;

/** One line per condition: minimum, cap, usage, validity. */
export const conditionLines = (info: CouponInfo): string[] => {
  const lines: string[] = [];
  if (isSet(info.minPurchaseAmount) && info.minPurchaseAmount > 0) {
    lines.push(`Minimum purchase ${formatMoney(info.minPurchaseAmount, info.currency)}`);
  }
  if (info.discountType === "percentage" && isSet(info.maxDiscountAmount) && info.maxDiscountAmount > 0) {
    lines.push(`Up to ${formatMoney(info.maxDiscountAmount, info.currency)} off`);
  }
  if (info.usageType === "single") lines.push("One-time use");
  else if (isSet(info.maxUsesPerCode) && info.maxUsesPerCode > 0) lines.push(`Use up to ${info.maxUsesPerCode} times`);
  else lines.push("Use multiple times");
  const validity = validityLabel(info);
  if (validity) lines.push(validity);
  return lines;
};

export const validityLabel = (info: Pick<CouponInfo, "validFrom" | "validUntil">) => {
  const fmt = (ts: number) => moment(ts).format("MMM D, YYYY");
  if (isSet(info.validFrom) && isSet(info.validUntil)) return `Valid ${fmt(info.validFrom)} – ${fmt(info.validUntil)}`;
  if (isSet(info.validUntil)) return `Valid until ${fmt(info.validUntil)}`;
  if (isSet(info.validFrom)) return `Valid from ${fmt(info.validFrom)}`;
  return "";
};

export type CouponLifecycle = "active" | "scheduled" | "expired" | "paused" | "archived" | "exhausted";

export const lifecycle = (info: CouponInfo, stats: CouponStats, now = Date.now()): CouponLifecycle => {
  if (info.status === "archived") return "archived";
  if (info.status === "paused") return "paused";
  if (isSet(info.validUntil) && now > info.validUntil) return "expired";
  if (isSet(info.totalRedemptionLimit) && info.totalRedemptionLimit > 0 && stats.redeemed >= info.totalRedemptionLimit) {
    return "exhausted";
  }
  if (isSet(info.validFrom) && now < info.validFrom) return "scheduled";
  return "active";
};
