import React, { FC, useCallback, useEffect, useMemo, useRef, useState } from "react";
import { Button } from "antd";
import type { ColumnsType } from "antd/es/table";
import { useDispatch, useSelector } from "react-redux";
import { RootState } from "reducers/rootReducer";
import { formatForRedis } from "utils/appUtil";
import { PERMISSION_TYPES } from "utils/PageTypes";
import { pushNotification } from "utils/notifications";
import { GET_AGGREGATE } from "../../../../../reducers/reducer";
import {
  DataTableCard,
  EmptyState,
  PageHeader,
  Pill,
  RowActions,
  matchesSearch,
} from "../../common/ui";
import EditSchedulerModal from "./EditSchedulerModal";
import {
  CHANNELS,
  Channel,
  NotificationRecord,
  describeSchedule,
  useScheduleApi,
} from "./notificationUtils";
import "../Dashboard.scss";
import "./Scheduler.scss";

// GET_AGGREGATE's saga never calls back on failure.
const LOAD_TIMEOUT_MS = 15000;
const RECIPIENTS_SHOWN = 3;

interface NotificationRow {
  key: string;
  name: string;
  channel?: Channel;
  schedule: string;
  timezone?: string;
  recipients: string[];
  record: NotificationRecord;
}

// Responders: can take jobs (OnMove) and are not admins.
const isResponderRole = (role: any) => {
  const p: string[] = role?.permissions || [];
  return p.includes(PERMISSION_TYPES.OnMove) && !p.includes(PERMISSION_TYPES.Admin);
};

const Recipients = ({ names }: { names: string[] }) => {
  if (!names.length) return <Pill tone="amber">No drivers</Pill>;
  const extra = names.length - RECIPIENTS_SHOWN;
  return (
    <span title={names.join(", ")}>
      {names.slice(0, RECIPIENTS_SHOWN).join(", ")}
      {extra > 0 && (
        <span className="mx-notifications__more">
          <Pill tone="gray" plain>
            +{extra}
          </Pill>
        </span>
      )}
    </span>
  );
};

const DATA_COLUMNS: ColumnsType<NotificationRow> = [
  {
    title: "Name",
    dataIndex: "name",
    key: "name",
    sorter: (a, b) => a.name.localeCompare(b.name),
    render: (name: string) => <strong>{name || "Untitled"}</strong>,
  },
  {
    title: "Channel",
    dataIndex: "channel",
    key: "channel",
    render: (channel?: Channel) =>
      channel && CHANNELS[channel] ? (
        <Pill tone={CHANNELS[channel].tone} plain>
          {CHANNELS[channel].label}
        </Pill>
      ) : (
        <Pill tone="gray">Unknown</Pill>
      ),
  },
  {
    title: "Schedule",
    key: "schedule",
    render: (_, r) => {
      const zone = Intl.DateTimeFormat().resolvedOptions().timeZone;
      return (
        <div>
          <div>{r.schedule}</div>
          {r.timezone && r.timezone !== zone && (
            <div className="mx-notifications__sub">{r.timezone} time</div>
          )}
        </div>
      );
    },
  },
  {
    title: "Recipients",
    key: "recipients",
    sorter: (a, b) => a.recipients.length - b.recipients.length,
    render: (_, r) => <Recipients names={r.recipients} />,
  },
];

/** "Notification" in the sidebar: recurring reminder notifications to drivers. */
const SchedulerModal: FC<{
  socket: ISocket;
  params?: any;
  componentUuid?: string;
}> = ({ socket }) => {
  const { projects, adminUserRoles } = useSelector((state: RootState) => state.auth);
  const dispatch = useDispatch();
  const { deleteSchedule } = useScheduleApi();

  const [records, setRecords] = useState<NotificationRecord[]>([]);
  const [loading, setLoading] = useState(false);
  const [loadFailed, setLoadFailed] = useState(false);
  const [search, setSearch] = useState("");
  const [driverNames, setDriverNames] = useState<Record<string, string>>({});
  // undefined = closed, {} = creating, record = editing
  const [editing, setEditing] = useState<Partial<NotificationRecord> | undefined>(undefined);

  const mounted = useRef(true);
  const requestSeq = useRef(0);
  const loadTimer = useRef<any>();

  useEffect(() => {
    document.title = "Notifications | Beam";
    mounted.current = true;
    return () => {
      mounted.current = false;
      clearTimeout(loadTimer.current);
    };
  }, []);

  const load = useCallback(() => {
    const seq = ++requestSeq.current;
    const request: any = {
      select: {
        index: {
          searchIndex: `${process.env.REACT_APP_ECO_SYSTEM}:schedule:status`,
          searchQuery: `@partitions:{'org\\:${formatForRedis(
            projects?.userServiceId
          )}}@partitions:{type\\:notification}`,
          searchOptions: "TIMEOUT 5000",
        },
        load: {
          id: "$.objectId",
          data: "$.data",
        },
      },
      apply: { expression: "", name: "" },
      result: {},
      filter: { expression: "" },
      anyStatus: false,
    };
    setLoading(true);
    clearTimeout(loadTimer.current);
    loadTimer.current = setTimeout(() => {
      if (!mounted.current || seq !== requestSeq.current) return;
      setLoading(false);
      setLoadFailed(true);
    }, LOAD_TIMEOUT_MS);
    dispatch(
      GET_AGGREGATE({
        requestData: request,
        callback: (response) => {
          // Ignore replies to superseded requests.
          if (!mounted.current || seq !== requestSeq.current) return;
          clearTimeout(loadTimer.current);
          setLoading(false);
          setLoadFailed(false);
          setRecords(
            (Array.isArray(response) ? response : [])
              .filter((x) => x?.id !== undefined)
              .map((x) => ({ scheduleId: `${x.id}`, data: x?.data || {} }))
          );
        },
      })
    );
  }, [dispatch, projects?.userServiceId]);

  // Driver display names; rows fall back to the stored beamId without them.
  const loadDriverNames = useCallback(
    (roles: any[]) => {
      const rolesQuery = (roles || [])
        .filter(isResponderRole)
        .map((y: any) => `@roleId === '${y._id}'`);
      if (!rolesQuery.length) return;
      dispatch(
        GET_AGGREGATE({
          requestData: {
            select: {
              index: {
                searchIndex: `${process.env.REACT_APP_ECO_SYSTEM}:userNameIndex`,
                searchQuery: `@serviceId:{'${formatForRedis(projects?.userServiceId)}'}`,
                searchOptions: "TIMEOUT 5000",
              },
              load: {
                id: "$.objectId",
                live: "$.persistent.static.live",
                roleId: "$..admin.profile.roleId",
              },
            },
            apply: { expression: "", name: "" },
            result: {},
            filter: { expression: `exists(@roleId) && (${rolesQuery.join("||")})` },
            anyStatus: false,
          },
          callback: (response) => {
            if (!mounted.current) return;
            const names: Record<string, string> = {};
            (Array.isArray(response) ? response : []).forEach((x) => {
              const { firstName, lastName } = x?.live?.profile || {};
              const name = [firstName, lastName].filter(Boolean).join(" ");
              if (x?.id !== undefined && name) names[`${x.id}`] = name;
            });
            setDriverNames(names);
          },
        })
      );
    },
    [dispatch, projects?.userServiceId]
  );

  useEffect(() => {
    if (projects?.adminUserId) load();
  }, [projects?.adminUserId, load]);

  useEffect(() => {
    if (projects?.adminUserId && adminUserRoles) loadDriverNames(adminUserRoles);
  }, [projects?.adminUserId, adminUserRoles, loadDriverNames]);

  const rows: NotificationRow[] = useMemo(
    () =>
      records
        .map((record) => {
          const { data } = record;
          return {
            key: record.scheduleId,
            name: data.name || "",
            channel: data.notificationType,
            schedule: describeSchedule(data),
            timezone: data.timezone,
            recipients: Object.values(data.drivers || {}).map(
              (d: any) => driverNames[`${d?.userId}`] || d?.beamId || "Unknown driver"
            ),
            record,
          };
        })
        .sort((a, b) => a.name.localeCompare(b.name)),
    [records, driverNames]
  );

  const filtered = useMemo(
    () =>
      rows.filter((r) =>
        matchesSearch(
          search,
          r.name,
          r.channel && CHANNELS[r.channel]?.label,
          r.schedule,
          ...r.recipients
        )
      ),
    [rows, search]
  );

  const removeNotification = async (row: NotificationRow) => {
    setRecords((current) => current.filter((r) => r.scheduleId !== row.key));
    const result = await deleteSchedule({ objectId: row.key });
    if (!mounted.current) return;
    if (result.ok) {
      pushNotification(`"${row.name || "Notification"}" deleted`, "success", "TOP_CENTER", 2000);
    } else {
      pushNotification("Couldn't delete the notification, please try again", "error", "TOP_CENTER", 3000);
    }
    load();
  };

  // Handlers change every render; columns read them through a ref so the
  // column definitions stay static.
  const handlers = useRef<any>({});
  handlers.current = { setEditing, removeNotification };

  const columns: ColumnsType<NotificationRow> = useMemo(
    () => [
      ...DATA_COLUMNS,
      {
        title: "",
        key: "actions",
        align: "right",
        width: 110,
        render: (_, row) => (
          <RowActions
            onEdit={() => handlers.current.setEditing(row.record)}
            onDelete={() => handlers.current.removeNotification(row)}
            deleteConfirm={`Delete "${row.name || "this notification"}"? Its ${
              row.recipients.length
            } ${row.recipients.length === 1 ? "driver" : "drivers"} will stop getting it.`}
          />
        ),
      },
    ],
    []
  );

  const openCreate = () => setEditing({});

  const emptyState = loadFailed ? (
    <EmptyState
      title="Couldn't load notifications"
      description={
        <Button className="mx-btn-secondary mt-2" onClick={load}>
          Try again
        </Button>
      }
    />
  ) : search.trim() ? (
    <EmptyState
      title="No matching notifications"
      description="Try a different name, channel, day or driver."
    />
  ) : (
    <EmptyState
      title="No notifications yet"
      description="Remind drivers about their upcoming jobs by push, email or SMS on the days you choose."
      action={{ label: "New notification", onClick: openCreate }}
    />
  );

  return (
    <div className="mx-notifications">
      <PageHeader
        title="Notifications"
        subtitle="Recurring reminders sent to drivers about their upcoming jobs"
        search={{
          value: search,
          onChange: setSearch,
          placeholder: "Search by name, day or driver",
        }}
        primaryAction={{ label: "New notification", onClick: openCreate }}
      />

      <DataTableCard<NotificationRow>
        rowKey="key"
        loading={loading}
        clickable
        caption={
          search.trim()
            ? `${filtered.length} of ${rows.length} notifications`
            : `${rows.length} ${rows.length === 1 ? "notification" : "notifications"}`
        }
        columns={columns}
        dataSource={filtered}
        empty={emptyState}
        scroll={{ x: true }}
        onRow={(row) => ({ onClick: () => setEditing(row.record) })}
      />

      {editing !== undefined && (
        <EditSchedulerModal
          socket={socket}
          student={editing}
          adminRoles={adminUserRoles}
          driverNames={driverNames}
          onClose={() => setEditing(undefined)}
          onAdd={() => {
            setEditing(undefined);
            load();
          }}
        />
      )}
    </div>
  );
};

export default SchedulerModal;
