import moment, { Moment } from "moment";
import type { PillTone } from "../../common/ui";

// Shape persisted at data.schedule (and in the first event's
// unstructuredAttributes.schedule). Keys must stay as they are.
export type ScheduleMode = "repeat" | "custom";
export type RepeatType = "daily" | "weekly" | "monthly";

export interface RecurringSchedule {
  mode?: ScheduleMode | null;
  customDates?: any[];
  repeatType?: RepeatType;
  /** 0 = Sunday ... 6 = Saturday */
  repeatDays?: number[];
  everyX?: number;
  monthRepeatDates?: number[];
  startDate?: any;
  endUntil?: any;
}

export const DEFAULT_SCHEDULE: RecurringSchedule = {
  mode: "repeat",
  customDates: [],
  repeatType: "weekly",
  repeatDays: [],
  everyX: 1,
  monthRepeatDates: [],
  endUntil: null,
  startDate: null,
};

/** Monday-first, values match `repeatDays`. */
export const WEEKDAYS = [
  { value: 1, short: "Mon", long: "Monday" },
  { value: 2, short: "Tue", long: "Tuesday" },
  { value: 3, short: "Wed", long: "Wednesday" },
  { value: 4, short: "Thu", long: "Thursday" },
  { value: 5, short: "Fri", long: "Friday" },
  { value: 6, short: "Sat", long: "Saturday" },
  { value: 0, short: "Sun", long: "Sunday" },
];

// Upper bound for walking an open-ended or very long range.
const MAX_SCAN_DAYS = 366 * 5;

export const toDay = (value: any): Moment | undefined => {
  if (!value) return undefined;
  const m = moment(value);
  return m.isValid() ? m.startOf("day") : undefined;
};

/** "09:30" from a stored time (moment or ISO string), or undefined. */
export const formatTime = (value: any): string | undefined => {
  if (!value) return undefined;
  const m = moment(value);
  return m.isValid() ? m.format("HH:mm") : undefined;
};

export const ordinal = (n: number) => {
  if (n > 3 && n < 21) return `${n}th`;
  switch (n % 10) {
    case 1:
      return `${n}st`;
    case 2:
      return `${n}nd`;
    case 3:
      return `${n}rd`;
    default:
      return `${n}th`;
  }
};

/** "A", "A & B", "A, B & C" */
export const joinList = (items: string[]) =>
  items.length <= 1
    ? items[0] || ""
    : `${items.slice(0, -1).join(", ")} & ${items[items.length - 1]}`;

const sortedWeekdays = (days: number[] = []) =>
  WEEKDAYS.filter((d) => days.includes(d.value));

const uniqueSortedDays = (dates: any[] = []) => {
  const seen = new Set<string>();
  return dates
    .map(toDay)
    .filter((d): d is Moment => !!d)
    .filter((d) => {
      const key = d.format("YYYY-MM-DD");
      if (seen.has(key)) return false;
      seen.add(key);
      return true;
    })
    .sort((a, b) => a.valueOf() - b.valueOf());
};

const shortDate = (d: Moment, withYear = false) => d.format(withYear ? "MMM D, YYYY" : "MMM D");

/** Plain-English pattern, e.g. "Every Mon, Wed & Fri". */
export const describePattern = (s?: RecurringSchedule): string => {
  if (!s?.mode) return "No schedule";
  if (s.mode === "custom") {
    const dates = uniqueSortedDays(s.customDates);
    if (!dates.length) return "No dates picked";
    if (dates.length <= 3) return `On ${joinList(dates.map((d) => shortDate(d)))}`;
    return `${dates.length} specific dates`;
  }
  if (s.repeatType === "daily") {
    const x = Number(s.everyX) || 1;
    return x > 1 ? `Every ${x} days` : "Every day";
  }
  if (s.repeatType === "weekly") {
    const days = sortedWeekdays(s.repeatDays);
    if (!days.length) return "Weekly (no days picked)";
    if (days.length === 7) return "Every day";
    const values = days.map((d) => d.value).join(",");
    if (values === "1,2,3,4,5") return "Weekdays";
    if (values === "6,0") return "Weekends";
    return `Every ${joinList(days.map((d) => d.short))}`;
  }
  if (s.repeatType === "monthly") {
    const dates = [...(s.monthRepeatDates || [])].sort((a, b) => a - b);
    if (!dates.length) return "Monthly (no dates picked)";
    return `Monthly on the ${joinList(dates.map(ordinal))}`;
  }
  return "No schedule";
};

export const scheduleBounds = (s?: RecurringSchedule): { start?: Moment; end?: Moment } => {
  if (s?.mode === "custom") {
    const dates = uniqueSortedDays(s.customDates);
    return { start: dates[0], end: dates[dates.length - 1] };
  }
  return { start: toDay(s?.startDate), end: toDay(s?.endUntil) };
};

/** "Oct 1 – Dec 31, 2026", "From Oct 1, 2026" or "". */
export const describeRange = (s?: RecurringSchedule): string => {
  const { start, end } = scheduleBounds(s);
  if (start && end) {
    if (start.isSame(end, "day")) return shortDate(start, true);
    return `${shortDate(start, !start.isSame(end, "year"))} – ${shortDate(end, true)}`;
  }
  if (start) return `From ${shortDate(start, true)}`;
  if (end) return `Until ${shortDate(end, true)}`;
  return "";
};

const matchesDay = (s: RecurringSchedule, day: Moment, start: Moment) => {
  if (s.repeatType === "daily") {
    const x = Math.max(1, Number(s.everyX) || 1);
    return day.diff(start, "days") % x === 0;
  }
  if (s.repeatType === "weekly") return (s.repeatDays || []).includes(day.day());
  if (s.repeatType === "monthly") return (s.monthRepeatDates || []).includes(day.date());
  return false;
};

/**
 * Dates the schedule produces on or after `from` (default: the start),
 * assuming daily repeats count from the start date and monthly dates a month
 * doesn't have are skipped. `unbounded` is true when there's no end date.
 */
export const listOccurrences = (
  s?: RecurringSchedule,
  { from, limit = Infinity }: { from?: Moment; limit?: number } = {}
): { dates: Moment[]; unbounded: boolean } => {
  if (!s?.mode) return { dates: [], unbounded: false };
  if (s.mode === "custom") {
    const dates = uniqueSortedDays(s.customDates).filter((d) => !from || !d.isBefore(from, "day"));
    return { dates: dates.slice(0, limit), unbounded: false };
  }
  const { start, end } = scheduleBounds(s);
  if (!start) return { dates: [], unbounded: !end };
  const dates: Moment[] = [];
  const cursor = from && from.isAfter(start) ? from.clone().startOf("day") : start.clone();
  for (let i = 0; i < MAX_SCAN_DAYS && dates.length < limit; i++) {
    if (end && cursor.isAfter(end, "day")) break;
    if (matchesDay(s, cursor, start)) dates.push(cursor.clone());
    cursor.add(1, "day");
  }
  return { dates, unbounded: !end };
};

export const nextOccurrence = (s?: RecurringSchedule, today = moment().startOf("day")) =>
  listOccurrences(s, { from: today, limit: 1 }).dates[0];

/** First problem with the schedule, phrased for the user, or undefined. */
export const validateSchedule = (s?: RecurringSchedule): string | undefined => {
  if (!s?.mode) return "Choose whether the booking repeats or runs on specific dates";
  if (s.mode === "custom") {
    return uniqueSortedDays(s.customDates).length ? undefined : "Add at least one date";
  }
  if (!s.repeatType) return "Choose daily, weekly or monthly";
  if (s.repeatType === "daily" && !(Number(s.everyX) >= 1)) {
    return "Repeat at least every 1 day";
  }
  if (s.repeatType === "weekly" && !s.repeatDays?.length) return "Pick at least one day of the week";
  if (s.repeatType === "monthly" && !s.monthRepeatDates?.length) {
    return "Pick at least one day of the month";
  }
  const { start, end } = scheduleBounds(s);
  if (!start) return "Pick a start date";
  // No end date means "until stopped"; existing bookings rely on that.
  if (end && end.isBefore(start, "day")) return "The end date must be on or after the start date";
  if (!listOccurrences(s, { limit: 1 }).dates.length) {
    return "No dates fall between the start and end date with this pattern";
  }
  return undefined;
};

export interface ScheduleStatus {
  label: string;
  tone: PillTone;
  /** Sort order: active first. */
  order: number;
}

export const getScheduleStatus = (
  s?: RecurringSchedule,
  today = moment().startOf("day")
): ScheduleStatus => {
  const next = nextOccurrence(s, today);
  if (!next) {
    const { end } = scheduleBounds(s);
    return end && end.isBefore(today)
      ? { label: "Ended", tone: "gray", order: 3 }
      : { label: "No upcoming dates", tone: "amber", order: 2 };
  }
  const { start } = scheduleBounds(s);
  if (start && start.isAfter(today)) return { label: "Upcoming", tone: "blue", order: 1 };
  return { label: "Active", tone: "green", order: 0 };
};

/**
 * One-line summary, e.g.
 * "Every Mon & Wed at 09:30, Oct 1 – Dec 31, 2026 · 26 rides".
 */
export const summarizeSchedule = (s?: RecurringSchedule, time?: string): string => {
  if (!s?.mode) return "No schedule yet";
  const pattern = describePattern(s);
  const parts = [time ? `${pattern} at ${time}` : pattern];
  const showRange = !(s.mode === "custom" && uniqueSortedDays(s.customDates).length <= 3);
  const range = describeRange(s);
  if (showRange && range) parts.push(range);
  const { dates, unbounded } = listOccurrences(s);
  let text = parts.join(", ");
  if (!unbounded && dates.length) text += ` · ${dates.length} ${dates.length === 1 ? "ride" : "rides"}`;
  return text;
};
