import React, { FC, useMemo, useState } from "react";
import { Row, Col } from "antd";
import DispatchPanel from "./DispatchPanel/index";
import MapPanel from "../../../containers/Dashboard/MapPanel/index";
import { useSelector } from "react-redux";
import { RootState } from "reducers/rootReducer";
import {
  getDisplayableCADSectionsWithFields,
  sectionNavLabel,
} from "../../../common/cadSectionUtils";
import Autocomplete from "react-google-autocomplete";
import Geocode from "react-geocode";

Geocode.setApiKey("AIzaSyDgNagv_ozKWc6IQ75Ol4cH8fxdntOaW6M");
Geocode.setLanguage("en");
Geocode.setRegion("us");

const CustomerCPCDashboard: FC<{ socket: ISocket }> = ({ socket }) => {
  const { sectionList } = useSelector((state: RootState) => state.auth);

  const formSectionsForNav = useMemo(
    () => getDisplayableCADSectionsWithFields(sectionList, {}),
    [sectionList]
  );

  const showSectionJumpNav = formSectionsForNav.length > 1;

  const [screens, setScreens] = useState<any>({
    form: true,
    map: false,
  });

  const params: any = {
    screens,
    setScreens,
  };

  const fixedColSize = 24;

  return (
    <Row className="main-layout">
      {screens.form && (
        <Col
          md={screens.map ? 12: fixedColSize}
          xs={24}
          className={screens.active === "form" ? "active-screen" : ""}
        >
          {showSectionJumpNav && (
            <nav
              className="customer-cpc-section-jump d-flex flex-wrap align-items-center px-3 py-2 border-bottom"
              aria-label="Form sections"
            >
              <span className="text-muted mr-2 mb-1" style={{ fontSize: 13 }}>
                Jump to:
              </span>
              {formSectionsForNav.map((section, i) => {
                const label = sectionNavLabel(section, i);
                if (!label) {
                  return null;
                }
                const sectionAnchorId = `customer-cpc-section-${i}`;
                return (
                  <a
                    key={i}
                    href={`#${sectionAnchorId}`}
                    className="mr-3 mb-1"
                    style={{ fontSize: 13 }}
                    onClick={(e) => {
                      e.preventDefault();
                      window.dispatchEvent(
                        new CustomEvent("customer-cpc-expand-section", {
                          detail: sectionAnchorId,
                        })
                      );
                      window.setTimeout(() => {
                        document
                          .getElementById(sectionAnchorId)
                          ?.scrollIntoView({
                            behavior: "smooth",
                            block: "start",
                          });
                      }, 120);
                    }}
                  >
                    {label}
                  </a>
                );
              })}
            </nav>
          )}
          <DispatchPanel socket={socket} params={params} />
        </Col>
      )}
      {screens.map && (
        <Col
          md={12}
          xs={24}
          className={screens.active === "map" ? "active-screen" : ""}
        >
          <MapPanel socket={socket} params={params} />
        </Col>
      )}
      <Autocomplete
        apiKey="AIzaSyDgNagv_ozKWc6IQ75Ol4cH8fxdntOaW6M"
        style={{ display: "none" }}
        options={{
          types: ["(regions)"],
          componentRestrictions: { country: ["us", "ca", "uk"] },
        }}
      />
    </Row>
  );
};
export default CustomerCPCDashboard;
