import React, { FC, useEffect, useMemo, useRef, useState } from "react";
import { Alert, Button, Col, DatePicker, Form, Input, InputNumber, Radio, Row, Select, Switch, Upload } from "antd";
import { DeleteOutlined, UploadOutlined } from "@ant-design/icons";
import moment, { Moment } from "moment";
import { useDispatch, useSelector } from "react-redux";
import { RootState } from "reducers/rootReducer";
import { UPLOAD_MEDIA } from "../../../reducers/reducer";
import { generateUUID } from "utils/appUtil";
import { pushNotification } from "utils/notifications";
import { FormModal, FormSection } from "../Medical/common/ui";
import CardPreview from "./card/CardPreview";
import { DEFAULT_ACCENT } from "./card/renderCard";
import { CouponInfo, CouponRecord } from "./types";

const { RangePicker } = DatePicker;
const { TextArea } = Input;

export const CURRENCIES = ["USD", "EUR", "GBP", "CAD", "AUD", "AED", "ZAR", "NGN", "KES", "PKR", "INR"];
const ACCENTS = ["#463bbd", "#e5484d", "#1f9d55", "#508afa", "#ff5f25", "#1d2433"];
const LOGO_MAX_BYTES = 2 * 1024 * 1024;
const LINK_TTL_DAYS = 7;
const PREVIEW_URL = `${window.location.origin}/coupon/redeem?token=preview`;

interface FormValues {
  title: string;
  brandName?: string;
  description?: string;
  code?: string;
  terms?: string;
  discountType: CouponInfo["discountType"];
  discountValue: number;
  currency: string;
  maxDiscountAmount?: number | null;
  minPurchaseAmount?: number | null;
  usageType: CouponInfo["usageType"];
  maxUsesPerCode?: number | null;
  totalRedemptionLimit?: number | null;
  validity: [Moment, Moment];
  active: boolean;
  headline?: string;
  text?: string;
  footer?: string;
  accentColor?: string;
}

const toValues = (info?: CouponInfo): Partial<FormValues> =>
  info
    ? {
        title: info.title,
        brandName: info.brandName,
        description: info.description,
        code: info.code,
        terms: info.terms,
        discountType: info.discountType,
        discountValue: info.discountValue,
        currency: info.currency || "USD",
        maxDiscountAmount: info.maxDiscountAmount ?? null,
        minPurchaseAmount: info.minPurchaseAmount ?? null,
        usageType: info.usageType,
        maxUsesPerCode: info.maxUsesPerCode ?? null,
        totalRedemptionLimit: info.totalRedemptionLimit ?? null,
        validity: [
          info.validFrom ? moment(info.validFrom) : moment().startOf("day"),
          info.validUntil ? moment(info.validUntil) : moment().add(30, "days").endOf("day"),
        ],
        active: info.status === "active",
        headline: info.card?.headline,
        text: info.card?.text,
        footer: info.card?.footer,
        accentColor: info.card?.accentColor || DEFAULT_ACCENT,
      }
    : {
        discountType: "percentage",
        currency: "USD",
        usageType: "single",
        validity: [moment().startOf("day"), moment().add(30, "days").endOf("day")],
        active: true,
        accentColor: DEFAULT_ACCENT,
      };

const blankToNull = (n: any) => (n === undefined || n === null || n === "" ? null : Number(n));

const toInfo = (v: Partial<FormValues>, logoUrl: string | undefined, previous?: CouponInfo): CouponInfo => ({
  ...(previous || {}),
  title: `${v.title || ""}`.trim(),
  brandName: `${v.brandName || ""}`.trim() || undefined,
  description: `${v.description || ""}`.trim() || undefined,
  code: `${v.code || ""}`.trim().toUpperCase() || undefined,
  terms: `${v.terms || ""}`.trim() || undefined,
  discountType: v.discountType || "percentage",
  discountValue: Number(v.discountValue) || 0,
  currency: v.currency || "USD",
  maxDiscountAmount: v.discountType === "percentage" ? blankToNull(v.maxDiscountAmount) : null,
  minPurchaseAmount: blankToNull(v.minPurchaseAmount),
  usageType: v.usageType || "single",
  maxUsesPerCode: v.usageType === "multiple" ? blankToNull(v.maxUsesPerCode) : 1,
  totalRedemptionLimit: blankToNull(v.totalRedemptionLimit),
  validFrom: v.validity?.[0] ? v.validity[0].clone().startOf("day").valueOf() : null,
  validUntil: v.validity?.[1] ? v.validity[1].clone().endOf("day").valueOf() : null,
  status: v.active === false ? "paused" : previous?.status === "archived" ? "archived" : "active",
  card: {
    logoUrl,
    headline: `${v.headline || ""}`.trim() || undefined,
    text: `${v.text || ""}`.trim() || undefined,
    footer: `${v.footer || ""}`.trim() || undefined,
    accentColor: v.accentColor || DEFAULT_ACCENT,
  },
});

interface Props {
  open: boolean;
  coupon?: CouponRecord;
  saving?: boolean;
  onCancel: () => void;
  onSave: (info: CouponInfo) => void;
}

const CouponFormModal: FC<Props> = ({ open, coupon, saving, onCancel, onSave }) => {
  const [form] = Form.useForm<FormValues>();
  const dispatch = useDispatch();
  const { fileToSend } = useSelector((state: RootState) => state.auth) as any;
  const [logoUrl, setLogoUrl] = useState<string | undefined>();
  const [uploading, setUploading] = useState(false);
  const uploadId = useRef<string | null>(null);
  const watched = Form.useWatch([], form) as Partial<FormValues> | undefined;

  useEffect(() => {
    if (!open) return;
    form.resetFields();
    form.setFieldsValue(toValues(coupon?.info) as any);
    setLogoUrl(coupon?.info.card?.logoUrl);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [open, coupon?.objectId]);

  // UPLOAD_MEDIA answers through the shared fileToSend slot; match our request id.
  useEffect(() => {
    if (!fileToSend?.id || fileToSend.id !== uploadId.current) return;
    uploadId.current = null;
    setUploading(false);
    const url = fileToSend.media?.urls?.original?.url;
    if (url) setLogoUrl(url);
    else pushNotification("Logo upload failed", "error", "TOP_CENTER", 2000);
  }, [fileToSend]);

  const beforeUpload = (file: File) => {
    if (!file.type.startsWith("image/")) {
      pushNotification("Choose an image file", "error", "TOP_CENTER", 2000);
      return Upload.LIST_IGNORE;
    }
    if (file.size > LOGO_MAX_BYTES) {
      pushNotification("Logo must be 2 MB or smaller", "error", "TOP_CENTER", 2000);
      return Upload.LIST_IGNORE;
    }
    const id = generateUUID();
    uploadId.current = id;
    setUploading(true);
    const data = new FormData();
    data.append("file", file);
    data.append("info", JSON.stringify({}));
    dispatch(UPLOAD_MEDIA({ form: data, id }));
    return false;
  };

  const previewInfo = useMemo(
    () => toInfo({ ...toValues(coupon?.info), ...(watched || {}) }, logoUrl, coupon?.info),
    [watched, logoUrl, coupon?.info]
  );

  const discountType = watched?.discountType ?? coupon?.info.discountType ?? "percentage";
  const usageType = watched?.usageType ?? coupon?.info.usageType ?? "single";
  const validUntil = watched?.validity?.[1];
  const longerThanLinks = validUntil && validUntil.diff(moment(), "days") > LINK_TTL_DAYS;

  const submit = (values: FormValues) => onSave(toInfo(values, logoUrl, coupon?.info));

  return (
    <FormModal
      open={open}
      title={coupon ? "Edit coupon" : "Create coupon"}
      subtitle="Set the discount and its rules, then design the card your customers will show at the store."
      width={1080}
      saving={saving || uploading}
      okText={coupon ? "Save changes" : "Create coupon"}
      onCancel={onCancel}
      onSubmit={() => form.submit()}
    >
      <Row gutter={24} className="cpn-form">
        <Col xs={24} lg={14}>
          <Form form={form} layout="vertical" onFinish={submit} requiredMark="optional">
            <FormSection index={1} title="Basics">
              <Form.Item name="title" label="Title" rules={[{ required: true, whitespace: true, max: 80 }]}>
                <Input placeholder="20% off Coca-Cola products" />
              </Form.Item>
              <Row gutter={12}>
                <Col span={12}>
                  <Form.Item name="brandName" label="Brand" rules={[{ max: 60 }]}>
                    <Input placeholder="Coca-Cola" />
                  </Form.Item>
                </Col>
                <Col span={12}>
                  <Form.Item
                    name="code"
                    label="Coupon code"
                    tooltip="Optional human-readable code printed on the card"
                    rules={[{ pattern: /^[A-Za-z0-9-]{0,20}$/, message: "Letters, numbers and dashes, up to 20" }]}
                  >
                    <Input placeholder="COKE20" style={{ textTransform: "uppercase" }} />
                  </Form.Item>
                </Col>
              </Row>
              <Form.Item name="description" label="Description" rules={[{ max: 300 }]}>
                <TextArea rows={2} placeholder="What the discount applies to" />
              </Form.Item>
              <Form.Item name="terms" label="Terms & conditions" rules={[{ max: 1000 }]}>
                <TextArea rows={2} placeholder="Shown to the store before they accept" />
              </Form.Item>
            </FormSection>

            <FormSection index={2} title="Discount">
              <Form.Item name="discountType" label="Type">
                <Radio.Group optionType="button" buttonStyle="solid">
                  <Radio.Button value="percentage">Percentage</Radio.Button>
                  <Radio.Button value="fixed">Fixed amount</Radio.Button>
                </Radio.Group>
              </Form.Item>
              <Row gutter={12}>
                <Col span={12}>
                  <Form.Item
                    name="discountValue"
                    label={discountType === "percentage" ? "Discount (%)" : "Discount amount"}
                    rules={[
                      { required: true, message: "Enter the discount" },
                      {
                        validator: (_, v) =>
                          v === undefined || v === null || (v > 0 && (discountType !== "percentage" || v <= 100))
                            ? Promise.resolve()
                            : Promise.reject(
                                new Error(discountType === "percentage" ? "Between 1 and 100" : "Must be more than 0")
                              ),
                      },
                    ]}
                  >
                    <InputNumber min={0} max={discountType === "percentage" ? 100 : undefined} style={{ width: "100%" }} />
                  </Form.Item>
                </Col>
                <Col span={12}>
                  <Form.Item name="currency" label="Currency">
                    <Select options={CURRENCIES.map((c) => ({ label: c, value: c }))} showSearch />
                  </Form.Item>
                </Col>
              </Row>
              <Row gutter={12}>
                <Col span={12}>
                  <Form.Item
                    name="minPurchaseAmount"
                    label="Minimum purchase"
                    tooltip="The bill must be at least this much. Leave empty for no minimum."
                  >
                    <InputNumber min={0} style={{ width: "100%" }} placeholder="No minimum" />
                  </Form.Item>
                </Col>
                <Col span={12}>
                  {discountType === "percentage" && (
                    <Form.Item
                      name="maxDiscountAmount"
                      label="Maximum discount"
                      tooltip="Caps the percentage discount. Leave empty for no cap."
                    >
                      <InputNumber min={0} style={{ width: "100%" }} placeholder="No cap" />
                    </Form.Item>
                  )}
                </Col>
              </Row>
            </FormSection>

            <FormSection index={3} title="Usage & validity">
              <Form.Item name="usageType" label="Each coupon can be used">
                <Radio.Group>
                  <Radio value="single">One time</Radio>
                  <Radio value="multiple">Multiple times</Radio>
                </Radio.Group>
              </Form.Item>
              <Row gutter={12}>
                <Col span={12}>
                  {usageType === "multiple" && (
                    <Form.Item name="maxUsesPerCode" label="Uses per recipient" tooltip="Leave empty for unlimited">
                      <InputNumber min={1} precision={0} style={{ width: "100%" }} placeholder="Unlimited" />
                    </Form.Item>
                  )}
                </Col>
                <Col span={12}>
                  <Form.Item
                    name="totalRedemptionLimit"
                    label="Total redemptions (all recipients)"
                    tooltip="Stops the campaign once this many coupons are used. Leave empty for unlimited."
                  >
                    <InputNumber min={1} precision={0} style={{ width: "100%" }} placeholder="Unlimited" />
                  </Form.Item>
                </Col>
              </Row>
              <Row gutter={12} align="middle">
                <Col span={16}>
                  <Form.Item name="validity" label="Valid" rules={[{ required: true, message: "Choose dates" }]}>
                    <RangePicker format="MMM D, YYYY" allowClear={false} style={{ width: "100%" }} />
                  </Form.Item>
                </Col>
                <Col span={8}>
                  <Form.Item name="active" label="Active" valuePropName="checked">
                    <Switch />
                  </Form.Item>
                </Col>
              </Row>
              {longerThanLinks && (
                <Alert
                  type="info"
                  showIcon
                  message={`Coupon links stay open for ${LINK_TTL_DAYS} days after they are sent. Resend to anyone who hasn't used theirs by then.`}
                />
              )}
            </FormSection>

            <FormSection index={4} title="Card design" description="The printable card and the image in each email.">
              <Form.Item label="Logo">
                <div className="cpn-logo-field">
                  {logoUrl && <img src={logoUrl} alt="Logo" />}
                  <Upload accept="image/*" showUploadList={false} beforeUpload={beforeUpload}>
                    <Button icon={<UploadOutlined />} loading={uploading}>
                      {logoUrl ? "Replace" : "Upload logo"}
                    </Button>
                  </Upload>
                  {logoUrl && (
                    <Button icon={<DeleteOutlined />} onClick={() => setLogoUrl(undefined)}>
                      Remove
                    </Button>
                  )}
                </div>
              </Form.Item>
              <Form.Item name="headline" label="Headline" tooltip="Defaults to the title" rules={[{ max: 60 }]}>
                <Input placeholder={watched?.title || "20% off Coca-Cola products"} />
              </Form.Item>
              <Form.Item name="text" label="Card text" tooltip="Defaults to the description" rules={[{ max: 220 }]}>
                <TextArea rows={3} placeholder="Free text printed on the card" showCount maxLength={220} />
              </Form.Item>
              <Row gutter={12}>
                <Col span={14}>
                  <Form.Item name="footer" label="Footer" rules={[{ max: 70 }]}>
                    <Input placeholder="Show this QR code at checkout" />
                  </Form.Item>
                </Col>
                <Col span={10}>
                  <Form.Item name="accentColor" label="Colour">
                    <AccentPicker />
                  </Form.Item>
                </Col>
              </Row>
            </FormSection>
          </Form>
        </Col>
        <Col xs={24} lg={10}>
          <div className="cpn-form__preview">
            <div className="cpn-form__preview-label">Card preview</div>
            <CardPreview info={previewInfo} url={PREVIEW_URL} caption="Customer name" />
          </div>
        </Col>
      </Row>
    </FormModal>
  );
};

const AccentPicker: FC<{ value?: string; onChange?: (v: string) => void }> = ({ value, onChange }) => (
  <div className="cpn-accent">
    {ACCENTS.map((c) => (
      <button
        key={c}
        type="button"
        aria-label={`Colour ${c}`}
        className={`cpn-accent__swatch ${value === c ? "cpn-accent__swatch--on" : ""}`}
        style={{ background: c }}
        onClick={() => onChange?.(c)}
      />
    ))}
    <input type="color" value={value || DEFAULT_ACCENT} onChange={(e) => onChange?.(e.target.value)} title="Custom colour" />
  </div>
);

export default CouponFormModal;
