import React, { useEffect, useState } from "react";
import { Button, Checkbox, Modal, Select } from "antd";
import { SORTABLE_COLUMNS } from "../constants";
import { SortDirection, SortOrder } from "../types";

interface Props {
  open: boolean;
  sortOrders: SortOrder[];
  onApply: (orders: SortOrder[]) => void;
  onClose: () => void;
}

const labelFor = (key: string) => SORTABLE_COLUMNS.find((c) => c.key === key)?.label || key;

/** Edits a draft copy; nothing changes until Apply or Reset. */
const SortModal = ({ open, sortOrders, onApply, onClose }: Props) => {
  const [draft, setDraft] = useState<SortOrder[]>([]);

  useEffect(() => {
    if (open) setDraft([...sortOrders]);
  }, [open, sortOrders]);

  const toggle = (columnKey: string, checked: boolean) =>
    setDraft((prev) =>
      checked
        ? [...prev, { columnKey, order: "ascend" }]
        : prev.filter((so) => so.columnKey !== columnKey)
    );

  const setDirection = (columnKey: string, order: SortDirection) =>
    setDraft((prev) => prev.map((so) => (so.columnKey === columnKey ? { ...so, order } : so)));

  return (
    <Modal
      title="Sort Table"
      open={open}
      onCancel={onClose}
      width={600}
      footer={[
        <Button
          key="reset"
          className="beam-btn"
          onClick={() => {
            onApply([]);
            onClose();
          }}
        >
          Reset
        </Button>,
        <Button key="cancel" className="beam-btn" onClick={onClose}>
          Cancel
        </Button>,
        <Button
          key="apply"
          type="primary"
          className="beam-btn"
          onClick={() => {
            onApply(draft);
            onClose();
          }}
        >
          Apply
        </Button>,
      ]}
    >
      <div style={{ marginBottom: 16 }}>
        <p>
          Select columns to sort by. Priority is based on selection order (first selected =
          highest priority).
        </p>
      </div>
      <div style={{ maxHeight: 400, overflowY: "auto" }}>
        {SORTABLE_COLUMNS.map((col) => {
          const index = draft.findIndex((so) => so.columnKey === col.key);
          const selected = index !== -1;
          return (
            <div
              key={col.key}
              style={{
                display: "flex",
                alignItems: "center",
                padding: "12px",
                borderBottom: "1px solid #f0f0f0",
              }}
            >
              <Checkbox
                checked={selected}
                onChange={(e) => toggle(col.key, e.target.checked)}
                style={{ marginRight: 12, minWidth: 150 }}
              >
                {col.label}
              </Checkbox>
              {selected && (
                <>
                  <span style={{ marginRight: 8, color: "#666", fontSize: 12 }}>
                    Priority: {index + 1}
                  </span>
                  <Select
                    value={draft[index].order}
                    onChange={(value) => setDirection(col.key, value)}
                    style={{ width: 100 }}
                    options={[
                      { value: "ascend", label: "Ascending" },
                      { value: "descend", label: "Descending" },
                    ]}
                  />
                </>
              )}
            </div>
          );
        })}
      </div>
      {draft.length > 0 && (
        <div style={{ marginTop: 16, padding: 12, backgroundColor: "#f5f5f5", borderRadius: 4 }}>
          <strong>Sort Order:</strong>
          <ol style={{ marginTop: 8, marginBottom: 0 }}>
            {draft.map((so) => (
              <li key={so.columnKey} style={{ marginBottom: 4 }}>
                {labelFor(so.columnKey)} ({so.order === "ascend" ? "Ascending" : "Descending"})
              </li>
            ))}
          </ol>
        </div>
      )}
    </Modal>
  );
};

export default SortModal;
