import React, { FC, useEffect, useMemo, useRef, useState } from "react";
import { Button, Checkbox, Col, DatePicker, Form, Input, InputNumber, Modal, Row } from "antd";
import moment, { Moment } from "moment";
import { useSelector } from "react-redux";
import { RootState } from "reducers/rootReducer";
import { ExtendedBioTopics, SocketTopics, UserTopics } from "constants/enums";
import LocationInput from "../../../../../common/LocationInput";
import ResponderInput from "../../../../../common/ResponderInput";
import useSocketActions from "../../../../../hooks/socketActions";
import { generateUUID } from "utils/appUtil";
import { pushNotification } from "utils/notifications";
import { FormModal, FormSection } from "../../common/ui";
import {
  REQUEST_TIMEOUT_MS,
  STORED_DATE_FORMAT,
  VehicleAsset,
  parseStoredDate,
} from "./vehicleApi";
import "./Vehicle.scss";

const { TextArea } = Input;

const DATE_TIME_FORMAT = "MM/DD/YYYY hh:mm A";
const TEXT_KEYS = [
  "name",
  "makeAndModel",
  "trim",
  "colour",
  "licensePlate",
  "vin",
  "permit",
  "tireSize",
  "engine",
] as const;
// Edited as numbers but stored as strings, as the old free-text inputs did.
const NUMBER_KEYS = ["year", "width", "mileage"] as const;
const PREFERENCE_KEYS = ["phoneMount", "holePunched", "bluetooth"] as const;
const MAINTENANCE_KEYS = [
  "maintenanceLocation",
  "typeOfWork",
  "dropoffDateTime",
  "pickupDateTime",
  "additionalInformation",
  "driverDropoff",
  "driverPickup",
] as const;

const MAX_YEAR = new Date().getFullYear() + 1;
const VIN_PATTERN = /^[A-HJ-NPR-Z0-9]{17}$/i;

const toNumber = (value: any) => {
  if (value === undefined || value === null || value === "") return undefined;
  const n = parseFloat(`${value}`.replace(/,/g, ""));
  return Number.isFinite(n) ? n : undefined;
};

// ResponderInput reports a cleared selection as an object without an id.
const toResponder = (driver?: { id?: string; value?: string; beamId?: string }) => {
  const id = driver?.id ?? driver?.value;
  return id ? { type: "responder", id, beamId: driver.beamId, valueName: driver.beamId } : undefined;
};

const isMaintenanceFilled = (values: any) =>
  !!(
    values?.maintenanceLocation?.label ||
    `${values?.typeOfWork ?? ""}`.trim() ||
    values?.dropoffDateTime ||
    values?.pickupDateTime ||
    `${values?.additionalInformation ?? ""}`.trim() ||
    toResponder(values?.driverDropoff) ||
    toResponder(values?.driverPickup)
  );

const requiredText = (message: string) => ({ required: true, whitespace: true, message });

/** Edit a vehicle (asset user): details, features and maintenance booking. */
const EditVehicleModal: FC<{
  onClose: () => void;
  socket?: ISocket;
  /** The vehicle asset being edited ({ id, static }). */
  student?: VehicleAsset | any;
  adminRoles?: any;
  onAdd?: () => void;
}> = ({ onClose, socket, student, adminRoles, onAdd }) => {
  const [form] = Form.useForm();
  const { projects } = useSelector((state: RootState) => state.auth);
  const { updateUserRequestPayloadV2 } = useSocketActions();
  const [saving, setSaving] = useState(false);
  const [maintenanceCleared, setMaintenanceCleared] = useState(false);
  const uuid = useRef(generateUUID()).current;
  const pending = useRef(false);
  const timer = useRef<any>();
  const mounted = useRef(true);
  const asset = student?.static || {};

  const initialValues = useMemo(() => {
    const m = asset.maintenance || {};
    return {
      ...Object.fromEntries(TEXT_KEYS.map((k) => [k, asset[k]])),
      ...Object.fromEntries(NUMBER_KEYS.map((k) => [k, toNumber(asset[k])])),
      ...Object.fromEntries(PREFERENCE_KEYS.map((k) => [k, asset.preferences?.[k]])),
      maintenanceDate: parseStoredDate(asset.maintenanceDate),
      maintenanceLocation: m.location,
      typeOfWork: m.typeOfWork,
      dropoffDateTime: parseStoredDate(m.dropoffDateTime),
      pickupDateTime: parseStoredDate(m.pickupDateTime),
      additionalInformation: m.additionalInformation,
      driverDropoff: toResponder(m.driverDropoff),
      driverPickup: toResponder(m.driverPickup),
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  // Booking fields are only required once the user edits one of them, so an
  // older, half-filled booking doesn't block saving other vehicle details.
  const [maintenanceActive, setMaintenanceActive] = useState(false);
  const [hasBooking, setHasBooking] = useState(() => !!isMaintenanceFilled(initialValues));

  useEffect(() => {
    mounted.current = true;
    socket?.subscribeToSurvey(
      SocketTopics.SurveyTopics,
      ExtendedBioTopics.UpdateUserBio,
      () => {
        // Shared reply topic: only react to our own save.
        if (!pending.current || !mounted.current) return;
        pending.current = false;
        clearTimeout(timer.current);
        setSaving(false);
        pushNotification("Vehicle saved", "success", "TOP_CENTER", 2000);
        if (onAdd) onAdd();
        else onClose();
      },
      uuid
    );
    return () => {
      mounted.current = false;
      clearTimeout(timer.current);
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  const isDirty = () => maintenanceCleared || form.isFieldsTouched();

  const handleCancel = () => {
    if (saving) return;
    if (!isDirty()) {
      onClose();
      return;
    }
    Modal.confirm({
      title: "Discard unsaved changes?",
      content: "Your edits to this vehicle haven't been saved.",
      okText: "Discard",
      okButtonProps: { danger: true },
      cancelText: "Keep editing",
      onOk: onClose,
    });
  };

  const clearMaintenance = () => {
    form.setFieldsValue(Object.fromEntries(MAINTENANCE_KEYS.map((k) => [k, undefined])));
    setMaintenanceCleared(true);
    setMaintenanceActive(false);
    setHasBooking(false);
  };

  const buildChanges = (values: any) => {
    const changes: any[] = [];
    const set = (key: string, value: any) =>
      changes.push({ op: "add", path: `/persistent/static/asset/${key}`, value });
    // Only write fields the user changed, so unreadable old values and
    // untouched optional fields are left exactly as stored.
    const touched = (key: string) => form.isFieldTouched(key);

    TEXT_KEYS.forEach((key) => {
      if (!touched(key)) return;
      const next = `${values[key] ?? ""}`.trim();
      if (next !== `${asset[key] ?? ""}`) set(key, next);
    });
    NUMBER_KEYS.forEach((key) => {
      if (!touched(key)) return;
      const next = values[key] === undefined || values[key] === null ? "" : `${values[key]}`;
      if (next !== `${asset[key] ?? ""}`) set(key, next);
    });
    if (touched("maintenanceDate")) {
      const next = (values.maintenanceDate as Moment).format(STORED_DATE_FORMAT);
      if (next !== asset.maintenanceDate) set("maintenanceDate", next);
    }
    if (PREFERENCE_KEYS.some(touched)) {
      const { phoneMount, holePunched, bluetooth } = values;
      set("preferences", { phoneMount, holePunched, bluetooth });
    }
    if (maintenanceCleared || MAINTENANCE_KEYS.some(touched)) {
      set(
        "maintenance",
        maintenanceActive
          ? {
              location: values.maintenanceLocation,
              typeOfWork: values.typeOfWork?.trim(),
              dropoffDateTime: values.dropoffDateTime?.format(STORED_DATE_FORMAT),
              pickupDateTime: values.pickupDateTime?.format(STORED_DATE_FORMAT),
              additionalInformation: values.additionalInformation?.trim() || undefined,
              driverPickup: toResponder(values.driverPickup),
              driverDropoff: toResponder(values.driverDropoff),
            }
          : {}
      );
    }
    return changes;
  };

  const save = (values: any) => {
    const changes = buildChanges(values);
    if (!changes.length) {
      pushNotification("No changes to save", "info", "TOP_CENTER", 1500);
      onClose();
      return;
    }
    setSaving(true);
    pending.current = true;
    clearTimeout(timer.current);
    timer.current = setTimeout(() => {
      if (!pending.current || !mounted.current) return;
      pending.current = false;
      setSaving(false);
      pushNotification(
        "No response from the server. Reopen the vehicle to check whether it was saved.",
        "error",
        "TOP_CENTER",
        4000
      );
    }, REQUEST_TIMEOUT_MS);
    socket?.publishToServiceIdSurvey(
      SocketTopics.SurveyTopics,
      UserTopics.UpdateUser,
      updateUserRequestPayloadV2(student?.id, changes),
      ExtendedBioTopics.UpdateUserBio,
      projects?.userServiceId
    );
  };

  const half = { xs: 24, md: 12 };

  return (
    <FormModal
      open
      width={880}
      title={`Edit ${asset.name || "vehicle"}`}
      subtitle={[asset.makeAndModel, asset.licensePlate].filter(Boolean).join(" · ") || undefined}
      onCancel={handleCancel}
      onSubmit={form.submit}
      saving={saving}
      okText="Save vehicle"
    >
      <Form
        form={form}
        className="mx-vehicle-form"
        layout="vertical"
        requiredMark={false}
        initialValues={initialValues}
        onFinish={save}
        onValuesChange={(changed, all) => {
          setHasBooking(!!isMaintenanceFilled(all));
          if (Object.keys(changed).some((k) => (MAINTENANCE_KEYS as readonly string[]).includes(k))) {
            setMaintenanceActive(!!isMaintenanceFilled(all));
          }
        }}
        scrollToFirstError
      >
        <FormSection index={1} title="Vehicle" description="How the vehicle appears across the app.">
          <Row gutter={16}>
            <Col {...half}>
              <Form.Item
                label="Name"
                name="name"
                rules={[
                  requiredText("Please input the vehicle name"),
                  { max: 80, message: "Keep the name under 80 characters" },
                ]}
              >
                <Input placeholder="e.g. Van 12" />
              </Form.Item>
            </Col>
            <Col {...half}>
              <Form.Item
                label="Make and model"
                name="makeAndModel"
                rules={[requiredText("Please enter the make and model"), { max: 80 }]}
              >
                <Input placeholder="e.g. Ford Transit" />
              </Form.Item>
            </Col>
            <Col xs={24} md={8}>
              <Form.Item
                label="Year"
                name="year"
                rules={[
                  { required: true, message: "Please enter the vehicle year" },
                  {
                    type: "number",
                    min: 1950,
                    max: MAX_YEAR,
                    message: `Enter a year between 1950 and ${MAX_YEAR}`,
                  },
                ]}
              >
                <InputNumber placeholder="e.g. 2021" precision={0} controls={false} />
              </Form.Item>
            </Col>
            <Col xs={24} md={8}>
              <Form.Item
                label="Trim"
                name="trim"
                rules={[requiredText("Please enter the vehicle trim"), { max: 60 }]}
              >
                <Input placeholder="e.g. XLT" />
              </Form.Item>
            </Col>
            <Col xs={24} md={8}>
              <Form.Item label="Colour" name="colour" rules={[{ max: 40 }]}>
                <Input placeholder="e.g. White" />
              </Form.Item>
            </Col>
          </Row>
        </FormSection>

        <FormSection index={2} title="Registration">
          <Row gutter={16}>
            <Col xs={24} md={8}>
              <Form.Item
                label="License plate"
                name="licensePlate"
                rules={[requiredText("Please enter the license plate number"), { max: 15 }]}
              >
                <Input placeholder="e.g. ABCD 123" />
              </Form.Item>
            </Col>
            <Col xs={24} md={8}>
              <Form.Item
                label="VIN"
                name="vin"
                rules={[
                  requiredText("Please enter the vehicle identification number (VIN)"),
                  {
                    pattern: VIN_PATTERN,
                    warningOnly: true,
                    message: "VINs are usually 17 letters and digits (no I, O or Q)",
                  },
                ]}
              >
                <Input placeholder="17 characters" />
              </Form.Item>
            </Col>
            <Col xs={24} md={8}>
              <Form.Item
                label="Permit #"
                name="permit"
                rules={[requiredText("Please enter permit #"), { max: 40 }]}
              >
                <Input placeholder="Enter permit #" />
              </Form.Item>
            </Col>
          </Row>
        </FormSection>

        <FormSection index={3} title="Specs & service">
          <Row gutter={16}>
            <Col {...half}>
              <Form.Item
                label="Engine"
                name="engine"
                rules={[requiredText("Please enter engine"), { max: 60 }]}
              >
                <Input placeholder="e.g. 3.5L V6" />
              </Form.Item>
            </Col>
            <Col {...half}>
              <Form.Item
                label="Tire size"
                name="tireSize"
                rules={[requiredText("Please enter tire size"), { max: 30 }]}
              >
                <Input placeholder="e.g. 235/65R16" />
              </Form.Item>
            </Col>
            <Col xs={24} md={8}>
              <Form.Item
                label="Ramp width"
                name="width"
                rules={[{ type: "number", min: 0, max: 200, message: "Enter a width up to 200 in" }]}
              >
                <InputNumber placeholder="Optional" addonAfter="in" step={0.5} />
              </Form.Item>
            </Col>
            <Col xs={24} md={8}>
              <Form.Item
                label="Current mileage"
                name="mileage"
                rules={[
                  { type: "number", min: 0, max: 2000000, message: "Enter a mileage of 0 or more" },
                ]}
              >
                <InputNumber
                  placeholder="Optional"
                  addonAfter="km"
                  precision={0}
                  formatter={(v) => `${v ?? ""}`.replace(/\B(?=(\d{3})+(?!\d))/g, ",")}
                  parser={(v) => `${v ?? ""}`.replace(/,/g, "") as any}
                />
              </Form.Item>
            </Col>
            <Col xs={24} md={8}>
              <Form.Item
                label="Last maintenance"
                name="maintenanceDate"
                rules={[
                  { required: true, message: "Please select the last maintenance date" },
                  {
                    validator: (_, value) =>
                      value && value.isAfter(moment(), "day")
                        ? Promise.reject(new Error("Can't be in the future"))
                        : Promise.resolve(),
                  },
                ]}
              >
                <DatePicker
                  format="MMM D, YYYY"
                  disabledDate={(d) => d && d.isAfter(moment(), "day")}
                />
              </Form.Item>
            </Col>
          </Row>
        </FormSection>

        <FormSection index={4} title="Features">
          <div className="mx-vehicle-form__features">
            <Form.Item name="phoneMount" valuePropName="checked">
              <Checkbox>Phone mount</Checkbox>
            </Form.Item>
            <Form.Item name="holePunched" valuePropName="checked">
              <Checkbox>Hole-punched CC</Checkbox>
            </Form.Item>
            <Form.Item name="bluetooth" valuePropName="checked">
              <Checkbox>Bluetooth</Checkbox>
            </Form.Item>
          </div>
        </FormSection>

        <FormSection
          index={5}
          title="Maintenance booking"
          description="Optional. Fill in to book the vehicle into the shop."
          extra={
            hasBooking && (
              <Button type="link" className="mx-vehicle-form__clear" onClick={clearMaintenance}>
                Clear booking
              </Button>
            )
          }
        >
          <Row gutter={16}>
            <Col {...half}>
              <Form.Item
                label="Location"
                name="maintenanceLocation"
                rules={[
                  { required: maintenanceActive, message: "Please select the maintenance location" },
                ]}
              >
                <LocationInput placeholder="Select location" />
              </Form.Item>
            </Col>
            <Col {...half}>
              <Form.Item
                label="Type of work"
                name="typeOfWork"
                rules={[
                  {
                    required: maintenanceActive,
                    whitespace: true,
                    message: "Please enter the type of work",
                  },
                  { max: 120 },
                ]}
              >
                <Input placeholder="e.g. Oil change" />
              </Form.Item>
            </Col>
            <Col {...half}>
              <Form.Item
                label="Drop-off"
                name="dropoffDateTime"
                rules={[
                  { required: maintenanceActive, message: "Please select the dropoff date and time" },
                ]}
              >
                <DatePicker
                  showTime={{ use12Hours: true, format: "hh:mm A" }}
                  format={DATE_TIME_FORMAT}
                  placeholder="Select dropoff date and time"
                />
              </Form.Item>
            </Col>
            <Col {...half}>
              <Form.Item
                label="Pick-up"
                name="pickupDateTime"
                dependencies={["dropoffDateTime"]}
                rules={[
                  { required: maintenanceActive, message: "Please select the pickup date and time" },
                  ({ getFieldValue }) => ({
                    validator: (_, value) => {
                      const dropoff = getFieldValue("dropoffDateTime");
                      return value && dropoff && !value.isAfter(dropoff)
                        ? Promise.reject(new Error("Pick-up must be after drop-off"))
                        : Promise.resolve();
                    },
                  }),
                ]}
              >
                <DatePicker
                  showTime={{ use12Hours: true, format: "hh:mm A" }}
                  format={DATE_TIME_FORMAT}
                  placeholder="Select pickup date and time"
                />
              </Form.Item>
            </Col>
            <Col {...half}>
              <Form.Item label="Drop-off driver" name="driverDropoff" rules={[{ required: false }]}>
                <ResponderInput placeholder="Select driver for dropoff" adminRoles={adminRoles} />
              </Form.Item>
            </Col>
            <Col {...half}>
              <Form.Item label="Pick-up driver" name="driverPickup" rules={[{ required: false }]}>
                <ResponderInput placeholder="Select driver for pickup" adminRoles={adminRoles} />
              </Form.Item>
            </Col>
            <Col span={24}>
              <Form.Item
                label="Additional information"
                name="additionalInformation"
                rules={[{ max: 500, message: "Keep it under 500 characters" }]}
              >
                <TextArea autoSize={{ minRows: 2, maxRows: 5 }} placeholder="Anything the shop or drivers should know" />
              </Form.Item>
            </Col>
          </Row>
        </FormSection>
      </Form>
    </FormModal>
  );
};

export default EditVehicleModal;
